class Stage61BuildError(RuntimeError):
    """入力identity、relocation、patch、または検証契約の不一致。"""


def _fail(message: str) -> NoReturn:
    raise Stage61BuildError(message)


def _sha(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def _stable(value: Any) -> bytes:
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2)
            + "\n").encode("utf-8")


def _mgba_oracle_canonical_sha256(value: Any) -> str:
    """Match the independent oracle/matrix compact JSON hash contract."""

    raw = (
        json.dumps(
            value, ensure_ascii=False, sort_keys=True,
            separators=(",", ":"),
        ) + "\n"
    ).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _align(value: int, alignment: int) -> int:
    if alignment <= 0 or alignment & (alignment - 1):
        _fail(f"alignmentが2の冪ではありません: {alignment}")
    return (value + alignment - 1) & ~(alignment - 1)


def _run(command: Sequence[str], label: str, *, timeout: int = 180) -> str:
    try:
        result = subprocess.run(
            list(command), cwd=ROOT, text=True, capture_output=True,
            check=False, timeout=timeout,
        )
    except subprocess.TimeoutExpired as exc:
        _fail(f"{label} timeout: {exc}")
    if result.returncode:
        detail = (result.stderr or result.stdout).strip()
        _fail(f"{label} failed ({result.returncode}): {detail[-8000:]}")
    return result.stdout.strip()


def _identity(contract: Mapping[str, Any], label: str) -> bytes:
    path = ROOT / str(contract["path"])
    try:
        raw = path.read_bytes()
    except OSError as exc:
        _fail(f"{label}を読めません: {path}: {exc}")
    if "size" in contract and len(raw) != int(contract["size"]):
        _fail(f"{label} size不一致: {len(raw)} != {contract['size']}")
    if _sha(raw) != str(contract["sha256"]):
        _fail(f"{label} SHA-256不一致: {path}")
    return raw


def _u32(raw: bytes | bytearray, offset: int, what: str) -> int:
    if offset < 0 or offset + 4 > len(raw):
        _fail(f"{what}: u32がROM範囲外です: {offset:#x}")
    return struct.unpack_from("<I", raw, offset)[0]


def _rom_offset(pointer: int, size: int, what: str) -> int:
    offset = pointer - GBA_BASE
    if offset < 0 or offset + size > ROM_SIZE:
        _fail(f"{what}: ROM pointer範囲外: {pointer:#010x}+{size:#x}")
    return offset


@dataclass(frozen=True)
class _Fixup:
    offset: int
    label: str
    thumb: bool = False


class _Blob:
    def __init__(self) -> None:
        self.data = bytearray()
        self.labels: dict[str, int] = {}
        self.fixups: list[_Fixup] = []

    def align(self, alignment: int = 4, fill: int = 0xFF) -> None:
        while len(self.data) % alignment:
            self.data.append(fill)

    def add(self, label: str, raw: bytes, alignment: int = 4) -> int:
        if label in self.labels:
            _fail(f"payload label重複: {label}")
        self.align(alignment)
        offset = len(self.data)
        self.labels[label] = offset
        self.data.extend(raw)
        return offset

    def reserve(self, label: str, size: int, alignment: int = 4) -> int:
        return self.add(label, bytes(size), alignment)

    def pointer(self, offset: int, label: str, *, thumb: bool = False) -> None:
        if offset < 0 or offset + 4 > len(self.data):
            _fail(f"payload pointer fixup範囲外: {offset:#x}")
        self.fixups.append(_Fixup(offset, label, thumb))

    def finish(self, load_address: int) -> bytes:
        result = bytearray(self.data)
        for fixup in self.fixups:
            if fixup.label not in self.labels:
                _fail(f"未解決payload label: {fixup.label}")
            address = load_address + self.labels[fixup.label]
            if fixup.thumb:
                address |= 1
            struct.pack_into("<I", result, fixup.offset, address)
        return bytes(result)


def _load_config(path: Path) -> dict[str, Any]:
    try:
        value = json.loads((ROOT / path).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        _fail(f"configを読めません: {exc}")
    if not isinstance(value, dict):
        _fail("config rootはobjectである必要があります")
    if (value.get("schema_version"), value.get("task"), value.get("stage")) \
            != (1, TASK, STAGE):
        _fail("config schema/task/stage不一致")
    return value


def _validate_namespace_registry(raw: bytes) -> dict[str, Any]:
    try:
        value = json.loads(raw)
    except json.JSONDecodeError as exc:
        _fail(f"namespace registry JSON不正: {exc}")
    if not isinstance(value, dict) or (
        value.get("schema_version"), value.get("task"), value.get("stage")
    ) != (1, TASK, STAGE):
        _fail("namespace registry schema/task/stage不一致")
    for kind in ("flags", "vars"):
        rows = value.get(kind)
        if not isinstance(rows, list) or not rows:
            _fail(f"namespace registry {kind}が空です")
        occupied: dict[int, str] = {}
        for row in rows:
            start = int(str(row["start"]), 0)
            end = int(str(row["end_inclusive"]), 0)
            count = int(row["count"])
            if start > end or end - start + 1 != count:
                _fail(f"namespace registry {kind}/{row['owner']} size不一致")
            for value_id in range(start, end + 1):
                if value_id in occupied:
                    _fail(
                        f"namespace registry {kind} overlap: {value_id:#06x} "
                        f"{occupied[value_id]}/{row['owner']}"
                    )
                occupied[value_id] = str(row["owner"])
    expected = {
        "CFRU_RAID_COMPLETION_FLAGS": (0x15C0, 0x162C),
        "KANTO_MAP_TOPOLOGY_SOURCE_FLAGS": (0x162D, 0x163E),
        "TRAINER_ARCHIVE_DEFEAT_FLAGS": (0x1800, 0x1846),
        "KANTO_FULL_CFG_SOURCE_FLAGS": (0x1847, 0x18C3),
        "STAGE61_UNALLOCATED_SCRIPT_FLAG_GUARD": (0x18C4, 0x18C4),
        "KANTO_SOURCE_OBJECT_VISIBILITY_FLAGS": (0x18C5, 0x18DF),
        "KANTO_REGION_VISIT_FLAGS": (0x18E0, 0x18FB),
        "STAGE61_EXPANDED_FLAG_BUFFER": (0x18FC, 0x18FF),
        "KANTO_MAP_TOPOLOGY_PERSISTENT_VARS": (0x5167, 0x516B),
        "KANTO_LEAGUE_PROJECT_SCENE_VAR": (0x516C, 0x516C),
        "KANTO_FULL_CFG_PERSISTENT_VARS": (0x516D, 0x517F),
        "T19_QOL_VOLATILE_AND_COUNTERS": (0x5180, 0x51FF),
    }
    actual = {
        str(row["owner"]): (
            int(str(row["start"]), 0), int(str(row["end_inclusive"]), 0)
        )
        for kind in ("flags", "vars") for row in value[kind]
    }
    if actual != expected:
        _fail(f"namespace registry fixed ownership不一致: {actual}")
    full_cfg_row = next(
        row for row in value["flags"]
        if row["owner"] == "KANTO_FULL_CFG_SOURCE_FLAGS"
    )
    if (
        full_cfg_row.get("allocation")
        != (
            "source_flag_id_ascending_excluding_engine_abi_0x0805_"
            "and_shadow_0x18B3"
        )
        or full_cfg_row.get("allocated_count") != 124
        or full_cfg_row.get("reserved_holes") != ["0x18B3"]
        or full_cfg_row.get("engine_identity_exclusions") != ["0x0805"]
    ):
        _fail(
            "namespace registry Strength engine flag identity/0x18B3 shadow "
            "guard契約不一致"
        )
    return value


def _json_pointer(value: Any, pointer: str, label: str) -> Any:
    """Resolve the small RFC6901 subset used by provenance manifests."""

    if not pointer.startswith("/"):
        _fail(f"{label}: JSON pointerがabsoluteではありません: {pointer!r}")
    current = value
    for raw_part in pointer[1:].split("/"):
        part = raw_part.replace("~1", "/").replace("~0", "~")
        if isinstance(current, Mapping):
            if part not in current:
                _fail(f"{label}: JSON pointer keyがありません: {pointer!r}")
            current = current[part]
        elif isinstance(current, list) and part.isdigit():
            index = int(part)
            if index >= len(current):
                _fail(f"{label}: JSON pointer index範囲外: {pointer!r}")
            current = current[index]
        else:
            _fail(f"{label}: JSON pointerを辿れません: {pointer!r}")
    return current


def _load_post_ledger_owner_manifest() -> dict[str, Any]:
    """Load and verify the nine Stage58 owners absent from the Stage54 ledger.

    The old catalog silently labelled any missing object as a project owner.
    That made later object additions indistinguishable from ledger drift.  This
    manifest instead binds every exception to exact Stage58 artifacts and the
    exact ObjectEventTemplate that Stage58 emitted.
    """

    path = ROOT / POST_LEDGER_OWNER_MANIFEST
    try:
        raw = path.read_bytes()
        value = json.loads(raw)
    except (OSError, json.JSONDecodeError) as exc:
        _fail(f"post-ledger owner manifestを読めません: {exc}")
    if not isinstance(value, dict) or (
        value.get("schema_version"), value.get("task"), value.get("stage"),
        value.get("source_stage"),
    ) != (1, TASK, STAGE, 58):
        _fail("post-ledger owner manifest schema/task/stage不一致")
    provenance = value.get("provenance")
    if not isinstance(provenance, Mapping) or set(provenance) != {
        "stage58_rom", "stage58_metadata", "stage58_runtime_cases",
        "stage58_builder", "stage58_config",
    }:
        _fail("post-ledger Stage58 provenance artifact集合不一致")
    stage58 = _identity(provenance["stage58_rom"], "post-ledger Stage58 ROM")
    metadata_raw = _identity(
        provenance["stage58_metadata"], "post-ledger Stage58 metadata"
    )
    cases_raw = _identity(
        provenance["stage58_runtime_cases"], "post-ledger Stage58 runtime cases"
    )
    # Source/config bytes are intentionally read even though their JSON/body is
    # not interpreted here: their exact hash is part of the provenance chain.
    _identity(provenance["stage58_builder"], "post-ledger Stage58 builder")
    _identity(provenance["stage58_config"], "post-ledger Stage58 config")
    try:
        metadata = json.loads(metadata_raw)
        cases = json.loads(cases_raw)
    except json.JSONDecodeError as exc:
        _fail(f"post-ledger Stage58 provenance JSON不正: {exc}")
    if (
        metadata.get("task") != "USER-20260828-STAGE57-QOL-WORLD-CONVENIENCE-DEBUG"
        or metadata.get("stage") != 58 or metadata.get("status") != "PASS"
        or metadata.get("output", {}).get("sha256") != _sha(stage58)
        or cases.get("task") != metadata.get("task")
        or cases.get("stage") != 58
        or cases.get("rom_sha256") != _sha(stage58)
    ):
        _fail("post-ledger Stage58 metadata/cases/ROM identity chain不一致")
    owners = value.get("owners")
    if not isinstance(owners, list) or len(owners) != 9:
        _fail("post-ledger ownerはexact 9件である必要があります")
    required = {
        "npc_id", "map_key", "group", "map", "object_index", "local_id",
        "script_pointer", "role", "branches", "provenance_record", "object",
    }
    by_key: dict[tuple[str, int, int, int], dict[str, Any]] = {}
    seen_local: set[tuple[int, int, int]] = set()
    for index, raw_owner in enumerate(owners):
        if not isinstance(raw_owner, Mapping) or set(raw_owner) != required:
            _fail(f"post-ledger owners[{index}] schema不一致")
        owner = dict(raw_owner)
        group, number, object_index, local_id = (
            int(owner[key])
            for key in ("group", "map", "object_index", "local_id")
        )
        expected_npc_id = f"OBJECT:{group:03d}/{number:03d}:{object_index:03d}"
        if owner["npc_id"] != expected_npc_id:
            _fail(f"post-ledger npc_id不一致: {owner['npc_id']}")
        key = ("OBJECT", group, number, object_index)
        if key in by_key or (group, number, local_id) in seen_local:
            _fail(f"post-ledger owner key/local重複: {key}")
        branches = owner["branches"]
        if branches != ["DEFAULT"]:
            _fail(f"post-ledger branch contract不一致: {owner['npc_id']}")
        if not str(owner["role"]).startswith("STAGE58_"):
            _fail(f"post-ledger role provenance不一致: {owner['npc_id']}")
        object_contract = owner["object"]
        if not isinstance(object_contract, Mapping) or set(object_contract) != {
            "graphics_id", "kind", "movement_type", "x", "y", "elevation",
            "trainer_type", "sight_range", "flag",
        }:
            _fail(f"post-ledger object schema不一致: {owner['npc_id']}")
        try:
            state = _stage_map_state(stage58, group, number)
        except RuntimeError as exc:
            _fail(f"post-ledger Stage58 map decode失敗: {owner['npc_id']}: {exc}")
        if object_index >= len(state["objects"]):
            _fail(f"post-ledger Stage58 object index範囲外: {owner['npc_id']}")
        actual = _object_fields(state["objects"][object_index])
        expected = {
            **{key: int(value) for key, value in object_contract.items()},
            "local_id": local_id,
            "script_pointer": int(owner["script_pointer"]),
        }
        if any(actual[key] != expected[key] for key in expected):
            _fail(
                f"post-ledger Stage58 ObjectEventTemplate drift: "
                f"{owner['npc_id']}: actual={actual} expected={expected}"
            )
        evidence = _json_pointer(
            metadata, str(owner["provenance_record"]),
            f"post-ledger {owner['npc_id']}",
        )
        if not isinstance(evidence, Mapping) or any(
            int(evidence[key]) != expected[key]
            for key in ("local_id", "graphics_id", "x", "y")
        ):
            _fail(f"post-ledger Stage58 metadata record drift: {owner['npc_id']}")
        owner["source_stage"] = 58
        owner["manifest_sha256"] = _sha(raw)
        owner["stage58_rom_sha256"] = _sha(stage58)
        by_key[key] = owner
        seen_local.add((group, number, local_id))
    return {
        "schema_version": 1,
        "manifest_path": str(POST_LEDGER_OWNER_MANIFEST),
        "manifest_sha256": _sha(raw),
        "stage58_rom_sha256": _sha(stage58),
        "owner_count": len(by_key),
        "owners": by_key,
    }


def _canonical_maps(map_outputs: Mapping[str, bytes]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for name, raw in map_outputs.items():
        if not name.startswith("generated/maps/kanto/") or name.endswith("index.json"):
            continue
        value = json.loads(raw)
        header = value.get("map_header", {})
        if header.get("scope_decision") not in {"INCLUDE", "REBUILD"}:
            continue
        rows.append(value)
    rows.sort(key=lambda row: (
        int(row["map_header"]["group_id"]),
        int(row["map_header"]["map_id"]),
        str(row["map_header"]["map_key"]),
    ))
    coords = {
        (int(row["map_header"]["group_id"]), int(row["map_header"]["map_id"]))
        for row in rows
    }
    if len(rows) != 253 or len(coords) != 253:
        _fail(f"canonical Kanto map cardinality不一致: {len(rows)}/{len(coords)}")
    return rows


def _source_map_coordinates() -> dict[str, tuple[int, int]]:
    groups = json.loads((
        ROOT / "vendor/upstream/pokefirered/data/maps/map_groups.json"
    ).read_text(encoding="utf-8"))
    order = groups.get("group_order")
    if not isinstance(order, list):
        _fail("clean map_groups group_order不正")
    result: dict[str, tuple[int, int]] = {}
    for group, group_name in enumerate(order):
        names = groups.get(group_name)
        if not isinstance(names, list):
            _fail(f"clean map group不正: {group_name}")
        for number, name in enumerate(names):
            key = str(name)
            if key in result:
                _fail(f"clean source map名重複: {key}")
            result[key] = (group, number)
    return result


def _decode_map_script_table_contract(
    rom: bytes,
    group: int,
    number: int,
    *,
    label: str,
) -> dict[str, Any]:
    """MapScripts tableとtype 2/4 condition rowsを境界どおりdecodeする。"""

    header = _map_header_offset(rom, group, number)
    pointer = _u32(rom, header + 8, f"{label} map-script pointer")
    if pointer in {0, 0xFFFFFFFF}:
        return {
            "pointer": pointer, "rows": [], "table_raw": b"",
            "table_sha256": _sha(b""),
        }
    cursor = pointer - GBA_BASE
    if cursor < 0 or cursor >= len(rom):
        _fail(f"{label} map-script table範囲外: {pointer:#010x}")
    start = cursor
    rows: list[dict[str, Any]] = []
    for table_index in range(64):
        if cursor + 1 > len(rom):
            _fail(f"{label} map-script table終端前にROM終端")
        tag = rom[cursor]
        if tag == 0:
            raw = rom[start:cursor + 1]
            return {
                "pointer": pointer,
                "rows": rows,
                "table_raw": raw,
                "table_sha256": _sha(raw),
            }
        if tag not in range(1, 8) or cursor + 5 > len(rom):
            _fail(
                f"{label} map-script tag/row不正: index={table_index} "
                f"tag={tag}"
            )
        target = _u32(rom, cursor + 1, f"{label} map-script target")
        row: dict[str, Any] = {
            "tag": tag,
            "table_index": table_index,
            "record_address": GBA_BASE + cursor,
            "target": target,
            "conditions": [],
        }
        if tag in {2, 4}:
            condition_cursor = target - GBA_BASE
            if condition_cursor < 0 or condition_cursor + 2 > len(rom):
                _fail(f"{label} condition table範囲外: {target:#010x}")
            condition_start = condition_cursor
            conditions: list[dict[str, Any]] = []
            for condition_index in range(256):
                if condition_cursor + 2 > len(rom):
                    _fail(f"{label} condition table終端前にROM終端")
                first = struct.unpack_from("<H", rom, condition_cursor)[0]
                if first == 0:
                    condition_raw = rom[
                        condition_start:condition_cursor + 2
                    ]
                    row["conditions"] = conditions
                    row["condition_raw"] = condition_raw
                    row["condition_sha256"] = _sha(condition_raw)
                    break
                if condition_cursor + 8 > len(rom):
                    _fail(f"{label} condition row範囲外")
                second = struct.unpack_from("<H", rom, condition_cursor + 2)[0]
                script = _u32(
                    rom, condition_cursor + 4,
                    f"{label} condition script",
                )
                conditions.append({
                    "condition_index": condition_index,
                    "record_address": GBA_BASE + condition_cursor,
                    "first_operand": first,
                    "second_operand": second,
                    "script": script,
                })
                condition_cursor += 8
            else:
                _fail(f"{label} condition tableにterminatorがありません")
        else:
            target_offset = target - GBA_BASE
            if target_offset < 0 or target_offset >= len(rom):
                _fail(f"{label} direct map-script範囲外: {target:#010x}")
        rows.append(row)
        cursor += 5
    _fail(f"{label} map-script tableにterminatorがありません")


def _materialize_project_league_map_scripts(
    blob: _Blob,
    clean: bytes,
    stage60: bytes,
    contract: Mapping[str, Any],
    data_address: int,
) -> dict[str, Any]:
    """四天王の地形状態だけをproject-owned scriptとして再構築する。

    FireRedのChampion/Hall of Fame本編を再配置せず、通常のwarp consumerに
    必要な向き変更、強制入室移動、入口閉鎖、勝利後出口開放だけを実装する。
    source rootは証跡として読むだけで、payloadへverbatim copyしない。
    """

    if contract.get("status") != "READY" or not all(
        contract.get("assertions", {}).values()
    ):
        _fail("League explicit map-script contractがREADYではありません")
    elite = contract.get("elite_rooms")
    champion = contract.get("champion_room")
    hall = contract.get("hall_of_fame")
    if not isinstance(elite, list) or len(elite) != 4 \
            or not isinstance(champion, Mapping) \
            or not isinstance(hall, Mapping):
        _fail("League explicit map-script contract schema不正")
    if int(STAGE61_KANTO_LEAGUE_SCENE_VAR) in range(0x5180, 0x5200):
        _fail("League scene varがQOL予約域と衝突しています")
    expected_lifecycle = {
        "initial_value": 0,
        "advance": "MONOTONIC_HIGH_WATER_MARK_ON_PHYSICAL_ROOM_ENTRY",
        "mid_room_save_reload": "PRESERVE_TO_AVOID_REPLAYING_ENTRY_MOVEMENT",
        "blackout_retry": "PRESERVE_DEFEATED_ROOM_PROGRESS",
        "completed_revisit": "KEEP_5_AND_LEAVE_COMPLETION_DOORS_OPEN",
        "rematch_geometry": "COMPLETED_OPEN_NO_FORCED_ENTRY_REPLAY",
        "reset_writer": "NONE_BY_DESIGN",
    }
    if contract.get("policy", {}).get("scene_lifecycle") != expected_lifecycle:
        _fail("League scene lifecycle policyが明示high-water契約と一致しません")

    patches: list[dict[str, Any]] = []
    completion_patches: list[dict[str, Any]] = []
    maps: list[dict[str, Any]] = []
    generated_ranges: list[tuple[int, int]] = []
    materialization_start = len(blob.data)

    def add(label: str, raw: bytes, alignment: int = 1) -> int:
        at = blob.add(label, raw, alignment)
        address = data_address + at
        generated_ranges.append((at, at + len(raw)))
        return address

    def source_raw(pointer: int, size: int, label: str) -> bytes:
        offset = _rom_offset(pointer, size, label)
        return clean[offset:offset + size]

    def checked_movement(row: Mapping[str, Any], label: str) -> bytes:
        pointer = int(str(row["pointer"]), 0)
        raw = bytes.fromhex(str(row["raw_hex"]))
        if len(raw) != int(row["size"]) \
                or _sha(raw) != str(row["sha256"]) \
                or not raw.endswith(b"\xFE") \
                or source_raw(pointer, len(raw), label) != raw:
            _fail(f"League movement provenance不一致: {label}")
        return raw

    def checked_geometry(
        row: Mapping[str, Any], label: str,
    ) -> tuple[bytes, list[str]]:
        if row.get("status") != "A2_ONLY" or not row.get("exact"):
            _fail(f"League geometryがA2-onlyではありません: {label}")
        action_hex = [str(value) for value in row.get("raw_actions", [])]
        evidence = row.get("evidence", {})
        topology = evidence.get("topology_actions", []) \
            if isinstance(evidence, Mapping) else []
        if len(action_hex) != len(topology) or not action_hex:
            _fail(f"League geometry action証跡不正: {label}")
        for expected, action in zip(action_hex, topology, strict=True):
            if not isinstance(action, Mapping) \
                    or str(action.get("raw_hex")) != expected:
                _fail(f"League geometry action対応不一致: {label}")
            address = int(str(action["address"]), 0)
            raw = bytes.fromhex(expected)
            if len(raw) != 9 or raw[0] != 0xA2 \
                    or source_raw(address, len(raw), label) != raw:
                _fail(f"League geometry source bytes不一致: {label}")
        return b"".join(bytes.fromhex(value) for value in action_hex) + b"\x03", action_hex

    def checked_completion_binding(
        group: int, number: int, completion_flag: int,
    ) -> dict[str, Any]:
        coord = (group, number)
        spec = STAGE61_LEAGUE_BATTLE_COMPLETION_BINDINGS.get(coord)
        if not isinstance(spec, Mapping) \
                or int(spec["completion_flag"]) != completion_flag:
            _fail(f"League battle completion binding欠落: {group}/{number}")
        root = int(spec["completion_root"])
        pointer_site = int(spec["proxy_goto_pointer_site"])
        root_raw = b"\x29" + struct.pack("<H", completion_flag) + b"\x02"
        root_offset = _rom_offset(
            root, len(root_raw), "Stage60 League completion root",
        )
        if stage60[root_offset:root_offset + len(root_raw)] != root_raw:
            _fail(f"League completion root drift: {group}/{number}")
        pointer_raw = struct.pack("<I", root)
        pointer_offset = _rom_offset(
            pointer_site, len(pointer_raw), "League proxy goto operand",
        )
        if stage60[pointer_offset - 1:pointer_offset + 4] \
                != b"\x05" + pointer_raw:
            _fail(f"League proxy post-battle goto drift: {group}/{number}")
        hits: list[int] = []
        cursor = 0
        while True:
            found = stage60.find(pointer_raw, cursor)
            if found < 0:
                break
            hits.append(GBA_BASE + found)
            cursor = found + 1
        if hits != [pointer_site]:
            _fail(
                "League completion root proxy reference非一意: "
                f"{group}/{number} {hits}"
            )
        return {
            "physical_map": f"{group:03d}/{number:03d}",
            "completion_flag": f"0x{completion_flag:04X}",
            "completion_root": f"0x{root:08X}",
            "completion_root_raw_hex": root_raw.hex(),
            "completion_root_sha256": _sha(root_raw),
            "proxy_goto_opcode_address": f"0x{pointer_site - 1:08X}",
            "proxy_goto_pointer_site": f"0x{pointer_site:08X}",
            "proxy_goto_raw_hex": (b"\x05" + pointer_raw).hex(),
            "unique_pointer_reference": True,
            "geometry_redraw": bool(spec["geometry_redraw"]),
        }

    def patch_for_table(
        group: int, number: int, map_key: str, table_address: int,
    ) -> dict[str, Any]:
        target = _decode_map_script_table_contract(
            stage60, group, number,
            label=f"Stage60 League target {group}/{number}",
        )
        if target["rows"]:
            _fail(f"League target tableが空ではありません: {group}/{number}")
        header = _map_header_offset(stage60, group, number)
        expected = int(target["pointer"])
        return {
            "name": f"project_league_map_script::{group:03d}/{number:03d}",
            "offset": header + 8,
            "expected": struct.pack("<I", expected),
            "replacement": struct.pack("<I", table_address),
            "group": group,
            "map": number,
            "map_key": map_key,
            "source_map": map_key,
            "before_pointer": f"0x{expected:08X}",
            "after_pointer": f"0x{table_address:08X}",
            "ownership": "PROJECT_OWNED_LEAGUE_TOPOLOGY_STATE_MACHINE",
        }

    expected_elite_maps = {(97, value) for value in range(75, 79)}
    observed_elite_maps: set[tuple[int, int]] = set()
    for room in elite:
        if room.get("status") != "READY_FOR_EXPLICIT_BUILDER":
            _fail("League elite room contractがbuilder readyではありません")
        physical = str(room["physical_map"])
        try:
            group, number = (int(value) for value in physical.split("/"))
        except (TypeError, ValueError):
            _fail(f"League physical map表記不正: {physical}")
        observed_elite_maps.add((group, number))
        map_key = str(room["map_key"])
        table_contract = room["table_contract"]
        on_load_contract = table_contract["tag_1_on_load"]
        tag2_contract = table_contract["tag_2_entry"]
        tag4_contract = table_contract["tag_4_turn"]
        tag5_contract = table_contract["tag_5_battle_resume"]
        completion_flag = int(str(on_load_contract["completion_flag"]), 0)
        if completion_flag != int(str(tag5_contract["condition_flag"]), 0):
            _fail(f"League completion flag contract不一致: {physical}")
        scene_before = int(tag2_contract["condition"]["equals"])
        scene_after = int(
            str(tag2_contract["operations"][-1]).rsplit("_", 1)[-1]
        )
        if scene_after != scene_before + 1:
            _fail(f"League scene transition不連続: {physical}")

        movements = room.get("entry_movement_payloads")
        if not isinstance(movements, list) or len(movements) != 1:
            _fail(f"League entry movementが一意ではありません: {physical}")
        movement_raw = checked_movement(
            movements[0], f"League movement {physical}",
        )
        movement_address = add(
            f"league::{group:03d}/{number:03d}::entry_movement",
            movement_raw,
        )
        open_raw, open_actions = checked_geometry(
            room["exit_open_geometry"], f"League open {physical}",
        )
        close_raw, close_actions = checked_geometry(
            room["entry_close_geometry"], f"League close {physical}",
        )
        open_address = add(
            f"league::{group:03d}/{number:03d}::open_geometry",
            open_raw,
        )
        close_address = add(
            f"league::{group:03d}/{number:03d}::close_geometry",
            close_raw,
        )
        open_draw_raw = (
            b"\x04" + struct.pack("<I", open_address)
            + bytes.fromhex("258e0003")
        )
        open_draw_address = add(
            f"league::{group:03d}/{number:03d}::open_and_draw",
            open_draw_raw,
        )
        completion_source = checked_completion_binding(
            group, number, completion_flag,
        )
        completion_after_battle_raw = (
            b"\x29" + struct.pack("<H", completion_flag)
            + b"\x04" + struct.pack("<I", open_draw_address)
            + b"\x02"
        )
        completion_after_battle_address = add(
            f"league::{group:03d}/{number:03d}::complete_and_redraw",
            completion_after_battle_raw,
        )
        completion_root = int(str(completion_source["completion_root"]), 0)
        pointer_site = int(
            str(completion_source["proxy_goto_pointer_site"]), 0,
        )
        completion_patches.append({
            "name": (
                "project_league_battle_completion::"
                f"{group:03d}/{number:03d}"
            ),
            "offset": pointer_site - GBA_BASE,
            "expected": struct.pack("<I", completion_root),
            "replacement": struct.pack(
                "<I", completion_after_battle_address,
            ),
            "group": group,
            "map": number,
            "physical_map": physical,
            "completion_flag": f"0x{completion_flag:04X}",
            "before_pointer": f"0x{completion_root:08X}",
            "after_pointer": f"0x{completion_after_battle_address:08X}",
            "proxy_goto_opcode_address": completion_source[
                "proxy_goto_opcode_address"
            ],
            "adapter_raw_hex": completion_after_battle_raw.hex(),
            "adapter_sha256": _sha(completion_after_battle_raw),
            "open_draw_pointer": f"0x{open_draw_address:08X}",
            "resolution_order": [
                "SET_COMPLETION_FLAG",
                "OPEN_EXIT_GEOMETRY_AND_DRAW_CURRENT_MAP",
                "END",
            ],
            "ownership": "PROJECT_OWNED_LEAGUE_POST_BATTLE_REDRAW",
        })
        turn_root = int(str(tag4_contract["source_root"]), 0)
        turn_raw = bytes.fromhex("5bff000202")
        if source_raw(turn_root, len(turn_raw), "League turn root") != turn_raw:
            _fail(f"League turn root drift: {physical}")
        turn_address = add(
            f"league::{group:03d}/{number:03d}::turn_north",
            turn_raw,
        )
        entry_raw = (
            b"\x69"
            + bytes.fromhex("4fff00") + struct.pack("<I", movement_address)
            + bytes.fromhex("5100002902002f2600")
            + b"\x04" + struct.pack("<I", close_address)
            + bytes.fromhex("258e0030")
            + struct.pack(
                "<BHH", 0x16, STAGE61_KANTO_LEAGUE_SCENE_VAR,
                scene_after,
            )
            + bytes.fromhex("6b02")
        )
        entry_address = add(
            f"league::{group:03d}/{number:03d}::entry",
            entry_raw,
        )
        on_load_raw = (
            struct.pack(
                "<BHH", 0x21, STAGE61_KANTO_LEAGUE_SCENE_VAR,
                scene_after,
            )
            + bytes((0x07, 1)) + struct.pack("<I", close_address)
            + struct.pack("<BH", 0x2B, completion_flag)
            + bytes((0x07, 1)) + struct.pack("<I", open_address)
            + b"\x02"
        )
        on_load_address = add(
            f"league::{group:03d}/{number:03d}::on_load",
            on_load_raw,
        )
        on_resume_raw = (
            struct.pack("<BH", 0x2B, completion_flag)
            + bytes((0x07, 1)) + struct.pack("<I", open_draw_address)
            + b"\x02"
        )
        on_resume_address = add(
            f"league::{group:03d}/{number:03d}::on_resume",
            on_resume_raw,
        )
        tag4_condition_raw = struct.pack(
            "<HHI", 0x4001, 0, turn_address,
        ) + b"\x00\x00"
        tag4_condition_address = add(
            f"league::{group:03d}/{number:03d}::tag4_conditions",
            tag4_condition_raw, 2,
        )
        tag2_condition_raw = struct.pack(
            "<HHI", STAGE61_KANTO_LEAGUE_SCENE_VAR,
            scene_before, entry_address,
        ) + b"\x00\x00"
        tag2_condition_address = add(
            f"league::{group:03d}/{number:03d}::tag2_conditions",
            tag2_condition_raw, 2,
        )
        table_raw = (
            struct.pack("<BI", 5, on_resume_address)
            + struct.pack("<BI", 1, on_load_address)
            + struct.pack("<BI", 4, tag4_condition_address)
            + struct.pack("<BI", 2, tag2_condition_address)
            + b"\x00"
        )
        table_address = add(
            f"league::{group:03d}/{number:03d}::table",
            table_raw,
        )
        patches.append(patch_for_table(
            group, number, map_key, table_address,
        ))
        maps.append({
            "group": group, "map": number, "physical_map": physical,
            "map_key": map_key, "table_pointer": f"0x{table_address:08X}",
            "table_raw_hex": table_raw.hex(),
            "table_sha256": _sha(table_raw),
            "tags": [5, 1, 4, 2],
            "project_scene_transition": [scene_before, scene_after],
            "completion_flag": f"0x{completion_flag:04X}",
            "entry_movement_sha256": _sha(movement_raw),
            "battle_completion_source": completion_source,
            "battle_completion_adapter_pointer": (
                f"0x{completion_after_battle_address:08X}"
            ),
            "battle_completion_adapter_raw_hex": (
                completion_after_battle_raw.hex()
            ),
            "battle_completion_adapter_sha256": _sha(
                completion_after_battle_raw
            ),
            "post_battle_resolution_order": [
                "SET_COMPLETION_FLAG",
                "OPEN_EXIT_GEOMETRY_AND_DRAW_CURRENT_MAP",
                "END",
            ],
            "on_load_pointer": f"0x{on_load_address:08X}",
            "on_load_raw_hex": on_load_raw.hex(),
            "on_load_resolution_order": [
                "SCENE_AFTER_CLOSE", "COMPLETION_OPEN_FINAL_PRIORITY",
            ],
            "on_load_state_matrix": [
                {
                    "scene": scene,
                    "completion": completion,
                    "result": (
                        "OPEN" if completion else
                        "CLOSED" if scene == scene_after else "UNCHANGED"
                    ),
                }
                for completion in (False, True)
                for scene in range(6)
            ],
            "exit_open_actions": open_actions,
            "entry_close_actions": close_actions,
            "source_story_roots_imported": False,
        })
    if observed_elite_maps != expected_elite_maps:
        _fail(f"League elite map集合drift: {observed_elite_maps}")

    if champion.get("status") != "READY_FOR_EXPLICIT_BUILDER":
        _fail("League Champion contractがbuilder readyではありません")
    champion_group, champion_number = (97, 79)
    if str(champion["physical_map"]) != "097/079":
        _fail("League Champion physical map drift")
    champion_movement = checked_movement(
        champion["tag_2_entry"]["movement"], "Champion movement",
    )
    champion_movement_address = add(
        "league::097/079::entry_movement", champion_movement,
    )
    champion_turn_root = int(str(champion["tag_4_turn"]["source_root"]), 0)
    champion_turn_raw = bytes.fromhex("5bff000202")
    if source_raw(
        champion_turn_root, len(champion_turn_raw), "Champion turn root",
    ) != champion_turn_raw:
        _fail("League Champion turn root drift")
    champion_turn_address = add(
        "league::097/079::turn_north", champion_turn_raw,
    )
    champion_before = int(champion["tag_2_entry"]["condition"]["equals"])
    champion_after = int(champion["tag_2_entry"]["set_project_scene_var"])
    if (champion_before, champion_after) != (4, 5):
        _fail("League Champion scene transition drift")
    champion_entry_raw = (
        b"\x69" + bytes.fromhex("4fff00")
        + struct.pack("<I", champion_movement_address)
        + bytes.fromhex("510000290200")
        + struct.pack(
            "<BHH", 0x16, STAGE61_KANTO_LEAGUE_SCENE_VAR,
            champion_after,
        )
        + bytes.fromhex("6b02")
    )
    champion_entry_address = add(
        "league::097/079::entry", champion_entry_raw,
    )
    champion_tag4_raw = struct.pack(
        "<HHI", 0x4001, 0, champion_turn_address,
    ) + b"\x00\x00"
    champion_tag4_address = add(
        "league::097/079::tag4_conditions", champion_tag4_raw, 2,
    )
    champion_tag2_raw = struct.pack(
        "<HHI", STAGE61_KANTO_LEAGUE_SCENE_VAR,
        champion_before, champion_entry_address,
    ) + b"\x00\x00"
    champion_tag2_address = add(
        "league::097/079::tag2_conditions", champion_tag2_raw, 2,
    )
    champion_table_raw = (
        struct.pack("<BI", 4, champion_tag4_address)
        + struct.pack("<BI", 2, champion_tag2_address)
        + b"\x00"
    )
    champion_table_address = add(
        "league::097/079::table", champion_table_raw,
    )
    champion_key = str(champion["map_key"])
    champion_completion = checked_completion_binding(
        champion_group, champion_number, 0x140C,
    )
    if champion_completion["geometry_redraw"] is not False:
        _fail("League Champion completion negative control不正")
    patches.append(patch_for_table(
        champion_group, champion_number, champion_key,
        champion_table_address,
    ))
    maps.append({
        "group": champion_group, "map": champion_number,
        "physical_map": "097/079", "map_key": champion_key,
        "table_pointer": f"0x{champion_table_address:08X}",
        "table_raw_hex": champion_table_raw.hex(),
        "table_sha256": _sha(champion_table_raw),
        "tags": [4, 2], "project_scene_transition": [4, 5],
        "completion_flag": "0x140C",
        "battle_completion_source": champion_completion,
        "post_battle_resolution_order": [
            "PRESERVE_STAGE60_SET_COMPLETION_ONLY_NO_DOOR_GEOMETRY",
        ],
        "entry_movement_sha256": _sha(champion_movement),
        "forbidden_source_story_root": champion[
            "forbidden_source_story_root"
        ],
        "source_story_roots_imported": False,
    })

    # Hall of Fame already owns the project dispatcher.  It is intentionally
    # not patched and its only tag-3 row is pinned by the independent contract.
    if hall.get("policy") != "PRESERVE_EXISTING_PROJECT_TAG_3_ONLY" \
            or not hall.get("exact"):
        _fail("Hall of Fame project table contract不正")
    hall_surface = _decode_map_script_table_contract(
        stage60, 97, 80, label="Stage60 Hall of Fame project table",
    )
    if [int(row["tag"]) for row in hall_surface["rows"]] != [3]:
        _fail("Hall of Fame project tag-3 table drift")

    materialization_end = len(blob.data)
    payload_raw = bytes(blob.data[materialization_start:materialization_end])
    forbidden_roots = {
        int(str(champion["forbidden_source_story_root"]), 0),
        0x0816A88D, 0x0816A897, 0x0816A87E, 0x0816A888,
    }
    leaked = sorted(
        pointer for pointer in forbidden_roots
        if struct.pack("<I", pointer) in payload_raw
    )
    assertions = {
        "elite_4_and_champion_exact": len(maps) == 5,
        "all_five_tables_patch_empty_project_stubs": len(patches) == 5,
        "scene_state_is_project_owned_nonidentity": (
            STAGE61_KANTO_LEAGUE_SCENE_VAR != 0x4068
        ),
        "scene_sequence_0_through_5": [
            row["project_scene_transition"] for row in maps
        ] == [[0, 1], [1, 2], [2, 3], [3, 4], [4, 5]],
        "source_story_root_literals_absent": not leaked,
        "hall_of_fame_project_tag_3_preserved": True,
        "all_interactions_use_real_map_script_consumers": all(
            row["tags"] for row in maps
        ),
        "completion_open_has_final_priority_all_scenes": all(
            row["result"] == "OPEN"
            for map_row in maps[:4]
            for row in map_row["on_load_state_matrix"]
            if row["completion"]
        ),
        "unfinished_scene_after_closes_entry": all(
            next(
                row for row in map_row["on_load_state_matrix"]
                if not row["completion"]
                and row["scene"] == map_row["project_scene_transition"][1]
            )["result"] == "CLOSED"
            for map_row in maps[:4]
        ),
        "scene_lifecycle_high_water_no_reset_by_design": (
            contract["policy"]["scene_lifecycle"] == expected_lifecycle
        ),
        "elite_post_battle_completion_redraw_4_exact": (
            len(completion_patches) == 4
            and {(row["group"], row["map"]) for row in completion_patches}
                == {(97, value) for value in range(75, 79)}
        ),
        "completion_flag_precedes_current_map_geometry_redraw": all(
            row["resolution_order"] == [
                "SET_COMPLETION_FLAG",
                "OPEN_EXIT_GEOMETRY_AND_DRAW_CURRENT_MAP",
                "END",
            ]
            and bytes.fromhex(row["adapter_raw_hex"])[0] == 0x29
            and bytes.fromhex(row["adapter_raw_hex"])[3] == 0x04
            and bytes.fromhex(row["adapter_raw_hex"])[-1] == 0x02
            for row in completion_patches
        ),
        "completion_proxy_pointer_preimages_unique": all(
            row["battle_completion_source"]["unique_pointer_reference"]
            for row in maps
        ),
        "champion_completion_has_no_door_redraw_by_design": (
            champion_completion["geometry_redraw"] is False
            and all(row["map"] != 79 for row in completion_patches)
        ),
    }
    if not all(assertions.values()):
        _fail(f"League explicit materialization assertion FAIL: {assertions}")
    return {
        "schema_version": 1, "status": "PASS",
        "contract_sha256": contract["contract_sha256"],
        "project_scene_var": f"0x{STAGE61_KANTO_LEAGUE_SCENE_VAR:04X}",
        "scene_lifecycle": expected_lifecycle,
        "payload_base": f"0x{data_address + materialization_start:08X}",
        "payload_size": len(payload_raw),
        "payload_sha256": _sha(payload_raw),
        "patches": patches,
        "completion_patches": completion_patches,
        "maps": maps,
        "champion_completion_negative_control": champion_completion,
        "hall_of_fame": dict(hall),
        "forbidden_source_pointer_literals": [
            f"0x{value:08X}" for value in leaked
        ],
        "assertions": assertions,
    }


def _league_completion_runtime_repair_row(
    patch: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind a League goto-operand patch to its complete script instruction.

    The physical patch owns only the four-byte goto operand, while the project
    CFG provenance scanner reports the enclosing five-byte instruction from
    its opcode address.  Preserve the operand-sized mutation and explicitly
    prove that its interval overlaps that one pinned instruction; otherwise a
    valid post-battle redraw repair is indistinguishable from an undeclared
    script mutation.
    """

    try:
        offset = int(patch["offset"])
        expected = bytes(patch["expected"])
        replacement = bytes(patch["replacement"])
        group = int(patch["group"])
        number = int(patch["map"])
        opcode_address = int(str(patch["proxy_goto_opcode_address"]), 0)
        before_pointer = int(str(patch["before_pointer"]), 0)
        after_pointer = int(str(patch["after_pointer"]), 0)
    except (KeyError, TypeError, ValueError) as error:
        _fail(f"League completion runtime repair schema不正: {error}")
    address = GBA_BASE + offset
    if len(expected) != 4 or len(replacement) != 4 \
            or opcode_address != address - 1 \
            or struct.unpack("<I", expected)[0] != before_pointer \
            or struct.unpack("<I", replacement)[0] != after_pointer \
            or patch.get("physical_map") != f"{group:03d}/{number:03d}" \
            or patch.get("resolution_order") != [
                "SET_COMPLETION_FLAG",
                "OPEN_EXIT_GEOMETRY_AND_DRAW_CURRENT_MAP",
                "END",
            ] \
            or patch.get("ownership") \
                != "PROJECT_OWNED_LEAGUE_POST_BATTLE_REDRAW":
        _fail(
            "League completion runtime repair preimage/interval不一致: "
            f"{group}/{number}"
        )
    return {
        "repair_id": (
            f"LEAGUE_POST_BATTLE_COMPLETION_{group:03d}_{number:03d}"
        ),
        "family": "LEAGUE_POST_BATTLE_COMPLETION_REDRAW",
        "address": address,
        "instruction_address": opcode_address,
        "instruction_size": 5,
        "expected_hex": expected.hex(),
        "replacement_hex": replacement.hex(),
        "physical_map": patch["physical_map"],
        "completion_flag": patch["completion_flag"],
        "before_pointer": f"0x{before_pointer:08X}",
        "after_pointer": f"0x{after_pointer:08X}",
        "source_provenance": (
            "PINNED_STAGE60_UNIQUE_GOTO_OPERAND_AND_PROJECT_LEAGUE_CONTRACT"
        ),
        "semantic_contract": (
            "SET_COMPLETION_FLAG_THEN_REDRAW_CURRENT_ELITE_ROOM_EXIT"
        ),
    }


def _map_header_offset(rom: bytes | bytearray, group: int, number: int) -> int:
    root_pointer = _u32(rom, MAP_GROUPS_POINTER_SITE, "gMapGroups pointer")
    root = _rom_offset(root_pointer, (group + 1) * 4, "gMapGroups")
    group_pointer = _u32(rom, root + group * 4, f"map group {group}")
    group_offset = _rom_offset(group_pointer, (number + 1) * 4,
                               f"map group {group}")
    header_pointer = _u32(rom, group_offset + number * 4,
                          f"map header {group}/{number}")
    return _rom_offset(header_pointer, 0x1C, f"map header {group}/{number}")


def _owner_pointer_site(rom: bytes | bytearray, owner: Mapping[str, Any]) -> int:
    group, number, index = (int(owner[key]) for key in ("group", "map", "index"))
    header = _map_header_offset(rom, group, number)
    event_pointer = _u32(rom, header + 4, f"event header {group}/{number}")
    event = _rom_offset(event_pointer, 0x14, f"event header {group}/{number}")
    if str(owner["event"]) == "OBJECT":
        count = rom[event]
        if index >= count:
            _fail(f"OBJECT owner index範囲外: {group}/{number} index={index}/{count}")
        array_pointer = _u32(rom, event + 4, f"object array {group}/{number}")
        array = _rom_offset(array_pointer, count * 0x18,
                            f"object array {group}/{number}")
        return array + index * 0x18 + 0x10
    if str(owner["event"]) == "BG":
        count = rom[event + 3]
        if index >= count:
            _fail(f"BG owner index範囲外: {group}/{number} index={index}/{count}")
        array_pointer = _u32(rom, event + 16, f"BG array {group}/{number}")
        array = _rom_offset(array_pointer, count * 0x0C,
                            f"BG array {group}/{number}")
        return array + index * 0x0C + 8
    _fail(f"未対応owner event: {owner['event']}")


def _read_text(raw: bytes, pointer: int, label: str, *, limit: int = 0x4000) -> bytes:
    offset = _rom_offset(pointer, 1, label)
    end = raw.find(b"\xFF", offset, min(len(raw), offset + limit))
    if end < 0:
        _fail(f"{label}: EOSがありません: {pointer:#010x}")
    return raw[offset:end + 1]


def _section_rows(raw: bytes) -> list[dict[str, Any]]:
    rows = list(csv.DictReader(raw.decode("utf-8-sig").splitlines()))
    parsed = [{key: int(value) if key in {
        "runtime_map_section_id", "source_map_section_id", "x", "y", "width", "height"
    } else value for key, value in row.items()} for row in rows]
    if len(parsed) != 53 \
            or [row["runtime_map_section_id"] for row in parsed] != list(range(53)):
        _fail("Kanto map-section runtime namespaceは0..52の53件である必要があります")
    return parsed


def _add_msgbox(data: bytearray, fixups: list[tuple[int, str]],
                text_label: str, msgbox_type: int = 4) -> None:
    data.extend((0x0F, 0x00))
    fixups.append((len(data), text_label))
    data.extend(bytes(4))
    data.extend((0x09, msgbox_type))


def _goto_if(data: bytearray, fixups: list[tuple[int, str]],
             condition: int, target: str) -> None:
    data.extend((0x06, condition))
    fixups.append((len(data), target))
    data.extend(bytes(4))


def _add_route_snorlax_script(
    blob: _Blob, label: str, *, local_id: int, hidden_flag: int,
    flute_flag: int, species: int,
) -> None:
    no_flute, cancel = f"{label}::no_flute", f"{label}::cancel"
    data, fixups = bytearray((0x6A, 0x5A, 0x2B)), []
    data.extend(struct.pack("<H", flute_flag))
    _goto_if(data, fixups, 0, no_flute)
    _add_msgbox(data, fixups, "text::snorlax_prompt", 5)
    data.append(0x21)
    data.extend(struct.pack("<HH", 0x800D, 1))
    _goto_if(data, fixups, 5, cancel)
    _add_msgbox(data, fixups, "text::snorlax_flute", 4)
    data.append(0xA1)
    data.extend(struct.pack("<HH", species, 0))
    data.append(0xC5)
    data.extend((0x1A, 0x00, 0x80))
    data.extend(struct.pack("<H", hidden_flag))
    data.append(0x23)
    data.extend(struct.pack("<I", THIN_FLAG_SET))
    data.append(0xB6)
    data.extend(struct.pack("<HBH", species, 30, 0))
    data.extend((0xB7, 0x53))
    data.extend(struct.pack("<H", local_id))
    data.extend((0x6C, 0x02))
    at = blob.add(label, bytes(data), 4)
    for offset, target in fixups:
        blob.pointer(at + offset, target)

    for branch, text in ((no_flute, "text::snorlax_no_flute"),
                         (cancel, "text::snorlax_asleep")):
        branch_data, branch_fixups = bytearray(), []
        _add_msgbox(branch_data, branch_fixups, text, 4)
        branch_data.extend((0x6C, 0x02))
        branch_at = blob.add(branch, bytes(branch_data), 4)
        for offset, target in branch_fixups:
            blob.pointer(branch_at + offset, target)


def _add_fuji_script(blob: _Blob, label: str, flute_flag: int) -> None:
    owned = f"{label}::owned"
    data, fixups = bytearray((0x6A, 0x5A, 0x2B)), []
    data.extend(struct.pack("<H", flute_flag))
    _goto_if(data, fixups, 1, owned)
    _add_msgbox(data, fixups, "text::fuji_not_owned", 4)
    data.extend((0x6C, 0x02))
    at = blob.add(label, bytes(data), 4)
    for offset, target in fixups:
        blob.pointer(at + offset, target)
    owned_data, owned_fixups = bytearray(), []
    _add_msgbox(owned_data, owned_fixups, "text::fuji_owned", 4)
    owned_data.extend((0x6C, 0x02))
    owned_at = blob.add(owned, bytes(owned_data), 4)
    for offset, target in owned_fixups:
        blob.pointer(owned_at + offset, target)


def _add_berry_rankings_script(blob: _Blob, label: str) -> None:
    data, fixups = bytearray((0x69,)), []
    _add_msgbox(data, fixups, "text::berry_rankings", 3)
    data.extend((0x6B, 0x02))
    at = blob.add(label, bytes(data), 4)
    for offset, target in fixups:
        blob.pointer(at + offset, target)


def _add_bill_sevii_scope_guard_script(
    blob: _Blob, label: str,
) -> tuple[int, int]:
    """本土scope外のSevii航路を開始せず、通常fieldへ必ず復帰する。

    FireRed rootはCinnabarへwarpした後のmap-script consumerと一体であり、
    producerだけを移植してはいけない。ここでは通常の対面+A interaction、可視
    dialogue、release/endだけを所有し、BGM/flag/var/object/warpを原子的に抑止する。
    """

    data, fixups = bytearray((0x6A, 0x5A)), []
    _add_msgbox(data, fixups, "text::bill_sevii_unavailable", 4)
    data.extend((0x6C, 0x02))
    at = blob.add(label, bytes(data), 4)
    for offset, target in fixups:
        blob.pointer(at + offset, target)
    return at, len(data)


def _bill_sevii_scope_guard_contract(
    *, clean: bytes, canonical: Sequence[Mapping[str, Any]],
    semantic: RelocationPlan, data_address: int, adapter_at: int,
    adapter_size: int, explicit_text_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Billの二段source eventと本土製品scopeの境界を独立証跡化する。"""

    source_root = 0x08189851
    owner_id = "OBJECT:098/077:006"
    root = semantic.root(source_root)
    if (
        not root.is_explicit
        or root.explicit_reason != "BILL_SEVII_OUT_OF_SCOPE_ATOMIC_ADAPTER"
        or [str(row["owner_id"]) for row in root.owners] != [owner_id]
    ):
        _fail("Bill Sevii scope guard semantic owner/reason不一致")

    graph = SemanticScriptGraph(clean)
    graph.walk((source_root,))
    if graph.diagnostics:
        _fail(f"Bill source CFG diagnostics: {graph.diagnostics}")
    addresses = sorted(graph.distances(source_root))
    instructions = [
        instruction
        for address in addresses
        for instruction in graph.nodes[address].instructions
    ]
    source_raw = b"".join(row.raw for row in instructions)
    exact_source_sites = {
        0x08189876: bytes.fromhex("290140"),  # volatile BGM transition flag
        0x08189879: bytes.fromhex("29a200"),  # hide PokeCenter Bill
        0x081898A3: bytes.fromhex("168a400100"),  # arrival scene=1
        0x081898A8: bytes.fromhex("2a6200"),  # show outdoor Bill
        0x081898AB: bytes.fromhex("390308ff0e000b00"),  # Cinnabar warp
    }
    by_site = {row.address: row.raw for row in instructions}

    source_paths = BILL_SEVII_SOURCE_EVIDENCE_PATHS
    source_evidence: list[dict[str, Any]] = []
    source_texts: dict[str, str] = {}
    for relative in source_paths:
        raw = (ROOT / relative).read_bytes()
        source_evidence.append({
            "path": relative.as_posix(), "sha256": _sha(raw),
        })
        try:
            source_texts[relative.as_posix()] = raw.decode("utf-8-sig")
        except UnicodeDecodeError as exc:
            _fail(f"Bill scope source UTF-8不正: {relative}: {exc}")

    center_text = source_texts[source_paths[0].as_posix()]
    arrival_text = source_texts[source_paths[1].as_posix()]
    policy_text = source_texts[source_paths[2].as_posix()]
    decisions_text = source_texts[source_paths[3].as_posix()]
    scope_text = source_texts[source_paths[4].as_posix()]
    canonical_source_maps = {
        str(row["map_header"]["source_map"]) for row in canonical
    }
    cinnabar_rows = [
        row for row in canonical
        if row["map_header"]["map_key"]
        == "KANTO_OUTDOOR_CINNABAR_ISLAND"
    ]
    if len(cinnabar_rows) != 1:
        _fail("Bill scope canonical Cinnabar一意性不一致")
    cinnabar_scripts = cinnabar_rows[0].get("scripts")
    bill_text_rows = [
        row for row in explicit_text_rows
        if row.get("semantic_contract", {}).get("meaning_id")
        == "BILL_SEVII_UNAVAILABLE"
    ]
    assertions = {
        "source_root_exact_operations_pinned": all(
            by_site.get(address) == expected
            for address, expected in exact_source_sites.items()
        ),
        "source_producer_sets_bgm_flag_scene_and_warps": (
            "setflag FLAG_DONT_TRANSITION_MUSIC" in center_text
            and "setvar VAR_MAP_SCENE_CINNABAR_ISLAND_2, 1" in center_text
            and "warp MAP_CINNABAR_ISLAND, 14, 11" in center_text
        ),
        "source_arrival_requires_missing_map_script_consumer": (
            "clearflag FLAG_DONT_TRANSITION_MUSIC" in arrival_text
            and "call CinnabarIsland_EventScript_SailToOneIsland"
            in arrival_text
            and "goto EventScript_SetSail" in arrival_text
        ),
        "product_policy_excludes_sevii_and_source_story": (
            "ナナシマはV2本体のscope外" in policy_text
            and "原作ストーリー状態は再利用しない" in decisions_text
        ),
        "canonical_scope_contains_cinnabar_not_one_island": (
            "CinnabarIsland" in canonical_source_maps
            and "OneIsland" not in canonical_source_maps
            and "OneIsland" not in scope_text
        ),
        "cinnabar_map_script_is_project_stub": (
            isinstance(cinnabar_scripts, Mapping)
            and cinnabar_scripts.get("policy") == "KANTO_NAMESPACED_STUB"
            and cinnabar_scripts.get("source_story_imported") is False
        ),
        "adapter_text_is_unique_and_visible": (
            len(bill_text_rows) == 1
            and int(bill_text_rows[0]["raw_size"]) > 1
        ),
        "adapter_has_finite_nonempty_extent": adapter_size == 12,
    }
    if not all(assertions.values()):
        _fail(f"Bill Sevii scope guard assertion FAIL: {assertions}")
    return {
        "schema_version": 1,
        "kind": "STAGE61_OUT_OF_SCOPE_STORY_ATOMIC_ADAPTER",
        "status": "PASS",
        "owner_id": owner_id,
        "source_contract": {
            "root": f"0x{source_root:08X}",
            "reachable_nodes": [f"0x{address:08X}" for address in addresses],
            "instruction_stream_sha256": _sha(source_raw),
            "exact_effect_sites": [
                {"address": f"0x{address:08X}", "raw_hex": raw.hex()}
                for address, raw in sorted(exact_source_sites.items())
            ],
            "source_destination": {"group": 3, "map": 8, "x": 14, "y": 11},
            "downstream": "CINNABAR_MAP_SCRIPT_TO_ONE_ISLAND",
            "source_evidence": source_evidence,
        },
        "product_contract": {
            "policy": "ATOMIC_PRODUCER_SUPPRESSION_FOR_OUT_OF_SCOPE_DESTINATION",
            "adapter_offset": adapter_at,
            "adapter_address": f"0x{data_address + adapter_at:08X}",
            "adapter_size": adapter_size,
            "text_pointer": bill_text_rows[0]["target_pointer"],
            "visible_text_sha256": bill_text_rows[0]["raw_sha256"],
            "allowed_semantics": [
                "LOCK", "FACEPLAYER", "VISIBLE_MSGBOX", "RELEASE", "END",
            ],
            "preserved_source_effect_classes": ["MENU_UI"],
            "suppressed_source_effect_classes": [
                effect for effect in sorted(root.side_effect_classes)
                if effect != "MENU_UI"
            ],
            "forbidden_product_effects": [
                "AUDIO", "FLAG_WRITE", "VAR_WRITE", "MOVEMENT", "OBJECT_MUTATION",
                "WARP", "WAITSTATE",
            ],
            "canonical_destination": None,
            "interaction": "REAL_WALK_FACE_A_THEN_FIELD_INPUT_RECOVERY",
        },
        "assertions": assertions,
    }


def _pick_fly_maps(canonical: Sequence[Mapping[str, Any]]) -> dict[int, tuple[int, int]]:
    choices: dict[int, list[tuple[int, int, int, str]]] = defaultdict(list)
    priority = {"OUTDOOR": 0, "DUNGEON": 1, "INDOOR": 2}
    for row in canonical:
        header = row["map_header"]
        section = int(header["runtime_map_section_id"])
        choices[section].append((
            priority.get(str(header["classification"]), 3),
            int(header["group_id"]), int(header["map_id"]),
            str(header["map_key"]),
        ))
    result = {
        section: (sorted(rows)[0][1], sorted(rows)[0][2])
        for section, rows in choices.items()
    }
    if set(result) != set(range(53)):
        _fail(f"Fly physical destination coverage不一致: {sorted(set(range(53))-set(result))}")
    return result


def _clean_route2_repair_plan(
    stage60: bytes, clean: bytes, charmap: Mapping[int, str],
) -> FullCfgRelocationPlan:
    """Build a closed clean-CFG plan for the two Stage03 EOS stubs.

    Route2's Aide and Rocker roots still exist at their clean physical
    addresses, but Stage03 replaced both entry instructions with the same
    EOS-only placeholder.  The Aide is stateful (flag/menu/item-capacity and
    give-item paths), so copying one text or inventing a dialogue adapter
    would lose reachable semantics.  Build the same typed full-CFG relocation
    used by SOURCE_DIRECT, limited to these two independently pinned roots.
    """

    roots = tuple(address for address, _owner in ROUTE2_EMPTY_OWNER_ROOTS)
    owner_by_root = dict(ROUTE2_EMPTY_OWNER_ROOTS)
    graph = SemanticScriptGraph(clean)
    graph.walk(roots)
    if graph.diagnostics:
        _fail(f"Route2 clean CFG diagnostics: {graph.diagnostics}")

    pointers: dict[int, int] = {}
    root_plans: list[RootPlan] = []
    for root in roots:
        distances = graph.distances(root)
        references = []
        semantic_classes: set[str] = set()
        side_effect_classes: set[str] = set()
        for node_address, distance in sorted(distances.items()):
            node = graph.nodes[node_address]
            for reference in node.references:
                pointers.setdefault(
                    reference.text_pointer, reference.source_data_pointer
                )
                references.append((reference, distance))
            for instruction in node.instructions:
                classification = classify_instruction(instruction)
                semantic_classes.update(classification.semantic_classes)
                side_effect_classes.update(classification.side_effect_classes)
        root_plans.append(RootPlan(
            source_script_pointer=root,
            event_kind="OBJECT",
            owners=({"owner_id": owner_by_root[root]},),
            source_labels=("CLEAN_FIRERED_REV0_ROUTE2_OWNER",),
            source_role="ROUTE2_VISIBLE_OWNER_SEMANTIC_RESTORE",
            replacement_role="PROJECT_FULL_CFG_SEMANTIC_RELOCATION",
            explicit_reason=None,
            reachable_nodes=tuple(sorted(distances)),
            references=tuple(references),
            opcode_audit=(),
            source_cfg_class=(
                "SIDE_EFFECTING" if side_effect_classes else "DIALOGUE_ONLY"
            ),
            source_cfg_opcode_classes=tuple(sorted(semantic_classes)),
            side_effect_classes=tuple(sorted(side_effect_classes)),
            selected_text=None,
            adapter_script_template=None,
            text_pointer_fixup_offset=None,
        ))
    assets = tuple(
        TextAsset(
            source_pointer=pointer,
            source_data_pointer=source_data_pointer,
            decoded=read_terminated_text(clean, pointer, charmap),
        )
        for pointer, source_data_pointer in sorted(pointers.items())
    )
    plan = RelocationPlan(
        stage60_sha256=_sha(stage60),
        clean_sha256=_sha(clean),
        clean_size=len(clean),
        canonical_script_policy=None,
        root_plans=tuple(root_plans),
        text_assets=assets,
        owner_assignments=(),
        graph_node_count=len(graph.nodes),
        graph_diagnostics=tuple(graph.diagnostics),
    ).full_cfg_plan(clean)
    report = plan.to_report()
    if report["status"] != "PASS" or report["root_count"] != 2:
        _fail(f"Route2 clean CFG repair plan不正: {report}")
    return plan


def _missing_silph_scope_semantic_evidence(
    clean: bytes,
    charmap: Mapping[int, str],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """欠落Silph Scope ownerのclean CFG/text provenanceをreport化する。

    このrootはStage60 owner ledger生成時にはobject templateごと欠落していたため、
    通常の679 root relocation planへ入らない。一方、Stage61ではtemplateとscriptを
    明示復元している。source pointerをcatalogへ書くだけでは独立text oracleが
    clean CFGとの対応を証明できないため、同じdecoder/classifierで2-node closureを
    再構築し、通常root planと同じschemaへ昇格する。
    """

    root = 0x081663AC
    owner_id = "OBJECT:097/045:006"
    graph = SemanticScriptGraph(clean)
    graph.walk([root])
    if graph.diagnostics:
        _fail(f"Silph Scope clean CFG diagnostics: {graph.diagnostics}")
    distances = graph.distances(root)
    if set(distances) != {root, 0x081944C5}:
        _fail(
            "Silph Scope clean CFG closure drift: "
            f"{[f'0x{value:08X}' for value in sorted(distances)]}"
        )
    references: list[tuple[Any, int]] = []
    assets: dict[int, TextAsset] = {}
    for node_address, distance in sorted(distances.items()):
        for reference in graph.nodes[node_address].references:
            references.append((reference, distance))
            previous = assets.get(reference.text_pointer)
            asset = TextAsset(
                source_pointer=reference.text_pointer,
                source_data_pointer=reference.source_data_pointer,
                decoded=read_terminated_text(
                    clean, reference.text_pointer, charmap,
                ),
            )
            if previous is not None and previous != asset:
                _fail("Silph Scope clean text provenance競合")
            assets[reference.text_pointer] = asset
    references.sort(key=lambda row: (
        row[1], row[0].priority, row[0].instruction_address,
        row[0].text_pointer, row[0].kind,
    ))
    opcode_audit, opcode_classes, side_effect_classes = _root_opcode_audit(
        graph, distances,
    )
    selected = next((
        assets[reference.text_pointer]
        for reference, _distance in references
        if reference.directly_visible
        and assets[reference.text_pointer].decoded.usable_dialogue
    ), None)
    if selected is None or not opcode_audit or not opcode_classes:
        _fail("Silph Scope clean CFG/text semantic evidence不足")
    plan = RootPlan(
        source_script_pointer=root,
        event_kind="OBJECT",
        owners=({"owner_id": owner_id},),
        source_labels=("RocketHideout_B4F_EventScript_SilphScope",),
        source_role="RESTORED_SOURCE_ITEM_OBJECT",
        replacement_role="STAGE61_MISSING_OBJECT_SEMANTIC_ADAPTER",
        explicit_reason="STAGE60_IMPORT_DROPPED_SOURCE_OBJECT_TEMPLATE",
        reachable_nodes=tuple(sorted(distances)),
        references=tuple(references),
        opcode_audit=opcode_audit,
        source_cfg_class=(
            "SIDE_EFFECTING" if side_effect_classes else "DIALOGUE_ONLY"
        ),
        source_cfg_opcode_classes=opcode_classes,
        side_effect_classes=side_effect_classes,
        selected_text=selected,
        adapter_script_template=None,
        text_pointer_fixup_offset=None,
    )
    return plan.to_report(), [
        asset.to_report() for _pointer, asset in sorted(assets.items())
    ]


def _trainer_intro_repair_plan(stage60: bytes) -> dict[str, Any]:
    """Derive every empty trainer-intro repair from immutable Stage35 data.

    The affected canonical proxy layout is deliberately decoded, not found by
    scanning for ``0x09363D90`` alone.  Each row must bind a serialized
    encounter, its physical defeat flag, two authored non-empty intro assets,
    the exact normal/rematch control-flow prelude, and the exact trainerbattle
    command in both published Stage35 and Stage60.
    """

    serialized_path = ROOT / TRAINER_SERIALIZED_PATH
    stage35_path = ROOT / TRAINER_STAGE35_ROM_PATH
    try:
        serialized_raw = serialized_path.read_bytes()
        stage35 = stage35_path.read_bytes()
        document = json.loads(serialized_raw)
    except (OSError, json.JSONDecodeError) as exc:
        _fail(f"trainer intro provenanceを読めません: {exc}")
    if _sha(serialized_raw) != TRAINER_SERIALIZED_SHA256:
        _fail("Stage35 serialized trainer provenance SHA-256不一致")
    if len(stage35) != ROM_SIZE or _sha(stage35) != TRAINER_STAGE35_ROM_SHA256:
        _fail("published Stage35 trainer ROM provenance不一致")
    battle_rows = document.get("battle_rows")
    if not isinstance(battle_rows, list) or len(battle_rows) != 1302:
        _fail("Stage35 serialized trainerbattle inventory不一致")
    tables = document.get("tables")
    rematch_rows = tables.get("rematch") \
        if isinstance(tables, Mapping) else None
    if not isinstance(rematch_rows, list) or len(rematch_rows) != 227:
        _fail("Stage35 serialized rematch inventory不一致")
    normalized_rematch_rows: list[dict[str, Any]] = []
    rematch_by_data_address: dict[int, dict[str, Any]] = {}
    rematch_stock_ids: set[int] = set()
    for index, raw_row in enumerate(rematch_rows):
        if not isinstance(raw_row, Mapping) or set(raw_row) != {
            "data_address", "encounter_key", "stock_trainer_id",
            "target_trainer_id",
        }:
            _fail(f"Stage35 serialized rematch row schema不正:{index}")
        data_address = int(raw_row["data_address"])
        stock_trainer_id = int(raw_row["stock_trainer_id"])
        target_trainer_id = int(raw_row["target_trainer_id"])
        encounter_key = str(raw_row["encounter_key"])
        if not GBA_BASE <= data_address < GBA_BASE + ROM_SIZE \
                or not encounter_key \
                or not 0 < stock_trainer_id < 0x10000 \
                or not 0 < target_trainer_id < 0x10000 \
                or target_trainer_id != stock_trainer_id \
                or data_address in rematch_by_data_address \
                or stock_trainer_id in rematch_stock_ids:
            _fail(f"Stage35 serialized rematch row identity不正:{index}")
        row = {
            "data_address": data_address,
            "encounter_key": encounter_key,
            "stock_trainer_id": stock_trainer_id,
            "target_trainer_id": target_trainer_id,
        }
        normalized_rematch_rows.append(row)
        rematch_by_data_address[data_address] = row
        rematch_stock_ids.add(stock_trainer_id)
    rematch_battle_rows = [
        row for row in battle_rows
        if isinstance(row, Mapping) and row.get("kind") in {5, 7}
    ]
    if len(rematch_battle_rows) != len(normalized_rematch_rows) or any(
        not isinstance(row.get("data_address"), int)
        or rematch_by_data_address.get(int(row["data_address"])) != {
            "data_address": int(row["data_address"]),
            "encounter_key": str(row["encounter_key"]),
            "stock_trainer_id": int(row["source_trainer_id"]),
            "target_trainer_id": int(row["target_trainer_id"]),
        }
        for row in rematch_battle_rows
    ):
        _fail("Stage35 trainerbattle/rematch exact tuple対応不一致")
    if stage60[TRAINER_EMPTY_TEXT_POINTER - GBA_BASE:
               TRAINER_EMPTY_TEXT_POINTER - GBA_BASE + 1] != b"\xFF":
        _fail("trainer empty text preimageがEOS-onlyではありません")

    repairs: list[dict[str, Any]] = []
    for source in sorted(
        battle_rows, key=lambda row: int(row["command_address"])
    ):
        command = int(source["command_address"])
        kind = int(source["kind"])
        roles = TRAINERBATTLE_POINTER_ROLES.get(kind)
        size = TRAINERBATTLE_SIZES.get(kind)
        if roles is None or size is None:
            _fail(f"trainerbattle kind未分類: {kind}")
        offset = _rom_offset(command, size, "trainer intro command")
        raw = stage60[offset:offset + size]
        if raw[:2] != bytes((0x5C, kind)):
            _fail(f"trainerbattle command drift: {command:#010x}")
        if struct.unpack_from("<H", raw, 2)[0] != int(source["target_trainer_id"]):
            _fail(f"trainerbattle trainer ID drift: {command:#010x}")
        pointers = {
            role: struct.unpack_from("<I", raw, 6 + index * 4)[0]
            for index, role in enumerate(roles)
        }
        if pointers.get("intro") != TRAINER_EMPTY_TEXT_POINTER:
            continue
        if source.get("binding_mode") != "CANONICAL" or "intro" not in roles:
            _fail(f"EOS-only trainer introの所有分類不正: {command:#010x}")
        if stage35[offset:offset + size] != raw:
            _fail(f"Stage35->Stage60 trainer command drift: {command:#010x}")

        proxy_root = command - 35
        root_offset = _rom_offset(proxy_root, 35, "trainer proxy prelude")
        prelude = stage60[root_offset:root_offset + 35]
        if stage35[root_offset:root_offset + 35] != prelude:
            _fail(f"Stage35->Stage60 trainer proxy drift: {proxy_root:#010x}")
        expected_flag = int(source["physical_flag"])
        valid_prelude = (
            prelude[0] == 0x2B
            and struct.unpack_from("<H", prelude, 1)[0] == expected_flag
            and prelude[3:5] == b"\x06\x01"
            and struct.unpack_from("<I", prelude, 5)[0] == proxy_root + 22
            and prelude[9:11] == b"\x0F\x00"
            and prelude[15:17] == b"\x09\x04"
            and prelude[17] == 0x05
            and struct.unpack_from("<I", prelude, 18)[0] == command
            and prelude[22:24] == b"\x0F\x00"
            and prelude[28:30] == b"\x09\x04"
            and prelude[30] == 0x05
            and struct.unpack_from("<I", prelude, 31)[0] == command
        )
        if not valid_prelude:
            _fail(f"trainer normal/rematch proxy ABI drift: {proxy_root:#010x}")
        normal_text = struct.unpack_from("<I", prelude, 11)[0]
        rematch_text = struct.unpack_from("<I", prelude, 24)[0]
        normal_raw = _read_text(
            stage60, normal_text, f"trainer normal intro {command:#x}"
        )
        rematch_raw = _read_text(
            stage60, rematch_text, f"trainer rematch intro {command:#x}"
        )
        if normal_raw == b"\xFF" or rematch_raw == b"\xFF":
            _fail(f"authored trainer introが空です: {command:#010x}")
        rematch = rematch_by_data_address.get(command + 1)
        if (kind in {5, 7}) != (rematch is not None):
            _fail(f"trainer intro rematch tuple対応不一致: {command:#010x}")
        repairs.append({
            "encounter_key": str(source["encounter_key"]),
            "command_address": command,
            "source_data_address": command + 1,
            "proxy_root": proxy_root,
            "source_script_root": proxy_root,
            "source_instruction": command,
            "kind": kind,
            "trainer_id": int(source["target_trainer_id"]),
            "source_trainer_id": int(source["source_trainer_id"]),
            "rematch_target_trainer_id": (
                None if rematch is None
                else int(rematch["target_trainer_id"])
            ),
            "physical_flag": expected_flag,
            "normal_text_pointer": normal_text,
            "normal_text_sha256": _sha(normal_raw),
            "rematch_text_pointer": rematch_text,
            "rematch_text_sha256": _sha(rematch_raw),
            "post_address": command + size,
            "command_raw": raw,
            "command_sha256": _sha(raw),
            "pointer_roles": pointers,
            "proxy_preimage": prelude,
            "source_closure": {
                "source_rom": "STAGE60",
                "root": f"0x{proxy_root:08X}",
                "instruction_addresses": [
                    f"0x{proxy_root:08X}", f"0x{command:08X}",
                ],
                "raw_sha256": _sha(prelude + raw),
                "provenance": (
                    "PINNED_STAGE35_PROXY_PRELUDE_AND_TRAINERBATTLE_COMMAND"
                ),
            },
            "visible_text_assets": [
                {
                    "pointer": f"0x{normal_text:08X}",
                    "raw_sha256": _sha(normal_raw),
                    "source_rom": "STAGE60",
                    "source_provenance": (
                        "PINNED_STAGE35_AUTHORED_NORMAL_INTRO"
                    ),
                },
                {
                    "pointer": f"0x{rematch_text:08X}",
                    "raw_sha256": _sha(rematch_raw),
                    "source_rom": "STAGE60",
                    "source_provenance": (
                        "PINNED_STAGE35_AUTHORED_REMATCH_INTRO"
                    ),
                },
            ],
        })
    # 477 commands are reachable from current product owners.  A paired
    # double-battle command (ENC_TOHOKU_REF_0679) is currently unreferenced but
    # has the same consumer-visible defect and must not remain as a latent
    # regression if an owner edge is restored later.
    if len(repairs) != 478 or len({
        row["command_address"] for row in repairs
    }) != 478 or len({row["proxy_root"] for row in repairs}) != 478:
        _fail(f"EOS-only trainer intro repair count不一致: {len(repairs)}")
    kind_counts = dict(sorted(Counter(row["kind"] for row in repairs).items()))
    if kind_counts != {0: 228, 4: 21, 5: 205, 6: 3, 7: 21}:
        _fail(f"EOS-only trainer kind inventory drift: {kind_counts}")
    return {
        "serialized_path": str(TRAINER_SERIALIZED_PATH),
        "serialized_sha256": _sha(serialized_raw),
        "stage35_rom_path": str(TRAINER_STAGE35_ROM_PATH),
        "stage35_rom_sha256": _sha(stage35),
        "empty_pointer": TRAINER_EMPTY_TEXT_POINTER,
        "repairs": repairs,
        "kind_counts": kind_counts,
        "rematch_rows": normalized_rematch_rows,
        "rematch_row_count": len(normalized_rematch_rows),
        "rematch_rows_sha256": _sha(_stable(normalized_rematch_rows)),
    }


def _trainer_intro_entry_patch_specs(
    repair: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Return the two legal Stage61 entry repairs for one trainer command.

    A field interaction may enter the generated proxy, but trainer sight and
    VS Seeker consumers read the physical trainerbattle command in place.  The
    proxy may therefore become a goto; the command opcode/mode/id prefix may
    not.  Repair its visible normal intro by changing only the pointer operand
    at command+6.
    """

    target = int(repair["adapter_address"])
    normal_text = int(repair["normal_text_pointer"])
    if normal_text == TRAINER_EMPTY_TEXT_POINTER:
        _fail("trainer normal intro pointerがEOS-onlyのままです")
    return (
        {
            "entry_kind": "proxy_root",
            "address": int(repair["proxy_root"]),
            "expected": bytes.fromhex(
                str(repair["proxy_root_expected_hex"])
            ),
            "replacement": b"\x05" + struct.pack("<I", target),
        },
        {
            "entry_kind": "battle_intro_pointer",
            "address": int(repair["command_address"]) + 6,
            "expected": bytes.fromhex(
                str(repair["intro_pointer_expected_hex"])
            ),
            "replacement": bytes.fromhex(
                str(repair["intro_pointer_replacement_hex"])
            ),
        },
    )


def _trainer_original_dialogue_restore_plan(
    stage60: bytes,
    vega_reference: bytes,
    consumers_raw: bytes,
) -> dict[str, Any]:
    """Keep ChangeKit parties while restoring every canonical Vega message.

    Stage35 redirected the physical Vega command to a generated command.  The
    generated command owns the new trainer ID/party, so replacing the physical
    command would also replace rematch identity.  Instead this plan keeps that
    command header byte-exact, copies only the original Vega text/continuation
    pointers, skips the generated generic post message, and bypasses the 35-byte
    generic normal/rematch prelude where one exists.
    """

    try:
        consumer_rows = list(csv.DictReader(
            consumers_raw.decode("utf-8-sig").splitlines()
        ))
        serialized_raw = (ROOT / TRAINER_SERIALIZED_PATH).read_bytes()
        serialized = json.loads(serialized_raw)
    except (UnicodeDecodeError, csv.Error, OSError, json.JSONDecodeError) as exc:
        _fail(f"Vega trainer dialogue provenanceを読めません: {exc}")
    if _sha(serialized_raw) != TRAINER_SERIALIZED_SHA256:
        _fail("Vega trainer dialogue serialized SHA-256不一致")
    if len(consumer_rows) != 1302:
        _fail(
            "trainer runtime consumer count不一致: "
            f"{len(consumer_rows)}"
        )
    required_fields = {
        "encounter_key", "runtime_trainer_id", "source_trainer_id",
        "binding_mode", "command_address", "trainerbattle_kind",
    }
    if not consumer_rows or not required_fields.issubset(consumer_rows[0]):
        _fail("trainer runtime consumer schema不正")
    battle_rows = serialized.get("battle_rows")
    if not isinstance(battle_rows, list) or len(battle_rows) != 1302:
        _fail("serialized trainerbattle inventory不一致")
    battle_by_key: dict[str, Mapping[str, Any]] = {}
    for index, row in enumerate(battle_rows):
        if not isinstance(row, Mapping):
            _fail(f"serialized trainerbattle row不正:{index}")
        key = str(row.get("encounter_key", ""))
        if not key or key in battle_by_key:
            _fail(f"serialized trainerbattle encounter重複:{key}")
        battle_by_key[key] = row

    canonical = [
        row for row in consumer_rows if row["binding_mode"] == "CANONICAL"
    ]
    if len(canonical) != 1030:
        _fail(f"canonical Vega trainer count不一致: {len(canonical)}")
    additional = [
        row for row in consumer_rows if row["binding_mode"] != "CANONICAL"
    ]
    additional_mode_counts = Counter(
        row["binding_mode"] for row in additional
    )
    if additional_mode_counts != {"ARCHIVE": 71, "KANTO_NEW": 201}:
        _fail(
            "additional trainer binding inventory不一致: "
            f"{dict(additional_mode_counts)}"
        )
    additional_command_ranges: list[tuple[int, int]] = []
    additional_validations: list[dict[str, Any]] = []
    for consumer in additional:
        key = consumer["encounter_key"]
        serialized_row = battle_by_key.get(key)
        kind = int(consumer["trainerbattle_kind"])
        size = TRAINERBATTLE_SIZES.get(kind)
        if serialized_row is None or size is None \
                or serialized_row.get("binding_mode") \
                    != consumer["binding_mode"] \
                or int(serialized_row["kind"]) != kind:
            _fail(f"additional trainer serialized binding不一致:{key}")
        command = int(serialized_row["command_address"])
        offset = _rom_offset(command, size, f"additional trainer {key}")
        raw = stage60[offset:offset + size]
        if raw[:2] != bytes((0x5C, kind)) \
                or struct.unpack_from("<H", raw, 2)[0] \
                    != int(consumer["runtime_trainer_id"]):
            _fail(f"additional trainer command identity不一致:{key}")
        additional_command_ranges.append((command, command + size))
        additional_validations.append({
            "encounter_key": key,
            "command_address": command,
            "expected_command": raw,
        })
    patches: list[dict[str, Any]] = []
    validations: list[dict[str, Any]] = []
    role_changes: Counter[str] = Counter()
    kind_counts: Counter[int] = Counter()
    proxy_delta_counts: Counter[int] = Counter()
    proxy_shape_counts: Counter[str] = Counter()
    original_text_assets: dict[int, str] = {}
    changed_encounters = 0
    unchanged_encounters = 0
    proxy_bypass_count = 0
    split_continuation_count = 0
    restored_split_continuation_count = 0
    generic_post_pointers: set[int] = set()
    route501: dict[str, Any] | None = None

    for consumer in sorted(
        canonical, key=lambda row: int(row["command_address"], 0)
    ):
        key = consumer["encounter_key"]
        serialized_row = battle_by_key.get(key)
        if serialized_row is None \
                or serialized_row.get("binding_mode") != "CANONICAL":
            _fail(f"canonical trainer serialized binding不一致:{key}")
        original_command = int(consumer["command_address"], 0)
        current_command = int(serialized_row["command_address"])
        kind = int(consumer["trainerbattle_kind"])
        roles = TRAINERBATTLE_POINTER_ROLES.get(kind)
        size = TRAINERBATTLE_SIZES.get(kind)
        runtime_trainer_id = int(consumer["runtime_trainer_id"])
        source_trainer_id = int(consumer["source_trainer_id"])
        if roles is None or size is None \
                or int(serialized_row["kind"]) != kind \
                or int(serialized_row["target_trainer_id"]) \
                    != runtime_trainer_id:
            _fail(f"canonical trainer identity不一致:{key}")
        original_offset = _rom_offset(
            original_command, size, f"Vega original trainer command {key}"
        )
        current_offset = _rom_offset(
            current_command, size, f"Stage60 trainer command {key}"
        )
        if original_offset + size > len(vega_reference):
            _fail(f"Vega original trainer command範囲外:{key}")
        original_raw = vega_reference[
            original_offset:original_offset + size
        ]
        current_raw = stage60[current_offset:current_offset + size]
        if original_raw[:2] != bytes((0x5C, kind)) \
                or current_raw[:2] != bytes((0x5C, kind)) \
                or struct.unpack_from("<H", original_raw, 2)[0] \
                    != source_trainer_id \
                or struct.unpack_from("<H", current_raw, 2)[0] \
                    != runtime_trainer_id:
            _fail(f"canonical trainer command header不一致:{key}")

        original_pointers = {
            role: struct.unpack_from("<I", original_raw, 6 + index * 4)[0]
            for index, role in enumerate(roles)
        }
        current_pointers = {
            role: struct.unpack_from("<I", current_raw, 6 + index * 4)[0]
            for index, role in enumerate(roles)
        }
        replacement_raw = bytearray(current_raw)
        changed_roles: list[str] = []
        for index, role in enumerate(roles):
            pointer = original_pointers[role]
            if role != "continuation":
                if not GBA_BASE <= pointer < GBA_BASE + len(vega_reference):
                    _fail(f"Vega trainer text pointer範囲外:{key}/{role}")
                text_raw = _read_text(
                    vega_reference, pointer,
                    f"Vega original trainer text {key}/{role}",
                )
                stage60_text_raw = _read_text(
                    stage60, pointer,
                    f"Stage60 Vega trainer text {key}/{role}",
                )
                if text_raw == b"\xFF":
                    _fail(f"Vega original trainer textがEOS-only:{key}/{role}")
                if stage60_text_raw != text_raw:
                    _fail(f"Vega trainer text Stage60実体不一致:{key}/{role}")
                digest = _sha(text_raw)
                previous = original_text_assets.setdefault(pointer, digest)
                if previous != digest:
                    _fail(f"Vega trainer text provenance競合:{pointer:#010x}")
            elif not GBA_BASE <= pointer < GBA_BASE + len(vega_reference):
                _fail(f"Vega trainer continuation範囲外:{key}")
            struct.pack_into("<I", replacement_raw, 6 + index * 4, pointer)
            if current_pointers[role] != pointer:
                changed_roles.append(role)
                role_changes[role] += 1

        site_raw = stage60[original_offset:original_offset + 5]
        if site_raw[:1] != b"\x05":
            _fail(f"Stage60 physical trainer redirect不一致:{key}")
        proxy_root = struct.unpack_from("<I", site_raw, 1)[0]
        proxy_delta = current_command - proxy_root
        if proxy_delta not in {0, 8, 35}:
            _fail(f"Stage60 trainer proxy layout不一致:{key}/{proxy_delta}")
        proxy_delta_counts[proxy_delta] += 1
        kind_counts[kind] += 1

        post_address = current_command + size
        post_offset = _rom_offset(post_address, 13, f"trainer post {key}")
        post_raw = stage60[post_offset:post_offset + 13]
        generic_post = (
            post_raw[:2] == b"\x0F\x00"
            and post_raw[6:9] == b"\x09\x04\x05"
        )
        victory_next = original_pointers.get(
            "continuation", original_command + size
        )
        already_fought_next = original_command + size
        if victory_next != already_fought_next:
            split_continuation_count += 1
        direct_post = (
            post_raw[:1] == b"\x05"
            and struct.unpack_from("<I", post_raw, 1)[0]
                == already_fought_next
            and post_raw[5:] == b"\xFF" * 8
        )
        changed = bool(changed_roles)
        if changed and (
            not generic_post
            or struct.unpack_from("<I", post_raw, 9)[0] != victory_next
        ):
            _fail(f"trainer generic dialogue ownership不一致:{key}")
        if not changed and not direct_post:
            _fail(f"trainer original post edge不一致:{key}")

        generic_intro_proxy = False
        if proxy_delta:
            proxy_offset = _rom_offset(
                proxy_root, proxy_delta, f"trainer dialogue proxy {key}"
            )
            proxy_raw = stage60[proxy_offset:proxy_offset + proxy_delta]
            direct_bypass = (
                proxy_raw[:1] == b"\x05"
                and struct.unpack_from("<I", proxy_raw, 1)[0]
                    == current_command
                and proxy_raw[5:] == b"\xFF" * (proxy_delta - 5)
            )
            external_intro = (
                proxy_delta == 8
                and proxy_raw[:2] == b"\x0F\x00"
                and proxy_raw[6:8] == b"\x09\x04"
                and GBA_BASE <= struct.unpack_from("<I", proxy_raw, 2)[0]
                    < GBA_BASE + len(stage60)
            )
            normal_rematch_intro = (
                proxy_delta == 35
                and proxy_raw[0] == 0x2B
                and proxy_raw[3:5] == b"\x06\x01"
                and proxy_raw[9:11] == b"\x0F\x00"
                and proxy_raw[15:18] == b"\x09\x04\x05"
                and struct.unpack_from("<I", proxy_raw, 18)[0]
                    == current_command
                and proxy_raw[22:24] == b"\x0F\x00"
                and proxy_raw[28:31] == b"\x09\x04\x05"
                and struct.unpack_from("<I", proxy_raw, 31)[0]
                    == current_command
            )
            if direct_bypass:
                proxy_shape_counts[f"{proxy_delta}_direct_bypass"] += 1
            elif external_intro or normal_rematch_intro:
                generic_intro_proxy = True
                proxy_shape_counts[
                    f"{proxy_delta}_generated_intro"
                ] += 1
                patches.append({
                    "entry_kind": "generic_intro_proxy_bypass",
                    "encounter_key": key,
                    "address": proxy_root,
                    "expected": proxy_raw[:5],
                    "replacement": (
                        b"\x05" + struct.pack("<I", current_command)
                    ),
                    "kind": kind,
                    "runtime_trainer_id": runtime_trainer_id,
                    "source_trainer_id": source_trainer_id,
                    "proxy_size": proxy_delta,
                })
                proxy_bypass_count += 1
            else:
                _fail(f"trainer dialogue proxy形状不一致:{key}")
        if generic_intro_proxy != changed and proxy_delta in {8, 35}:
            _fail(f"trainer intro proxy ownership不一致:{key}")
        if not changed:
            unchanged_encounters += 1
            validations.append({
                "encounter_key": key,
                "command_address": current_command,
                "expected_command": current_raw,
                "pointer_roles": original_pointers,
            })
            continue

        changed_encounters += 1
        generic_post_pointers.add(struct.unpack_from("<I", post_raw, 2)[0])
        if victory_next != already_fought_next:
            restored_split_continuation_count += 1

        patches.extend((
            {
                "entry_kind": "trainerbattle_original_pointer_set",
                "encounter_key": key,
                "address": current_command,
                "expected": current_raw,
                "replacement": bytes(replacement_raw),
                "kind": kind,
                "runtime_trainer_id": runtime_trainer_id,
                "source_trainer_id": source_trainer_id,
                "changed_roles": changed_roles,
            },
            {
                "entry_kind": "generic_post_bypass",
                "encounter_key": key,
                "address": post_address,
                "expected": post_raw[:5],
                "replacement": (
                    b"\x05" + struct.pack("<I", already_fought_next)
                ),
                "kind": kind,
                "runtime_trainer_id": runtime_trainer_id,
                "source_trainer_id": source_trainer_id,
                "victory_next": victory_next,
                "already_fought_next": already_fought_next,
            },
        ))
        validations.append({
            "encounter_key": key,
            "command_address": current_command,
            "expected_command": bytes(replacement_raw),
            "pointer_roles": original_pointers,
        })
        if original_command == 0x08E03080:
            route501 = {
                "encounter_key": key,
                "original_command_address": f"0x{original_command:08X}",
                "generated_command_address": f"0x{current_command:08X}",
                "runtime_trainer_id": runtime_trainer_id,
                "source_trainer_id": source_trainer_id,
                "restored_roles": changed_roles,
                "original_command_sha256": _sha(original_raw),
            }

    expected_roles = {
        "continuation": 20,
        "defeat": 855,
        "intro": 834,
        "not_enough": 60,
    }
    if changed_encounters != 855 or unchanged_encounters != 175 \
            or proxy_bypass_count != 499 \
            or dict(sorted(role_changes.items())) != expected_roles \
            or dict(sorted(proxy_shape_counts.items())) != {
                "35_direct_bypass": 3,
                "35_generated_intro": 478,
                "8_direct_bypass": 150,
                "8_generated_intro": 21,
            } \
            or split_continuation_count != 30 \
            or restored_split_continuation_count != 20 \
            or generic_post_pointers != {0x09364546} \
            or route501 is None:
        _fail(
            "Vega trainer dialogue restore inventory不一致: "
            f"changed={changed_encounters}, unchanged={unchanged_encounters}, "
            f"proxy={proxy_bypass_count}, roles={dict(role_changes)}"
        )
    patch_ranges = sorted(
        (int(row["address"]), int(row["address"]) + len(row["expected"]))
        for row in patches
    )
    if len(patch_ranges) != len(set(patch_ranges)) or any(
        right_start < left_end
        for (_left_start, left_end), (right_start, _right_end)
        in zip(patch_ranges, patch_ranges[1:])
    ):
        _fail("Vega trainer dialogue restore patch range重複")
    if any(
        patch_start < additional_end
        and additional_start < patch_end
        for patch_start, patch_end in patch_ranges
        for additional_start, additional_end in additional_command_ranges
    ):
        _fail("Vega trainer dialogue patchがadditional trainerと重複")
    patch_projection = [
        {
            "encounter_key": row["encounter_key"],
            "entry_kind": row["entry_kind"],
            "address": f"0x{int(row['address']):08X}",
            "expected_sha256": _sha(bytes(row["expected"])),
            "replacement_sha256": _sha(bytes(row["replacement"])),
        }
        for row in patches
    ]
    report = {
        "status": "PASS",
        "policy": "VEGA_ORIGINAL_DIALOGUE_KEEP_CHANGEKIT_PARTIES",
        "canonical_vega_trainer_count": len(canonical),
        "restored_encounter_count": changed_encounters,
        "already_original_encounter_count": unchanged_encounters,
        "additional_trainer_count_untouched": len(additional),
        "additional_trainer_mode_counts": dict(sorted(
            additional_mode_counts.items()
        )),
        "generic_intro_proxy_bypass_count": proxy_bypass_count,
        "restored_pointer_count": sum(role_changes.values()),
        "restored_role_counts": dict(sorted(role_changes.items())),
        "explicit_victory_continuation_count": split_continuation_count,
        "restored_split_victory_and_already_fought_edge_count": (
            restored_split_continuation_count
        ),
        "trainerbattle_kind_counts": dict(sorted(kind_counts.items())),
        "proxy_delta_counts": {
            str(key): value for key, value in sorted(proxy_delta_counts.items())
        },
        "proxy_shape_counts": dict(sorted(proxy_shape_counts.items())),
        "original_text_asset_count": len(original_text_assets),
        "patch_count": len(patches),
        "patch_projection_sha256": _sha(_stable(patch_projection)),
        "serialized_path": str(TRAINER_SERIALIZED_PATH),
        "serialized_sha256": TRAINER_SERIALIZED_SHA256,
        "consumer_sha256": _sha(consumers_raw),
        "vega_reference_sha256": _sha(vega_reference),
        "route501_regression": route501,
        "assertions": {
            "trainerbattle_opcode_mode_id_and_flags_preserved": True,
            "all_visible_and_continuation_pointers_from_vega_reference": True,
            "generated_generic_intro_and_post_bypassed": True,
            "victory_and_already_fought_edges_distinguished": True,
            "kanto_and_archive_trainers_untouched": True,
        },
    }
    text_validations = [
        {
            "pointer": pointer,
            "expected_text": _read_text(
                vega_reference, pointer, "Vega trainer text final validation"
            ),
        }
        for pointer in sorted(original_text_assets)
    ]
    return {
        "report": report,
        "patches": patches,
        "validations": validations,
        "text_validations": text_validations,
        "additional_validations": additional_validations,
    }


def _wild_overlay_rate_plan(stage60: bytes, policy_raw: bytes) -> dict[str, Any]:
    """Derive normal-layer rates from each location's added-species count."""

    try:
        policy = json.loads(policy_raw)
    except json.JSONDecodeError as exc:
        _fail(f"wild overlay rate policy JSON不正: {exc}")
    if not isinstance(policy, Mapping) \
            or policy.get("schema_version") != 1 \
            or policy.get("stage") != STAGE \
            or policy.get("policy_id") \
                != "LOCATION_CANDIDATE_COUNT_DEFAULT_V1" \
            or policy.get("preserve_non_normal_layers") is not True:
        _fail("wild overlay rate policy schema不一致")
    table = policy.get("table")
    rules = policy.get("rates_by_candidate_count")
    if not isinstance(table, Mapping) or not isinstance(rules, list):
        _fail("wild overlay rate policy table/rules不正")
    address = int(str(table.get("address")), 0)
    entry_size = int(table.get("entry_size", 0))
    entry_count = int(table.get("entry_count", 0))
    table_size = int(table.get("size", 0))
    if entry_size != 104 or entry_count != 95 \
            or table_size != entry_size * entry_count:
        _fail("wild overlay table shape不一致")
    table_offset = _rom_offset(address, table_size, "wild overlay table")
    table_raw = stage60[table_offset:table_offset + table_size]
    if _sha(table_raw) != table.get("stage60_sha256"):
        _fail("wild overlay Stage60 table SHA-256不一致")
    normalized_rules: list[tuple[int, int, int]] = []
    for index, row in enumerate(rules):
        if not isinstance(row, Mapping):
            _fail(f"wild overlay rate rule不正:{index}")
        lower = int(row.get("min_inclusive", 0))
        upper = int(row.get("max_inclusive", 0))
        rate = int(row.get("rate_percent", 0))
        if not 1 <= lower <= upper <= 12 or not 1 <= rate <= 100:
            _fail(f"wild overlay rate rule range不正:{index}")
        normalized_rules.append((lower, upper, rate))
    coverage = {
        candidate_count: [
            rate for lower, upper, rate in normalized_rules
            if lower <= candidate_count <= upper
        ]
        for candidate_count in range(1, 13)
    }
    if any(len(values) != 1 for values in coverage.values()):
        _fail("wild overlay candidate-count policyにgap/overlapがあります")

    normal_layer = int(policy.get("normal_layer", -1))
    patches: list[dict[str, Any]] = []
    normal_rows: list[dict[str, Any]] = []
    before_counts: Counter[int] = Counter()
    after_counts: Counter[int] = Counter()
    layer_counts: Counter[int] = Counter()
    simulated = bytearray(table_raw)
    seen_keys: set[tuple[int, int, int, int]] = set()
    selection_thresholds: dict[tuple[int, int, int], dict[int, int]] = (
        defaultdict(dict)
    )
    for index in range(entry_count):
        relative = index * entry_size
        raw = table_raw[relative:relative + entry_size]
        group, map_number, area, layer = raw[:4]
        threshold, candidate_count, rate, reserved = raw[4:8]
        key = (group, map_number, area, layer)
        if key in seen_keys or reserved != 0 \
                or not 1 <= candidate_count <= 12 \
                or threshold != min(255, (rate * 256 + 50) // 100):
            _fail(f"wild overlay table row不正:{index}/{key}")
        seen_keys.add(key)
        candidates = struct.unpack_from(
            f"<{candidate_count}H", raw, 8
        )
        if not candidates or any(value == 0 for value in candidates):
            _fail(f"wild overlay candidate不正:{index}/{key}")
        layer_counts[layer] += 1
        selection_thresholds[(group, map_number, area)][layer] = threshold
        if layer != normal_layer:
            continue
        if len(set(raw[80:80 + candidate_count])) != 1 \
                or len(set(raw[92:92 + candidate_count])) != 1:
            _fail(f"wild overlay normal candidate unlock不統一:{index}/{key}")
        target_rate = coverage[candidate_count][0]
        target_threshold = min(255, (target_rate * 256 + 50) // 100)
        selection_thresholds[(group, map_number, area)][
            normal_layer
        ] = target_threshold
        expected = raw[4:8]
        replacement = bytes((
            target_threshold, candidate_count, target_rate, reserved,
        ))
        before_counts[rate] += 1
        after_counts[target_rate] += 1
        normal_rows.append({
            "index": index,
            "group": group,
            "map": map_number,
            "area": area,
            "candidate_count": candidate_count,
            "before_rate_percent": rate,
            "after_rate_percent": target_rate,
            "after_threshold": target_threshold,
        })
        if expected != replacement:
            patches.append({
                "entry_kind": "normal_layer_rate",
                "index": index,
                "address": address + relative + 4,
                "expected": expected,
                "replacement": replacement,
                "group": group,
                "map": map_number,
                "area": area,
                "candidate_count": candidate_count,
                "before_rate_percent": rate,
                "after_rate_percent": target_rate,
            })
            simulated[relative + 4:relative + 8] = replacement
    expected_layer_counts = {0: 48, 1: 3, 2: 13, 3: 9, 4: 8, 5: 14}
    changed_offsets = [
        index for index, (before, after) in enumerate(zip(table_raw, simulated))
        if before != after
    ]
    special_rows_preserved = all(
        table_raw[index * entry_size:(index + 1) * entry_size]
        == simulated[index * entry_size:(index + 1) * entry_size]
        for index in range(entry_count)
        if table_raw[index * entry_size + 3] != normal_layer
    )
    if len(normal_rows) != int(policy.get("normal_entry_count", -1)) \
            or len(patches) != len(normal_rows) \
            or dict(sorted(after_counts.items())) \
                != {20: 19, 30: 11, 40: 6, 50: 12} \
            or dict(sorted(layer_counts.items())) != expected_layer_counts \
            or len(changed_offsets) != 96 \
            or {offset % entry_size for offset in changed_offsets} != {4, 6} \
            or not special_rows_preserved:
        _fail(
            "wild overlay normal-layer inventory不一致: "
            f"rows={len(normal_rows)}, patches={len(patches)}, "
            f"rates={dict(after_counts)}"
        )
    route501 = next((
        row for row in normal_rows
        if (row["group"], row["map"], row["area"]) == (3, 19, 0)
    ), None)
    if route501 is None or route501["candidate_count"] != 8 \
            or route501["after_rate_percent"] != 50:
        _fail("T501 wild overlay policy regression不一致")
    # AUTO mode tries an active swarm, then day/night, then normal.  Guard the
    # most crowded possible location so the native Vega table always retains
    # at least one third of encounters even when all optional layers align.
    composed: list[tuple[float, tuple[int, int, int], int]] = []
    for location, layers in selection_thresholds.items():
        for phase_layer in (1, 2):
            miss = 1.0
            for layer in (3, phase_layer, normal_layer):
                if layer in layers:
                    miss *= 1.0 - layers[layer] / 256.0
            composed.append((1.0 - miss, location, phase_layer))
    max_composed, max_location, max_phase = max(composed)
    route501_layers = selection_thresholds[(3, 19, 0)]
    route501_miss = 1.0
    for layer in (3, normal_layer):
        if layer in route501_layers:
            route501_miss *= 1.0 - route501_layers[layer] / 256.0
    route501_composed = 1.0 - route501_miss
    if max_composed >= 2.0 / 3.0:
        _fail(f"wild overlay composed rate過大:{max_composed}")
    report = {
        "status": "PASS",
        "policy_id": policy["policy_id"],
        "policy_sha256": _sha(policy_raw),
        "table_address": f"0x{address:08X}",
        "entry_count": entry_count,
        "normal_entry_count": len(normal_rows),
        "non_normal_entry_count": entry_count - len(normal_rows),
        "patch_count": len(patches),
        "before_rate_counts": {
            str(key): value for key, value in sorted(before_counts.items())
        },
        "after_rate_counts": {
            str(key): value for key, value in sorted(after_counts.items())
        },
        "layer_counts": {
            str(key): value for key, value in sorted(layer_counts.items())
        },
        "stage60_table_sha256": _sha(table_raw),
        "stage61_table_sha256": _sha(bytes(simulated)),
        "normal_rows_sha256": _sha(_stable(normal_rows)),
        "route501_regression": route501,
        "route501_max_swarm_composed_percent": round(
            route501_composed * 100.0, 8
        ),
        "maximum_auto_composed": {
            "group": max_location[0],
            "map": max_location[1],
            "area": max_location[2],
            "phase_layer": max_phase,
            "overlay_percent": round(max_composed * 100.0, 8),
            "native_percent_floor": round((1.0 - max_composed) * 100.0, 8),
        },
        "actual_changed_byte_count": len(changed_offsets),
        "actual_changed_entry_offsets": [4, 6],
        "assertions": {
            "normal_rate_selected_by_location_candidate_count": True,
            "non_normal_day_night_swarm_fishing_hidden_rows_preserved": True,
            "candidate_species_and_order_preserved": True,
            "normal_candidate_unlocks_uniform_within_each_location": True,
            "maximum_auto_overlay_below_two_thirds": True,
        },
    }
    return {"report": report, "patches": patches}


def _add_runtime_event_repair_payloads(
    blob: _Blob, *, stage60: bytes, clean: bytes,
    namespace_policy: NamespacePolicy, charmap: Mapping[int, str],
    data_address: int,
) -> dict[str, Any]:
    """Materialize independent clean/authored repair assets into Stage61."""

    bag_text = _read_text(
        clean, BAG_FULL_TEXT_POINTER, "clean bag-full text", limit=0x100
    )
    if _sha(bag_text) != BAG_FULL_TEXT_SHA256:
        _fail("clean bag-full text provenance不一致")
    source_offset = _rom_offset(
        BAG_FULL_SOURCE_SCRIPT_POINTER, len(BAG_FULL_SOURCE_SCRIPT),
        "clean bag-full source script",
    )
    if clean[source_offset:source_offset + len(BAG_FULL_SOURCE_SCRIPT)] \
            != BAG_FULL_SOURCE_SCRIPT:
        _fail("clean EventScript_BagIsFull preimage不一致")
    bag_text_at = blob.add("event_repair::bag_full::text", bag_text, 1)
    bag_script = bytearray(BAG_FULL_SOURCE_SCRIPT)
    # The clean script's only pointer is the exact clean text at operand +2.
    bag_script[2:6] = b"\0\0\0\0"
    bag_script_at = blob.add(
        "event_repair::bag_full::script", bytes(bag_script), 4
    )
    blob.pointer(bag_script_at + 2, "event_repair::bag_full::text")

    route2_plan = _clean_route2_repair_plan(stage60, clean, charmap)
    route2_base = data_address + _align(len(blob.data), 4)
    route2_materialized = route2_plan.materialize(
        route2_base, namespace_policy
    )
    route2_at = blob.add(
        "event_repair::route2_clean_cfg",
        route2_materialized.payload,
        4,
    )
    if data_address + route2_at != route2_base:
        _fail("Route2 repair payload baseずれ")
    route2_text_relocations: list[dict[str, Any]] = []
    for asset in route2_plan.assets:
        if asset.kind not in {"TEXT", "BRAILLE"}:
            continue
        target = route2_materialized.asset_addresses.get(asset.key)
        if target is None:
            _fail("Route2 text asset materialization不足")
        target_offset = target - route2_base
        if route2_materialized.payload[
            target_offset:target_offset + len(asset.raw)
        ] != asset.raw:
            _fail("Route2 relocated text raw不一致")
        route2_text_relocations.append({
            "source_pointer": f"0x{asset.source_pointer:08X}",
            "target_pointer": f"0x{target:08X}",
            "raw_size": len(asset.raw),
            "raw_sha256": _sha(asset.raw),
            "source_rom": "CLEAN_FIRERED_REV0",
            "owner_source_roots": [
                f"0x{root:08X}" for root in sorted(asset.root_addresses)
            ],
        })
    if not route2_text_relocations:
        _fail("Route2 clean text relocation evidenceが空です")
    route2_graph = SemanticScriptGraph(clean)
    route2_graph.walk(root for root, _owner in ROUTE2_EMPTY_OWNER_ROOTS)
    if route2_graph.diagnostics:
        _fail(f"Route2 source closure diagnostics: {route2_graph.diagnostics}")
    route2_source_closures: dict[int, dict[str, Any]] = {}
    for root, owner in ROUTE2_EMPTY_OWNER_ROOTS:
        addresses = sorted(route2_graph.distances(root))
        instructions = [
            instruction
            for address in addresses
            for instruction in route2_graph.nodes[address].instructions
        ]
        raw = b"".join(instruction.raw for instruction in instructions)
        if not raw:
            _fail(f"Route2 source closureが空です: {root:#010x}")
        route2_source_closures[root] = {
            "source_root": f"0x{root:08X}",
            "owner_keys": [owner],
            "reachable_node_addresses": [
                f"0x{address:08X}" for address in addresses
            ],
            "reachable_instruction_sha256": _sha(raw),
            "source_rom": "CLEAN_FIRERED_REV0",
            "source_rom_sha256": _sha(clean),
        }

    trainer_plan = _trainer_intro_repair_plan(stage60)
    trainer_rows: list[dict[str, Any]] = []
    for source in trainer_plan["repairs"]:
        key = str(source["encounter_key"])
        label = f"event_repair::trainer_intro::{key}"
        rematch_label = f"{label}::rematch"
        common_label = f"{label}::common_post"
        command_raw = bytes(source["command_raw"])
        roles = TRAINERBATTLE_POINTER_ROLES[int(source["kind"])]
        data = bytearray((0x2B,))
        data.extend(struct.pack("<H", int(source["physical_flag"])))
        branch_offset = len(data)
        data.extend(b"\x06\x01\0\0\0\0")

        internal_fixups: list[tuple[int, str]] = [(branch_offset + 2, rematch_label)]

        def append_command(intro_pointer: int) -> int:
            start = len(data)
            cloned = bytearray(command_raw)
            for index, role in enumerate(roles):
                pointer_offset = 6 + index * 4
                if role == "intro":
                    struct.pack_into("<I", cloned, pointer_offset, intro_pointer)
                elif role == "continuation":
                    struct.pack_into("<I", cloned, pointer_offset, 0)
                    internal_fixups.append(
                        (start + pointer_offset, common_label)
                    )
            data.extend(cloned)
            goto_offset = len(data)
            data.extend(b"\x05\0\0\0\0")
            internal_fixups.append((goto_offset + 1, common_label))
            return start

        normal_offset = append_command(int(source["normal_text_pointer"]))
        rematch_offset = len(data)
        append_command(int(source["rematch_text_pointer"]))
        common_offset = len(data)
        data.extend(b"\x05" + struct.pack("<I", int(source["post_address"])))
        at = blob.add(label, bytes(data), 4)
        for alias, relative in (
            (rematch_label, rematch_offset),
            (common_label, common_offset),
        ):
            if alias in blob.labels:
                _fail(f"trainer repair payload label重複: {alias}")
            blob.labels[alias] = at + relative
        for relative, target in internal_fixups:
            blob.pointer(at + relative, target)
        adapter_address = data_address + at
        normal_command_address = adapter_address + normal_offset
        rematch_command_address = adapter_address + rematch_offset
        trainer_rows.append({
            **{
                key_name: value for key_name, value in source.items()
                if key_name not in {
                    "command_raw", "pointer_roles", "proxy_preimage"
                }
            },
            "adapter_label": label,
            "adapter_address": adapter_address,
            "adapter_size": len(data),
            "normal_command_offset": normal_offset,
            "rematch_command_offset": rematch_offset,
            "normal_command_address": normal_command_address,
            "normal_data_address": normal_command_address + 1,
            "rematch_command_address": rematch_command_address,
            "rematch_data_address": rematch_command_address + 1,
            "common_post_offset": common_offset,
            "proxy_root_expected_hex": bytes(source["proxy_preimage"])[:5].hex(),
            "command_expected_hex": command_raw[:5].hex(),
            "command_prefix_expected_hex": command_raw[:6].hex(),
            "intro_pointer_expected_hex": struct.pack(
                "<I", TRAINER_EMPTY_TEXT_POINTER
            ).hex(),
            "intro_pointer_replacement_hex": struct.pack(
                "<I", int(source["normal_text_pointer"])
            ).hex(),
            "entry_patch_count": 2,
        })

    rematch_source_by_data = {
        int(row["data_address"]): row
        for row in trainer_plan["rematch_rows"]
    }
    rematch_alias_rows: list[dict[str, Any]] = []
    for repair in trainer_rows:
        if int(repair["kind"]) not in {5, 7}:
            continue
        source_data_address = int(repair["source_data_address"])
        source = rematch_source_by_data.get(source_data_address)
        if source is None \
                or source["encounter_key"] != repair["encounter_key"] \
                or int(source["stock_trainer_id"]) \
                    != int(repair["source_trainer_id"]) \
                or int(source["target_trainer_id"]) \
                    != int(repair["rematch_target_trainer_id"]):
            _fail(
                "trainer rematch relocated/source tuple不一致:"
                f"{repair['encounter_key']}"
            )
        for branch, address_key in (
            ("NORMAL_INTRO", "normal_data_address"),
            ("REMATCH_INTRO", "rematch_data_address"),
        ):
            rematch_alias_rows.append({
                "data_address": int(repair[address_key]),
                "source_data_address": source_data_address,
                "stock_trainer_id": int(source["stock_trainer_id"]),
                "target_trainer_id": int(source["target_trainer_id"]),
                "trainerbattle_type": int(repair["kind"]),
                "encounter_key": str(repair["encounter_key"]),
                "intro_branch": branch,
            })
    rematch_alias_rows.sort(key=lambda row: int(row["data_address"]))
    if len(rematch_alias_rows) != TRAINER_REMATCH_ALIAS_EXPECTED_COUNT \
            or len({int(row["data_address"]) for row in rematch_alias_rows}) \
                != len(rematch_alias_rows):
        _fail(
            "trainer rematch relocated alias count/identity不一致:"
            f"{len(rematch_alias_rows)}"
        )
    rematch_alias_raw = b"".join(
        struct.pack(
            "<IHH", int(row["data_address"]),
            int(row["stock_trainer_id"]), int(row["target_trainer_id"]),
        )
        for row in rematch_alias_rows
    )
    return {
        "bag_full": {
            "source_text_pointer": BAG_FULL_TEXT_POINTER,
            "source_text_sha256": _sha(bag_text),
            "source_script_pointer": BAG_FULL_SOURCE_SCRIPT_POINTER,
            "source_script_sha256": _sha(BAG_FULL_SOURCE_SCRIPT),
            "adapter_address": data_address + bag_script_at,
            "adapter_size": len(bag_script),
            "branch_site_count": len(BAG_FULL_BRANCH_SITES),
        },
        "route2_empty_dialogue": {
            "owner_count": len(ROUTE2_EMPTY_OWNER_ROOTS),
            "owners": [owner for _root, owner in ROUTE2_EMPTY_OWNER_ROOTS],
            "source_roots": [root for root, _owner in ROUTE2_EMPTY_OWNER_ROOTS],
            "root_targets": {
                root: route2_materialized.root_entry(root)
                for root, _owner in ROUTE2_EMPTY_OWNER_ROOTS
            },
            "plan": route2_plan.to_report(),
            "materialization": route2_materialized.to_report(),
            "materialized_range": {
                "kind": "ROUTE2_CLEAN_FULL_CFG_PROXY",
                "target_base": f"0x{route2_base:08X}",
                "size": len(route2_materialized.payload),
                "sha256": _sha(route2_materialized.payload),
                "source_roots": [
                    f"0x{root:08X}"
                    for root, _owner in ROUTE2_EMPTY_OWNER_ROOTS
                ],
                "source_rom": "CLEAN_FIRERED_REV0",
                "source_rom_sha256": _sha(clean),
            },
            "source_closures": {
                f"0x{root:08X}": evidence
                for root, evidence in sorted(route2_source_closures.items())
            },
            "text_relocations": sorted(
                route2_text_relocations,
                key=lambda row: (row["source_pointer"], row["target_pointer"]),
            ),
        },
        "trainer_intro": {
            **{
                key: value for key, value in trainer_plan.items()
                if key not in {"repairs", "rematch_rows"}
            },
            "repair_count": len(trainer_rows),
            "entry_patch_count": 2 * len(trainer_rows),
            "repairs": trainer_rows,
            "rematch_alias_table": {
                # Installed only after every pre-existing Stage61 data label.
                # Keeping the raw private until _build_data_blob's final append
                # preserves all previously pinned semantic/event addresses.
                "address": None,
                "row_count": len(rematch_alias_rows),
                "row_size": TRAINER_REMATCH_ALIAS_ROW_SIZE,
                "size": len(rematch_alias_raw),
                "sha256": _sha(rematch_alias_raw),
                "rows_sha256": _mgba_oracle_canonical_sha256(
                    rematch_alias_rows
                ),
                "rows": rematch_alias_rows,
                "_raw": rematch_alias_raw,
                "relation": (
                    "RELOCATED_COMMAND_DATA_ADDRESS_TO_PINNED_CHANGEKIT_"
                    "REMATCH_TARGET"
                ),
            },
        },
        "invalid_callstd": {
            "site_count": len(INVALID_CALLSTD_SITES),
            "expected_hex": "0966",
            "replacement_hex": "6600",
            "semantic_replacement": "WAITMESSAGE_THEN_NOP",
        },
    }


def _gym_bg_defeat_dialogue_rows(
    raw: bytes,
    trainer_plan: Mapping[str, Any],
) -> dict[int, dict[str, Any]]:
    if _sha(raw) != GYM_BG_DIALOGUE_SHA256:
        _fail("gym BG defeat dialogue canonical CSV SHA-256 drift")
    try:
        rows = list(csv.DictReader(raw.decode("utf-8-sig").splitlines()))
    except (UnicodeDecodeError, csv.Error) as exc:
        _fail(f"gym BG dialogue CSV不正: {exc}")
    bindings = [
        row for row in trainer_plan.get("bindings", [])
        if isinstance(row, Mapping)
        and isinstance(row.get("trainer_id"), int)
        and int(row["trainer_id"]) in range(751, 759)
    ]
    if len(bindings) != 8 or {int(row["trainer_id"]) for row in bindings} \
            != set(range(751, 759)):
        _fail("gym BG trainer plan binding 751..758一意性不一致")
    text_assets = {
        str(row["text_key"]): row
        for row in trainer_plan.get("texts", [])
        if isinstance(row, Mapping) and isinstance(row.get("text_key"), str)
    }
    result: dict[int, dict[str, Any]] = {}
    for trainer_id in range(751, 759):
        binding = next(
            row for row in bindings if int(row["trainer_id"]) == trainer_id
        )
        encounter_key = str(binding["encounter_key"])
        text_keys = binding.get("text_keys")
        if not isinstance(text_keys, Mapping) \
                or not isinstance(text_keys.get("defeat"), str):
            _fail(f"gym BG defeat text key不足: trainer={trainer_id}")
        defeat_text_key = str(text_keys["defeat"])
        matches = [
            row for row in rows
            if row.get("encounter_key") == encounter_key
            and row.get("state_key") == "DEFEAT"
        ]
        if len(matches) != 1:
            _fail(f"gym BG defeat dialogue一意性不一致: {encounter_key}")
        row = matches[0]
        if (row.get("status"), row.get("width_check"), row.get("next_state")) \
                != ("READY_TO_SERIALIZE", "PASS", "END"):
            _fail(f"gym BG defeat dialogue status不正: {encounter_key}")
        normalized = normalize_dialogue_text(str(row["text"]))
        encoded = encode_dialogue_text(ROOT, normalized)
        serialized = text_assets.get(defeat_text_key)
        if not isinstance(serialized, Mapping) \
                or bytes.fromhex(str(serialized.get("data_hex", ""))) != encoded \
                or serialized.get("normalized_text") != normalized \
                or serialized.get("sha256") != _sha(encoded):
            _fail(
                f"gym BG defeat CSV/event-plan serialized text不一致: "
                f"trainer={trainer_id} key={defeat_text_key}"
            )
        if encoded == b"\xFF":
            _fail(f"gym BG defeat dialogueがEOS-onlyです: {encounter_key}")
        result[trainer_id] = {
            "trainer_id": trainer_id,
            "encounter_key": encounter_key,
            "dialogue_set_key": str(row["dialogue_set_key"]),
            "state_key": "DEFEAT",
            "text_key": defeat_text_key,
            "speaker": str(row["speaker"]),
            "source_text": str(row["text"]),
            "normalized_text": normalized,
            "encoded": encoded,
            "encoded_sha256": _sha(encoded),
            "source_path": str(GYM_BG_DIALOGUE_PATH),
            "source_sha256": GYM_BG_DIALOGUE_SHA256,
        }
    if set(result) != set(range(751, 759)):
        _fail("gym BG defeat trainer ID集合不一致")
    return result


def _build_data_blob(
    stage60: bytes, clean: bytes, canonical: Sequence[Mapping[str, Any]],
    sections: Sequence[Mapping[str, Any]], semantic: RelocationPlan,
    semantic_complete: RelocationPlan, full_cfg: FullCfgRelocationPlan,
    namespace_policy: NamespacePolicy,
    local_objects: LocalObjectNamespacePlan,
    object_visibility: ObjectVisibilityNamespacePlan,
    region: RegionMapPlan, graphics: GraphicsNamespacePlan,
    story: Mapping[str, Any], trainer_plan: Mapping[str, Any],
    trainer_dialogue_raw: bytes,
    map_script_projection: Mapping[str, Any], data_address: int,
) -> tuple[_Blob, dict[int, int], dict[str, Any]]:
    """全payloadを一つのaddress-aware blobへmaterializeする。

    source eventは会話一文への縮退を一切行わず、674 rootの全reachable
    CFG、TEXT、MOVEMENTをexact clean ROMから再配置する。5つの統合仕様root
    だけを明示adapterに置換する。Town Map/Fly dataとstock trampolineも同じ
    allocationに含め、全pointerのprovenanceを一箇所で確定する。
    """

    if data_address % 4:
        _fail(f"Stage61 data addressが4-byte境界ではありません: {data_address:#x}")
    blob = _Blob()

    charmap = load_charmap(ROOT / "vendor/upstream/CFRU-JP/charmap.tbl")
    name_rows: list[dict[str, Any]] = []
    for row in sections:
        source_id = int(row["source_map_section_id"])
        pointer_site = STOCK_MAP_NAMES - GBA_BASE + (source_id - 88) * 4
        pointer = _u32(clean, pointer_site, f"map name source {source_id}")
        raw = _read_text(clean, pointer, f"map name {source_id}", limit=128)
        decoded = decode_text(raw, charmap)
        if not decoded.usable_dialogue:
            _fail(f"map nameが可視文字列ではありません: source={source_id}")
        label = f"map_name::{int(row['runtime_map_section_id']):02d}"
        blob.add(label, raw, 1)
        name_rows.append({
            **dict(row), "source_pointer": pointer,
            "decoded_utf8": decoded.decoded_utf8,
            "raw_sha256": _sha(raw), "label": label,
        })
    table_at = blob.reserve("kanto_name_table", 53 * 4, 4)
    for row in name_rows:
        blob.pointer(table_at + int(row["runtime_map_section_id"]) * 4,
                     str(row["label"]))

    visit_flags = {
        requirement.runtime_id: 0x18E0 + index
        for index, requirement in enumerate(region.visit_flag_requirements)
    }
    region_payloads = [
        *region.payloads,
        region.materialize_visit_flag_payload(visit_flags),
    ]
    region_labels: dict[str, str] = {}
    runtime_macros: dict[str, int] = {
        "STAGE61_KANTO_NAME_TABLE": data_address + table_at,
        # The Stage61 wrapper is reached from the two stock callers, never by
        # overwriting this entry (which would make its own stock call recurse).
        "STAGE61_STOCK_HANDLE_SAVING_DATA": 0x080DB231,
    }
    for payload in region_payloads:
        label = f"region::{payload.name}"
        blob.add(label, payload.data, payload.alignment)
        region_labels[payload.name] = label
        runtime_macros[payload.macro] = data_address + blob.labels[label]

    quest_log_crosswalk = build_quest_log_physical_crosswalk(
        ROOT, stage60=stage60
    )
    quest_log_rows = quest_log_crosswalk["rows"]
    if len(quest_log_rows) != 51:
        _fail("Quest Log project inside/outside crosswalkが51行ではありません")
    quest_log_source_table = bytearray()
    quest_log_project_table = bytearray()
    for index, row in enumerate(quest_log_rows):
        if int(row["index"]) != index:
            _fail(f"Quest Log crosswalk index不連続: {row['index']} != {index}")
        for namespace, table in (
            ("source", quest_log_source_table),
            ("project", quest_log_project_table),
        ):
            inside = row[namespace]["inside"]
            outside = row[namespace]["outside"]
            values = (
                int(inside["group"]), int(inside["map"]),
                int(outside["group"]), int(outside["map"]),
                int(inside["section"]), int(outside["section"]),
            )
            if any(value < 0 or value > 0xFF for value in values):
                _fail(
                    "Quest Log crosswalk byte範囲外: "
                    f"namespace={namespace}, index={index}, values={values}"
                )
            table.extend(values)
    quest_log_source_at = blob.add(
        "map_section::quest_log_source_pairs",
        bytes(quest_log_source_table),
        1,
    )
    quest_log_project_at = blob.add(
        "map_section::quest_log_project_pairs",
        bytes(quest_log_project_table),
        1,
    )
    runtime_macros["STAGE61_QUEST_LOG_SOURCE_PAIRS"] = (
        data_address + quest_log_source_at
    )
    runtime_macros["STAGE61_QUEST_LOG_PROJECT_PAIRS"] = (
        data_address + quest_log_project_at
    )

    trampoline_labels: dict[str, str] = {}
    trampoline_macros = {
        "stock_get_mapsec_type": "STAGE61_STOCK_GET_MAPSEC_TYPE",
        "stock_get_dungeon_mapsec_type": "STAGE61_STOCK_GET_DUNGEON_MAPSEC_TYPE",
        "stock_get_player_position": "STAGE61_STOCK_GET_PLAYER_POSITION",
        "stock_get_selected_map_section": "STAGE61_STOCK_GET_SELECTED_MAP_SECTION",
    }
    trampoline_rows: list[dict[str, Any]] = []
    for spec in region.trampolines:
        label = f"trampoline::{spec.name}"
        address = data_address + _align(len(blob.data), 4)
        raw = materialize_trampoline(spec, address)
        at = blob.add(label, raw, 4)
        if data_address + at != address:
            _fail(f"stock trampoline配置ずれ: {spec.name}")
        trampoline_labels[spec.name] = label
        runtime_macros[trampoline_macros[spec.name]] = address | 1
        trampoline_rows.append({
            "name": spec.name,
            "address": address,
            "size": len(raw),
            "sha256": _sha(raw),
            "resume_address": spec.resume_address,
        })

    semantic_trampoline_macros = {
        "stock_get_map_preview_screen_idx": (
            "STAGE61_STOCK_GET_MAP_PREVIEW_SCREEN_IDX"
        ),
        "stock_get_dungeon_flavor_text": (
            "STAGE61_STOCK_GET_DUNGEON_FLAVOR_TEXT"
        ),
        "stock_get_dungeon_name": "STAGE61_STOCK_GET_DUNGEON_NAME",
    }
    for spec in MAP_SECTION_TRAMPOLINES:
        label = f"trampoline::{spec.name}"
        address = data_address + _align(len(blob.data), 4)
        raw = materialize_trampoline(spec, address)
        at = blob.add(label, raw, 4)
        if data_address + at != address:
            _fail(f"map-section stock trampoline配置ずれ: {spec.name}")
        trampoline_labels[spec.name] = label
        runtime_macros[semantic_trampoline_macros[spec.name]] = address | 1
        trampoline_rows.append({
            "name": spec.name,
            "address": address,
            "size": len(raw),
            "sha256": _sha(raw),
            "resume_address": spec.resume_address,
        })

    multichoice_base = data_address + _align(len(blob.data), 4)
    multichoice = materialize_multichoice_runtime_contract(
        clean, stage60, multichoice_base
    )
    multichoice_at = blob.add(
        "namespace::multichoice_runtime", multichoice.payload, 4
    )
    if data_address + multichoice_at != multichoice_base:
        _fail("multichoice materialization baseがblob配置と一致しません")

    graphics_base = data_address + _align(len(blob.data), 4)
    graphics_materialized = graphics.materialize(graphics_base)
    graphics_at = blob.add(
        "graphics::clean_kanto_closures", graphics_materialized.payload, 4
    )
    if data_address + graphics_at != graphics_base:
        _fail("graphics namespace materialization baseがblob配置と一致しません")
    snorlax_info = graphics_materialized.graphics_info_addresses.get(109)
    if snorlax_info is None:
        _fail("source graphics 109の完全closureがmaterializeされていません")
    extended = graphics.build_extended_graphics_table(
        graphics_materialized,
        reserved_graphics_pointers={int(story["snorlax_graphics_id"]): snorlax_info},
    )
    graphics_table_at = blob.add("object_graphics_table", extended, 4)
    graphics_table_address = data_address + graphics_table_at
    graphics_installation_patches = graphics.graphics_table_installation_patches(
        graphics_table_address
    )

    # MapScripts is an array of five-byte rows terminated by a zero tag.  This
    # single-byte table is project-owned and is used only to replace the two
    # invalid physical Vega pointers; it must never be inferred from a clean
    # map sharing the same numeric group/map.
    empty_map_script_at = blob.add(
        "event_repair::empty_project_map_script_table", b"\x00", 1
    )
    empty_map_script_address = data_address + empty_map_script_at

    custom_texts = {
        "text::snorlax_prompt": "ポケモンの ふえを\nつかいますか？",
        "text::snorlax_flute": "ポケモンの ふえを\nかなでた！",
        "text::snorlax_no_flute": "ポケモンの ふえが\nひつようだ。",
        "text::snorlax_asleep": "カビゴンは ぐっすり\nねむっている。",
        "text::fuji_not_owned": "ポケモンの ふえは\nトーホクで うけとれます。",
        "text::fuji_owned": "ふえの ねいろなら\nカビゴンも おきるでしょう。",
        "text::berry_rankings": "きろくは まだ\nありません。",
        "text::bill_sevii_unavailable": (
            "ナナシマへの こうろは\nいま じゅんびちゅうです。"
        ),
    }
    explicit_materialized_start = len(blob.data)
    explicit_text_rows: list[dict[str, Any]] = []
    builder_source_path = "scripts/build_stage61_display_npc_event_audit.py"
    builder_source_sha256 = _sha((ROOT / builder_source_path).read_bytes())
    for label, text in custom_texts.items():
        encoded = encode_dialogue_text(ROOT, text)
        at = blob.add(label, encoded, 1)
        explicit_text_rows.append({
            "target_pointer": f"0x{data_address + at:08X}",
            "raw_size": len(encoded),
            "raw_sha256": _sha(encoded),
            "semantic_contract": {
                "kind": "EXPLICIT_ADAPTER_TEXT",
                "meaning_id": label.removeprefix("text::").upper(),
                "authored_text_utf8": text,
                "authored_raw_hex": encoded.hex(),
                "authored_raw_sha256": _sha(encoded),
                "encoder": "tools.trainer_final.kanto_events.encode_dialogue_text",
                "source_path": builder_source_path,
                "source_sha256": builder_source_sha256,
                "effect_relation": (
                    "TRACKED_STAGE61_PROJECT_ADAPTER_DIALOGUE;"
                    "NOT_LEARNED_FROM_MGBA_OUTPUT"
                ),
            },
        })
    gym_bg_dialogues = _gym_bg_defeat_dialogue_rows(
        trainer_dialogue_raw, trainer_plan
    )
    for trainer_id, row in sorted(gym_bg_dialogues.items()):
        label = f"text::gym_bg_battle_defeat::{trainer_id:04d}"
        at = blob.add(label, bytes(row["encoded"]), 1)
        row["label"] = label
        row["address"] = data_address + at

    _add_route_snorlax_script(
        blob, "event_adapter::081769BB", local_id=15,
        hidden_flag=int(str(story["route12_hidden_flag"]), 0),
        flute_flag=int(str(story["tohoku_flute_flag"]), 0),
        species=int(story["canonical_snorlax_species"]),
    )
    _add_route_snorlax_script(
        blob, "event_adapter::08177A29", local_id=6,
        hidden_flag=int(str(story["route16_hidden_flag"]), 0),
        flute_flag=int(str(story["tohoku_flute_flag"]), 0),
        species=int(story["canonical_snorlax_species"]),
    )
    _add_fuji_script(
        blob, "event_adapter::08181B5D",
        int(str(story["tohoku_flute_flag"]), 0),
    )
    _add_berry_rankings_script(blob, "event_adapter::081817CC")
    bill_adapter_at, bill_adapter_size = _add_bill_sevii_scope_guard_script(
        blob, "event_adapter::08189851"
    )
    bill_sevii_scope_guard = _bill_sevii_scope_guard_contract(
        clean=clean,
        canonical=canonical,
        semantic=semantic,
        data_address=data_address,
        adapter_at=bill_adapter_at,
        adapter_size=bill_adapter_size,
        explicit_text_rows=explicit_text_rows,
    )
    explicit_materialized_end = len(blob.data)

    runtime_event_repairs = _add_runtime_event_repair_payloads(
        blob,
        stage60=stage60,
        clean=clean,
        namespace_policy=namespace_policy,
        charmap=charmap,
        data_address=data_address,
    )
    full_base = data_address + _align(len(blob.data), 4)
    materialized = full_cfg.materialize(full_base, namespace_policy)
    full_at = blob.add("semantic::full_cfg", materialized.payload, 4)
    if data_address + full_at != full_base:
        _fail("full CFG materialization baseがblob配置と一致しません")
    root_targets = {
        source: materialized.root_entry(source)
        for source in full_cfg.root_source_addresses
    }
    for pointer in EXPLICIT_ROOTS:
        label = f"event_adapter::{pointer:08X}"
        root_targets[pointer] = data_address + blob.labels[label]
    if set(root_targets) != set(full_cfg.root_source_addresses) | set(
        EXPLICIT_ROOTS
    ):
        _fail("全semantic rootのtargetが一意に解決されていません")

    def merge_projection_mapping(
        label: str,
        *sources: Mapping[int, int],
    ) -> dict[int, int]:
        merged: dict[int, int] = {}
        for source in sources:
            for source_id, target_id in source.items():
                previous = merged.get(int(source_id))
                if previous is not None and previous != int(target_id):
                    _fail(
                        f"map-script projection {label} mapping衝突: "
                        f"{int(source_id):#06x} {previous:#06x}/{int(target_id):#06x}"
                    )
                merged[int(source_id)] = int(target_id)
        return merged

    projection_flag_mapping = merge_projection_mapping(
        "flag",
        namespace_policy.mappings["flag"],
        namespace_policy.mappings["temp_flag"],
        STAGE61_KANTO_TOPOLOGY_FLAG_MAPPING,
    )
    projection_var_mapping = merge_projection_mapping(
        "var",
        namespace_policy.mappings["var"],
        STAGE61_KANTO_TOPOLOGY_VAR_MAPPING,
    )
    projection_base = data_address + _align(len(blob.data), 4)
    map_script_projection_materialized = materialize_projection(
        map_script_projection,
        payload_base=projection_base,
        flag_mapping=projection_flag_mapping,
        var_mapping=projection_var_mapping,
        # B3F/B4F require physical falling-boulder producers, reset latches,
        # coord events and object-array repair.  The dedicated topology owner
        # below materializes those two complete tables; generating the generic
        # A/B projection as well would create two competing pointer owners.
        delegated_maps={(97, 86), (97, 87)},
    )
    projection_raw = bytes.fromhex(
        str(map_script_projection_materialized["payload_raw_hex"])
    )
    if (
        len(projection_raw)
        != int(map_script_projection_materialized["payload_size"])
        or _sha(projection_raw)
        != str(map_script_projection_materialized["payload_sha256"])
    ):
        _fail("map-script projection payload raw/hash不一致")
    projection_at = blob.add(
        "map_script::safe_topology_projection", projection_raw, 4
    )
    if data_address + projection_at != projection_base:
        _fail("map-script projection baseがblob配置と一致しません")

    topology_contract = build_stage61_topology_producer_contract(
        clean, stage60,
    )
    if TOPOLOGY_STRENGTH_SOURCE_ROOT not in root_targets:
        _fail("topology producer用Strength semantic root targetがありません")
    topology_base = data_address + _align(len(blob.data), 4)
    topology_producer = materialize_stage61_topology_producer_state(
        topology_contract,
        clean,
        stage60,
        topology_base,
        root_targets={
            TOPOLOGY_STRENGTH_SOURCE_ROOT: root_targets[
                TOPOLOGY_STRENGTH_SOURCE_ROOT
            ]
        },
    )
    topology_at = blob.add(
        "topology::physical_producer_state",
        topology_producer.payload,
        4,
    )
    if data_address + topology_at != topology_base:
        _fail("topology producer baseがblob配置と一致しません")

    league_map_scripts = _materialize_project_league_map_scripts(
        blob,
        clean,
        stage60,
        map_script_projection["league_explicit_adapter_contract"],
        data_address,
    )

    projection_installation_patches: list[dict[str, Any]] = []
    layout_pointer_patch = map_script_projection_materialized[
        "layout_installation"
    ]["pointer_patch"]
    projection_installation_patches.append({
        "name": "safe_map_script_projection::gMapLayouts_root",
        "offset": int(str(layout_pointer_patch["address"]), 0) - GBA_BASE,
        "expected": struct.pack(
            "<I", int(str(layout_pointer_patch["expected_pointer"]), 0)
        ),
        "replacement": struct.pack(
            "<I", int(str(layout_pointer_patch["replacement_pointer"]), 0)
        ),
        "ownership": "PROJECT_OWNED_SAFE_LAYOUT_EXTENSION",
        "physical_map": None,
    })
    for map_row in map_script_projection_materialized["maps"]:
        pointer_patch = map_row["map_script_pointer_patch"]
        projection_installation_patches.append({
            "name": (
                "safe_map_script_projection::"
                f"{int(map_row['group']):03d}/{int(map_row['map']):03d}"
            ),
            "offset": int(str(pointer_patch["address"]), 0) - GBA_BASE,
            "expected": struct.pack(
                "<I", int(str(pointer_patch["expected_pointer"]), 0)
            ),
            "replacement": struct.pack(
                "<I", int(str(pointer_patch["replacement_pointer"]), 0)
            ),
            "ownership": "PROJECT_OWNED_SAFE_TOPOLOGY_PROJECTION",
            "physical_map": str(map_row["physical_map"]),
        })
    if (
        len(projection_installation_patches) != 32
        or len(league_map_scripts["patches"]) != 5
        or len(league_map_scripts["completion_patches"]) != 4
        or len(topology_producer.patches) != 26
    ):
        _fail("map-script projection/topology/League installation patch件数drift")

    missing_base = data_address + _align(len(blob.data), 4)
    missing_object = materialize_stage61_missing_object_templates(
        ROOT,
        local_objects,
        materialized,
        clean,
        stage60,
        missing_base,
        graphics_id_mapping={
            source_id: graphics.graphics_id_remap.get(source_id, source_id)
            for source_id in range(256)
        },
        visibility_flag_mapping=object_visibility.source_to_target,
    )
    missing_at = blob.add(
        "semantic::missing_silph_scope_object",
        missing_object.payload,
        4,
    )
    if data_address + missing_at != missing_base:
        _fail("missing object materialization baseがblob配置と一致しません")

    explicit_owner_ids = sorted({
        str(owner["owner_id"])
        for root in semantic.root_plans
        if root.source_script_pointer in EXPLICIT_ROOTS
        for owner in root.owners
    })
    explicit_source_roots = sorted(EXPLICIT_ROOTS)
    if explicit_owner_ids != [
        "BG:098/027:000",
        "OBJECT:096/023:014",
        "OBJECT:096/027:005",
        "OBJECT:098/030:000",
        "OBJECT:098/077:006",
    ]:
        _fail(f"explicit adapter owner集合drift: {explicit_owner_ids}")
    additional_materialized_range_specs = [
        {
            "kind": "EXPLICIT_PROJECT_ADAPTERS_AND_TRACKED_TEXT",
            # schema v1 consumers require one canonical source_root field;
            # source_roots is the complete fail-closed membership set.
            "source_root": f"0x{explicit_source_roots[0]:08X}",
            "source_roots": [
                f"0x{root:08X}" for root in explicit_source_roots
            ],
            "target_base": data_address + explicit_materialized_start,
            "offset": explicit_materialized_start,
            "size": explicit_materialized_end - explicit_materialized_start,
            "owner_ids": explicit_owner_ids,
            "provenance": (
                "TRACKED_STAGE61_EXPLICIT_ADAPTER_SOURCE_AND_CLEAN_ROOT_PLAN"
            ),
            "text_relocations": explicit_text_rows,
        },
        {
            "kind": "MISSING_SILPH_SCOPE_OBJECT_SCRIPT_CLOSURE",
            "source_root": "0x081663AC",
            "source_roots": ["0x081663AC"],
            "target_base": missing_object.script_address,
            "offset": missing_at,
            "size": len(missing_object.payload),
            "owner_ids": ["OBJECT:097/045:006"],
            "provenance": (
                "CLEAN_FIRERED_REV0_SCRIPT_PLUS_STAGE61_NAMESPACE_ADAPTER"
            ),
            "text_relocations": [],
        },
    ]

    rebased_object_patches: list[dict[str, Any]] = []

    def rebase_materialized_object_address(
        source_address: int,
    ) -> tuple[int | None, str | None]:
        candidates = [
            (topology_producer.rebase_object_address(source_address),
             "TOPOLOGY_PRODUCER"),
            (missing_object.rebase_object_address(source_address),
             "MISSING_SILPH_OBJECT"),
        ]
        resolved = [row for row in candidates if row[0] is not None]
        if len(resolved) > 1:
            _fail(
                "materialized object rebase owner衝突: "
                f"{source_address:#010x} {resolved}"
            )
        return resolved[0] if resolved else (None, None)

    def integrate_rebased_object_patch(
        source_address: int, expected: bytes, replacement: bytes, role: str,
    ) -> bool:
        target_address, rebase_owner = rebase_materialized_object_address(
            source_address
        )
        if target_address is None:
            return False
        target_offset = target_address - data_address
        actual = bytes(blob.data[target_offset:target_offset + len(expected)])
        already_materialized = actual == replacement
        if actual != expected and not already_materialized:
            _fail(
                f"materialized object rebase preimage不一致: {role} "
                f"{source_address:#010x}->{target_address:#010x} "
                f"{actual.hex()} != {expected.hex()}"
            )
        if not already_materialized:
            blob.data[
                target_offset:target_offset + len(replacement)
            ] = replacement
        rebased_object_patches.append({
            "role": role,
            "source_address": source_address,
            "target_address": target_address,
            "rebase_owner": rebase_owner,
            "already_materialized": already_materialized,
            "expected_hex": expected.hex(),
            "replacement_hex": replacement.hex(),
        })
        return True

    for root in semantic.root_plans:
        target = root_targets[root.source_script_pointer]
        for owner in root.owners:
            if str(owner["event"]) != "OBJECT":
                continue
            site = _owner_pointer_site(stage60, owner)
            integrate_rebased_object_patch(
                GBA_BASE + site,
                stage60[site:site + 4],
                struct.pack("<I", target),
                f"semantic_owner::{owner['owner_id']}",
            )
    for patch in graphics.object_patches:
        integrate_rebased_object_patch(
            GBA_BASE + patch.offset,
            patch.expected,
            patch.replacement,
            patch.name,
        )
    for visibility in object_visibility.owner_rows:
        source_flag = int(visibility["source_flag"])
        target_flag = (
            0 if source_flag == 0
            else int(object_visibility.source_to_target[source_flag])
        )
        expected_flag = int(visibility["target_flag_before"])
        if target_flag == expected_flag:
            continue
        integrate_rebased_object_patch(
            int(str(visibility["target_record"]), 0) + 20,
            struct.pack("<H", expected_flag),
            struct.pack("<H", target_flag),
            f"object_visibility::{visibility['owner_id']}",
        )
    if not rebased_object_patches:
        _fail("missing object arrayへrebaseされたpending patchがありません")

    resolution_rows: list[dict[str, Any]] = []
    for root in semantic_complete.root_plans:
        pointer = root.source_script_pointer
        if pointer in EXPLICIT_ROOTS:
            continue
        resolution_rows.append({
            "source_script_pointer": pointer,
            "target_script_pointer": root_targets[pointer],
            "source_cfg_class": root.source_cfg_class,
            "replacement_role": "PROJECT_FULL_CFG_SEMANTIC_RELOCATION",
            "suppressed_side_effect_classes": [],
            "preserved_side_effect_classes": list(root.side_effect_classes),
            "selected_text_pointer": (
                root.selected_text.source_pointer if root.selected_text else None
            ),
        })
    for pointer, role in EXPLICIT_ROOTS.items():
        is_bill_scope_adapter = pointer == 0x08189851
        resolution_rows.append({
            "source_script_pointer": pointer,
            "target_script_pointer": root_targets[pointer],
            "source_cfg_class": "EXPLICIT_PROJECT_ADAPTER",
            "replacement_role": role.upper(),
            "suppressed_side_effect_classes": (
                bill_sevii_scope_guard["product_contract"]
                ["suppressed_source_effect_classes"]
                if is_bill_scope_adapter else []
            ),
            "preserved_side_effect_classes": (
                bill_sevii_scope_guard["product_contract"]
                ["preserved_source_effect_classes"]
                if is_bill_scope_adapter else []
            ),
            "selected_text_pointer": (
                int(str(bill_sevii_scope_guard["product_contract"]
                        ["text_pointer"]), 0)
                if is_bill_scope_adapter else None
            ),
        })

    fly_rows = [{
        "runtime_map_section_id": row.runtime_id,
        "group": row.destination_group,
        "map": row.destination_map,
        "x": row.fly_x,
        "y": row.fly_y,
        "fly_enabled": row.fly_enabled,
        "visit_flag": visit_flags.get(row.runtime_id),
    } for row in region.sections]
    policy_audit = full_cfg.policy_audit(namespace_policy)
    if policy_audit["status"] != "PASS":
        _fail(f"full CFG namespace policy audit FAIL: {policy_audit}")
    semantic_materialization_report = materialized.to_report()
    strength_flag_sites = {
        0x081A48D0: ("READ", bytes.fromhex("2b0508")),
        0x081A4914: ("WRITE", bytes.fromhex("290508")),
    }
    strength_flag_rows: list[dict[str, Any]] = []
    for source_address, (access, expected) in sorted(
        strength_flag_sites.items()
    ):
        target_address = materialized.instruction_addresses.get(source_address)
        if target_address is None:
            _fail(
                "Strength engine system flag instructionがmaterializeされていません: "
                f"{source_address:#010x}"
            )
        target_offset = target_address - materialized.payload_base
        actual = materialized.payload[
            target_offset:target_offset + len(expected)
        ]
        if actual != expected:
            _fail(
                "Strength engine system flag 0x0805がidentityでmaterializeされて"
                "いません: "
                f"{source_address:#010x}->{target_address:#010x}:"
                f"{actual.hex()}!={expected.hex()}"
            )
        strength_flag_rows.append({
            "source_address": f"0x{source_address:08X}",
            "target_address": f"0x{target_address:08X}",
            "access": access,
            "flag_id": "0x0805",
            "raw_hex": expected.hex(),
        })
    semantic_materialization_report["engine_system_flag_identity"] = {
        "status": "PASS",
        "symbol": "FLAG_SYS_USE_STRENGTH",
        "flag_id": "0x0805",
        "former_invalid_shadow_target": "0x18B3",
        "sites": strength_flag_rows,
        "assertions": {
            "read_and_write_sites_exact": len(strength_flag_rows) == 2,
            "relocated_operands_remain_0x0805": all(
                row["raw_hex"].endswith("0508")
                for row in strength_flag_rows
            ),
        },
    }
    semantic_materialization_report["root_addresses"].update({
        f"0x{source:08X}": f"0x{target:08X}"
        for source, target in sorted(root_targets.items())
    })
    semantic_materialization_report["root_addresses"]["0x081663AC"] = (
        f"0x{missing_object.script_address:08X}"
    )
    materialized_text_addresses = {
        asset.source_pointer: materialized.asset_addresses[asset.key]
        for asset in full_cfg.assets
        if asset.kind in {"TEXT", "BRAILLE"}
        and asset.key in materialized.asset_addresses
    }
    primary_text_relocations: list[dict[str, Any]] = []
    for asset in semantic_complete.text_assets:
        target = materialized_text_addresses.get(asset.source_pointer)
        if target is None:
            continue
        offset = target - materialized.payload_base
        raw = asset.decoded.raw
        if materialized.payload[offset:offset + len(raw)] != raw:
            _fail(
                "full CFG text relocation raw不一致: "
                f"{asset.source_pointer:#010x}->{target:#010x}"
            )
        primary_text_relocations.append({
            "source_pointer": f"0x{asset.source_pointer:08X}",
            "target_pointer": f"0x{target:08X}",
            "raw_size": len(raw),
            "raw_sha256": _sha(raw),
        })
    if not primary_text_relocations:
        _fail("full CFG text relocation証跡が空です")
    semantic_materialization_report["text_relocations"] = sorted(
        primary_text_relocations,
        key=lambda row: (row["source_pointer"], row["target_pointer"]),
    )
    for row in name_rows:
        label = str(row["label"])
        if label not in blob.labels:
            _fail(f"Kanto map name label不足: {label}")
        row["materialized_pointer"] = data_address + blob.labels[label]

    # Append-only compatibility data: placing this after every historical
    # label keeps all semantic roots and their cyclic-decision byte pins at
    # exactly the pre-repair addresses.  Only the Stage61 code block moves.
    rematch_alias_table = runtime_event_repairs["trainer_intro"][
        "rematch_alias_table"
    ]
    rematch_alias_raw = rematch_alias_table.pop("_raw", None)
    if not isinstance(rematch_alias_raw, bytes) \
            or len(rematch_alias_raw) != rematch_alias_table["size"] \
            or _sha(rematch_alias_raw) != rematch_alias_table["sha256"]:
        _fail("trainer rematch alias deferred payload不一致")
    rematch_alias_at = blob.add(
        "event_repair::trainer_rematch_alias_table",
        rematch_alias_raw, 4,
    )
    rematch_alias_table["address"] = data_address + rematch_alias_at
    runtime_macros.update({
        "STAGE61_TRAINER_REMATCH_ALIAS_TABLE": int(
            rematch_alias_table["address"]
        ),
        "STAGE61_TRAINER_REMATCH_ALIAS_COUNT": int(
            rematch_alias_table["row_count"]
        ),
        "STAGE61_CHANGEKIT_GET_REMATCH": (
            TRAINER_CHANGEKIT_GET_REMATCH_ENTRY
        ),
    })

    return blob, root_targets, {
        "map_names": name_rows, "fly_destinations": fly_rows,
        "semantic_resolution": sorted(
            resolution_rows, key=lambda row: row["source_script_pointer"]
        ),
        "semantic_materialization": semantic_materialization_report,
        "additional_materialized_range_specs": (
            additional_materialized_range_specs
        ),
        "namespace_policy_audit": policy_audit,
        "bill_sevii_scope_guard": bill_sevii_scope_guard,
        "runtime_event_repairs": runtime_event_repairs,
        "map_script_projection_plan": map_script_projection,
        "map_script_projection_materialization": (
            map_script_projection_materialized
        ),
        "map_script_projection_patches": projection_installation_patches,
        "topology_producer_materialization": topology_producer,
        "topology_producer_report": {
            "contract": topology_contract.to_report(),
            "materialization": {
                key: value
                for key, value in topology_producer.to_report().items()
                if key != "payload_raw_hex"
            },
            "integrated_rebased_patches": [
                row for row in rebased_object_patches
                if row["rebase_owner"] == "TOPOLOGY_PRODUCER"
            ],
            "integrated_payload_sha256": _sha(bytes(
                blob.data[
                    topology_at:topology_at + len(topology_producer.payload)
                ]
            )),
        },
        "league_map_scripts": league_map_scripts,
        "empty_project_map_script_table": {
            "address": empty_map_script_address,
            "size": 1,
            "raw_hex": "00",
            "semantic_contract": "NO_MAP_SCRIPT_ROWS",
        },
        "gym_bg_battle_defeat_dialogues": [{
            key: value for key, value in row.items() if key != "encoded"
        } for _trainer_id, row in sorted(gym_bg_dialogues.items())],
        "multichoice_materialization": multichoice.to_report(),
        "multichoice_runtime_patches": multichoice.patches,
        "missing_object_materialization": missing_object,
        "missing_object_report": {
            **missing_object.to_report(),
            "integrated_rebased_patches": [
                row for row in rebased_object_patches
                if row["rebase_owner"] == "MISSING_SILPH_OBJECT"
            ],
            "integrated_payload_sha256": _sha(bytes(
                blob.data[missing_at:missing_at + len(missing_object.payload)]
            )),
        },
        "visit_flags": {
            str(section): flag for section, flag in sorted(visit_flags.items())
        },
        "region_payloads": [{
            "name": payload.name,
            "macro": payload.macro,
            "address": runtime_macros[payload.macro],
            "size": len(payload.data),
            "sha256": _sha(payload.data),
        } for payload in region_payloads],
        "region_trampolines": trampoline_rows,
        "quest_log_project_crosswalk": {
            "source_address": runtime_macros[
                "STAGE61_QUEST_LOG_SOURCE_PAIRS"
            ],
            "project_address": runtime_macros[
                "STAGE61_QUEST_LOG_PROJECT_PAIRS"
            ],
            "row_count": len(quest_log_rows),
            "row_size": 6,
            "source_sha256": _sha(bytes(quest_log_source_table)),
            "project_sha256": _sha(bytes(quest_log_project_table)),
            "canonical_sha256": quest_log_crosswalk["canonical_sha256"],
            "source_runtime_section_contract": quest_log_crosswalk[
                "source_runtime_section_contract"
            ],
            "special_case_rewrites": quest_log_crosswalk[
                "special_case_rewrites"
            ],
        },
        "runtime_macros": runtime_macros,
        "graphics_materialization": {
            **graphics.audit_dict(),
            "payload_address": graphics_materialized.load_address,
            "payload_size": len(graphics_materialized.payload),
            "payload_sha256": graphics_materialized.sha256,
            "pointer_fixup_count": graphics_materialized.fixup_count,
            "palette_table_address": graphics_materialized.palette_table_address,
            "palette_pointer_patches": [{
                "name": patch.name,
                "offset": patch.offset,
                "expected_hex": patch.expected.hex(),
                "replacement_hex": patch.replacement.hex(),
            } for patch in graphics_materialized.palette_pointer_patches],
            "graphics_table_address": graphics_table_address,
            "graphics_table_installation_patches": [{
                "name": patch.name,
                "offset": patch.offset,
                "expected_hex": patch.expected.hex(),
                "replacement_hex": patch.replacement.hex(),
            } for patch in graphics_installation_patches],
        },
        "graphics_palette_pointer_patches": (
            graphics_materialized.palette_pointer_patches
        ),
        "graphics_table_installation_patches": graphics_installation_patches,
        "snorlax_graphics": {
            "runtime_graphics_id": int(story["snorlax_graphics_id"]),
            "source_graphics_id": 109,
            "clean_closure_sha256": graphics.closure_signatures_clean[109].sha256,
            "graphics_info_address": snorlax_info,
            "complete_closure": True,
        },
    }


_RUNTIME_TOOL_ENVIRONMENT = {
    "LANG": "C",
    "LC_ALL": "C",
    "PATH": "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin",
    "SOURCE_DATE_EPOCH": "0",
}


def _runtime_tool_environment() -> dict[str, str]:
    # Allowlist-only: no ambient compiler/binutils/loader variable may alter
    # the product while escaping the provenance manifest.
    return dict(_RUNTIME_TOOL_ENVIRONMENT)


def _runtime_tool_environment_contract() -> dict[str, Any]:
    return {
        "policy": "ALLOWLIST_ONLY_NO_AMBIENT_INHERITANCE",
        "environment": dict(sorted(_runtime_tool_environment().items())),
    }


def _runtime_tool_raw_command(
    argv: Sequence[str], label: str, *, cwd: Path = ROOT,
) -> tuple[bytes, bytes]:
    try:
        result = subprocess.run(
            list(argv), cwd=cwd, capture_output=True, check=False,
            timeout=30, env=_runtime_tool_environment(),
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        _fail(f"Stage61 toolchain {label}実行失敗: {exc}")
    if result.returncode:
        detail = (result.stderr or result.stdout)[-8000:]
        _fail(
            f"Stage61 toolchain {label} failed ({result.returncode}): "
            f"{detail!r}"
        )
    return result.stdout, result.stderr


def _runtime_run(
    command: Sequence[str], label: str, *, timeout: int = 180,
) -> str:
    try:
        result = subprocess.run(
            list(command), cwd=ROOT, text=True, capture_output=True,
            check=False, timeout=timeout,
            env=_runtime_tool_environment(),
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        _fail(f"{label}実行失敗: {exc}")
    if result.returncode:
        detail = (result.stderr or result.stdout).strip()
        _fail(f"{label} failed ({result.returncode}): {detail[-8000:]}")
    return result.stdout.strip()


def _runtime_tool_file_identity(path: Path, label: str) -> dict[str, Any]:
    try:
        resolved = path.resolve(strict=True)
        raw = resolved.read_bytes()
    except OSError as exc:
        _fail(f"Stage61 toolchain {label} identity取得失敗: {exc}")
    if not resolved.is_file() or not raw:
        _fail(f"Stage61 toolchain {label}が非空file")
    return {
        "resolved_realpath": str(resolved),
        "binary_size": len(raw),
        "binary_sha256": _sha(raw),
    }


def _runtime_tool_identity(
    path: Path, label: str, *,
    version_arguments: Sequence[str] = ("--version",),
) -> dict[str, Any]:
    if not version_arguments or any(
        not isinstance(value, str) or not value for value in version_arguments
    ):
        _fail(f"Stage61 toolchain {label} version argv不正")
    identity = _runtime_tool_file_identity(path, label)
    # GCC's internal cc1 writes ``<stdin>.s`` when queried with
    # ``-version -quiet`` and no explicit input/output.  Every identity probe
    # is therefore isolated outside the workspace, including revalidation
    # after the compile temporary directory has already been removed.
    with tempfile.TemporaryDirectory(
        prefix="stage61-tool-identity-",
    ) as identity_directory:
        stdout, stderr = _runtime_tool_raw_command(
            [identity["resolved_realpath"], *version_arguments],
            f"{label} version", cwd=Path(identity_directory),
        )
    try:
        stdout_text = stdout.decode("utf-8")
        stderr_text = stderr.decode("utf-8")
    except UnicodeDecodeError as exc:
        _fail(f"Stage61 toolchain {label} versionがUTF-8でない: {exc}")
    if not stdout and not stderr:
        _fail(f"Stage61 toolchain {label} version出力空")
    identity["version"] = {
        "argv": [f"$TOOL:{label}", *version_arguments],
        "stdout_raw": stdout_text,
        "stdout_sha256": _sha(stdout),
        "stderr_raw": stderr_text,
        "stderr_sha256": _sha(stderr),
    }
    return identity


def _runtime_tool_query(
    tool: Mapping[str, Any], label: str, *arguments: str,
) -> dict[str, Any]:
    stdout, stderr = _runtime_tool_raw_command(
        [str(tool["resolved_realpath"]), *arguments], label,
    )
    try:
        stdout_text = stdout.decode("utf-8")
        stderr_text = stderr.decode("utf-8")
    except UnicodeDecodeError as exc:
        _fail(f"Stage61 toolchain {label}出力がUTF-8でない: {exc}")
    return {
        "argv": ["$TOOL:gcc", *arguments],
        "stdout_raw": stdout_text,
        "stdout_sha256": _sha(stdout),
        "stderr_raw": stderr_text,
        "stderr_sha256": _sha(stderr),
    }


_RUNTIME_GCC_QUERY_ARGUMENTS = {
    "assembler": ("-print-prog-name=as",),
    "cc1": ("-print-prog-name=cc1",),
    "collect2": ("-print-prog-name=collect2",),
    "dumpmachine": ("-dumpmachine",),
    "dumpspecs": ("-dumpspecs",),
    "include_directory": ("-print-file-name=include",),
    "ld": ("-print-prog-name=ld",),
    "libgcc": ("-print-libgcc-file-name",),
    "search_directories": ("-print-search-dirs",),
    "sysroot": ("-print-sysroot",),
}


def _runtime_compiler_queries(
    gcc: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    queries = {
        name: _runtime_tool_query(
            gcc, f"gcc {' '.join(arguments)}", *arguments,
        )
        for name, arguments in sorted(_RUNTIME_GCC_QUERY_ARGUMENTS.items())
    }
    if any(row["stderr_raw"] for row in queries.values()) \
            or queries["dumpmachine"]["stdout_raw"].strip() \
                != "arm-none-eabi" \
            or not queries["dumpspecs"]["stdout_raw"] \
            or not queries["search_directories"]["stdout_raw"]:
        _fail("Stage61 runtime compiler query不正/ABI外")
    return queries


def _runtime_resolve_compiler_path(
    gcc: Mapping[str, Any], raw: Any, label: str,
) -> Path:
    if not isinstance(raw, str) or not raw.strip():
        _fail(f"Stage61 runtime compiler {label} path query空")
    path = Path(raw.strip())
    if not path.is_absolute():
        path = Path(str(gcc["resolved_realpath"])).parent / path
    try:
        return path.resolve(strict=True)
    except OSError as exc:
        _fail(f"Stage61 runtime compiler {label} path解決失敗: {exc}")


def _runtime_dynamic_dependency_contract(
    executable: Path, label: str, resolver: Mapping[str, Any],
) -> dict[str, Any]:
    try:
        result = subprocess.run(
            [str(resolver["resolved_realpath"]), str(executable)],
            cwd=ROOT, capture_output=True, check=False, timeout=30,
            env=_runtime_tool_environment(),
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        _fail(f"Stage61 toolchain {label} ldd失敗: {exc}")
    try:
        stdout = result.stdout.decode("utf-8")
        stderr = result.stderr.decode("utf-8")
    except UnicodeDecodeError as exc:
        _fail(f"Stage61 toolchain {label} ldd出力がUTF-8でない: {exc}")
    if result.returncode:
        detail = (stderr or stdout).strip()
        if "not a dynamic executable" in detail \
                or "statically linked" in detail:
            contract = {
                "mode": "STATIC_ASSERTED_BY_LDD",
                "dependencies": [],
                "virtual_dependencies": [],
            }
            contract["closure_sha256"] = _sha(_stable(contract))
            return contract
        _fail(
            f"Stage61 toolchain {label} ldd failed "
            f"({result.returncode}): {detail[-8000:]}"
        )
    if stderr:
        _fail(f"Stage61 toolchain {label} ldd stderr非空")
    dependencies: dict[str, dict[str, Any]] = {}
    virtual: set[str] = set()
    for raw_line in stdout.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        soname: str
        target_text: str | None
        if "=>" in line:
            left, right = line.split("=>", 1)
            soname = left.strip()
            right = right.strip()
            if right.startswith("not found"):
                _fail(f"Stage61 toolchain {label} dependency未解決:{soname}")
            target_text = right.split(" (", 1)[0].strip()
        else:
            first = line.split(None, 1)[0]
            if first.startswith("/"):
                soname, target_text = Path(first).name, first
            else:
                virtual.add(first)
                continue
        try:
            target = Path(str(target_text)).resolve(strict=True)
        except OSError as exc:
            _fail(
                f"Stage61 toolchain {label} dependency path不正:"
                f"{target_text}:{exc}"
            )
        identity = _runtime_tool_file_identity(
            target, f"{label} dependency {soname}",
        )
        key = identity["resolved_realpath"]
        previous = dependencies.get(key)
        if previous is None:
            dependencies[key] = {"sonames": [soname], **identity}
        elif soname not in previous["sonames"]:
            previous["sonames"].append(soname)
            previous["sonames"].sort()
    if not dependencies:
        _fail(f"Stage61 toolchain {label} dynamic dependency closure空")
    contract = {
        "mode": "DYNAMIC_LDD_TRANSITIVE_CLOSURE",
        "dependencies": sorted(
            dependencies.values(),
            key=lambda row: str(row["resolved_realpath"]),
        ),
        "virtual_dependencies": sorted(virtual),
    }
    contract["closure_sha256"] = _sha(_stable(contract))
    return contract


def _runtime_preprocessor_dependency_manifest(
    gcc: Mapping[str, Any], canonical_compile: Sequence[str],
) -> dict[str, Any]:
    if len(canonical_compile) < 5 \
            or canonical_compile[-4] != "-c" \
            or not canonical_compile[-3].startswith("$WORKSPACE/") \
            or canonical_compile[-2:] != ["-o", "$BUILD/runtime.o"]:
        _fail("Stage61 runtime dependency scan compile argv不正")
    canonical_argv = [
        *canonical_compile[:-4], "-M", "-MT", "runtime.o",
        canonical_compile[-3],
    ]
    actual_argv = [
        str(gcc["resolved_realpath"])
        if value == "$TOOL:gcc" else
        str((ROOT / value[len("$WORKSPACE/"):]).resolve(strict=True))
        if value.startswith("$WORKSPACE/") else value
        for value in canonical_argv
    ]
    stdout, stderr = _runtime_tool_raw_command(
        actual_argv, "gcc preprocessor dependency scan",
    )
    try:
        stdout_text = stdout.decode("utf-8")
        stderr_text = stderr.decode("utf-8")
        flattened = stdout_text.replace("\\\n", " ")
        tokens = shlex.split(flattened, posix=True)
    except (UnicodeDecodeError, ValueError) as exc:
        _fail(f"Stage61 runtime dependency scan parse失敗: {exc}")
    if stderr_text or not tokens or tokens[0] != "runtime.o:":
        _fail("Stage61 runtime dependency scan出力不正")
    identities: dict[str, dict[str, Any]] = {}
    for index, raw_path in enumerate(tokens[1:]):
        try:
            path = Path(raw_path).resolve(strict=True)
        except OSError as exc:
            _fail(
                "Stage61 runtime dependency scan path不正:"
                f"{index}:{raw_path}:{exc}"
            )
        identity = _runtime_tool_file_identity(
            path, f"preprocessor dependency {index}",
        )
        identities[identity["resolved_realpath"]] = identity
    source_path = str((
        ROOT / canonical_compile[-3][len("$WORKSPACE/"):]
    ).resolve(strict=True))
    if source_path not in identities \
            or not any(Path(path).name == "stdint.h" for path in identities):
        _fail("Stage61 runtime dependency scan source/stdint.h欠落")
    files = sorted(
        identities.values(), key=lambda row: str(row["resolved_realpath"]),
    )
    manifest = {
        "argv_canonical": canonical_argv,
        "stdout_raw": stdout_text,
        "stdout_sha256": _sha(stdout),
        "stderr_raw": stderr_text,
        "stderr_sha256": _sha(stderr),
        "files": files,
    }
    manifest["dependency_manifest_sha256"] = _sha(_stable(manifest))
    return manifest


def _runtime_canonical_argv(
    argv: Sequence[str], replacements: Mapping[str, str],
    *, temp_directory: Path,
) -> list[str]:
    result: list[str] = []
    linker_prefix = "-Wl,-T,"
    for raw in argv:
        value = str(raw)
        if value in replacements:
            value = replacements[value]
        elif value.startswith(linker_prefix) \
                and value[len(linker_prefix):] in replacements:
            value = linker_prefix + replacements[value[len(linker_prefix):]]
        if str(temp_directory) in value:
            _fail("Stage61 toolchain canonical argvに一時path残留")
        result.append(value)
    return result


def _runtime_linker_script(load_address: int) -> str:
    if isinstance(load_address, bool) or not isinstance(load_address, int) \
            or not 0x08000000 <= load_address < 0x0A000000:
        _fail("Stage61 runtime linker load addressがROM範囲外")
    return (
        "SECTIONS\n{\n" f"  . = 0x{load_address:08X};\n"
        "  .text : { KEEP(*(.text.Stage61*)) "
        "*(.text*) *(.rodata*) *(.v4_bx) *(.glue_7) *(.glue_7t) }\n"
        f"  ASSERT(ADDR(.text) == 0x{load_address:08X}, "
        '"Stage61 .text VMA mismatch")\n'
        "  /DISCARD/ : { *(.comment*) *(.ARM.attributes*) *(.note*) "
        "*(.ARM.exidx*) *(.ARM.extab*) }\n}\n"
    )


def _runtime_toolchain_manifest(
    *, tools: Mapping[str, Path], source: Path, load_address: int,
    compile_argv: Sequence[str], link_argv: Sequence[str],
    post_link_argv: Mapping[str, Sequence[str]],
    linker_path: Path, linker_raw: bytes, object_path: Path,
    elf_path: Path, binary_path: Path, temp_directory: Path,
) -> dict[str, Any]:
    if set(tools) != {"gcc", "nm", "objcopy", "objdump"}:
        _fail("Stage61 runtime toolchain入力tool一覧不一致")
    identities = {
        name: _runtime_tool_identity(path, name)
        for name, path in sorted(tools.items())
    }
    gcc = identities["gcc"]
    queries = _runtime_compiler_queries(gcc)
    ld_path = _runtime_resolve_compiler_path(
        gcc, queries["ld"]["stdout_raw"], "ld",
    )
    ld_identity = _runtime_tool_identity(ld_path, "ld")
    internal_tools = {
        "as": _runtime_tool_identity(
            _runtime_resolve_compiler_path(
                gcc, queries["assembler"]["stdout_raw"], "assembler",
            ),
            "as",
        ),
        "cc1": _runtime_tool_identity(
            _runtime_resolve_compiler_path(
                gcc, queries["cc1"]["stdout_raw"], "cc1",
            ),
            "cc1",
            version_arguments=("-version", "-quiet"),
        ),
        "collect2": _runtime_tool_identity(
            _runtime_resolve_compiler_path(
                gcc, queries["collect2"]["stdout_raw"], "collect2",
            ),
            "collect2",
        ),
    }
    libgcc_identity = _runtime_tool_file_identity(
        _runtime_resolve_compiler_path(
            gcc, queries["libgcc"]["stdout_raw"], "libgcc",
        ),
        "libgcc",
    )
    source_path = (ROOT / source).resolve(strict=True)
    try:
        source_relative = source_path.relative_to(ROOT).as_posix()
    except ValueError:
        _fail("Stage61 runtime sourceがworkspace外")
    source_raw = source_path.read_bytes()
    replacements = {
        str(tools["gcc"]): "$TOOL:gcc",
        str(source_path): f"$WORKSPACE/{source_relative}",
        str(object_path): "$BUILD/runtime.o",
        str(elf_path): "$BUILD/runtime.elf",
        str(binary_path): "$BUILD/runtime.bin",
        str(linker_path): "$BUILD/linker.ld",
        **{
            str(tools[name]): f"$TOOL:{name}"
            for name in ("nm", "objcopy", "objdump")
        },
    }
    canonical_compile = _runtime_canonical_argv(
        compile_argv, replacements, temp_directory=temp_directory,
    )
    canonical_link = _runtime_canonical_argv(
        link_argv, replacements, temp_directory=temp_directory,
    )
    if set(post_link_argv) != {
        "nm_undefined", "nm_symbols", "objdump_sections", "objcopy_text",
    }:
        _fail("Stage61 runtime post-link command一覧不一致")
    canonical_post_link = {
        name: _runtime_canonical_argv(
            argv, replacements, temp_directory=temp_directory,
        )
        for name, argv in sorted(post_link_argv.items())
    }
    compile_fixed = [
        "$TOOL:gcc", "-mthumb", "-mcpu=arm7tdmi", "-mthumb-interwork",
        "-Os", "-std=c11", "-Wall", "-Wextra", "-Werror",
        "-ffreestanding", "-fno-builtin", "-fno-unwind-tables",
        "-fno-asynchronous-unwind-tables", "-fdata-sections",
        "-ffunction-sections", "-fno-common",
    ]
    if canonical_compile[:len(compile_fixed)] != compile_fixed \
            or canonical_compile[-4:] != [
                "-c", f"$WORKSPACE/{source_relative}",
                "-o", "$BUILD/runtime.o",
            ]:
        _fail("Stage61 runtime compile argv ABI外")
    macro_argv = canonical_compile[len(compile_fixed):-4]
    if not macro_argv or macro_argv != sorted(macro_argv) or any(
        not value.startswith("-D") or "=0x" not in value
        or not value.endswith("u") for value in macro_argv
    ):
        _fail("Stage61 runtime compile macro argv不正")
    required_link = [
        "$TOOL:gcc", "-mthumb", "-mcpu=arm7tdmi", "-mthumb-interwork",
        "-nostdlib", "-Wl,--build-id=none", "-Wl,--gc-sections",
        "-Wl,-e,Stage61DisplayNpcEvent_Probe",
        "-Wl,-T,$BUILD/linker.ld", "$BUILD/runtime.o", "-lgcc",
        "-o", "$BUILD/runtime.elf",
    ]
    if canonical_link != required_link:
        _fail("Stage61 runtime link argv ABI外")
    required_post_link = {
        "nm_undefined": ["$TOOL:nm", "-u", "$BUILD/runtime.elf"],
        "nm_symbols": [
            "$TOOL:nm", "-n", "-S", "--defined-only",
            "$BUILD/runtime.elf",
        ],
        "objcopy_text": [
            "$TOOL:objcopy", "-j", ".text", "-O", "binary",
            "$BUILD/runtime.elf", "$BUILD/runtime.bin",
        ],
        "objdump_sections": [
            "$TOOL:objdump", "-h", "$BUILD/runtime.elf",
        ],
    }
    if canonical_post_link != required_post_link:
        _fail("Stage61 runtime post-link argv ABI外")
    try:
        linker_text = linker_raw.decode("ascii")
    except UnicodeDecodeError as exc:
        _fail(f"Stage61 linker scriptがASCIIでない: {exc}")
    ldd_path_raw = shutil.which("ldd", path=_runtime_tool_environment()["PATH"])
    if not ldd_path_raw:
        _fail("Stage61 runtime dynamic dependency resolver ldd不足")
    dependency_resolver = _runtime_tool_identity(
        Path(ldd_path_raw).resolve(strict=True), "ldd",
    )
    all_executables = {
        **{f"tool:{name}": identity for name, identity in identities.items()},
        "tool:ld": ld_identity,
        **{
            f"internal:{name}": identity
            for name, identity in internal_tools.items()
        },
    }
    dependency_closures = {
        name: _runtime_dynamic_dependency_contract(
            Path(str(identity["resolved_realpath"])), name,
            dependency_resolver,
        )
        for name, identity in sorted(all_executables.items())
    }
    preprocessor_dependencies = _runtime_preprocessor_dependency_manifest(
        gcc, canonical_compile,
    )
    manifest = {
        "schema_version": 1,
        "kind": "STAGE61_ARM_RUNTIME_TOOLCHAIN_PROVENANCE",
        "target_abi": {
            "target_triple": "arm-none-eabi",
            "architecture": "ARMv4T",
            "cpu": "arm7tdmi",
            "instruction_set": "THUMB",
            "thumb_interwork": True,
            "freestanding": True,
            "host_standard_library_linked": False,
        },
        "tool_execution_environment":
            _runtime_tool_environment_contract(),
        "tools": {**identities, "ld": ld_identity},
        "internal_tools": internal_tools,
        "dynamic_dependency_resolver": dependency_resolver,
        "dynamic_dependency_closures": dependency_closures,
        "libgcc": {
            "kind": "GNU_LIBGCC_STATIC_ARCHIVE",
            **libgcc_identity,
        },
        "compiler_queries": queries,
        "preprocessor_dependency_manifest": preprocessor_dependencies,
        "source": {
            "path": source_relative, "size": len(source_raw),
            "sha256": _sha(source_raw),
        },
        "compile_argv_canonical": canonical_compile,
        "link_argv_canonical": canonical_link,
        "post_link_argv_canonical": canonical_post_link,
        "linker_script": {
            "canonical_path": "$BUILD/linker.ld",
            "load_address": f"0x{load_address:08X}",
            "size": len(linker_raw), "raw": linker_text,
            "sha256": _sha(linker_raw),
        },
    }
    manifest["manifest_sha256"] = _sha(_stable(manifest))
    return manifest


def _validate_runtime_toolchain_manifest(
    manifest: Mapping[str, Any],
    *, actual_linker_path: Path | None = None,
) -> None:
    root_keys = {
        "schema_version", "kind", "target_abi", "tools", "libgcc",
        "tool_execution_environment", "internal_tools",
        "dynamic_dependency_resolver", "dynamic_dependency_closures",
        "compiler_queries", "source", "compile_argv_canonical",
        "link_argv_canonical", "post_link_argv_canonical",
        "preprocessor_dependency_manifest", "linker_script",
        "manifest_sha256",
    }
    if not isinstance(manifest, Mapping) or set(manifest) != root_keys \
            or manifest.get("schema_version") != 1 \
            or manifest.get("kind") \
                != "STAGE61_ARM_RUNTIME_TOOLCHAIN_PROVENANCE":
        _fail("Stage61 runtime toolchain manifest root不一致")
    unsigned = deepcopy(dict(manifest))
    digest = unsigned.pop("manifest_sha256", None)
    if not isinstance(digest, str) or digest != _sha(_stable(unsigned)):
        _fail("Stage61 runtime toolchain manifest self-hash不一致")
    if manifest.get("target_abi") != {
        "target_triple": "arm-none-eabi", "architecture": "ARMv4T",
        "cpu": "arm7tdmi", "instruction_set": "THUMB",
        "thumb_interwork": True, "freestanding": True,
        "host_standard_library_linked": False,
    }:
        _fail("Stage61 runtime toolchain target ABI不一致")
    if manifest.get("tool_execution_environment") \
            != _runtime_tool_environment_contract():
        _fail("Stage61 runtime toolchain execution environment変化")
    tools = manifest.get("tools")
    if not isinstance(tools, Mapping) or set(tools) != {
        "gcc", "nm", "objcopy", "objdump", "ld",
    }:
        _fail("Stage61 runtime toolchain tool一覧不一致")
    for name, identity in tools.items():
        if not isinstance(identity, Mapping) or set(identity) != {
            "resolved_realpath", "binary_size", "binary_sha256", "version",
        }:
            _fail(f"Stage61 runtime toolchain {name} schema不一致")
        actual = _runtime_tool_identity(
            Path(str(identity["resolved_realpath"])), str(name),
        )
        if actual != identity:
            _fail(f"Stage61 runtime toolchain {name}がbuild中に変化")
    internal_tools = manifest.get("internal_tools")
    if not isinstance(internal_tools, Mapping) or set(internal_tools) != {
        "as", "cc1", "collect2",
    }:
        _fail("Stage61 runtime compiler internal tool一覧不一致")
    for name, identity in internal_tools.items():
        if not isinstance(identity, Mapping) or set(identity) != {
            "resolved_realpath", "binary_size", "binary_sha256", "version",
        } or _runtime_tool_identity(
            Path(str(identity.get("resolved_realpath"))), str(name),
            version_arguments=("-version", "-quiet") if name == "cc1"
            else ("--version",),
        ) != identity:
            _fail(f"Stage61 runtime compiler internal {name} identity不一致")
    dependency_resolver = manifest.get("dynamic_dependency_resolver")
    if not isinstance(dependency_resolver, Mapping) or set(
        dependency_resolver
    ) != {
        "resolved_realpath", "binary_size", "binary_sha256", "version",
    } or _runtime_tool_identity(
        Path(str(dependency_resolver.get("resolved_realpath"))), "ldd",
    ) != dependency_resolver:
        _fail("Stage61 runtime dynamic dependency resolver不一致")
    expected_ldd = shutil.which(
        "ldd", path=_runtime_tool_environment()["PATH"],
    )
    if not expected_ldd or str(Path(expected_ldd).resolve(strict=True)) \
            != dependency_resolver["resolved_realpath"]:
        _fail("Stage61 runtime dynamic dependency resolver path変化")
    dependency_closures = manifest.get("dynamic_dependency_closures")
    executable_identities = {
        **{f"tool:{name}": identity for name, identity in tools.items()},
        **{
            f"internal:{name}": identity
            for name, identity in internal_tools.items()
        },
    }
    if not isinstance(dependency_closures, Mapping) \
            or set(dependency_closures) != set(executable_identities):
        _fail("Stage61 runtime dynamic dependency closure一覧不一致")
    for name, identity in executable_identities.items():
        expected_closure = _runtime_dynamic_dependency_contract(
            Path(str(identity["resolved_realpath"])), name,
            dependency_resolver,
        )
        if dependency_closures[name] != expected_closure:
            _fail(f"Stage61 runtime dynamic dependency変化:{name}")
    libgcc = manifest.get("libgcc")
    if not isinstance(libgcc, Mapping) or set(libgcc) != {
        "kind", "resolved_realpath", "binary_size", "binary_sha256",
    } or libgcc.get("kind") != "GNU_LIBGCC_STATIC_ARCHIVE" \
            or _runtime_tool_file_identity(
                Path(str(libgcc.get("resolved_realpath"))), "libgcc",
            ) != {key: libgcc[key] for key in (
                "resolved_realpath", "binary_size", "binary_sha256",
            )}:
        _fail("Stage61 runtime libgcc identity不一致")
    queries = manifest.get("compiler_queries")
    if not isinstance(queries, Mapping) \
            or set(queries) != set(_RUNTIME_GCC_QUERY_ARGUMENTS):
        _fail("Stage61 runtime compiler query schema不一致")
    gcc = tools["gcc"]
    current_queries = _runtime_compiler_queries(gcc)
    if current_queries != queries \
            or queries["dumpmachine"]["stdout_raw"].strip() \
                != "arm-none-eabi":
        _fail("Stage61 runtime compiler queryがbuild中に変化/ABI外")
    source = manifest.get("source")
    if not isinstance(source, Mapping) or set(source) != {
        "path", "size", "sha256",
    }:
        _fail("Stage61 runtime toolchain source schema不一致")
    source_path = (ROOT / str(source["path"])).resolve(strict=True)
    try:
        source_relative = source_path.relative_to(ROOT).as_posix()
    except ValueError:
        _fail("Stage61 runtime toolchain sourceがworkspace外")
    source_raw = source_path.read_bytes()
    if source_relative != source["path"] \
            or len(source_raw) != source["size"] \
            or _sha(source_raw) != source["sha256"]:
        _fail("Stage61 runtime sourceがbuild中に変化")
    linker = manifest.get("linker_script")
    if not isinstance(linker, Mapping) or set(linker) != {
        "canonical_path", "load_address", "size", "raw", "sha256",
    } or linker.get("canonical_path") != "$BUILD/linker.ld" \
            or not isinstance(linker.get("raw"), str):
        _fail("Stage61 runtime linker script schema不一致")
    try:
        linker_raw = linker["raw"].encode("ascii")
    except UnicodeEncodeError as exc:
        _fail(f"Stage61 runtime linker scriptがASCIIでない: {exc}")
    load_address_text = linker.get("load_address")
    if not isinstance(load_address_text, str) \
            or len(load_address_text) != 10 \
            or not load_address_text.startswith("0x") \
            or any(character not in "0123456789ABCDEF"
                   for character in load_address_text[2:]):
        _fail("Stage61 runtime linker load address書式不一致")
    load_address = int(load_address_text, 16)
    if len(linker_raw) != linker["size"] \
            or _sha(linker_raw) != linker["sha256"] \
            or linker["raw"] != _runtime_linker_script(load_address):
        _fail("Stage61 runtime linker script SHA不一致")
    if actual_linker_path is not None:
        try:
            actual_linker_raw = actual_linker_path.resolve(
                strict=True,
            ).read_bytes()
        except (OSError, RuntimeError) as exc:
            _fail(f"Stage61 runtime linker script実体読取失敗: {exc}")
        if actual_linker_raw != linker_raw \
                or len(actual_linker_raw) != linker["size"] \
                or _sha(actual_linker_raw) != linker["sha256"]:
            _fail("Stage61 runtime linker script実体がmanifestと不一致")
    compile_argv = manifest.get("compile_argv_canonical")
    link_argv = manifest.get("link_argv_canonical")
    post_link_argv = manifest.get("post_link_argv_canonical")
    compile_fixed = [
        "$TOOL:gcc", "-mthumb", "-mcpu=arm7tdmi", "-mthumb-interwork",
        "-Os", "-std=c11", "-Wall", "-Wextra", "-Werror",
        "-ffreestanding", "-fno-builtin", "-fno-unwind-tables",
        "-fno-asynchronous-unwind-tables", "-fdata-sections",
        "-ffunction-sections", "-fno-common",
    ]
    compile_tail = [
        "-c", f"$WORKSPACE/{source['path']}", "-o", "$BUILD/runtime.o",
    ]
    expected_link = [
        "$TOOL:gcc", "-mthumb", "-mcpu=arm7tdmi", "-mthumb-interwork",
        "-nostdlib", "-Wl,--build-id=none", "-Wl,--gc-sections",
        "-Wl,-e,Stage61DisplayNpcEvent_Probe",
        "-Wl,-T,$BUILD/linker.ld", "$BUILD/runtime.o", "-lgcc",
        "-o", "$BUILD/runtime.elf",
    ]
    expected_post_link = {
        "nm_undefined": ["$TOOL:nm", "-u", "$BUILD/runtime.elf"],
        "nm_symbols": [
            "$TOOL:nm", "-n", "-S", "--defined-only",
            "$BUILD/runtime.elf",
        ],
        "objcopy_text": [
            "$TOOL:objcopy", "-j", ".text", "-O", "binary",
            "$BUILD/runtime.elf", "$BUILD/runtime.bin",
        ],
        "objdump_sections": [
            "$TOOL:objdump", "-h", "$BUILD/runtime.elf",
        ],
    }
    if not isinstance(compile_argv, list) \
            or len(compile_argv) <= len(compile_fixed) + len(compile_tail) \
            or compile_argv[:len(compile_fixed)] != compile_fixed \
            or compile_argv[-len(compile_tail):] != compile_tail \
            or not isinstance(link_argv, list) \
            or link_argv != expected_link \
            or post_link_argv != expected_post_link \
            or any(not isinstance(value, str) or not value
                   for value in [
                       *compile_argv, *link_argv,
                       *(item for row in expected_post_link.values()
                         for item in row),
                   ]):
        _fail("Stage61 runtime canonical argv ABI不一致")
    macro_argv = compile_argv[
        len(compile_fixed):-len(compile_tail)
    ]
    macro_names: list[str] = []
    for value in macro_argv:
        assignment = value[2:] if value.startswith("-D") else ""
        name, separator, raw_value = assignment.partition("=")
        if not separator or not name or not name.replace("_", "A").isalnum() \
                or name[0].isdigit() or not name.isupper() \
                or len(raw_value) != 11 or not raw_value.startswith("0x") \
                or not raw_value.endswith("u") \
                or any(character not in "0123456789ABCDEF"
                       for character in raw_value[2:-1]):
            _fail("Stage61 runtime compile macro argv ABI不一致")
        macro_names.append(name)
    if macro_argv != sorted(macro_argv) \
            or len(macro_names) != len(set(macro_names)):
        _fail("Stage61 runtime compile macro順序/重複不一致")
    dependency_manifest = manifest.get("preprocessor_dependency_manifest")
    if not isinstance(dependency_manifest, Mapping) \
            or dependency_manifest \
                != _runtime_preprocessor_dependency_manifest(
                    gcc, compile_argv,
                ):
        _fail("Stage61 runtime preprocessor dependency manifest変化")
    expected_tool_paths = {
        name: Path(_arm_tool(ROOT, f"arm-none-eabi-{name}")).resolve(
            strict=True,
        )
        for name in ("gcc", "nm", "objcopy", "objdump")
    }
    if any(
        identity["resolved_realpath"] != str(expected_tool_paths[name])
        for name, identity in tools.items() if name != "ld"
    ):
        _fail("Stage61 runtime tool pathが許可toolchain外")
    queried_ld = _runtime_resolve_compiler_path(
        gcc, queries["ld"]["stdout_raw"], "ld",
    )
    queried_libgcc = _runtime_resolve_compiler_path(
        gcc, queries["libgcc"]["stdout_raw"], "libgcc",
    )
    if str(queried_ld) != tools["ld"]["resolved_realpath"] \
            or str(queried_libgcc) != libgcc["resolved_realpath"]:
        _fail("Stage61 runtime queried ld/libgcc identity不一致")
    internal_query_names = {
        "as": "assembler", "cc1": "cc1", "collect2": "collect2",
    }
    for name, query_name in internal_query_names.items():
        queried = _runtime_resolve_compiler_path(
            gcc, queries[query_name]["stdout_raw"], name,
        )
        if str(queried) != internal_tools[name]["resolved_realpath"]:
            _fail(f"Stage61 runtime queried internal {name} identity不一致")


def _compile_runtime(
    source: Path, load_address: int, macros: Mapping[str, int],
) -> tuple[bytes, dict[str, int], str, dict[str, Any]]:
    gcc = Path(_arm_tool(ROOT, "arm-none-eabi-gcc")).resolve(strict=True)
    nm = Path(_arm_tool(ROOT, "arm-none-eabi-nm")).resolve(strict=True)
    objcopy = Path(_arm_tool(ROOT, "arm-none-eabi-objcopy")).resolve(strict=True)
    objdump = Path(_arm_tool(ROOT, "arm-none-eabi-objdump")).resolve(strict=True)
    (ROOT / ".local").mkdir(exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="stage61-runtime-", dir=ROOT / ".local") as tmp:
        directory = Path(tmp)
        obj, elf, binary = (directory / "runtime.o", directory / "runtime.elf",
                            directory / "runtime.bin")
        linker = directory / "linker.ld"
        define_args = [
            f"-D{name}=0x{int(address):08X}u"
            for name, address in sorted(macros.items())
        ]
        source_path = (ROOT / source).resolve(strict=True)
        compile_argv = [
            gcc, "-mthumb", "-mcpu=arm7tdmi", "-mthumb-interwork", "-Os",
            "-std=c11", "-Wall", "-Wextra", "-Werror", "-ffreestanding",
            "-fno-builtin", "-fno-unwind-tables", "-fno-asynchronous-unwind-tables",
            "-fdata-sections", "-ffunction-sections", "-fno-common",
            *define_args,
            "-c", str(source_path), "-o", str(obj),
        ]
        linker_text = _runtime_linker_script(load_address)
        linker_raw = linker_text.encode("ascii")
        linker.write_bytes(linker_raw)
        link_argv = [
            gcc, "-mthumb", "-mcpu=arm7tdmi", "-mthumb-interwork",
            "-nostdlib", "-Wl,--build-id=none", "-Wl,--gc-sections",
            "-Wl,-e,Stage61DisplayNpcEvent_Probe", f"-Wl,-T,{linker}",
            str(obj), "-lgcc", "-o", str(elf),
        ]
        post_link_argv = {
            "nm_undefined": [nm, "-u", str(elf)],
            "nm_symbols": [
                nm, "-n", "-S", "--defined-only", str(elf),
            ],
            "objcopy_text": [
                objcopy, "-j", ".text", "-O", "binary", str(elf),
                str(binary),
            ],
            "objdump_sections": [objdump, "-h", str(elf)],
        }
        # Capture every executable, compiler query, dependency and complete
        # argv before the first product compile.  A post-use validation below
        # rejects any binary/header/spec swap during command execution.
        toolchain = _runtime_toolchain_manifest(
            tools={
                "gcc": gcc, "nm": nm, "objcopy": objcopy,
                "objdump": objdump,
            },
            source=source, load_address=load_address,
            compile_argv=compile_argv, link_argv=link_argv,
            post_link_argv=post_link_argv,
            linker_path=linker, linker_raw=linker_raw,
            object_path=obj, elf_path=elf, binary_path=binary,
            temp_directory=directory,
        )
        _validate_runtime_toolchain_manifest(
            toolchain, actual_linker_path=linker,
        )
        _runtime_run(compile_argv, "Stage61 runtime compile")
        # The linker script is an actual command input, not merely a generated
        # manifest string.  Re-read it immediately before and after the link so
        # a compile-time/racing replacement cannot make the recorded canonical
        # bytes describe a different file than the linker consumed.
        _validate_runtime_toolchain_manifest(
            toolchain, actual_linker_path=linker,
        )
        _runtime_run(link_argv, "Stage61 runtime link")
        _validate_runtime_toolchain_manifest(
            toolchain, actual_linker_path=linker,
        )
        undefined = _runtime_run(
            post_link_argv["nm_undefined"], "Stage61 undefined audit",
        )
        if undefined:
            _fail(f"Stage61 runtime未解決symbol: {undefined}")
        nm_text = _runtime_run(
            post_link_argv["nm_symbols"], "Stage61 nm",
        )
        symbols: dict[str, int] = {}
        mutable: list[str] = []
        for line in nm_text.splitlines():
            fields = line.split()
            if len(fields) < 4:
                continue
            try:
                address = int(fields[0], 16)
            except ValueError:
                continue
            symbols[fields[3]] = address
            if fields[2] in {"B", "b", "C", "c", "D", "d", "G", "g", "S", "s"}:
                mutable.append(fields[3])
        if REQUIRED_SYMBOLS - set(symbols) or mutable:
            _fail(f"Stage61 runtime symbol監査不一致: missing={REQUIRED_SYMBOLS-set(symbols)} mutable={mutable}")
        sections = _runtime_run(
            post_link_argv["objdump_sections"], "Stage61 section audit",
        )
        text_section: tuple[int, int, int] | None = None
        for line in sections.splitlines():
            fields = line.split()
            if len(fields) >= 6 and fields[1] == ".text":
                try:
                    text_section = (
                        int(fields[2], 16),
                        int(fields[3], 16),
                        int(fields[4], 16),
                    )
                except ValueError as exc:
                    _fail(f"Stage61 .text section parse失敗: {line}: {exc}")
                break
        if text_section is None:
            _fail("Stage61 ELFに.text sectionがありません")
        text_size, text_vma, text_lma = text_section
        if text_vma != load_address or text_lma != load_address:
            _fail(
                "Stage61 .text配置不一致: "
                f"expected={load_address:#010x}, vma={text_vma:#010x}, "
                f"lma={text_lma:#010x}"
            )
        _runtime_run(
            post_link_argv["objcopy_text"], "Stage61 objcopy",
        )
        _validate_runtime_toolchain_manifest(
            toolchain, actual_linker_path=linker,
        )
        code = binary.read_bytes()
        if len(code) != text_size:
            _fail(
                f"Stage61 .text/binary size不一致: text={text_size}, "
                f"binary={len(code)}"
            )
        if not code or len(code) > 16 * 1024:
            _fail(f"Stage61 runtime size不正: {len(code)}")
        escaped = {
            name: address for name, address in symbols.items()
            if name in REQUIRED_SYMBOLS
            and not load_address <= address < load_address + len(code)
        }
        if escaped:
            _fail(f"Stage61 runtime symbolが.text外です: {escaped}")
        return code, symbols, nm_text, toolchain


def _previous_requests(previous: Mapping[str, Any]) -> list[dict[str, Any]]:
    if previous.get("summaries", {}).get("overlap_count") != 0:
        _fail("Stage60 allocationにoverlapがあります")
    keys = ("name", "region", "size", "alignment", "owner", "purpose",
            "content_sha256")
    return [{key: row[key] for key in keys} for row in previous["allocations"]]


def _allocate(previous: Mapping[str, Any], size: int, digest: str) \
        -> tuple[dict[str, Any], dict[str, Any]]:
    requests = _previous_requests(previous)
    requests.append({
        "name": ALLOCATION_NAME, "region": "integration_modules", "size": size,
        "alignment": 16, "owner": TASK,
        "purpose": "表示名名前空間、全SOURCE_DIRECT event、最終NPC配置、カビゴン固定遭遇の統合修復",
        "content_sha256": digest,
    })
    report = build_allocation_report_from_csv(ROOT / "config/rom_regions.csv", requests)
    # Allocation is append-only across stages.  Re-running all historical
    # requests through a changed region table/policy must never silently move
    # an earlier payload and let the current stage self-authorize the new
    # addresses.  Compare the normalized regions and every complete prefix
    # row, including placement and sequence, with the signed Stage60 report.
    if report.get("regions") != previous.get("regions"):
        _fail("Stage60/current ROM region contract drift")
    previous_rows = previous.get("allocations")
    if not isinstance(previous_rows, list) \
            or report.get("allocations", [])[:len(previous_rows)] != previous_rows:
        _fail("Stage60 allocation prefix moved or changed")
    rows = [row for row in report["allocations"] if row["name"] == ALLOCATION_NAME]
    if len(rows) != 1 or report["summaries"]["overlap_count"]:
        _fail("Stage61 payload allocation不正")
    return rows[0], report


def _payload(data: bytes, code: bytes) -> tuple[bytes, int]:
    # GCC/ld may raise .text alignment when a new runtime function introduces
    # a more strictly aligned literal/veneer section.  Four-byte alignment was
    # only accidentally sufficient for the earlier object.  Keep the runtime
    # VMA stable under such source growth by using the payload allocator's
    # native 16-byte alignment contract.
    code_offset = _align(
        PAYLOAD_HEADER_SIZE + len(data), RUNTIME_CODE_ALIGNMENT
    )
    size = _align(code_offset + len(code), 16)
    result = bytearray(b"\xFF" * size)
    result[PAYLOAD_HEADER_SIZE:PAYLOAD_HEADER_SIZE + len(data)] = data
    result[code_offset:code_offset + len(code)] = code
    struct.pack_into(
        "<8s7I", result, 0, b"VEGADS61", 1, size,
        PAYLOAD_HEADER_SIZE, len(data), code_offset, len(code), 844,
    )
    return bytes(result), code_offset


def _jump_stub(target: int) -> bytes:
    return struct.pack("<HHI", 0x4B00, 0x4718, target | 1)


def _register_jump_stub(target: int, register: int) -> bytes:
    """Materialize the canonical 8-byte Thumb literal tail jump."""

    if not 0 <= register <= 7:
        _fail(f"Thumb jump registerがlow registerではありません: r{register}")
    return struct.pack(
        "<HHI",
        0x4800 | (register << 8),
        0x4700 | (register << 3),
        target | 1,
    )


def _aligned_register_jump_stub(address: int, target: int, register: int) -> bytes:
    """Match CFRU Hook() at word- and halfword-aligned Thumb sites."""

    if address & 1:
        _fail(f"Thumb hook addressがhalfword境界ではありません: {address:#x}")
    if address & 2:
        return struct.pack(
            "<HHHI",
            0x4801 | (register << 8),
            0x4700 | (register << 3),
            0x0000,
            target | 1,
        )
    return _register_jump_stub(target, register)


def _preserving_four_arg_jump_stub(target: int) -> bytes:
    """Tail-jump while preserving r0-r3 and the caller's r4.

    The compact literal jump uses r3 as scratch, but the region graphics
    consumer carries its fourth ABI argument there.  Save r4, copy the target
    into caller-saved ip/r12, restore r4, then tail-jump with the BL-provided
    LR intact.
    """

    return struct.pack(
        "<HHHHHHI",
        0xB410,  # push {r4}
        0x4C02,  # ldr r4, [pc, #8]
        0x46A4,  # mov ip, r4
        0xBC10,  # pop {r4}
        0x4760,  # bx ip
        0x46C0,  # nop / literal alignment
        target | 1,
    )


def _dungeon_resolver_patch(target: int, size: int) -> bytes:
    # 0x080C1DCEの34-byte windowは、名前pointer解決だけでなく後半の
    # SetDispCnt/window初期化まで所有している。resolver呼出し後にstockの
    # 命令列をexactに再実行しなければ洞窟popupの窓が壊れる。
    #
    #   ldr r3, literal; bl local_thunk; mov r4,r0
    #   movs r0,1; movs r1,0; bl SetDispCnt
    #   ldr r0,[r5]; ldr r1,=0x00006A60; add r0,r1
    #   movs r1,1; strh r1,[r0]; b resume; local_thunk: bx r3
    #   literal: resolver|1
    if size != 34:
        _fail(f"dungeon resolver patchはexact 34 bytesが必要です: {size}")
    raw = struct.pack(
        "<15HI",
        0x4B07, 0xF000, 0xF80B, 0x1C04, 0x2001,
        0x2100, 0xF004, 0xF851, 0x6828, 0x4922,
        0x1840, 0x2101, 0x8001, 0xE002, 0x4718,
        target | 1,
    )
    if len(raw) != size:
        _fail("dungeon resolver patch size不一致")
    return raw


def _changed_spans(before: bytes, after: bytes) -> list[dict[str, int]]:
    rows: list[dict[str, int]] = []
    index = 0
    while index < len(before):
        if before[index] == after[index]:
            index += 1
            continue
        start = index
        while index < len(before) and before[index] != after[index]:
            index += 1
        rows.append({"start": start, "end_exclusive": index,
                     "size": index - start})
    return rows


def _aligned_pointer_references(raw: bytes, value: int) -> list[int]:
    references: list[int] = []
    pattern = struct.pack("<I", value)
    start = 0
    while True:
        offset = raw.find(pattern, start)
        if offset < 0:
            break
        if offset % 4 == 0:
            references.append(offset)
        start = offset + 1
    return references


def _species_bound_thunk_audit(
    stage60: bytes, previous_allocation: Mapping[str, Any],
) -> dict[str, Any]:
    provenance_rows: list[dict[str, Any]] = []
    roms: list[tuple[str, bytes]] = []
    for label, relative, size, digest in SPECIES_BOUND_PROVENANCE:
        contract = {"path": str(relative), "size": size, "sha256": digest}
        raw = _identity(contract, label)
        roms.append((label, raw))
        provenance_rows.append({
            "label": label, "path": str(relative), "size": len(raw),
            "sha256": _sha(raw),
        })
    roms.append(("Stage60 exact input", stage60))
    cave_preimages = {
        label: raw[
            SPECIES_BOUND_THUNK_OFFSET:
            SPECIES_BOUND_THUNK_OFFSET + len(SPECIES_BOUND_THUNK)
        ].hex()
        for label, raw in roms
    }
    expected_caves = {
        "Stage07 species ROM": "ff" * len(SPECIES_BOUND_THUNK),
        "Stage09 species-surface ROM": SPECIES_BOUND_THUNK.hex(),
        "Stage60 exact input": "ff" * len(SPECIES_BOUND_THUNK),
    }
    if cave_preimages != expected_caves:
        _fail(f"species-bound low-ROM cave preimage drift: {cave_preimages}")
    for label, raw in roms:
        if label != "Stage07 species ROM" and raw[
            SPECIES_BOUND_NEIGHBOR_OFFSET:
            SPECIES_BOUND_NEIGHBOR_OFFSET + len(SPECIES_BOUND_NEIGHBOR_STAGE09)
        ] != SPECIES_BOUND_NEIGHBOR_STAGE09:
            _fail(f"species-bound cave隣接nickname veneer drift: {label}")
    reference_rows: list[dict[str, Any]] = []
    for label, raw in roms:
        even = _aligned_pointer_references(raw, SPECIES_BOUND_THUNK_ADDRESS)
        thumb = _aligned_pointer_references(raw, SPECIES_BOUND_THUNK_ADDRESS | 1)
        reference_rows.append({
            "label": label,
            "even_pointer_reference_offsets": even,
            "thumb_pointer_reference_offsets": thumb,
            "reference_count": len(even) + len(thumb),
        })
    if any(row["reference_count"] for row in reference_rows):
        _fail(f"species-bound cave aligned pointer referenceあり: {reference_rows}")
    overlaps = [
        str(row["name"]) for row in previous_allocation.get("allocations", [])
        if not (
            SPECIES_BOUND_THUNK_OFFSET + len(SPECIES_BOUND_THUNK)
                <= int(row["start"])
            or int(row["end_exclusive"]) <= SPECIES_BOUND_THUNK_OFFSET
        )
    ]
    if overlaps:
        _fail(f"species-bound cave allocation overlap: {overlaps}")
    return {
        "status": "PASS",
        "cave_address": f"0x{SPECIES_BOUND_THUNK_ADDRESS:08X}",
        "cave_offset": SPECIES_BOUND_THUNK_OFFSET,
        "size": len(SPECIES_BOUND_THUNK),
        "preimage_hex": "ff" * len(SPECIES_BOUND_THUNK),
        "replacement_hex": SPECIES_BOUND_THUNK.hex(),
        "abi": "r0=1620; r1-r3/r4-r7/lr preserved; flags set by caller cmp",
        "neighbor_stage09_nickname_veneer": (
            f"0x{GBA_BASE + SPECIES_BOUND_NEIGHBOR_OFFSET:08X}"
        ),
        "provenance": provenance_rows,
        "aligned_pointer_references": reference_rows,
        "allocation_overlap_count": 0,
        "callsite_count": len(SPECIES_BOUND_CALLSITE_PATCHES),
        "assertions": {
            "stage07_and_stage60_preimage_is_ff8": True,
            "stage09_root_generator_uses_same_exact_thunk": True,
            "stage09_stage60_neighbor_veneer_exact": True,
            "aligned_pointer_reference_count_zero": True,
            "stage60_allocation_overlap_count_zero": True,
            "thumb_bl_range_valid_for_all_callsites": all(
                abs(SPECIES_BOUND_THUNK_ADDRESS - (GBA_BASE + offset + 4))
                    < (1 << 22)
                for offset, _expected, _register, _branch
                in SPECIES_BOUND_CALLSITE_PATCHES
            ),
        },
    }


def _apply_patch(
    baseline: bytes, output: bytearray, declared: list[dict[str, Any]],
    *, name: str, offset: int, expected: bytes, replacement: bytes,
    category: str,
) -> None:
    if len(expected) != len(replacement):
        _fail(f"{name}: patch length不一致")
    if baseline[offset:offset + len(expected)] != expected:
        _fail(f"{name}: expected byte不一致 at {offset:#x}: "
              f"{baseline[offset:offset+len(expected)].hex()} != {expected.hex()}")
    overlap = [
        row for row in declared
        if not (
            offset + len(replacement) <= int(row["start"])
            or int(row["end_exclusive"]) <= offset
        )
    ]
    if overlap:
        _fail(f"{name}: declared patch overlap: {[row['name'] for row in overlap]}")
    output[offset:offset + len(replacement)] = replacement
    declared.append({
        "name": name, "category": category, "start": offset,
        "end_exclusive": offset + len(replacement), "size": len(replacement),
        "expected_hex": expected.hex(), "replacement_hex": replacement.hex(),
    })


def _runtime_nm_symbol_span(
    nm_text: str, symbols: Mapping[str, int], symbol: str,
) -> tuple[int, int]:
    """Return one exact text symbol address/size from the current link."""

    matches: list[tuple[int, int]] = []
    for line in nm_text.splitlines():
        fields = line.split()
        if len(fields) != 4 or fields[3] != symbol:
            continue
        try:
            address, size = int(fields[0], 16), int(fields[1], 16)
        except ValueError:
            continue
        if fields[2] not in {"T", "t"} or size <= 0:
            continue
        matches.append((address, size))
    if len(matches) != 1 or symbols.get(symbol) != matches[0][0]:
        _fail(f"Stage61 Factory adapter symbol span不一致:{symbol}:{matches}")
    return matches[0]


def _apply_factory_prepare_error_adapter(
    stage60: bytes,
    output: bytearray,
    declared: list[dict[str, Any]],
    symbols: Mapping[str, int],
    nm_text: str,
) -> dict[str, Any]:
    """Rebind one physical Factory callnative to the one-shot Stage61 seam."""

    script_offset = FACTORY_PREPARE_SCRIPT_ADDRESS - GBA_BASE
    script_raw = stage60[
        script_offset:script_offset + FACTORY_PREPARE_SCRIPT_SIZE
    ]
    if len(script_raw) != FACTORY_PREPARE_SCRIPT_SIZE \
            or script_raw != FACTORY_PREPARE_SCRIPT_PREIMAGE \
            or _sha(script_raw) != FACTORY_PREPARE_SCRIPT_SHA256 \
            or output[
                script_offset:script_offset + FACTORY_PREPARE_SCRIPT_SIZE
            ] != script_raw:
        _fail("Factory PrepareBattle physical script full-span identity不一致")
    pointer_offset = FACTORY_PREPARE_POINTER_SITE - GBA_BASE
    if pointer_offset != script_offset + 1 \
            or script_raw[1:5] != FACTORY_PREPARE_POINTER_PREIMAGE \
            or struct.unpack("<I", FACTORY_PREPARE_POINTER_PREIMAGE)[0] \
                != FACTORY_PREPARE_ORIGINAL_ENTRY:
        _fail("Factory PrepareBattle callnative pointer identity不一致")

    original_offset = FACTORY_PREPARE_ORIGINAL_ENTRY - GBA_BASE
    original_span = stage60[
        original_offset:
        original_offset + FACTORY_PREPARE_ORIGINAL_SPAN_SIZE
    ]
    if len(original_span) != FACTORY_PREPARE_ORIGINAL_SPAN_SIZE \
            or _sha(original_span) != FACTORY_PREPARE_ORIGINAL_SPAN_SHA256 \
            or output[
                original_offset:
                original_offset + FACTORY_PREPARE_ORIGINAL_SPAN_SIZE
            ] != original_span:
        _fail("Factory PrepareBattle original delegate span不一致")

    adapter_address, adapter_size = _runtime_nm_symbol_span(
        nm_text, symbols, FACTORY_PREPARE_ADAPTER_SYMBOL,
    )
    setter_address, setter_size = _runtime_nm_symbol_span(
        nm_text, symbols, FACTORY_PREPARE_FAULT_SETTER_SYMBOL,
    )
    if adapter_address & 1 or setter_address & 1 \
            or not GBA_BASE <= adapter_address < GBA_BASE + len(output) \
            or not GBA_BASE <= setter_address < GBA_BASE + len(output):
        _fail("Factory Stage61 adapter/setter symbol address不正")
    adapter_offset = adapter_address - GBA_BASE
    setter_offset = setter_address - GBA_BASE
    adapter_raw = bytes(output[
        adapter_offset:adapter_offset + adapter_size
    ])
    setter_raw = bytes(output[setter_offset:setter_offset + setter_size])
    if len(adapter_raw) != adapter_size or len(setter_raw) != setter_size \
            or not adapter_raw or not setter_raw \
            or stage60[adapter_offset:adapter_offset + adapter_size] \
                != b"\xFF" * adapter_size \
            or stage60[setter_offset:setter_offset + setter_size] \
                != b"\xFF" * setter_size:
        _fail("Factory Stage61 adapter/setter payload ownership不一致")

    replacement = struct.pack("<I", adapter_address | 1)
    _apply_patch(
        stage60,
        output,
        declared,
        name="factory_prepare_error::stage61_one_shot_adapter_pointer",
        offset=pointer_offset,
        expected=FACTORY_PREPARE_POINTER_PREIMAGE,
        replacement=replacement,
        category="FACILITY_PHYSICAL_PREPARE_ERROR_VALIDATION_SEAM",
    )
    final_script = bytes(output[
        script_offset:script_offset + FACTORY_PREPARE_SCRIPT_SIZE
    ])
    expected_final = bytearray(FACTORY_PREPARE_SCRIPT_PREIMAGE)
    expected_final[1:5] = replacement
    if final_script != bytes(expected_final):
        _fail("Factory PrepareBattle Stage61 script pointer-only差分不一致")

    sources = []
    for path in FACTORY_PREPARE_SOURCE_PATHS:
        raw = (ROOT / path).read_bytes()
        sources.append({
            "path": path.as_posix(), "size": len(raw),
            "sha256": _sha(raw),
        })
    return {
        "status": "PASS",
        "physical_script": {
            "address": f"0x{FACTORY_PREPARE_SCRIPT_ADDRESS:08X}",
            "byte_length": FACTORY_PREPARE_SCRIPT_SIZE,
            "stage60_sha256": FACTORY_PREPARE_SCRIPT_SHA256,
            "stage61_sha256": _sha(final_script),
        },
        "pointer_patch": {
            "address": f"0x{FACTORY_PREPARE_POINTER_SITE:08X}",
            "expected_hex": FACTORY_PREPARE_POINTER_PREIMAGE.hex(),
            "replacement_hex": replacement.hex(),
            "original_target": f"0x{FACTORY_PREPARE_ORIGINAL_ENTRY:08X}",
            "adapter_target": f"0x{adapter_address | 1:08X}",
        },
        "adapter": {
            "symbol": FACTORY_PREPARE_ADAPTER_SYMBOL,
            "address": f"0x{adapter_address:08X}",
            "byte_length": adapter_size,
            "sha256": _sha(adapter_raw),
            "normal_delegate": f"0x{FACTORY_PREPARE_ORIGINAL_ENTRY:08X}",
        },
        "fault_setter": {
            "symbol": FACTORY_PREPARE_FAULT_SETTER_SYMBOL,
            "address": f"0x{setter_address:08X}",
            "byte_length": setter_size,
            "sha256": _sha(setter_raw),
            "lifecycle_calls": 0,
        },
        "original_delegate": {
            "address": f"0x{FACTORY_PREPARE_ORIGINAL_ENTRY:08X}",
            "byte_length": FACTORY_PREPARE_ORIGINAL_SPAN_SIZE,
            "sha256": FACTORY_PREPARE_ORIGINAL_SPAN_SHA256,
        },
        "arm_schema": {
            "state_address": "0x0203F220",
            "state_size": 1280,
            "state_magic": "0x324D4846",
            "last_status_offset": "0x20",
            "active_offset": "0x62",
            "phase_offset": "0x6A",
            "reserved_header_offset": "0x7D",
            "reserved_header_size": 4,
            "arm_hex": "5346acb9",
            "active_value": 1,
            "active_phase": 3,
            "error_status": 0,
            "var_result_address": "0x02037004",
        },
        "source_binding": sources,
        "assertions": {
            "physical_script_full_span_pinned": True,
            "only_callnative_pointer_rebound": True,
            "adapter_and_setter_current_link_spans_pinned": True,
            "original_delegate_stage60_stage61_identical": True,
            "arm_is_four_byte_magic_with_inverse": True,
            "fault_arm_consumed_before_result_publish": True,
            "fault_preserves_active_phase_for_script_abort": True,
            "normal_invalid_stale_and_second_calls_delegate_original": True,
            "setter_calls_no_facility_lifecycle": True,
        },
    }


def _apply_create_box_mon_friendship_repair(
    stage60: bytes,
    clean: bytes,
    output: bytearray,
    declared: list[dict[str, Any]],
) -> dict[str, Any]:
    """Restore the widened base-stat friendship pointer in CreateBoxMon."""

    context_offset = CREATE_BOX_MON_FRIENDSHIP_CONTEXT_START - GBA_BASE
    context_size = len(CREATE_BOX_MON_FRIENDSHIP_STAGE60_CONTEXT)
    clean_context = clean[context_offset:context_offset + context_size]
    stage60_context = stage60[context_offset:context_offset + context_size]
    if clean_context != CREATE_BOX_MON_FRIENDSHIP_CLEAN_CONTEXT:
        _fail("CreateBoxMon friendship clean stride preimage不一致")
    if stage60_context != CREATE_BOX_MON_FRIENDSHIP_STAGE60_CONTEXT:
        _fail("CreateBoxMon friendship Stage60 stride preimage不一致")

    function_offset = CREATE_BOX_MON_ENTRY - GBA_BASE
    stage60_function = stage60[
        function_offset:function_offset + CREATE_BOX_MON_SIZE
    ]
    if len(stage60_function) != CREATE_BOX_MON_SIZE \
            or _sha(stage60_function) != CREATE_BOX_MON_STAGE60_SHA256:
        _fail("CreateBoxMon Stage60 function identity不一致")

    special_raw = (ROOT / CREATE_BOX_MON_SPECIAL_INSERTS_PATH).read_bytes()
    c_source_raw = (ROOT / CREATE_BOX_MON_C_SOURCE_PATH).read_bytes()
    if _sha(special_raw) != CREATE_BOX_MON_SPECIAL_INSERTS_SHA256:
        _fail("CreateBoxMon special_inserts source identity不一致")
    if _sha(c_source_raw) != CREATE_BOX_MON_C_SOURCE_SHA256:
        _fail("CreateBoxMon C source identity不一致")
    special_text = special_raw.decode("utf-8")
    c_source_text = c_source_raw.decode("utf-8")
    if (
        ".org 0x3D384, 0xFF\n\tlsl r0, r1, #0x5\n"
        not in special_text
    ):
        _fail("CreateBoxMon malformed friendship insert source drift")
    if (
        "SetBoxMonData(boxMon, MON_DATA_FRIENDSHIP, "
        "&gBaseStats[species].friendship);"
        not in c_source_text
    ):
        _fail("CreateBoxMon friendship C contract drift")

    _apply_patch(
        stage60,
        output,
        declared,
        name="create_box_mon::expanded_base_stats_friendship_stride",
        offset=CREATE_BOX_MON_FRIENDSHIP_SITE - GBA_BASE,
        expected=CREATE_BOX_MON_FRIENDSHIP_PREIMAGE,
        replacement=CREATE_BOX_MON_FRIENDSHIP_REPLACEMENT,
        category="GENERATED_MON_BASE_STATS_ABI_REPAIR",
    )
    stage61_context = bytes(
        output[context_offset:context_offset + context_size]
    )
    stage61_function = bytes(
        output[function_offset:function_offset + CREATE_BOX_MON_SIZE]
    )
    if stage61_context != CREATE_BOX_MON_FRIENDSHIP_STAGE61_CONTEXT:
        _fail("CreateBoxMon friendship repaired dataflow不一致")
    if _sha(stage61_function) != CREATE_BOX_MON_STAGE61_SHA256:
        _fail("CreateBoxMon friendship repaired function identity不一致")

    return {
        "status": "PASS",
        "entry": f"0x{CREATE_BOX_MON_ENTRY:08X}",
        "function_size": CREATE_BOX_MON_SIZE,
        "friendship_instruction": (
            f"0x{CREATE_BOX_MON_FRIENDSHIP_SITE:08X}"
        ),
        "stage60_function_sha256": CREATE_BOX_MON_STAGE60_SHA256,
        "stage61_function_sha256": CREATE_BOX_MON_STAGE61_SHA256,
        "clean_context_hex": clean_context.hex(),
        "stage60_context_hex": stage60_context.hex(),
        "stage61_context_hex": stage61_context.hex(),
        "preimage_hex": CREATE_BOX_MON_FRIENDSHIP_PREIMAGE.hex(),
        "replacement_hex": CREATE_BOX_MON_FRIENDSHIP_REPLACEMENT.hex(),
        "source_provenance": {
            "commit": CREATE_BOX_MON_CFRU_COMMIT,
            "special_inserts": {
                "path": CREATE_BOX_MON_SPECIAL_INSERTS_PATH.as_posix(),
                "sha256": CREATE_BOX_MON_SPECIAL_INSERTS_SHA256,
                "observed_instruction": "lsl r0, r1, #0x5",
            },
            "create_box_mon_c": {
                "path": CREATE_BOX_MON_C_SOURCE_PATH.as_posix(),
                "sha256": CREATE_BOX_MON_C_SOURCE_SHA256,
                "contract": (
                    "MON_DATA_FRIENDSHIP <- "
                    "gBaseStats[species].friendship"
                ),
            },
        },
        "thumb_dataflow": {
            "species_register": "r0",
            "destination_register": "r2",
            "stride": 32,
            "field_offset": 18,
            "consumer": "SetBoxMonData MON_DATA_FRIENDSHIP",
        },
        "assertions": {
            "clean_28_byte_stride_context_exact": True,
            "stage60_malformed_halfword_exact": True,
            "fixed_upstream_sources_sha256_pinned": True,
            "replacement_is_lsl_r2_r0_5": True,
            "following_add_field_and_base_instructions_preserved": True,
            "only_one_thumb_halfword_declared": True,
            "complete_create_box_mon_postimage_sha256_pinned": True,
        },
    }


def _apply_species_name_padding_repair(
    stage60: bytes,
    output: bytearray,
    declared: list[dict[str, Any]],
) -> dict[str, Any]:
    """Copy every canonical Species-name row byte, including EOS padding."""

    thunk_offset = GET_SPECIES_NAME_THUNK - GBA_BASE
    if stage60[
        thunk_offset:thunk_offset + len(GET_SPECIES_NAME_THUNK_RAW)
    ] != GET_SPECIES_NAME_THUNK_RAW:
        _fail("GetSpeciesName thunk identity不一致")
    if _u32(
        stage60, thunk_offset + 4, "GetSpeciesName implementation pointer"
    ) != GET_SPECIES_NAME_IMPLEMENTATION | 1:
        _fail("GetSpeciesName thunk target不一致")

    implementation_offset = GET_SPECIES_NAME_IMPLEMENTATION - GBA_BASE
    implementation = stage60[
        implementation_offset:
        implementation_offset + GET_SPECIES_NAME_IMPLEMENTATION_SIZE
    ]
    if len(implementation) != GET_SPECIES_NAME_IMPLEMENTATION_SIZE \
            or _sha(implementation) != GET_SPECIES_NAME_STAGE60_SHA256:
        _fail("GetSpeciesName Stage60 implementation identity不一致")

    table_size = (
        GET_SPECIES_NAME_TABLE_STRIDE * GET_SPECIES_NAME_TABLE_COUNT
    )
    table_offset = GET_SPECIES_NAME_TABLE - GBA_BASE
    table = stage60[table_offset:table_offset + table_size]
    table_artifact = (ROOT / GET_SPECIES_NAME_TABLE_PATH).read_bytes()
    if len(table) != table_size or table != table_artifact \
            or _sha(table) != GET_SPECIES_NAME_TABLE_SHA256:
        _fail("GetSpeciesName canonical table identity不一致")
    for species in range(GET_SPECIES_NAME_TABLE_COUNT):
        row = table[
            species * GET_SPECIES_NAME_TABLE_STRIDE:
            (species + 1) * GET_SPECIES_NAME_TABLE_STRIDE
        ]
        try:
            eos = row.index(0xFF)
        except ValueError:
            _fail(f"GetSpeciesName table row EOS欠落:{species}")
        if row[eos:] != b"\xFF" * (len(row) - eos):
            _fail(f"GetSpeciesName table row padding不一致:{species}")

    source_raw = (ROOT / GET_SPECIES_NAME_SOURCE_PATH).read_bytes()
    if _sha(source_raw) != GET_SPECIES_NAME_SOURCE_SHA256:
        _fail("GetSpeciesName source identity不一致")
    source_text = source_raw.decode("utf-8")
    if "if (name[i] == EOS)\n            break;" not in source_text \
            or "name[i] = EOS;" not in source_text:
        _fail("GetSpeciesName source early-exit contract drift")

    _apply_patch(
        stage60,
        output,
        declared,
        name="get_species_name::copy_canonical_eos_padding",
        offset=GET_SPECIES_NAME_EARLY_EXIT_SITE - GBA_BASE,
        expected=GET_SPECIES_NAME_EARLY_EXIT_PREIMAGE,
        replacement=GET_SPECIES_NAME_EARLY_EXIT_REPLACEMENT,
        category="GENERATED_MON_NAME_INITIALIZATION_ABI_REPAIR",
    )
    repaired = bytes(output[
        implementation_offset:
        implementation_offset + GET_SPECIES_NAME_IMPLEMENTATION_SIZE
    ])
    if _sha(repaired) != GET_SPECIES_NAME_STAGE61_SHA256:
        _fail("GetSpeciesName Stage61 implementation identity不一致")

    return {
        "status": "PASS",
        "thunk": f"0x{GET_SPECIES_NAME_THUNK:08X}",
        "implementation": f"0x{GET_SPECIES_NAME_IMPLEMENTATION:08X}",
        "implementation_size": GET_SPECIES_NAME_IMPLEMENTATION_SIZE,
        "early_exit_instruction": (
            f"0x{GET_SPECIES_NAME_EARLY_EXIT_SITE:08X}"
        ),
        "stage60_implementation_sha256": GET_SPECIES_NAME_STAGE60_SHA256,
        "stage61_implementation_sha256": GET_SPECIES_NAME_STAGE61_SHA256,
        "preimage_hex": GET_SPECIES_NAME_EARLY_EXIT_PREIMAGE.hex(),
        "replacement_hex": GET_SPECIES_NAME_EARLY_EXIT_REPLACEMENT.hex(),
        "canonical_table": {
            "address": f"0x{GET_SPECIES_NAME_TABLE:08X}",
            "path": GET_SPECIES_NAME_TABLE_PATH.as_posix(),
            "sha256": GET_SPECIES_NAME_TABLE_SHA256,
            "row_count": GET_SPECIES_NAME_TABLE_COUNT,
            "row_size": GET_SPECIES_NAME_TABLE_STRIDE,
            "all_rows_eos_padded": True,
        },
        "source_provenance": {
            "path": GET_SPECIES_NAME_SOURCE_PATH.as_posix(),
            "commit": GET_SPECIES_NAME_SOURCE_COMMIT,
            "sha256": GET_SPECIES_NAME_SOURCE_SHA256,
            "observed_behavior": "BREAK_AT_FIRST_EOS_LEAVES_TAIL_UNWRITTEN",
        },
        "assertions": {
            "thunk_and_thumb_target_exact": True,
            "stage60_early_exit_instruction_exact": True,
            "canonical_table_matches_generated_artifact": True,
            "all_1621_rows_are_fully_eos_padded": True,
            "replacement_is_thumb_nop": True,
            "visible_name_terminator_is_unchanged": True,
            "complete_implementation_postimage_sha256_pinned": True,
            "create_box_mon_short_name_tail_is_history_invariant": True,
        },
    }


def _apply_bg_numeric_zero_return_patch(
    stage60: bytes,
    output: bytearray,
    declared: list[dict[str, Any]],
) -> dict[str, Any]:
    """Make the stock BG-event numeric-zero path return a real NULL.

    Stage60's ``cmp r0, #0`` path loads an unrelated script pointer before the
    shared return branch.  A BG record normalized from 0x08000000 to numeric
    zero therefore still starts that script and can leave field input locked.
    Bind the fix to both the two-byte instruction and the adjacent branch: the
    replacement is exactly ``movs r0, #0`` and the existing return control flow
    must remain byte-identical.
    """

    patch_offset = BG_NUMERIC_ZERO_RETURN_PATCH_ADDRESS - GBA_BASE
    branch_offset = BG_NUMERIC_ZERO_RETURN_BRANCH_ADDRESS - GBA_BASE
    stage60_window = (
        BG_NUMERIC_ZERO_RETURN_PATCH_PREIMAGE
        + BG_NUMERIC_ZERO_RETURN_BRANCH_PREIMAGE
    )
    stage61_window = (
        BG_NUMERIC_ZERO_RETURN_PATCH_REPLACEMENT
        + BG_NUMERIC_ZERO_RETURN_BRANCH_PREIMAGE
    )
    if stage60[patch_offset:branch_offset + 2] != stage60_window:
        _fail(
            "BG numeric-zero return Stage60 instruction/branch preimage不一致: "
            f"{stage60[patch_offset:branch_offset + 2].hex()} != "
            f"{stage60_window.hex()}"
        )
    if bytes(output[patch_offset:branch_offset + 2]) != stage60_window:
        _fail("BG numeric-zero return patch前output preimage不一致")
    _apply_patch(
        stage60,
        output,
        declared,
        name="event_repair::bg_numeric_zero_returns_null_0806c908",
        offset=patch_offset,
        expected=BG_NUMERIC_ZERO_RETURN_PATCH_PREIMAGE,
        replacement=BG_NUMERIC_ZERO_RETURN_PATCH_REPLACEMENT,
        category="EVENT_BG_NULL_CONSUMER_ABI_REPAIR",
    )
    if bytes(output[patch_offset:branch_offset + 2]) != stage61_window:
        _fail("BG numeric-zero return patch後instruction/branch不一致")
    return {
        "repair_id": "BG_NUMERIC_ZERO_RETURNS_NULL_0806C908",
        "family": "BG_NUMERIC_ZERO_CONSUMER_RETURNS_UNRELATED_SCRIPT",
        "address": BG_NUMERIC_ZERO_RETURN_PATCH_ADDRESS,
        "expected_hex": BG_NUMERIC_ZERO_RETURN_PATCH_PREIMAGE.hex(),
        "replacement_hex": BG_NUMERIC_ZERO_RETURN_PATCH_REPLACEMENT.hex(),
        "preserved_return_branch_address": (
            BG_NUMERIC_ZERO_RETURN_BRANCH_ADDRESS
        ),
        "preserved_return_branch_hex": (
            BG_NUMERIC_ZERO_RETURN_BRANCH_PREIMAGE.hex()
        ),
        "stage60_instruction_and_branch_sha256": _sha(stage60_window),
        "stage61_instruction_and_branch_sha256": _sha(stage61_window),
        "previous_nonnull_fallback_pointer": "0x081A9CE3",
        "semantic_contract": "NUMERIC_ZERO_BG_RETURNS_NULL",
        "source_provenance": {
            "kind": (
                "PINNED_STAGE60_ENGINE_PREIMAGE_AND_UPSTREAM_SOURCE_"
                "CONTRACT"
            ),
            "stage60_rom_sha256": _sha(stage60),
            "source_path": EVENT_CONSUMER_SOURCE_CONTRACT["source_path"],
            "source_commit": EVENT_CONSUMER_SOURCE_CONTRACT["source_commit"],
            "source_sha256": EVENT_CONSUMER_SOURCE_CONTRACT["source_sha256"],
            "function": EVENT_CONSUMER_SOURCE_CONTRACT["bg_function"],
            "definition_line": EVENT_CONSUMER_SOURCE_CONTRACT[
                "bg_definition_line"
            ],
            "project_policy": EVENT_CONSUMER_SOURCE_CONTRACT[
                "project_policy"
            ],
        },
        "assertions": {
            "stage60_two_byte_preimage_exact": True,
            "stage60_adjacent_return_branch_exact": True,
            "stage61_r0_is_numeric_null_on_cmp_equal_path": True,
            "stage61_adjacent_return_branch_byte_identical": True,
            "only_two_instruction_bytes_replaced": True,
            "null_bg_interaction_start_suppressed": True,
        },
    }


def _apply_materialized_payload_patch(
    output: bytearray, declared: list[dict[str, Any]], *,
    name: str, offset: int, expected: bytes, replacement: bytes,
    category: str,
) -> None:
    """Patch a byte range already owned by the Stage61 payload declaration.

    Canonical map objects live inside the newly materialized payload, so their
    Stage60 bytes are deliberately FF and cannot be used as a second patch
    preimage.  Bind the repair to the exact current materialization bytes and
    retain it as a nested declaration under the one payload owner.  The final
    payload/allocation SHA is recomputed after every placement repair.
    """

    if len(expected) != len(replacement):
        _fail(f"{name}: materialized patch length不一致")
    if bytes(output[offset:offset + len(expected)]) != expected:
        _fail(
            f"{name}: materialized current preimage不一致 at {offset:#x}"
        )
    owners = [
        row for row in declared
        if row["category"] == "PAYLOAD"
        and int(row["start"]) <= offset
        and offset + len(replacement) <= int(row["end_exclusive"])
    ]
    if len(owners) != 1:
        _fail(
            f"{name}: materialized payload ownerが一意ではありません: "
            f"{[row['name'] for row in owners]}"
        )
    output[offset:offset + len(replacement)] = replacement
    owners[0].setdefault("nested_repairs", []).append({
        "name": name, "category": category, "start": offset,
        "end_exclusive": offset + len(replacement),
        "size": len(replacement), "expected_hex": expected.hex(),
        "replacement_hex": replacement.hex(),
    })


def _decode_event_tiles(state: Mapping[str, Any]) -> tuple[list[dict[str, int]], set[tuple[int, int]]]:
    warps_raw = bytes.fromhex(str(state["warps_hex"]))
    coords_raw = bytes.fromhex(str(state["coords_hex"]))
    bg_raw = bytes.fromhex(str(state["bg_hex"]))
    warps: list[dict[str, int]] = []
    reserved: set[tuple[int, int]] = set()
    for index in range(int(state["counts"]["warps"])):
        x, y = struct.unpack_from("<hh", warps_raw, index * 8)
        warps.append({"x": x, "y": y})
        reserved.add((x, y))
    for index in range(int(state["counts"]["coords"])):
        reserved.add(struct.unpack_from("<HH", coords_raw, index * 16))
    for index in range(int(state["counts"]["bg"])):
        reserved.add(struct.unpack_from("<HH", bg_raw, index * 12))
    return warps, reserved


def _archive_placements(
    stage60: bytes, canonical: Sequence[Mapping[str, Any]],
    trainer_plan: Mapping[str, Any],
) -> tuple[list[dict[str, Any]], dict[tuple[int, int, int], ConversationPlacement]]:
    catalog = {str(row["map_header"]["map_key"]): row for row in canonical}
    by_map: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for binding in trainer_plan["bindings"]:
        if binding.get("owner_kind") == "ARCHIVE":
            by_map[str(binding["map_key"])].append(dict(binding))
    if sum(map(len, by_map.values())) != 71:
        _fail("Trainer Archive bindingは71件である必要があります")
    # Reuse the same exact reverse producer model as the final product gate.
    # A map's own WarpEvent and outgoing connection are not entrances, and a
    # connection must contribute only its offset-transformed foreign arrival
    # tiles.  This closes the old generator/final-audit split where Archive
    # placement could be built using four guessed borders and pass only due to
    # a later, stricter audit.
    coords = _all_coordinates(canonical)
    scripted_entries, _stored_warp_producers = _scripted_entry_producers(
        stage60, coords,
    )
    connection_entries = _connection_entry_producers(stage60, coords)
    locally_seeded_maps: set[tuple[int, int]] = set()
    for group, number, _map_key in coords:
        try:
            entry_state = _stage_map_state(stage60, group, number)
            entry_geometry = _map_geometry(stage60, group, number)
        except RuntimeError:
            continue
        entry_seeds, _entry_report, _reserved = _map_entry_seeds(
            stage60, group, number, entry_state, entry_geometry,
            coords, scripted_entries, connection_entries,
        )
        if entry_seeds:
            locally_seeded_maps.add((group, number))
    engine_entries = _native_local_entry_producers(
        stage60, coords, locally_seeded_maps,
    )
    reports: list[dict[str, Any]] = []
    placements_by_local: dict[tuple[int, int, int], ConversationPlacement] = {}
    for map_key, bindings in sorted(by_map.items()):
        row = catalog[map_key]
        header = row["map_header"]
        group, number = int(header["group_id"]), int(header["map_id"])
        state = _stage_map_state(stage60, group, number)
        width, height, blocks = _layout_blockdata(ROOT, row)
        geometry = _map_geometry(stage60, group, number)
        if (width, height, tuple(blocks)) != (
            int(geometry["width"]), int(geometry["height"]),
            tuple(int(value) for value in geometry["blocks"]),
        ):
            _fail(
                f"Archive source recipe/final layout drift: {map_key}"
            )
        archive_ids = {int(binding["local_ids"][0]) for binding in bindings}
        decoded = [_object_fields(raw) for raw in state["objects"]]
        objects_offset = _rom_offset(
            int(state["pointers"]["objects"]),
            len(state["objects"]) * 24, f"object array {group}/{number}",
        )
        fixed = {(item["x"], item["y"]) for item in decoded
                 if item["local_id"] not in archive_ids}
        seeds, entry_report, reserved = _map_entry_seeds(
            stage60, group, number, state, geometry,
            coords, scripted_entries, connection_entries, engine_entries,
        )
        if not seeds:
            _fail(f"Archive mapにlocal exact incoming seedがありません: {map_key}")
        ordered = sorted(bindings, key=lambda item: int(item["archive_index"]))
        origins: list[tuple[int, int]] = []
        for binding in ordered:
            local_id = int(binding["local_ids"][0])
            matches = [item for item in decoded if item["local_id"] == local_id]
            if len(matches) != 1:
                _fail(f"Archive object不一致: {group}/{number} local={local_id}")
            origins.append((matches[0]["x"], matches[0]["y"]))
        placements = allocate_objects_with_stances(
            blocks, width, height, seeds, fixed, origins,
            reserved_tiles=reserved, elevation=3,
        )
        audit = audit_conversation_placements(
            blocks, width, height, seeds, fixed, placements,
            reserved_tiles=reserved, elevation=3,
        )
        if audit["status"] != "PASS":
            _fail(f"Archive最終配置audit FAIL: {map_key}: {audit}")
        object_rows = []
        for binding, origin, placement in zip(ordered, origins, placements, strict=True):
            local_id = int(binding["local_ids"][0])
            placements_by_local[(group, number, local_id)] = placement
            object_rows.append({
                "archive_index": int(binding["archive_index"]),
                "encounter_key": str(binding["encounter_key"]),
                "local_id": local_id, "before": list(origin),
                "after": list(placement.object_tile),
                "conversation_stance": list(placement.stance_tile),
            })
        reports.append({
            "map_key": map_key, "group": group, "map": number,
            "status": "PASS", "objects": object_rows, "final_audit": audit,
            "entry": entry_report,
            "entry_basis": (
                "EXACT_REVERSE_INCOMING_WARP_CONNECTION_SCRIPT_NATIVE"
            ),
        })
    if len(placements_by_local) != 71:
        _fail("Archive最終配置結果は71件である必要があります")
    return reports, placements_by_local


def _decode_map_layout_geometry(
    rom: bytes, *, header: int, layout_pointer: int,
    layout_id: int, layout_basis: str, label: str,
) -> dict[str, Any]:
    """Decode one exact final-ROM layout selected by the field engine."""

    layout = _rom_offset(layout_pointer, 0x1A, f"map layout {label}")
    width = _u32(rom, layout, f"map width {label}")
    height = _u32(rom, layout + 4, f"map height {label}")
    if not 0 < width <= 1024 or not 0 < height <= 1024 \
            or width * height > 0x100000:
        _fail(f"map layout dimensions不正: {label}: {width}x{height}")
    blocks_pointer = _u32(rom, layout + 12, f"map blocks {label}")
    blocks_offset = _rom_offset(
        blocks_pointer, width * height * 2, f"map blocks {label}"
    )
    blocks = struct.unpack_from(f"<{width * height}H", rom, blocks_offset)
    attribute_offsets: list[int] = []
    for tileset_label, pointer_site in (
        ("primary", layout + 16), ("secondary", layout + 20),
    ):
        tileset_pointer = _u32(
            rom, pointer_site, f"{tileset_label} tileset {layout_id}",
        )
        tileset = _rom_offset(
            tileset_pointer, 0x18, f"{tileset_label} tileset {layout_id}",
        )
        attributes_pointer = _u32(
            rom, tileset + 20,
            f"{tileset_label} metatile attributes {layout_id}",
        )
        attribute_offsets.append(_rom_offset(
            attributes_pointer, 640 * 4,
            f"{tileset_label} metatile attributes {layout_id}",
        ))
    behaviors: list[int] = []
    for block in blocks:
        metatile = block & 0x3FF
        table = attribute_offsets[0] if metatile < 640 else attribute_offsets[1]
        index = metatile if metatile < 640 else metatile - 640
        behaviors.append(_u32(
            rom, table + index * 4,
            f"metatile behavior {layout_id}/{metatile}",
        ) & 0x1FF)
    layout_raw = rom[layout:layout + 0x1C]
    blocks_raw = rom[blocks_offset:blocks_offset + width * height * 2]
    behavior_raw = struct.pack(f"<{len(behaviors)}H", *behaviors)
    return {
        "header": header, "layout_address": layout_pointer,
        "layout_id": layout_id, "layout_basis": layout_basis,
        "layout_struct_sha256": _sha(layout_raw),
        "blocks_address": blocks_pointer,
        "blocks_sha256": _sha(blocks_raw),
        "behaviors_u16le_sha256": _sha(behavior_raw),
        "width": width, "height": height, "blocks": blocks,
        "behaviors": tuple(behaviors),
    }


def _map_geometry(
    rom: bytes, group: int, number: int,
) -> dict[str, Any]:
    """Decode the map-header default layout and its collision geometry."""

    header = _map_header_offset(rom, group, number)
    layout_pointer = _u32(rom, header, f"map layout {group}/{number}")
    layout_id = struct.unpack_from("<H", rom, header + 0x12)[0]
    if layout_id == 0:
        _fail(f"map header layout IDがzeroです: {group}/{number}")
    return _decode_map_layout_geometry(
        rom, header=header, layout_pointer=layout_pointer,
        layout_id=layout_id, layout_basis="MAP_HEADER_DEFAULT",
        label=f"{group}/{number}/layout-{layout_id}",
    )


def _map_geometry_from_layout_id(
    rom: bytes, group: int, number: int, layout_id: int,
) -> dict[str, Any]:
    """Resolve an engine-selected layout through final-ROM gMapLayouts."""

    if isinstance(layout_id, bool) or not isinstance(layout_id, int) \
            or not 1 <= layout_id <= 0xFFFF:
        _fail(f"map layout ID不正: {layout_id!r}")
    header = _map_header_offset(rom, group, number)
    table_pointer = _u32(
        rom, MAP_LAYOUTS_POINTER_SITE, "gMapLayouts pointer",
    )
    table_offset = _rom_offset(
        table_pointer, layout_id * 4,
        f"gMapLayouts table layout {layout_id}",
    )
    layout_pointer = _u32(
        rom, table_offset + (layout_id - 1) * 4,
        f"gMapLayouts[{layout_id}]",
    )
    return _decode_map_layout_geometry(
        rom, header=header, layout_pointer=layout_pointer,
        layout_id=layout_id,
        layout_basis="STATE_VARIANT_GMAPLAYOUTS_ID",
        label=f"{group}/{number}/layout-{layout_id}",
    )


def _collision_zero(geometry: Mapping[str, Any], point: tuple[int, int]) -> bool:
    x, y = point
    width, height = int(geometry["width"]), int(geometry["height"])
    if not 0 <= x < width or not 0 <= y < height:
        return False
    return ((int(geometry["blocks"][y * width + x]) >> 10) & 3) == 0


def _in_map_bounds(
    geometry: Mapping[str, Any], point: tuple[int, int],
) -> bool:
    x, y = point
    return (
        0 <= x < int(geometry["width"])
        and 0 <= y < int(geometry["height"])
    )


def _cell_evidence(
    geometry: Mapping[str, Any], point: tuple[int, int],
    reserved: set[tuple[int, int]], permanent: set[tuple[int, int]],
) -> dict[str, Any]:
    x, y = point
    width, height = int(geometry["width"]), int(geometry["height"])
    if not 0 <= x < width or not 0 <= y < height:
        return {"point": [x, y], "in_bounds": False}
    block = int(geometry["blocks"][y * width + x])
    return {
        "point": [x, y], "in_bounds": True,
        "metatile": block & 0x3FF,
        "collision": (block >> 10) & 3,
        "elevation": (block >> 12) & 0xF,
        "behavior": int(geometry["behaviors"][y * width + x]),
        "reserved_event_tile": point in reserved,
        "permanent_object_tile": point in permanent,
    }


def _decode_connection_rows(
    rom: bytes, group: int, number: int,
) -> list[dict[str, Any]]:
    """Decode the exact MapConnection rows owned by one physical map."""

    header = _map_header_offset(rom, group, number)
    pointer = _u32(rom, header + 12, f"map connections {group}/{number}")
    if pointer in (0, 0xFFFFFFFF):
        return []
    at = _rom_offset(pointer, 8, f"map connections {group}/{number}")
    count = struct.unpack_from("<i", rom, at)[0]
    if not 0 <= count <= 64:
        _fail(f"map connection count不正: {group}/{number}: {count}")
    if count == 0:
        return []
    rows_pointer = _u32(rom, at + 4, f"map connection rows {group}/{number}")
    rows_at = _rom_offset(
        rows_pointer, count * 12, f"map connection rows {group}/{number}"
    )
    result: list[dict[str, Any]] = []
    for index in range(count):
        row_at = rows_at + index * 12
        direction = rom[row_at]
        if direction not in {1, 2, 3, 4, 5, 6}:
            _fail(
                f"map connection direction不正: "
                f"{group}/{number}/{index}: {direction}"
            )
        result.append({
            "source": [group, number], "index": index,
            "row_address": f"0x{GBA_BASE + row_at:08X}",
            "row_raw_hex": rom[row_at:row_at + 12].hex(),
            "direction": direction,
            "offset": struct.unpack_from("<i", rom, row_at + 4)[0],
            "target": [rom[row_at + 8], rom[row_at + 9]],
        })
    return result


def _connection_entry_producers(
    rom: bytes, coords: Sequence[tuple[int, int, str]],
) -> dict[tuple[int, int], list[dict[str, Any]]]:
    """Reverse-index exact foreign connection rows and arrival transforms.

    A connection stored on the current map is an *outgoing* edge and cannot
    prove that the player can enter that same map.  The only static evidence is
    a row stored on a foreign map whose target is the current map.  The
    coordinate transform below is the inverse of fieldmap.c's
    ``SetPositionFromConnection``: destination_axis = source_axis - offset,
    and the destination boundary is the side opposite the foreign direction.
    """

    map_keys = {(group, number): key for group, number, key in coords}
    geometry_cache: dict[tuple[int, int], dict[str, Any]] = {}

    def geometry(group: int, number: int) -> dict[str, Any]:
        key = (group, number)
        if key not in geometry_cache:
            geometry_cache[key] = _map_geometry(rom, group, number)
        return geometry_cache[key]

    all_rows: dict[tuple[int, int], list[dict[str, Any]]] = {}
    for group, number, _ in coords:
        all_rows[(group, number)] = _decode_connection_rows(
            rom, group, number,
        )
    opposite = {1: 2, 2: 1, 3: 4, 4: 3, 5: 6, 6: 5}
    result: dict[tuple[int, int], list[dict[str, Any]]] = defaultdict(list)
    for (source_group, source_map), rows in sorted(all_rows.items()):
        source_geometry = geometry(source_group, source_map)
        source_width = int(source_geometry["width"])
        source_height = int(source_geometry["height"])
        for row in rows:
            target_group, target_map = map(int, row["target"])
            target_key = (target_group, target_map)
            if target_key not in map_keys:
                _fail(
                    "map connectionの物理targetがinventory外です: "
                    f"{source_group}/{source_map}/{row['index']} -> "
                    f"{target_group}/{target_map}"
                )
            target_geometry = geometry(target_group, target_map)
            target_width = int(target_geometry["width"])
            target_height = int(target_geometry["height"])
            direction = int(row["direction"])
            offset = int(row["offset"])
            candidates: list[dict[str, Any]] = []
            if direction in {1, 2}:  # SOUTH/NORTH: x is translated.
                source_y = source_height - 1 if direction == 1 else 0
                target_y = 0 if direction == 1 else target_height - 1
                for source_x in range(source_width):
                    target_x = source_x - offset
                    if not 0 <= target_x < target_width:
                        continue
                    source_point = (source_x, source_y)
                    target_point = (target_x, target_y)
                    candidates.append({
                        "source_boundary_tile": list(source_point),
                        "arrival_tile": list(target_point),
                        "source_collision_zero": _collision_zero(
                            source_geometry, source_point,
                        ),
                        "target_collision_zero": _collision_zero(
                            target_geometry, target_point,
                        ),
                    })
            elif direction in {3, 4}:  # WEST/EAST: y is translated.
                source_x = 0 if direction == 3 else source_width - 1
                target_x = target_width - 1 if direction == 3 else 0
                for source_y in range(source_height):
                    target_y = source_y - offset
                    if not 0 <= target_y < target_height:
                        continue
                    source_point = (source_x, source_y)
                    target_point = (target_x, target_y)
                    candidates.append({
                        "source_boundary_tile": list(source_point),
                        "arrival_tile": list(target_point),
                        "source_collision_zero": _collision_zero(
                            source_geometry, source_point,
                        ),
                        "target_collision_zero": _collision_zero(
                            target_geometry, target_point,
                        ),
                    })
            usable = [
                item for item in candidates
                if item["source_collision_zero"]
                and item["target_collision_zero"]
            ]
            reciprocal = [
                candidate for candidate in all_rows[target_key]
                if int(candidate["direction"]) == opposite[direction]
                and int(candidate["offset"]) == -offset
                and tuple(map(int, candidate["target"]))
                == (source_group, source_map)
            ]
            result[target_key].append({
                **row,
                "source_map_key": map_keys[(source_group, source_map)],
                "target_map_key": map_keys[target_key],
                "opposite_arrival_direction": opposite[direction],
                "candidate_count": len(candidates),
                "usable_arrival_count": len(usable),
                "arrival_tiles": [item["arrival_tile"] for item in usable],
                "coordinate_evidence": candidates,
                "reciprocal_exact_row_addresses": [
                    item["row_address"] for item in reciprocal
                ],
                "seed_basis": (
                    "FOREIGN_ROW_TARGETS_CURRENT_AND_EXACT_"
                    "SET_POSITION_FROM_CONNECTION_INVERSE"
                    if direction in {1, 2, 3, 4}
                    else "DIVE_EMERGE_HAS_NO_STATIC_BOUNDARY_SEED"
                ),
                "engine_source": {
                    "path": "vendor/upstream/pokefirered/src/fieldmap.c",
                    "function": "SetPositionFromConnection",
                    "sha256": _sha((
                        ROOT / "vendor/upstream/pokefirered/src/fieldmap.c"
                    ).read_bytes()),
                },
            })
    for rows in result.values():
        rows.sort(key=lambda item: (
            tuple(item["source"]), int(item["index"]),
        ))
    return dict(result)


def _map_entry_seeds(
    rom: bytes, group: int, number: int, state: Mapping[str, Any],
    geometry: Mapping[str, Any],
    coords: Sequence[tuple[int, int, str]],
    scripted_entries: Mapping[tuple[int, int], Sequence[Mapping[str, Any]]],
    connection_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    engine_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ] | None = None,
) -> tuple[set[tuple[int, int]], dict[str, Any], set[tuple[int, int]]]:
    warps, reserved = _decode_event_tiles(state)
    warp_seeds: set[tuple[int, int]] = set()
    incoming_rows: list[dict[str, Any]] = []
    # WarpEvent rows on this map are outgoing triggers, not evidence that the
    # player can appear there.  Only a structurally decoded foreign row whose
    # destination map and warpId select this exact current-map row may seed the
    # entrance component.  Adjacent tiles are deliberately not broadened.
    for source_group, source_map, source_key in coords:
        try:
            source_state = _stage_map_state(
                rom, source_group, source_map,
            )
        except RuntimeError:
            continue
        raw = bytes.fromhex(str(source_state["warps_hex"]))
        for source_index in range(int(source_state["counts"]["warps"])):
            at = source_index * 8
            destination_warp = raw[at + 5]
            destination_map = raw[at + 6]
            destination_group = raw[at + 7]
            if (destination_group, destination_map) != (group, number):
                continue
            source_x, source_y = struct.unpack_from("<hh", raw, at)
            source_geometry = _map_geometry(
                rom, source_group, source_map,
            )
            source_point = (source_x, source_y)
            source_in_bounds = _in_map_bounds(
                source_geometry, source_point,
            )
            source_collision_zero = (
                source_in_bounds
                and _collision_zero(source_geometry, source_point)
            )
            source_behavior = (
                int(source_geometry["behaviors"][
                    source_y * int(source_geometry["width"]) + source_x
                ]) if source_in_bounds else -1
            )
            all_source_predecessors = [
                point for point in (
                    (source_x, source_y - 1),
                    (source_x - 1, source_y),
                    (source_x + 1, source_y),
                    (source_x, source_y + 1),
                )
                if _collision_zero(source_geometry, point)
            ]
            # field_control_avatar.c accepts only a concrete warp metatile.
            # MB_WARP_DOOR (0x69) is the one collision-bearing exception:
            # holding North from the tile immediately south invokes
            # TryDoorWarp against the impassable door.  Every other static
            # warp family is step/current-tile based and therefore requires a
            # collision-zero event tile plus a collision-zero predecessor.
            warp_behaviors = set(range(0x60, 0x70)) | {0x71}
            source_predecessors = (
                [(source_x, source_y + 1)]
                if source_behavior == 0x69
                and _collision_zero(
                    source_geometry, (source_x, source_y + 1),
                ) else all_source_predecessors
            )
            source_trigger_usable = bool(source_predecessors) and (
                source_behavior == 0x69
                or (
                    source_behavior in warp_behaviors
                    and source_collision_zero
                )
            )
            if destination_warp >= len(warps):
                center = (
                    int(geometry["width"]) // 2,
                    int(geometry["height"]) // 2,
                )
                usable = _in_map_bounds(geometry, center)
                if usable and source_trigger_usable:
                    warp_seeds.add(center)
                incoming_rows.append({
                    "source": [source_group, source_map, source_index],
                    "source_map_key": source_key,
                    "source_trigger_tile": list(source_point),
                    "source_trigger_in_bounds": source_in_bounds,
                    "source_trigger_collision_zero": source_collision_zero,
                    "source_trigger_behavior": source_behavior,
                    "source_predecessor_tiles": [
                        list(point) for point in source_predecessors
                    ],
                    "source_trigger_usable": source_trigger_usable,
                    "destination_warp_id": destination_warp,
                    "arrival_tile": list(center),
                    "in_bounds": usable,
                    "collision_zero": _collision_zero(geometry, center),
                    "seed_basis": (
                        "ENGINE_INVALID_WARP_ID_WITH_NEGATIVE_XY_"
                        "FALLS_BACK_TO_MAP_CENTER"
                    ),
                })
                continue
            target = (
                int(warps[destination_warp]["x"]),
                int(warps[destination_warp]["y"]),
            )
            usable = _in_map_bounds(geometry, target)
            if usable and source_trigger_usable:
                warp_seeds.add(target)
            incoming_rows.append({
                "source": [source_group, source_map, source_index],
                "source_map_key": source_key,
                "source_trigger_tile": list(source_point),
                "source_trigger_in_bounds": source_in_bounds,
                "source_trigger_collision_zero": source_collision_zero,
                "source_trigger_behavior": source_behavior,
                "source_predecessor_tiles": [
                    list(point) for point in source_predecessors
                ],
                "source_trigger_usable": source_trigger_usable,
                "destination_warp_id": destination_warp,
                "arrival_tile": list(target),
                "in_bounds": usable,
                "collision_zero": _collision_zero(geometry, target),
                "seed_basis": (
                    "EXACT_INCOMING_WARP_DESTINATION_ROW"
                ),
            })
    connections = [
        dict(row) for row in connection_entries.get((group, number), [])
    ]
    connection_seeds = {
        tuple(map(int, point))
        for row in connections for point in row["arrival_tiles"]
    }
    scripted_seeds: set[tuple[int, int]] = set()
    scripted_rows: list[dict[str, Any]] = []
    for producer in scripted_entries.get((group, number), []):
        if str(producer.get("opcode")) == "0x3C":
            # warphole derives the destination coordinates from the live
            # player position (or a previously populated fixed-hole slot).
            # The literal target map proves a transition edge, but it cannot
            # prove one exact arrival component without a concrete origin
            # state/input trace.
            scripted_rows.append({
                **dict(producer), "arrival_tile": None,
                "collision_zero": False,
                "seed_basis": (
                    "WARPHOLE_PLAYER_POSITION_REQUIRES_EXACT_ORIGIN_TRACE"
                ),
            })
            continue
        warp_id = int(producer["warp_id"])
        x_operand, y_operand = (
            int(producer["x_operand"]), int(producer["y_operand"]),
        )
        if 0 <= warp_id < len(warps):
            point = (
                int(warps[warp_id]["x"]), int(warps[warp_id]["y"]),
            )
            basis = "SCRIPT_EXACT_DESTINATION_WARP_ID"
        elif x_operand < 0x4000 and y_operand < 0x4000:
            point = (x_operand, y_operand)
            basis = "SCRIPT_EXACT_LITERAL_DESTINATION_COORDINATES"
        elif x_operand == 0xFFFF and y_operand == 0xFFFF:
            point = (
                int(geometry["width"]) // 2,
                int(geometry["height"]) // 2,
            )
            basis = "SCRIPT_NEGATIVE_COORDINATES_MAP_CENTER_FALLBACK"
        else:
            scripted_rows.append({
                **dict(producer), "arrival_tile": None,
                "collision_zero": False,
                "seed_basis": "VARIABLE_DESTINATION_NOT_A_STATIC_SEED",
            })
            continue
        usable = _in_map_bounds(geometry, point)
        if usable:
            scripted_seeds.add(point)
        scripted_rows.append({
            **dict(producer), "arrival_tile": list(point),
            "in_bounds": usable,
            "collision_zero": _collision_zero(geometry, point),
            "seed_basis": basis,
        })
    engine_seeds: set[tuple[int, int]] = set()
    engine_rows: list[dict[str, Any]] = []
    for producer in (engine_entries or {}).get((group, number), []):
        point_raw = producer.get("arrival_tile")
        if not isinstance(point_raw, list) or len(point_raw) != 2:
            _fail(f"engine entry arrival tile不正: {group}/{number}: {producer}")
        point = tuple(map(int, point_raw))
        usable = _in_map_bounds(geometry, point)
        if usable:
            engine_seeds.add(point)
        engine_rows.append({
            **dict(producer), "in_bounds": usable,
            "collision_zero": _collision_zero(geometry, point),
        })
    seeds = warp_seeds | connection_seeds | scripted_seeds | engine_seeds
    return seeds, {
        "reachability_scope": "STRUCTURAL_EXACT_INCOMING_CANDIDATE_NOT_GLOBAL_ROOT",
        "globally_reachable_from_new_game": None,
        "warp_count": len(warps), "incoming_warp_reference_count": len(incoming_rows),
        "invalid_or_dynamic_incoming_warp_count": sum(
            row["seed_basis"].startswith("ENGINE_INVALID_WARP_ID")
            for row in incoming_rows
        ),
        "unusable_source_trigger_incoming_warp_count": sum(
            not row["source_trigger_usable"] for row in incoming_rows
        ),
        "warp_seed_count": len(warp_seeds), "incoming_warps": incoming_rows,
        "connection_count": len(connections),
        "connection_seed_count": len(connection_seeds),
        "connections": connections,
        "scripted_entry_producer_count": len(scripted_rows),
        "scripted_entry_seed_count": len(scripted_seeds),
        "scripted_entries": scripted_rows,
        "engine_entry_producer_count": len(engine_rows),
        "engine_entry_seed_count": len(engine_seeds),
        "engine_entries": engine_rows,
        "seed_count": len(seeds),
    }, reserved


def _map_event_script_roots(
    rom: bytes, group: int, number: int, state: Mapping[str, Any],
    *, tolerate_invalid_map_script_table: bool = False,
) -> list[dict[str, Any]]:
    """Return every explicitly rooted event script for one physical map.

    The map-script table has a different ABI from event bytecode.  Decode its
    1..7 tags and conditional tables structurally; never resynchronise through
    an invalid tag or scan ROM bytes for a plausible pointer.
    """

    roots: list[dict[str, Any]] = []
    for index, raw in enumerate(state["objects"]):
        pointer = struct.unpack_from("<I", raw, 16)[0]
        if pointer:
            roots.append({
                "label": f"OBJECT:{index}", "kind": "OBJECT",
                "index": index, "pointer": pointer,
            })
    coords = bytes.fromhex(str(state["coords_hex"]))
    for index in range(int(state["counts"]["coords"])):
        pointer = struct.unpack_from("<I", coords, index * 16 + 12)[0]
        if pointer:
            roots.append({
                "label": f"COORD:{index}", "kind": "COORD",
                "index": index, "pointer": pointer,
            })
    backgrounds = bytes.fromhex(str(state["bg_hex"]))
    for index in range(int(state["counts"]["bg"])):
        at = index * 12
        kind = backgrounds[at + 5]
        pointer = struct.unpack_from("<I", backgrounds, at + 8)[0]
        if kind not in {7, 8} and pointer:
            roots.append({
                "label": f"BG:{index}", "kind": "BG",
                "index": index, "pointer": pointer,
            })

    header = _map_header_offset(rom, group, number)
    table_pointer = _u32(rom, header + 8, f"map script table {group}/{number}")
    if table_pointer not in {0, 0xFFFFFFFF}:
        cursor = _rom_offset(
            table_pointer, 1, f"map script table {group}/{number}",
        )
        for table_index in range(64):
            script_type = rom[cursor]
            if script_type == 0:
                break
            if script_type not in range(1, 8):
                if tolerate_invalid_map_script_table:
                    break
                _fail(
                    f"map script table tag不正: {group}/{number} "
                    f"index={table_index} type={script_type}"
                )
            target = _u32(
                rom, cursor + 1,
                f"map script target {group}/{number}/{table_index}",
            )
            if script_type in {2, 4}:
                condition = _rom_offset(
                    target, 2,
                    f"conditional map script {group}/{number}/{table_index}",
                )
                for condition_index in range(256):
                    variable = struct.unpack_from("<H", rom, condition)[0]
                    if variable == 0:
                        break
                    pointer = _u32(
                        rom, condition + 4,
                        f"conditional map script target "
                        f"{group}/{number}/{table_index}/{condition_index}",
                    )
                    roots.append({
                        "label": (
                            f"MAP_SCRIPT:{script_type}:{table_index}:"
                            f"{condition_index}"
                        ),
                        "kind": "MAP_SCRIPT_CONDITION",
                        "index": condition_index, "pointer": pointer,
                    })
                    condition += 8
                else:
                    _fail(f"conditional map script終端なし: {group}/{number}")
            else:
                roots.append({
                    "label": f"MAP_SCRIPT:{script_type}:{table_index}",
                    "kind": "MAP_SCRIPT", "index": table_index,
                    "pointer": target,
                })
            cursor += 5
        else:
            _fail(f"map script table終端なし: {group}/{number}")
    return roots


def _scripted_entry_producers(
    rom: bytes, coords: Sequence[tuple[int, int, str]],
) -> tuple[
    dict[tuple[int, int], list[dict[str, Any]]],
    dict[tuple[int, int], list[dict[str, Any]]],
]:
    """Index immediate transitions separately from stored warp producers.

    ``setwarp``/``setdynamicwarp``/``setdivewarp``/``setholewarp`` and
    ``setescapewarp`` only mutate a future destination slot.  Treating their
    operands as an immediate player arrival was the same category error as
    treating an outgoing ``MAP_DYNAMIC`` WarpEvent as an incoming entrance.
    Keep those rows as typed producer evidence, but only the opcodes that call
    a field transition in the same command are permitted to seed a map.
    """

    root_provenance: dict[int, list[dict[str, Any]]] = defaultdict(list)
    for group, number, map_key in coords:
        try:
            state = _stage_map_state(rom, group, number)
        except RuntimeError:
            continue
        for root in _map_event_script_roots(
            rom, group, number, state,
            tolerate_invalid_map_script_table=True,
        ):
            root_provenance[int(root["pointer"])].append({
                "map": [group, number], "map_key": map_key,
                "root_label": str(root["label"]),
                "root_kind": str(root["kind"]),
            })
    graph = SemanticScriptGraph(rom)
    graph.walk(root_provenance)
    if graph.diagnostics:
        _fail(f"scripted entry CFG diagnostics: {graph.diagnostics[:8]}")
    immediate: dict[tuple[int, int], list[dict[str, Any]]] = defaultdict(list)
    stored: dict[tuple[int, int], list[dict[str, Any]]] = defaultdict(list)
    immediate_opcodes = {0x39, 0x3A, 0x3B, 0x3C, 0x3D, 0xD1}
    stored_families = {
        0x3E: "PENDING_WARP_DESTINATION",
        0x3F: "DYNAMIC_WARP_SLOT",
        0x40: "FIXED_DIVE_WARP_SLOT",
        0x41: "FIXED_HOLE_WARP_SLOT",
        0xC4: "ESCAPE_WARP_SLOT",
    }
    seen: set[tuple[int, int, int, int, int, int]] = set()
    for node in graph.nodes.values():
        for instruction in node.instructions:
            if instruction.opcode not in immediate_opcodes \
                    and instruction.opcode not in stored_families:
                continue
            if instruction.opcode == 0x3C:
                if len(instruction.raw) != 3:
                    _fail("warphole opcode length drift")
                target_group, target_map = instruction.raw[1:3]
                warp_id = 0xFF
                x_operand = y_operand = 0xFFFF
            else:
                if len(instruction.raw) != 8:
                    _fail(
                        f"warp producer opcode length drift: "
                        f"{instruction.opcode:#04x}/{len(instruction.raw)}"
                    )
                target_group = instruction.raw[1]
                target_map = instruction.raw[2]
                warp_id = instruction.raw[3]
                x_operand, y_operand = struct.unpack_from(
                    "<HH", instruction.raw, 4,
                )
            key = (
                instruction.address, target_group, target_map, warp_id,
                x_operand, y_operand,
            )
            if key in seen:
                continue
            seen.add(key)
            reachable_roots = sorted(
                root for root in root_provenance
                if node.address in graph.distances(root)
            )
            family = (
                "IMMEDIATE_FIELD_TRANSITION"
                if instruction.opcode in immediate_opcodes else
                stored_families[instruction.opcode]
            )
            row = {
                "instruction_address": f"0x{instruction.address:08X}",
                "opcode": f"0x{instruction.opcode:02X}",
                "opcode_name": OPCODE_NAMES.get(
                    instruction.opcode, f"opcode_{instruction.opcode:02X}"
                ),
                "raw_hex": instruction.raw.hex(),
                "warp_id": warp_id,
                "x_operand": x_operand, "y_operand": y_operand,
                "reachable_root_addresses": [
                    f"0x{root:08X}" for root in reachable_roots
                ],
                "root_provenance": [
                    row for root in reachable_roots
                    for row in root_provenance[root]
                ],
                "producer_family": family,
                "immediate_transition": instruction.opcode in immediate_opcodes,
                "basis": (
                    "LIVE_STAGE61_MAP_ROOT_CFG_IMMEDIATE_TRANSITION_OPERANDS"
                    if instruction.opcode in immediate_opcodes else
                    "LIVE_STAGE61_MAP_ROOT_CFG_STORED_WARP_PRODUCER_OPERANDS"
                ),
            }
            target = immediate if instruction.opcode in immediate_opcodes else stored
            target[(target_group, target_map)].append(row)
    for rows in (*immediate.values(), *stored.values()):
        rows.sort(key=lambda row: str(row["instruction_address"]))
    return dict(immediate), dict(stored)


def _native_local_entry_producers(
    rom: bytes, coords: Sequence[tuple[int, int, str]],
    locally_seeded_maps: set[tuple[int, int]],
) -> dict[tuple[int, int], list[dict[str, Any]]]:
    """Resolve native/table-driven destinations from locally seeded roots.

    The Seagallop transition is not an event ``warp`` opcode: event special
    379 enters ``Task_Seagallop_3``, which indexes the fixed 11-row ``sSeag``
    table and calls SetWarpDestination.  Treating only event opcodes therefore
    falsely labels the island harbors as orphaned.  Bind all three layers -- a
    reachable special site, the exact native consumer, and the exact table --
    before admitting any arrival seed.
    """

    seagallop_special = 379
    table_address = 0x08434784
    table_offset = table_address - GBA_BASE
    table_size = 11 * 4
    expected_table = bytes.fromhex(
        "03051720200408052104080526000805230508052402080525020805"
        "1f06080503081507023b0805023a0805"
    )
    if rom[table_offset:table_offset + table_size] != expected_table:
        _fail("Seagallop native destination table preimage不一致")
    native_address = 0x08147730
    native_raw = rom[
        native_address - GBA_BASE:native_address - GBA_BASE + 0x68
    ]
    expected_native_sha256 = (
        "b71350bd094769a8e3c7ecc3fad894f719fa62bc9a796eb5cc19865e2673f86d"
    )
    if len(native_raw) != 0x68 or _sha(native_raw) != expected_native_sha256:
        _fail("Seagallop native consumer prefix SHA-256不一致")
    literal_site = 0x081477A0
    if _u32(rom, literal_site - GBA_BASE, "sSeag literal") != table_address:
        _fail("Seagallop native consumer table pointer不一致")

    root_provenance: dict[int, list[dict[str, Any]]] = defaultdict(list)
    for group, number, map_key in coords:
        try:
            state = _stage_map_state(rom, group, number)
        except RuntimeError:
            continue
        for root in _map_event_script_roots(
            rom, group, number, state,
            tolerate_invalid_map_script_table=True,
        ):
            root_provenance[int(root["pointer"])].append({
                "map": [group, number], "map_key": map_key,
                "root_label": str(root["label"]),
                "root_kind": str(root["kind"]),
            })
    graph = SemanticScriptGraph(rom)
    graph.walk(root_provenance)
    if graph.diagnostics:
        _fail(f"native entry CFG diagnostics: {graph.diagnostics[:8]}")
    special_sites: list[dict[str, Any]] = []
    live_origin_roots: set[int] = set()
    distance_cache = {
        root: graph.distances(root) for root in root_provenance
    }
    for node in graph.nodes.values():
        for instruction in node.instructions:
            if instruction.opcode not in {0x25, 0x26}:
                continue
            operand_offset = 1 if instruction.opcode == 0x25 else 3
            special = struct.unpack_from(
                "<H", instruction.raw, operand_offset,
            )[0]
            if special != seagallop_special:
                continue
            roots = sorted(
                root for root, reached in distance_cache.items()
                if node.address in reached
            )
            live = [
                root for root in roots
                if any(
                    tuple(map(int, provenance["map"])) in locally_seeded_maps
                    for provenance in root_provenance[root]
                )
            ]
            live_origin_roots.update(live)
            special_sites.append({
                "instruction_address": f"0x{instruction.address:08X}",
                "raw_hex": instruction.raw.hex(),
                "special_id": seagallop_special,
                "reachable_root_addresses": [
                    f"0x{root:08X}" for root in roots
                ],
                "locally_seeded_origin_root_addresses": [
                    f"0x{root:08X}" for root in live
                ],
            })
    if not special_sites or not live_origin_roots:
        _fail("Seagallop native producerにlocally seeded special rootがありません")
    live_provenance = sorted(
        (
            {**row, "root_address": f"0x{root:08X}"}
            for root in live_origin_roots for row in root_provenance[root]
        ),
        key=lambda row: (
            row["map"], row["root_label"], row["root_address"],
        ),
    )
    inventory = {(group, number) for group, number, _ in coords}
    result: dict[tuple[int, int], list[dict[str, Any]]] = defaultdict(list)
    for index in range(11):
        group, number, x, y = struct.unpack_from(
            "<bbbb", expected_table, index * 4,
        )
        if (group, number) not in inventory:
            _fail(f"Seagallop destination inventory外: {group}/{number}")
        result[(group, number)].append({
            "family": "NATIVE_TABLE_WARP",
            "producer": "SEAGALLOP_SPECIAL_379",
            "arrival_tile": [x, y],
            "table_index": index,
            "table_row_address": f"0x{table_address + index * 4:08X}",
            "table_row_raw_hex": expected_table[index * 4:index * 4 + 4].hex(),
            "table_sha256": _sha(expected_table),
            "native_function_address": f"0x{native_address:08X}",
            "native_function_prefix_sha256": _sha(native_raw),
            "native_table_pointer_site": f"0x{literal_site:08X}",
            "special_sites": special_sites,
            "locally_seeded_origin_root_provenance": live_provenance,
            "reachability_scope": "STRUCTURAL_EXACT_INCOMING_CANDIDATE_NOT_GLOBAL_ROOT",
            "basis": (
                "LOCALLY_SEEDED_MAP_ROOT_SPECIAL_TO_EXACT_NATIVE_CONSUMER_"
                "AND_DESTINATION_TABLE_NOT_GLOBAL_ROOT_PROOF"
            ),
        })
    return dict(result)


def _map_binary_fingerprint(
    rom: bytes, group: int, number: int,
) -> dict[str, Any]:
    """Hash every structural owner of a loadable physical map.

    Addresses are included deliberately: a pointer-only or bytes-only digest
    cannot distinguish a silently repointed owner from the intended physical
    map.  Script roots are pinned by exact address and a 64-byte prefix; the
    full reachable CFG is independently decoded by the entry producer audit.
    """

    state = _stage_map_state(rom, group, number)
    geometry = _map_geometry(rom, group, number)
    header = _map_header_offset(rom, group, number)
    roots = _map_event_script_roots(
        rom, group, number, state,
        tolerate_invalid_map_script_table=True,
    )
    root_rows: list[dict[str, Any]] = []
    for root in roots:
        pointer = int(root["pointer"])
        offset = _rom_offset(
            pointer, 1, f"entry fingerprint root {group}/{number}",
        )
        length = min(64, len(rom) - offset)
        raw = rom[offset:offset + length]
        root_rows.append({
            "label": str(root["label"]),
            "kind": str(root["kind"]),
            "pointer": f"0x{pointer:08X}",
            "prefix_size": length,
            "prefix_sha256": _sha(raw),
        })
    root_rows.sort(key=lambda row: (row["label"], row["pointer"]))
    objects = b"".join(bytes(row) for row in state["objects"])
    warps = bytes.fromhex(str(state["warps_hex"]))
    coords = bytes.fromhex(str(state["coords_hex"]))
    backgrounds = bytes.fromhex(str(state["bg_hex"]))
    blocks = struct.pack(
        f"<{len(geometry['blocks'])}H", *geometry["blocks"],
    )
    behaviors = struct.pack(
        f"<{len(geometry['behaviors'])}H", *geometry["behaviors"],
    )
    connection_rows = _decode_connection_rows(rom, group, number)
    result = {
        "map": [group, number],
        "map_header_address": f"0x{GBA_BASE + header:08X}",
        "map_header_sha256": _sha(rom[header:header + 0x1C]),
        "event_header_address": f"0x{int(state['event_header_address']):08X}",
        "event_header_sha256": _sha(bytes.fromhex(state["event_header_hex"])),
        "counts": dict(state["counts"]),
        "array_addresses": {
            key: (
                f"0x{int(value):08X}" if int(value) not in {0, 0xFFFFFFFF}
                else None
            )
            for key, value in state["pointers"].items()
        },
        "array_sha256": {
            "objects": _sha(objects), "warps": _sha(warps),
            "coords": _sha(coords), "bg": _sha(backgrounds),
        },
        "layout": {
            "address": f"0x{int(geometry['layout_address']):08X}",
            "width": int(geometry["width"]),
            "height": int(geometry["height"]),
            "blocks_sha256": _sha(blocks),
            "behaviors_sha256": _sha(behaviors),
        },
        "connection_rows": connection_rows,
        "script_roots": root_rows,
    }
    result["fingerprint_sha256"] = _sha(_stable(result))
    return result


def _source_map_artifact_hashes(map_key: str) -> dict[str, Any]:
    base = ROOT / "vendor/upstream/pokefirered/data/maps" / map_key
    rows: list[dict[str, Any]] = []
    for name in ("map.json", "scripts.inc", "text.inc"):
        path = base / name
        relative = str(path.relative_to(ROOT))
        if path.is_file():
            raw = path.read_bytes()
            rows.append({
                "path": relative, "exists": True,
                "size": len(raw), "sha256": _sha(raw),
            })
        else:
            rows.append({"path": relative, "exists": False})
    return {"files": rows, "tree_sha256": _sha(_stable(rows))}


def _entry_producer_contract(
    rom: bytes, group: int, number: int,
    state: Mapping[str, Any], entry_report: Mapping[str, Any],
    stored_producers: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
) -> dict[str, Any]:
    warps = bytes.fromhex(str(state["warps_hex"]))
    outgoing_dynamic = 0
    outgoing_literal = 0
    for index in range(int(state["counts"]["warps"])):
        at = index * 8
        if warps[at + 6:at + 8] == b"\x7F\x7F":
            outgoing_dynamic += 1
        else:
            outgoing_literal += 1
    roots = _map_event_script_roots(
        rom, group, number, state,
        tolerate_invalid_map_script_table=True,
    )
    root_counts = Counter(str(row["kind"]) for row in roots)
    return {
        "local_exact_incoming_seed_count": int(entry_report["seed_count"]),
        "incoming_warp_reference_count": int(
            entry_report["incoming_warp_reference_count"]
        ),
        "incoming_connection_row_count": int(entry_report["connection_count"]),
        "immediate_script_transition_producer_count": int(
            entry_report["scripted_entry_producer_count"]
        ),
        "native_table_producer_count": int(
            entry_report["engine_entry_producer_count"]
        ),
        "stored_warp_state_producer_count": len(
            stored_producers.get((group, number), [])
        ),
        "outgoing_dynamic_warp_count": outgoing_dynamic,
        "outgoing_literal_warp_count": outgoing_literal,
        "map_root_count": len(roots),
        "root_kind_counts": dict(sorted(root_counts.items())),
    }


def _load_local_static_incoming_exception_manifest() \
        -> tuple[bytes, dict[str, Any]]:
    path = ROOT / ENTRY_REACHABILITY_EXCEPTION_MANIFEST
    try:
        raw = path.read_bytes()
        value = json.loads(raw)
    except (OSError, json.JSONDecodeError) as exc:
        _fail(f"entry reachability exception manifestを読めません: {exc}")
    if not isinstance(value, dict) or (
        value.get("schema_version"), value.get("task"), value.get("stage")
    ) != (1, TASK, STAGE):
        _fail("entry reachability exception manifest schema/task/stage不一致")
    if value.get("stage60_rom_sha256") != (
        "3f9983eb099c2ca7205c14047460c8b2ed73a6180bd2a131a09c74af9d359ff1"
    ):
        _fail("entry reachability manifest Stage60 identity drift")
    expected_counts = value.get("expected_counts")
    if expected_counts != {
        "local_static_incoming_exception_map_count": 40,
        "canonical_clone_shadowed_local_incoming_absent_count": 30,
        "engine_dormant_local_incoming_absent_count": 6,
        "project_state_dependent_topology_entry_count": 4,
    }:
        _fail("entry reachability exception count contract不一致")
    rows = value.get("maps")
    if not isinstance(rows, list) or len(rows) != 40:
        _fail("entry reachability exception mapはexact 40件です")
    required = {
        "group", "map", "map_key", "classification", "canonical_clone",
        "source_artifacts", "stage60_fingerprint_sha256",
        "expected_producer_contract",
    }
    identities: set[tuple[int, int]] = set()
    for index, row in enumerate(rows):
        if not isinstance(row, Mapping) or set(row) != required:
            _fail(f"entry exception maps[{index}] schema不一致")
        key = (int(row["group"]), int(row["map"]))
        if key in identities:
            _fail(f"entry exception map重複: {key}")
        identities.add(key)
        classification = str(row["classification"])
        if classification not in {
            "CANONICAL_CLONE_SHADOWED_LOCAL_INCOMING_ABSENT",
            "ENGINE_DORMANT_LOCAL_INCOMING_ABSENT",
            "PROJECT_STATE_DEPENDENT_TOPOLOGY_ENTRY",
        }:
            _fail(f"entry exception classification不正: {classification}")
        if (classification == "CANONICAL_CLONE_SHADOWED_LOCAL_INCOMING_ABSENT") \
                != isinstance(row["canonical_clone"], Mapping):
            _fail(f"entry exception clone/classification矛盾: {key}")
    return raw, value


def _load_non_product_shadow_alias_manifest() \
        -> tuple[bytes, dict[str, dict[str, Any]]]:
    """Load the exact two physically isolated Route 4 shadow aliases.

    The legacy Route4 header retains an unreachable left-hand source pane.
    Those two templates are still exercised with teleport + face + A, but a
    real walk can only be proven on their canonical group-96 counterparts.
    This manifest binds each non-product source to that exact physical owner
    instead of allowing a broad map-level walk exception.
    """

    path = ROOT / NON_PRODUCT_SHADOW_ALIAS_MANIFEST
    try:
        raw = path.read_bytes()
        value = json.loads(raw)
    except (OSError, json.JSONDecodeError) as exc:
        _fail(f"non-product shadow alias manifestを読めません: {exc}")
    if not isinstance(value, dict) or set(value) != {
        "schema_version", "task", "stage", "expected_alias_count", "aliases",
    } or (value.get("schema_version"), value.get("task"), value.get("stage")) \
            != (1, TASK, STAGE):
        _fail("non-product shadow alias manifest schema/task/stage不一致")
    rows = value.get("aliases")
    if value.get("expected_alias_count") != 2 \
            or not isinstance(rows, list) or len(rows) != 2:
        _fail("non-product shadow aliasはexact 2件です")
    required = {
        "source_owner_id", "source_map", "source_map_key",
        "source_object_index", "source_local_id", "source_script_pointer",
        "source_diagnostic_stance", "source_diagnostic_action",
        "canonical_owner_id", "canonical_map", "canonical_map_key",
        "canonical_object_index", "canonical_local_id",
        "canonical_source_script_pointer", "canonical_walk_start",
        "canonical_walk_sequence", "canonical_stance", "canonical_action",
        "shared_template_fields",
    }
    field_keys = {
        "graphics_id", "x", "y", "elevation", "movement_type",
        "movement_range_x", "movement_range_y", "trainer_type",
        "sight_range", "flag",
    }
    by_source: dict[str, dict[str, Any]] = {}
    canonical_ids: set[str] = set()
    for index, row in enumerate(rows):
        if not isinstance(row, dict) or set(row) != required:
            _fail(f"non-product shadow aliases[{index}] schema不一致")
        source = str(row["source_owner_id"])
        canonical = str(row["canonical_owner_id"])
        if source in by_source or canonical in canonical_ids or source == canonical:
            _fail("non-product shadow alias owner重複")
        if source != (
            f"OBJECT:{int(row['source_map'][0]):03d}/"
            f"{int(row['source_map'][1]):03d}:"
            f"{int(row['source_object_index']):03d}"
        ) or canonical != (
            f"OBJECT:{int(row['canonical_map'][0]):03d}/"
            f"{int(row['canonical_map'][1]):03d}:"
            f"{int(row['canonical_object_index']):03d}"
        ):
            _fail(f"non-product shadow alias owner identity不一致: {source}")
        if row["source_map"] != [3, 22] or row["canonical_map"] != [96, 15]:
            _fail(f"non-product shadow alias map scope不一致: {source}")
        for key in ("source_diagnostic_stance", "canonical_walk_start",
                    "canonical_stance"):
            point = row[key]
            if not isinstance(point, list) or len(point) != 2 \
                    or any(isinstance(item, bool) or not isinstance(item, int)
                           for item in point):
                _fail(f"non-product shadow alias {key}不正: {source}")
        sequence = row["canonical_walk_sequence"]
        if not isinstance(sequence, list) or not sequence \
                or any(token not in {"UP", "DOWN", "LEFT", "RIGHT"}
                       for token in sequence):
            _fail(f"non-product shadow alias walk sequence不正: {source}")
        cursor = list(row["canonical_walk_start"])
        for token in sequence:
            dx, dy = {
                "UP": (0, -1), "DOWN": (0, 1),
                "LEFT": (-1, 0), "RIGHT": (1, 0),
            }[token]
            cursor[0] += dx
            cursor[1] += dy
        if cursor != row["canonical_stance"] \
                or row["source_diagnostic_stance"] != row["canonical_stance"] \
                or row["source_diagnostic_action"] != row["canonical_action"] \
                or row["canonical_action"] not in {"UP", "DOWN", "LEFT", "RIGHT"}:
            _fail(f"non-product shadow alias geometry不一致: {source}")
        if not isinstance(row["shared_template_fields"], dict) \
                or set(row["shared_template_fields"]) != field_keys:
            _fail(f"non-product shadow alias template field schema不一致: {source}")
        try:
            source_script = int(str(row["source_script_pointer"]), 0)
            canonical_source = int(
                str(row["canonical_source_script_pointer"]), 0,
            )
        except ValueError as exc:
            _fail(f"non-product shadow alias script pointer不正: {exc}")
        if source_script != canonical_source:
            _fail(f"non-product shadow alias semantic source不一致: {source}")
        by_source[source] = dict(row)
        canonical_ids.add(canonical)
    if set(by_source) != {"OBJECT:003/022:000", "OBJECT:003/022:003"} \
            or canonical_ids != {
                "OBJECT:096/015:007", "OBJECT:096/015:008",
            }:
        _fail("non-product shadow alias exact owner集合drift")
    return raw, by_source


def _build_local_static_incoming_exception_audit(
    stage60: bytes, rom: bytes,
    coords: Sequence[tuple[int, int, str]],
    canonical: Sequence[Mapping[str, Any]],
    scripted_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    stored_producers: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    connection_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    engine_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
) -> tuple[dict[tuple[int, int], dict[str, Any]], dict[str, Any]]:
    """Bind maps without a usable local static incoming seed to a manifest.

    The candidate set is derived from the final physical ROM, never from the
    manifest.  The manifest may only classify that exact derived set, so an
    added/removed producer, object, clone, source file, or binary owner fails
    the build instead of silently changing the interactive denominator.
    """

    manifest_raw, manifest = _load_local_static_incoming_exception_manifest()
    coord_keys = {(group, number): key for group, number, key in coords}
    canonical_by_source: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    for row in canonical:
        canonical_by_source[str(row["map_header"]["source_map"])].append(row)
    manifest_rows = {
        (int(row["group"]), int(row["map"])): row
        for row in manifest["maps"]
    }
    observed: dict[tuple[int, int], dict[str, Any]] = {}
    inventory_local_incoming_absent_rows: list[dict[str, Any]] = []
    invalid_physical_rows: list[dict[str, Any]] = []
    for group, number, map_key in coords:
        try:
            state = _stage_map_state(rom, group, number)
            geometry = _map_geometry(rom, group, number)
        except RuntimeError as exc:
            invalid_physical_rows.append({
                "group": group, "map": number, "map_key": map_key,
                "reason": str(exc),
            })
            continue
        seeds, entry_report, _ = _map_entry_seeds(
            rom, group, number, state, geometry, coords,
            scripted_entries, connection_entries, engine_entries,
        )
        # A structurally referenced destination on an impassable isolated
        # tile is not a usable local incoming component.  Keep the exact
        # arrival itself as a
        # diagnostic BFS origin (doors may be collision-bearing), but require
        # that it expands to at least one normal collision-zero field tile.
        # Route4/Ember Spa is the pinned regression: its lone incoming warp
        # lands at (32,5), surrounded by collision, while the canonical Route4
        # clone owns the usable source-map interaction surface.
        entry_reached = _reachable_distances(geometry, seeds, set())
        walkable_entry_tiles = sorted(
            point for point in entry_reached
            if _collision_zero(geometry, point)
        )
        if seeds and walkable_entry_tiles:
            continue
        producer_contract = _entry_producer_contract(
            rom, group, number, state, entry_report, stored_producers,
        )
        inventory_local_incoming_absent_rows.append({
            "group": group, "map": number, "map_key": map_key,
            "counts": dict(state["counts"]),
            "producer_contract": producer_contract,
            "local_static_incoming_component_reachable_tile_count": len(
                entry_reached
            ),
            "local_static_incoming_component_collision_zero_tile_count": len(
                walkable_entry_tiles
            ),
            "candidate_basis": (
                "EXACT_ZERO_ENTRY_SEEDS" if not seeds else
                "STRUCTURAL_ARRIVAL_HAS_ZERO_WALKABLE_EGRESS"
            ),
        })
        if not state["objects"]:
            continue
        observed[(group, number)] = {
            "group": group, "map": number, "map_key": map_key,
            "state": state, "geometry": geometry,
            "entry_report": entry_report,
            "producer_contract": producer_contract,
            "local_static_incoming_component_reachable_tile_count": len(
                entry_reached
            ),
            "local_static_incoming_component_collision_zero_tile_count": len(
                walkable_entry_tiles
            ),
        }
    if set(observed) != set(manifest_rows):
        derived_details = [
            {
                "map": list(key),
                "map_key": observed[key]["map_key"],
                "producer_contract": observed[key]["producer_contract"],
                "incoming_warps": observed[key]["entry_report"][
                    "incoming_warps"
                ],
                "scripted_entries": observed[key]["entry_report"][
                    "scripted_entries"
                ],
                "engine_entries": observed[key]["entry_report"][
                    "engine_entries"
                ],
            }
            for key in sorted(set(observed) - set(manifest_rows))
        ]
        _fail(
            "entry exception候補/manifest集合drift: "
            f"derived_only={sorted(set(observed) - set(manifest_rows))} "
            f"manifest_only={sorted(set(manifest_rows) - set(observed))} "
            f"derived_details={derived_details}"
        )

    result: dict[tuple[int, int], dict[str, Any]] = {}
    report_rows: list[dict[str, Any]] = []
    class_counts: Counter[str] = Counter()
    for key in sorted(observed):
        group, number = key
        actual = observed[key]
        expected = manifest_rows[key]
        if str(expected["map_key"]) != coord_keys[key] \
                or str(actual["map_key"]) != str(expected["map_key"]):
            _fail(f"entry exception map key drift: {key}")
        source_artifacts = _source_map_artifact_hashes(str(actual["map_key"]))
        if expected["source_artifacts"] != {
            "tree_sha256": source_artifacts["tree_sha256"]
        }:
            _fail(f"entry exception source artifact drift: {key}")
        stage60_fingerprint = _map_binary_fingerprint(stage60, group, number)
        if stage60_fingerprint["fingerprint_sha256"] != str(
            expected["stage60_fingerprint_sha256"]
        ):
            _fail(f"entry exception Stage60 physical owner drift: {key}")
        if actual["producer_contract"] != expected["expected_producer_contract"]:
            _fail(
                f"entry exception producer contract drift: {key}: "
                f"actual={actual['producer_contract']} "
                f"expected={expected['expected_producer_contract']}"
            )
        clones = canonical_by_source.get(str(actual["map_key"]), [])
        clone_contract = expected["canonical_clone"]
        classification = str(expected["classification"])
        clone_report: dict[str, Any] | None = None
        comparison: dict[str, Any] | None = None
        project_state_transition: dict[str, Any] | None = None
        if classification == "CANONICAL_CLONE_SHADOWED_LOCAL_INCOMING_ABSENT":
            if len(clones) != 1 or not isinstance(clone_contract, Mapping):
                _fail(f"shadowed local-incoming-absent clone一意性FAIL: {key}")
            clone = clones[0]
            clone_header = clone["map_header"]
            actual_contract = {
                "group": int(clone_header["group_id"]),
                "map": int(clone_header["map_id"]),
                "map_key": str(clone_header["map_key"]),
                "recipe_sha256": _sha(_stable(clone)),
            }
            if actual_contract != dict(clone_contract):
                _fail(
                    f"shadowed local-incoming-absent recipe drift: {key}: "
                    f"actual={actual_contract} expected={dict(clone_contract)}"
                )
            clone_fingerprint = _map_binary_fingerprint(
                rom, actual_contract["group"], actual_contract["map"],
            )
            source_final_fingerprint = _map_binary_fingerprint(
                rom, group, number,
            )
            comparison = {
                "same_dimensions": (
                    stage60_fingerprint["layout"]["width"],
                    stage60_fingerprint["layout"]["height"],
                ) == (
                    clone_fingerprint["layout"]["width"],
                    clone_fingerprint["layout"]["height"],
                ),
                "same_blockdata": (
                    stage60_fingerprint["layout"]["blocks_sha256"]
                    == clone_fingerprint["layout"]["blocks_sha256"]
                ),
                "same_event_counts": (
                    stage60_fingerprint["counts"] == clone_fingerprint["counts"]
                ),
                "same_object_bytes": (
                    stage60_fingerprint["array_sha256"]["objects"]
                    == clone_fingerprint["array_sha256"]["objects"]
                ),
                "same_warp_bytes": (
                    stage60_fingerprint["array_sha256"]["warps"]
                    == clone_fingerprint["array_sha256"]["warps"]
                ),
                "source_final_fingerprint_sha256": source_final_fingerprint[
                    "fingerprint_sha256"
                ],
                "clone_final_fingerprint_sha256": clone_fingerprint[
                    "fingerprint_sha256"
                ],
            }
            clone_report = {**actual_contract, "fingerprint": clone_fingerprint}
        elif classification == "ENGINE_DORMANT_LOCAL_INCOMING_ABSENT":
            if clones or clone_contract is not None:
                _fail(f"engine dormant mapにcanonical cloneがあります: {key}")
        else:
            expected_scene_before = {
                (97, 75): 0,
                (97, 76): 1,
                (97, 77): 2,
                (97, 79): 4,
            }
            if key not in expected_scene_before \
                    or clones or clone_contract is not None:
                _fail(f"project-state topology entry map contract不正: {key}")
            surface = _decode_map_script_table_contract(
                rom, group, number,
                label=f"Stage61 project-state entry {group}/{number}",
            )
            expected_tags = [5, 1, 4, 2] if number != 79 else [4, 2]
            if [int(row["tag"]) for row in surface["rows"]] != expected_tags:
                _fail(f"project-state topology table tag drift: {key}")
            conditional = {
                int(row["tag"]): row
                for row in surface["rows"] if int(row["tag"]) in {2, 4}
            }
            scene_conditions = conditional[2].get("conditions", [])
            turn_conditions = conditional[4].get("conditions", [])
            if (
                len(scene_conditions) != 1
                or int(scene_conditions[0]["first_operand"])
                != STAGE61_KANTO_LEAGUE_SCENE_VAR
                or int(scene_conditions[0]["second_operand"])
                != expected_scene_before[key]
                or len(turn_conditions) != 1
                or int(turn_conditions[0]["first_operand"]) != 0x4001
                or int(turn_conditions[0]["second_operand"]) != 0
            ):
                _fail(f"project-state topology condition drift: {key}")
            project_state_transition = {
                "ownership": "PROJECT_OWNED_LEAGUE_TOPOLOGY_STATE_MACHINE",
                "scene_var": f"0x{STAGE61_KANTO_LEAGUE_SCENE_VAR:04X}",
                "scene_before": expected_scene_before[key],
                "scene_after": expected_scene_before[key] + 1,
                "table_pointer": f"0x{int(surface['pointer']):08X}",
                "tags": expected_tags,
                "real_map_script_consumer": True,
                "runtime_transition_fixture_required": True,
            }
        class_counts[classification] += 1
        contract = {
            "classification": classification,
            "local_static_incoming_available": False,
            "runtime_interaction_fixture_expected": True,
            "diagnostic_teleport_required": True,
            "basis": (
                "NO_USABLE_LOCAL_STATIC_INCOMING_COMPONENT_AND_CANONICAL_"
                "RECIPE_REPLACEMENT"
                if classification == "CANONICAL_CLONE_SHADOWED_LOCAL_INCOMING_ABSENT" else
                "NO_USABLE_STATIC_ENTRY_UNTIL_PROJECT_LEAGUE_SCENE_"
                "TRANSITION_EXECUTES"
                if classification == "PROJECT_STATE_DEPENDENT_TOPOLOGY_ENTRY" else
                "NO_USABLE_LOCAL_STATIC_INCOMING_COMPONENT_AND_NO_"
                "CANONICAL_RECIPE"
            ),
            "manifest_path": str(ENTRY_REACHABILITY_EXCEPTION_MANIFEST),
            "manifest_sha256": _sha(manifest_raw),
            "producer_contract": dict(actual["producer_contract"]),
            "canonical_clone": clone_contract,
            "project_state_transition": project_state_transition,
            "local_static_incoming_component_reachable_tile_count": actual[
                "local_static_incoming_component_reachable_tile_count"
            ],
            "local_static_incoming_component_collision_zero_tile_count": actual[
                "local_static_incoming_component_collision_zero_tile_count"
            ],
        }
        result[key] = contract
        report_rows.append({
            "group": group, "map": number,
            "map_key": actual["map_key"],
            **contract,
            "source_artifacts": source_artifacts,
            "stage60_fingerprint": stage60_fingerprint,
            "final_source_fingerprint": _map_binary_fingerprint(
                rom, group, number,
            ),
            "clone": clone_report,
            "source_clone_comparison": comparison,
            "entry": actual["entry_report"],
        })
    expected_class_counts = {
        "CANONICAL_CLONE_SHADOWED_LOCAL_INCOMING_ABSENT": 30,
        "ENGINE_DORMANT_LOCAL_INCOMING_ABSENT": 6,
        "PROJECT_STATE_DEPENDENT_TOPOLOGY_ENTRY": 4,
    }
    if dict(sorted(class_counts.items())) != expected_class_counts:
        _fail(f"entry exception class count drift: {class_counts}")
    return result, {
        "schema_version": 1, "task": TASK, "stage": STAGE,
        "status": "PASS", "rom_sha256": _sha(rom),
        "manifest": {
            "path": str(ENTRY_REACHABILITY_EXCEPTION_MANIFEST),
            "sha256": _sha(manifest_raw),
        },
        "local_static_incoming_exception_map_count": len(result),
        "classification_counts": expected_class_counts,
        "all_loadable_local_static_incoming_absent_map_count": len(
            inventory_local_incoming_absent_rows
        ),
        "invalid_physical_map_header_count": len(invalid_physical_rows),
        "all_loadable_local_static_incoming_absent_maps": (
            inventory_local_incoming_absent_rows
        ),
        "invalid_physical_maps": invalid_physical_rows,
        "maps": report_rows,
        "assertions": {
            "derived_interaction_exception_set_matches_manifest": True,
            "all_source_artifacts_hash_pinned": True,
            "all_stage60_physical_owners_hash_pinned": True,
            "all_exception_maps_have_zero_walkable_local_incoming_component": all(
                row[
                    "local_static_incoming_component_collision_zero_tile_count"
                ] == 0
                for row in result.values()
            ),
            "all_shadowed_local_incoming_absent_maps_have_one_recipe": True,
            "all_engine_local_incoming_absent_maps_have_no_recipe": True,
            "all_project_state_entries_bind_real_map_script_consumers": all(
                row["classification"]
                != "PROJECT_STATE_DEPENDENT_TOPOLOGY_ENTRY"
                or row["project_state_transition"][
                    "real_map_script_consumer"
                ]
                for row in result.values()
            ),
            "no_outgoing_warp_or_connection_used_as_incoming_seed": True,
            "diagnostic_teleport_retained_for_every_exception_map": True,
        },
    }


def _local_object_operation_evidence(
    rom: bytes, group: int, number: int, state: Mapping[str, Any],
    object_index: int, local_id: int, owner_root: int,
    visibility_flag: int,
) -> dict[str, Any]:
    """Decode exact local-object consumers reachable from this map's roots."""

    evidence: dict[tuple[str, int, int], dict[str, Any]] = {}
    lifecycle_proofs: list[dict[str, Any]] = []
    visibility_proofs: list[dict[str, Any]] = []
    owner_label = f"OBJECT:{object_index}"
    external_reaches_owner_entry = False
    owner_visible_reference_count = 0
    for root in _map_event_script_roots(rom, group, number, state):
        graph = SemanticScriptGraph(rom)
        graph.walk([int(root["pointer"])])
        if graph.diagnostics:
            _fail(
                f"local-object CFG decode diagnostics: {group}/{number} "
                f"{root['label']} {graph.diagnostics[:2]}"
            )
        is_external = str(root["label"]) != owner_label
        if is_external and owner_root in graph.distances(int(root["pointer"])):
            external_reaches_owner_entry = True
        if not is_external:
            owner_visible_reference_count = sum(
                int(reference.directly_visible)
                for node in graph.nodes.values()
                for reference in node.references
            )
        root_operations: list[dict[str, Any]] = []
        flag_sites: list[dict[str, Any]] = []
        for node in graph.nodes.values():
            for instruction_index, instruction in enumerate(node.instructions):
                if instruction.opcode in {0x29, 0x2A, 0x2B} \
                        and len(instruction.raw) >= 3 \
                        and struct.unpack_from("<H", instruction.raw, 1)[0] \
                        == visibility_flag:
                    flag_sites.append({
                        "node_address": node.address,
                        "instruction_index": instruction_index,
                        "instruction_address": instruction.address,
                        "operation": {
                            0x29: "SET_FLAG", 0x2A: "CLEAR_FLAG",
                            0x2B: "CHECK_FLAG",
                        }[instruction.opcode],
                    })
                operation = LOCAL_OBJECT_OPERATIONS.get(instruction.opcode)
                if operation is None or len(instruction.raw) < 3:
                    continue
                operand = struct.unpack_from("<H", instruction.raw, 1)[0]
                if operand != local_id:
                    continue
                row: dict[str, Any] = {
                    "root_label": str(root["label"]),
                    "root_kind": str(root["kind"]),
                    "root_address": f"0x{int(root['pointer']):08X}",
                    "instruction_address": f"0x{instruction.address:08X}",
                    "node_address": f"0x{node.address:08X}",
                    "instruction_index": instruction_index,
                    "opcode": f"0x{instruction.opcode:02X}",
                    "operation": operation,
                    "raw_hex": instruction.raw.hex(),
                    "external_to_owner": is_external,
                }
                if instruction.opcode in {0x57, 0x63}:
                    x, y = struct.unpack_from("<HH", instruction.raw, 3)
                    if x < 0x4000 and y < 0x4000:
                        row["literal_position"] = [x, y]
                if instruction.opcode == 0x65:
                    row["literal_movement_type"] = instruction.raw[3]
                if instruction.opcode in {0x4F, 0x50}:
                    movement_pointer = struct.unpack_from(
                        "<I", instruction.raw, 3,
                    )[0]
                    movement_offset = _rom_offset(
                        movement_pointer, 1,
                        f"movement script {group}/{number}/{local_id}",
                    )
                    movement_end = rom.find(
                        b"\xFE", movement_offset,
                        min(len(rom), movement_offset + 0x100),
                    )
                    if movement_end < 0:
                        _fail(
                            f"movement script終端なし: "
                            f"{movement_pointer:#010x}"
                        )
                    movement_raw = rom[movement_offset:movement_end + 1]
                    row.update({
                        "movement_script_pointer": (
                            f"0x{movement_pointer:08X}"
                        ),
                        "movement_script_sha256": _sha(movement_raw),
                        "movement_actions_hex": movement_raw.hex(),
                    })
                evidence[(str(root["label"]), instruction.address,
                          instruction.opcode)] = row
                root_operations.append(row)
        if is_external:
            reachability = {
                address: graph.distances(address) for address in graph.nodes
            }

            def precedes(left: Mapping[str, Any], right: Mapping[str, Any]) -> bool:
                left_node = int(str(left["node_address"]), 16)
                right_node = int(str(right["node_address"]), 16)
                if left_node == right_node:
                    return int(left["instruction_index"]) < int(
                        right["instruction_index"]
                    )
                return right_node in reachability[left_node]

            adds = [row for row in root_operations if row["operation"] == "ADD_OBJECT"]
            moves = [
                row for row in root_operations
                if row["operation"] == "APPLY_MOVEMENT"
            ]
            removes = [
                row for row in root_operations
                if row["operation"] == "REMOVE_OBJECT"
            ]
            for add in adds:
                for movement in moves:
                    for remove in removes:
                        if precedes(add, movement) and precedes(movement, remove):
                            lifecycle_proofs.append({
                                "root_label": str(root["label"]),
                                "root_address": f"0x{int(root['pointer']):08X}",
                                "ordered_operations": [
                                    add["instruction_address"],
                                    movement["instruction_address"],
                                    remove["instruction_address"],
                                ],
                                "order": [
                                    "ADD_OBJECT", "APPLY_MOVEMENT",
                                    "REMOVE_OBJECT",
                                ],
                                "proof": "SAME_EXTERNAL_ROOT_REACHABLE_CFG_PATH",
                            })
            for flag_site in flag_sites:
                if flag_site["operation"] != "SET_FLAG":
                    continue
                visibility_proofs.append({
                    "root_label": str(root["label"]),
                    "root_address": f"0x{int(root['pointer']):08X}",
                    "instruction_address": (
                        f"0x{int(flag_site['instruction_address']):08X}"
                    ),
                    "visibility_flag": visibility_flag,
                    "operation": "SET_FLAG",
                    "proof": "EXTERNAL_ROOT_EXPLICITLY_HIDES_TEMPLATE",
                })
    rows = sorted(
        evidence.values(), key=lambda row: (
            str(row["root_label"]), str(row["instruction_address"]),
            str(row["operation"]),
        ),
    )
    return {
        "operation_count": len(rows),
        "external_operation_count": sum(
            bool(row["external_to_owner"]) for row in rows
        ),
        "external_reaches_owner_entry": external_reaches_owner_entry,
        "owner_manual_visible_reference_count": owner_visible_reference_count,
        "ordered_lifecycle_proofs": sorted(
            lifecycle_proofs,
            key=lambda row: (row["root_label"], row["ordered_operations"]),
        ),
        "visibility_state_proofs": sorted(
            visibility_proofs,
            key=lambda row: (row["root_label"], row["instruction_address"]),
        ),
        "operations": rows,
    }


def _interaction_contracts(
    rom: bytes, npc_catalog: Mapping[str, Any],
    placement: Mapping[str, Any],
    entry_exceptions: Mapping[tuple[int, int], Mapping[str, Any]],
) -> tuple[dict[str, dict[str, Any]], dict[str, Any]]:
    """Classify portless templates without silently dropping manual owners."""

    placement_by_id = {
        str(row["npc_id"]): row for row in placement["objects"]
    }
    contracts: dict[str, dict[str, Any]] = {}
    reviews: list[dict[str, Any]] = []
    protected_roles = ("TRAINER", "ITEM", "ARCHIVE", "MART", "HEAL", "PC")
    for npc in npc_catalog["npcs"]:
        npc_id = str(npc["npc_id"])
        placement_row = placement_by_id[npc_id]
        contract: dict[str, Any] = {
            "mode": "MANUAL_INPUT_REQUIRED",
            "basis": "FAIL_CLOSED_DEFAULT_FOR_EVERY_SCRIPT_OBJECT",
            "template_has_legal_port": placement_row["port"] is not None,
            "external_cfg_evidence": [],
        }
        entry_exception = entry_exceptions.get((
            int(npc["group"]), int(npc["map"]),
        ))
        if entry_exception is not None:
            diagnostic_port = placement_row.get("diagnostic_port")
            diagnostic_action = placement_row.get("diagnostic_action")
            diagnostic_walk_cycle = placement_row.get(
                "diagnostic_walk_cycle"
            )
            runtime_position: list[int] | None = None
            runtime_movement_type: int | None = None
            state = _stage_map_state(
                rom, int(npc["group"]), int(npc["map"]),
            )
            operations = _local_object_operation_evidence(
                rom, int(npc["group"]), int(npc["map"]), state,
                int(npc["object_index"]), int(npc["local_id"]),
                int(npc["script_pointer"]), int(npc["flag"]),
            )
            external = [
                row for row in operations["operations"]
                if row["external_to_owner"]
            ]
            permanent_positions = sorted({
                tuple(int(value) for value in row["literal_position"])
                for row in external
                if row["operation"] == "SET_OBJECT_XY_PERMANENT"
                and "literal_position" in row
            })
            if len(permanent_positions) > 1:
                _fail(
                    "diagnostic mapのexact runtime positionが複数です: "
                    f"{npc_id} positions={permanent_positions}"
                )
            # Some dormant/shadowed maps deliberately move a template into
            # its eventual interaction position from a different map root.
            # Resolve an exact setobjectxyperm destination even when the stale
            # template happens to have a diagnostic port; map-load execution
            # determines which physical actor the player will actually see.
            if len(permanent_positions) == 1:
                runtime_position = list(permanent_positions[0])
                movement_rows = [
                    row for row in external
                    if row["operation"] == "SET_OBJECT_MOVEMENT_TYPE"
                    and "literal_movement_type" in row
                ]
                runtime_movement_type = (
                    int(movement_rows[-1]["literal_movement_type"])
                    if movement_rows else int(npc["movement_type"])
                )
                geometry = _map_geometry(
                    rom, int(npc["group"]), int(npc["map"]),
                )
                _, reserved = _decode_event_tiles(state)
                decoded = [_object_fields(raw) for raw in state["objects"]]
                blockers = {
                    (
                        tuple(runtime_position)
                        if index == int(npc["object_index"]) else
                        (int(row["x"]), int(row["y"]))
                    )
                    for index, row in enumerate(decoded)
                }
                diagnostic = _diagnostic_interaction_port(
                    geometry, tuple(runtime_position), reserved, blockers,
                )
                if diagnostic is None:
                    _fail(
                        "diagnostic runtime positionにもlegal portがあり"
                        f"ません: {npc_id} position={runtime_position}"
                    )
                diagnostic_port = list(diagnostic[0])
                diagnostic_action = diagnostic[1]
                diagnostic_walk_cycle = _diagnostic_walk_cycle(
                    geometry, diagnostic[0], reserved, blockers,
                )
            if not isinstance(diagnostic_port, list) \
                    or len(diagnostic_port) != 2:
                _fail(f"diagnostic teleport interaction port欠落: {npc_id}")
            classification = str(entry_exception["classification"])
            contract = {
                "mode": f"DIAGNOSTIC_TELEPORT_REQUIRED_LOCAL_INCOMING_ABSENT_{classification}",
                "basis": str(entry_exception["basis"]),
                "interaction_expected": False,
                "local_static_incoming_available": False,
                "diagnostic_teleport_required": True,
                "diagnostic_port": list(diagnostic_port),
                "diagnostic_action": diagnostic_action,
                "diagnostic_walk_cycle": list(diagnostic_walk_cycle or []),
                "diagnostic_walk_steps_minimum": (
                    1 if diagnostic_walk_cycle else 0
                ),
                "diagnostic_isolated_port": not bool(diagnostic_walk_cycle),
                "direct_script_call_forbidden": True,
                "entry_exception": dict(entry_exception),
                "template_has_legal_port": False,
                "external_cfg_evidence": [
                    row for row in operations["operations"]
                    if row["external_to_owner"]
                ],
            }
            if runtime_position is not None:
                contract.update({
                    "basis": (
                        "MANIFEST_PINNED_NON_PRODUCT_MAP_AND_MAP_SCRIPT_"
                        "EXACT_PERMANENT_RUNTIME_POSITION"
                    ),
                    "runtime_position": runtime_position,
                    "runtime_movement_type": runtime_movement_type,
                })
            contracts[npc_id] = contract
            reviews.append({
                "npc_id": npc_id,
                "map": [npc["group"], npc["map"]],
                "object_index": npc["object_index"],
                "local_id": npc["local_id"],
                "template": [npc["x"], npc["y"]],
                "initial_mode": placement_row["mode"],
                "interaction_contract": contract,
                "all_local_object_operation_count": operations[
                    "operation_count"
                ],
            })
            continue
        if placement_row["port"] is not None:
            contracts[npc_id] = contract
            continue
        state = _stage_map_state(rom, int(npc["group"]), int(npc["map"]))
        operations = _local_object_operation_evidence(
            rom, int(npc["group"]), int(npc["map"]), state,
            int(npc["object_index"]), int(npc["local_id"]),
            int(npc["script_pointer"]),
            int(npc["flag"]),
        )
        external = [
            row for row in operations["operations"]
            if row["external_to_owner"]
        ]
        lifecycle_roots = {
            str(row["root_label"])
            for row in operations["ordered_lifecycle_proofs"]
        }
        visibility_roots = {
            str(row["root_label"])
            for row in operations["visibility_state_proofs"]
        }
        actor_only = (
            bool(operations["ordered_lifecycle_proofs"])
            and not bool(operations["external_reaches_owner_entry"])
            and (
                int(operations["owner_manual_visible_reference_count"]) == 0
                or bool(lifecycle_roots & visibility_roots)
            )
        )
        permanent_positions = sorted({
            tuple(row["literal_position"])
            for row in external
            if row["operation"] == "SET_OBJECT_XY_PERMANENT"
            and "literal_position" in row
        })
        if actor_only:
            contract = {
                "mode": "SCRIPT_ACTOR_ONLY_HIDDEN",
                "basis": (
                    "SAME_EXTERNAL_ROOT_PATH_ORDERS_ADD_APPLY_REMOVE_"
                    "WITHOUT_REACHING_OWNER_ENTRY_AND_EXACT_MANUAL_"
                    "VISIBILITY_PROOF"
                ),
                "template_has_legal_port": False,
                "visibility_flag": int(npc["flag"]),
                "manual_entry_expected_visible_text_count": 0,
                "external_reaches_owner_entry": bool(
                    operations["external_reaches_owner_entry"]
                ),
                "external_cfg_evidence": external,
                "ordered_lifecycle_proofs": operations[
                    "ordered_lifecycle_proofs"
                ],
                "manual_visibility_state_proofs": operations[
                    "visibility_state_proofs"
                ],
                "owner_manual_visible_reference_count": operations[
                    "owner_manual_visible_reference_count"
                ],
            }
        elif len(permanent_positions) == 1:
            position = permanent_positions[0]
            movement_rows = [
                row for row in external
                if row["operation"] == "SET_OBJECT_MOVEMENT_TYPE"
                and "literal_movement_type" in row
            ]
            contract.update({
                "basis": "MAP_SCRIPT_EXACT_PERMANENT_RUNTIME_POSITION",
                "runtime_position": list(position),
                "runtime_movement_type": (
                    int(movement_rows[-1]["literal_movement_type"])
                    if movement_rows else int(npc["movement_type"])
                ),
                "external_cfg_evidence": external,
            })
        elif len(permanent_positions) > 1:
            _fail(
                f"manual ownerのruntime permanent positionが複数です: "
                f"{npc_id} {permanent_positions}"
            )
        else:
            contract["external_cfg_evidence"] = external
        contracts[npc_id] = contract
        reviews.append({
            "npc_id": npc_id,
            "map": [npc["group"], npc["map"]],
            "object_index": npc["object_index"],
            "local_id": npc["local_id"],
            "template": [npc["x"], npc["y"]],
            "initial_mode": placement_row["mode"],
            "interaction_contract": contract,
            "all_local_object_operation_count": operations["operation_count"],
        })
    portless = [
        row for row in placement["objects"] if row["port"] is None
    ]
    actor_ids = sorted(
        npc_id for npc_id, contract in contracts.items()
        if contract["mode"] == "SCRIPT_ACTOR_ONLY_HIDDEN"
    )
    runtime_ids = sorted(
        npc_id for npc_id, contract in contracts.items()
        if "runtime_position" in contract
    )
    diagnostic_ids = sorted(
        npc_id for npc_id, contract in contracts.items()
        if str(contract["mode"]).startswith("DIAGNOSTIC_TELEPORT_REQUIRED_LOCAL_INCOMING_ABSENT_")
    )
    return contracts, {
        "schema_version": 1,
        "initial_portless_owner_count": len(portless),
        "script_actor_only_hidden_count": len(actor_ids),
        "scripted_runtime_position_count": len(runtime_ids),
        "diagnostic_teleport_required_local_incoming_absent_count": len(diagnostic_ids),
        "manual_relocation_required_count": (
            # An exact setobjectxyperm destination is not an exception to
            # manual reachability.  The allocator moves the visible runtime
            # destination and patches its literal operand together with the
            # selected stance; only actor-only and non-product diagnostic
            # owners leave the normal local-incoming/manual denominator.
            len(portless) - len(actor_ids) - len(diagnostic_ids)
        ),
        "script_actor_only_hidden_ids": actor_ids,
        "scripted_runtime_position_ids": runtime_ids,
        "diagnostic_teleport_required_local_incoming_absent_ids": diagnostic_ids,
        "reviews": reviews,
    }


def _reachable_distances(
    geometry: Mapping[str, Any], seeds: Iterable[tuple[int, int]],
    blocked: set[tuple[int, int]],
) -> dict[tuple[int, int], int]:
    # A door/ladder warp may deliberately place the avatar on a warp metatile
    # whose collision nibble is non-zero.  That exact arrival remains a valid
    # BFS origin; only tiles entered *after* arrival must be collision zero.
    # Broadening the origin to adjacent tiles would overstate reachability, so
    # retain the exact coordinate and expand from it normally.
    reached = {
        point: 0 for point in seeds
        if point not in blocked and _in_map_bounds(geometry, point)
    }
    pending = deque(sorted(reached, key=lambda point: (point[1], point[0])))
    while pending:
        x, y = pending.popleft()
        for point in ((x, y - 1), (x - 1, y), (x + 1, y), (x, y + 1)):
            if point in reached or point in blocked \
                    or not _collision_zero(geometry, point):
                continue
            reached[point] = reached[(x, y)] + 1
            pending.append(point)
    return reached


def _shortest_safe_walk_path(
    geometry: Mapping[str, Any],
    starts: Sequence[tuple[int, int]],
    target: tuple[int, int],
    blocked: set[tuple[int, int]],
    reserved: set[tuple[int, int]],
) -> dict[str, Any]:
    """Return one deterministic real-input path from an exact arrival.

    Unlike the broad reachability audit, a runnable fixture must not walk
    across a second warp/coord/BG trigger on the way to its target.  The exact
    arrival tile itself may be a reserved/collision-bearing warp destination;
    every subsequently entered tile must be collision-zero, object-free and
    event-free.  Each incoming warp is searched independently so provenance
    retains the concrete source row rather than only a multi-source distance.
    """

    directions = (
        ("UP", (0, -1)),
        ("LEFT", (-1, 0)),
        ("RIGHT", (1, 0)),
        ("DOWN", (0, 1)),
    )
    candidates: list[tuple[int, int, int, tuple[str, ...], list[tuple[int, int]]]] = []
    for start in sorted(set(starts), key=lambda point: (point[1], point[0])):
        if start in blocked or not _in_map_bounds(geometry, start):
            continue
        pending = deque([start])
        predecessor: dict[
            tuple[int, int], tuple[tuple[int, int], str] | None
        ] = {start: None}
        while pending and target not in predecessor:
            cursor = pending.popleft()
            for key, (dx, dy) in directions:
                point = (cursor[0] + dx, cursor[1] + dy)
                if point in predecessor or point in blocked \
                        or (point in reserved and point != start) \
                        or not _collision_zero(geometry, point):
                    continue
                predecessor[point] = (cursor, key)
                pending.append(point)
        if target not in predecessor:
            continue
        reverse_keys: list[str] = []
        reverse_tiles = [target]
        cursor = target
        while cursor != start:
            edge = predecessor[cursor]
            if edge is None:
                _fail("shortest walk predecessor chain不正")
            cursor, key = edge
            reverse_keys.append(key)
            reverse_tiles.append(cursor)
        keys = tuple(reversed(reverse_keys))
        tiles = list(reversed(reverse_tiles))
        candidates.append((len(keys), start[1], start[0], keys, tiles))
    if not candidates:
        _fail(f"exact incoming warpから安全な実歩行pathなし: target={target}")
    _length, _y, _x, keys, tiles = min(candidates)
    return {
        "start": list(tiles[0]),
        "key_sequence": list(keys),
        "tiles": [list(point) for point in tiles],
        "step_count": len(keys),
    }


def _port_action(
    object_point: tuple[int, int], port: tuple[int, int],
) -> str:
    dx, dy = object_point[0] - port[0], object_point[1] - port[1]
    actions = {(0, -1): "UP", (0, 1): "DOWN", (-1, 0): "LEFT", (1, 0): "RIGHT"}
    # Counter interaction uses the same vector at distance two.
    normalized = (
        0 if dx == 0 else 1 if dx > 0 else -1,
        0 if dy == 0 else 1 if dy > 0 else -1,
    )
    if normalized not in actions or (dx and dy):
        _fail(f"interaction port direction不正: object={object_point} port={port}")
    return actions[normalized]


def _diagnostic_interaction_port(
    geometry: Mapping[str, Any], object_point: tuple[int, int],
    reserved: set[tuple[int, int]], blockers: set[tuple[int, int]],
) -> tuple[tuple[int, int], str, str] | None:
    """Choose a deterministic legal port for a local-incoming-absent map.

    This does not assert fresh-game global reachability.  It provides a normal
    direction plus A input after the runner teleports to the physical map.
    Prefer a collision-zero stance and real step.  A manifest-pinned map may
    have only collision-bearing stale terrain; in that diagnostic case an
    isolated in-bounds stance is retained explicitly without pretending a
    structural local incoming candidate is a global path.  Event tiles and
    every potentially visible object remain unavailable as ports.
    """

    adjacent = (
        (object_point[0], object_point[1] - 1),
        (object_point[0] - 1, object_point[1]),
        (object_point[0] + 1, object_point[1]),
        (object_point[0], object_point[1] + 1),
    )
    legal = [
        point for point in adjacent
        if _collision_zero(geometry, point)
        and point not in reserved and point not in blockers
    ]
    if legal:
        # A direction+A stance alone is not sufficient evidence: every
        # runtime-required owner must also receive real movement immediately
        # before the interaction.  Prefer a stance with a closed one-tile
        # cycle instead of silently choosing the first geometrically legal
        # adjacent tile and delegating movement to an unrelated map probe.
        point = next((
            candidate for candidate in legal
            if _diagnostic_walk_cycle(
                geometry, candidate, reserved, blockers,
            ) is not None
        ), legal[0])
        return point, _port_action(object_point, point), "ADJACENT_DIRECTION_A"
    beyond_rows = (
        ((object_point[0], object_point[1] - 1),
         (object_point[0], object_point[1] - 2)),
        ((object_point[0] - 1, object_point[1]),
         (object_point[0] - 2, object_point[1])),
        ((object_point[0] + 1, object_point[1]),
         (object_point[0] + 2, object_point[1])),
        ((object_point[0], object_point[1] + 1),
         (object_point[0], object_point[1] + 2)),
    )
    counter_candidates: list[tuple[int, int]] = []
    for middle, beyond in beyond_rows:
        if not _in_map_bounds(geometry, middle):
            continue
        middle_index = (
            middle[1] * int(geometry["width"]) + middle[0]
        )
        if int(geometry["behaviors"][middle_index]) != 0x80:
            continue
        if _collision_zero(geometry, beyond) \
                and beyond not in reserved and beyond not in blockers:
            counter_candidates.append(beyond)
    if counter_candidates:
        point = next((
            candidate for candidate in counter_candidates
            if _diagnostic_walk_cycle(
                geometry, candidate, reserved, blockers,
            ) is not None
        ), counter_candidates[0])
        return (
            point, _port_action(object_point, point),
            "COUNTER_DIRECTION_A",
        )
    isolated = [
        point for point in adjacent
        if _in_map_bounds(geometry, point)
        and point not in reserved and point not in blockers
    ]
    if isolated:
        # A collision-bearing arrival can still leave toward a collision-zero
        # tile in the stock field engine.  Prefer the candidate for which that
        # real key transition is demonstrably available; the loaded-field
        # mGBA run remains the final arbiter.
        point = next((
            candidate for candidate in isolated
            if _diagnostic_walk_cycle(
                geometry, candidate, reserved, blockers,
            ) is not None
        ), isolated[0])
        return (
            point, _port_action(object_point, point),
            "COLLISION_BEARING_DIAGNOSTIC_DIRECTION_A",
        )
    return None


def _diagnostic_walk_cycle(
    geometry: Mapping[str, Any], port: tuple[int, int],
    reserved: set[tuple[int, int]], blockers: set[tuple[int, int]],
) -> list[str] | None:
    directions = (
        ("UP", "DOWN", (0, -1)),
        ("LEFT", "RIGHT", (-1, 0)),
        ("RIGHT", "LEFT", (1, 0)),
        ("DOWN", "UP", (0, 1)),
    )
    for outward, inward, (dx, dy) in directions:
        neighbor = (port[0] + dx, port[1] + dy)
        if _collision_zero(geometry, neighbor) \
                and neighbor not in reserved and neighbor not in blockers:
            return [outward, inward]
    return None


def _block_elevation(
    geometry: Mapping[str, Any], point: tuple[int, int],
) -> int:
    x, y = point
    return (
        int(geometry["blocks"][y * int(geometry["width"]) + x]) >> 12
    ) & 0xF


def _runtime_position_root_binding_evidence(
    rom: bytes, *, npc_id: str, canonical_root: int,
    control: Mapping[str, Any],
    expected_aliases: Sequence[Mapping[str, Any]],
    position_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Separate the tag-3 state consumer from rooted producer aliases.

    ``_local_object_operation_evidence`` intentionally walks every explicit
    owner root.  A coordinate event may set the controlling flag and call the
    same position body that the tag-3 map-load consumer reaches.  Such an
    alias is real producer provenance, not a second map-load owner.  Bind the
    canonical consumer exactly, require every alias to reach the very same
    instruction bytes, and prove each current coordinate alias sets the flag
    immediately before it calls that body.
    """

    if not position_rows:
        _fail(f"runtime position root binding rows欠落:{npc_id}")

    def address(row: Mapping[str, Any], key: str) -> int:
        try:
            value = int(str(row[key]), 0)
        except (KeyError, TypeError, ValueError) as exc:
            _fail(f"runtime position {key}不正:{npc_id}:{exc}")
        if value < GBA_BASE or value >= GBA_BASE + len(rom):
            _fail(f"runtime position {key}範囲外:{npc_id}:0x{value:08X}")
        return value

    def site_identity(row: Mapping[str, Any]) -> tuple[int, int, str, tuple[int, int]]:
        instruction = address(row, "instruction_address")
        node = address(row, "node_address")
        raw_hex = row.get("raw_hex")
        position = row.get("literal_position")
        if not isinstance(raw_hex, str) or not raw_hex \
                or not isinstance(position, list) or len(position) != 2 \
                or any(isinstance(value, bool) or not isinstance(value, int)
                       for value in position):
            _fail(f"runtime position instruction identity不正:{npc_id}")
        return instruction, node, raw_hex, (position[0], position[1])

    canonical_rows = [
        row for row in position_rows
        if row.get("root_kind") == "MAP_SCRIPT"
        and isinstance(row.get("root_label"), str)
        and str(row["root_label"]).startswith("MAP_SCRIPT:3:")
        and address(row, "root_address") == canonical_root
    ]
    map_script_roots = {
        address(row, "root_address")
        for row in position_rows
        if row.get("root_kind") == "MAP_SCRIPT"
    }
    if not canonical_rows or map_script_roots != {canonical_root}:
        _fail(
            "runtime position canonical tag3 root binding不一致:"
            f"{npc_id} roots={sorted(map_script_roots)}"
        )
    canonical_sites = {site_identity(row) for row in canonical_rows}
    all_sites = {site_identity(row) for row in position_rows}
    if all_sites != canonical_sites:
        _fail(
            "runtime position producer alias instruction差分:"
            f"{npc_id} canonical={sorted(canonical_sites)} "
            f"all={sorted(all_sites)}"
        )

    roots_by_address: dict[int, dict[str, Any]] = {}
    for row in position_rows:
        root_address = address(row, "root_address")
        identity = {
            "root_address": f"0x{root_address:08X}",
            "root_label": str(row.get("root_label")),
            "root_kind": str(row.get("root_kind")),
        }
        previous = roots_by_address.setdefault(root_address, identity)
        if previous != identity:
            _fail(f"runtime position rooted producer identity衝突:{npc_id}")

    aliases = [
        roots_by_address[root]
        for root in sorted(roots_by_address) if root != canonical_root
    ]
    normalized_expected_aliases = sorted(
        (deepcopy(dict(row)) for row in expected_aliases),
        key=lambda row: str(row.get("root_address")),
    )
    if aliases != normalized_expected_aliases:
        _fail(
            "runtime position producer alias exact集合不一致:"
            f"{npc_id} expected={normalized_expected_aliases} actual={aliases}"
        )
    alias_proofs: list[dict[str, Any]] = []
    if aliases and control.get("kind") != "FLAG":
        _fail(f"runtime position non-FLAG producer alias未契約:{npc_id}")
    control_flag = int(control.get("id", -1))
    body_nodes = {site[1] for site in canonical_sites}
    for alias in aliases:
        if alias["root_kind"] != "COORD":
            _fail(
                "runtime position producer alias kind未契約:"
                f"{npc_id}:{alias}"
            )
        alias_root = int(alias["root_address"], 0)
        graph = SemanticScriptGraph(rom)
        graph.walk([alias_root])
        if graph.diagnostics:
            _fail(
                "runtime position producer alias CFG不正:"
                f"{npc_id}:{alias['root_address']}:{graph.diagnostics[:2]}"
            )
        proof_pairs: list[dict[str, str]] = []
        for body_node in sorted(body_nodes):
            parents = [
                node for node in graph.nodes.values()
                if body_node in node.edges
            ]
            if len(parents) != 1 or tuple(parents[0].edges) != (body_node,):
                _fail(
                    "runtime position producer alias body dominance不一致:"
                    f"{npc_id}:{alias['root_address']}:0x{body_node:08X}"
                )
            node = parents[0]
            instructions = list(node.instructions)
            for flag_index, instruction in enumerate(instructions):
                if instruction.opcode != 0x29 or len(instruction.raw) < 3 \
                        or struct.unpack_from("<H", instruction.raw, 1)[0] \
                            != control_flag:
                    continue
                for call_index, call in enumerate(
                    instructions[flag_index + 1:], start=flag_index + 1,
                ):
                    if call.opcode != 0x04 or len(call.raw) < 5:
                        continue
                    target = struct.unpack_from("<I", call.raw, 1)[0]
                    if target in body_nodes:
                        intervening_control_access = any(
                            candidate.opcode in {0x29, 0x2A, 0x2B}
                            and len(candidate.raw) >= 3
                            and struct.unpack_from(
                                "<H", candidate.raw, 1,
                            )[0] == control_flag
                            for candidate in instructions[
                                flag_index + 1:call_index
                            ]
                        )
                        if intervening_control_access:
                            continue
                        proof_pairs.append({
                            "parent_node": f"0x{node.address:08X}",
                            "set_flag_instruction": (
                                f"0x{instruction.address:08X}"
                            ),
                            "body_call_instruction": f"0x{call.address:08X}",
                            "body": f"0x{target:08X}",
                        })
        if len(proof_pairs) != len(body_nodes):
            _fail(
                "runtime position producer alias flag-before-body proof欠落:"
                f"{npc_id}:{alias['root_address']}"
            )
        alias_proofs.append({**alias, "flag_before_body": proof_pairs})

    return {
        "canonical_consumer": {
            "root_address": f"0x{canonical_root:08X}",
            "root_kind": "MAP_SCRIPT",
            "map_script_tag": 3,
        },
        "canonical_instruction_addresses": sorted({
            f"0x{site[0]:08X}" for site in canonical_sites
        }),
        "rooted_execution_provenance": [
            roots_by_address[root] for root in sorted(roots_by_address)
        ],
        "state_producer_aliases": alias_proofs,
        "assertions": {
            "canonical_tag3_consumer_root_exact": True,
            "state_producer_alias_set_exact": True,
            "all_rooted_aliases_share_canonical_instruction_bytes": True,
            "all_state_producer_aliases_flag_before_body_proven": True,
            "last_control_flag_access_before_alias_body_is_set": True,
            "no_second_map_script_consumer_root": True,
        },
    }


def _runtime_position_final_operation_evidence(
    rom: bytes, npc: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Re-decode position provenance from the post-placement final bytes."""

    required = {
        "npc_id", "group", "map", "object_index", "local_id",
        "script_pointer", "flag",
    }
    if not required.issubset(npc):
        _fail(
            "runtime position final evidence owner schema不一致:"
            f"{npc.get('npc_id')}"
        )
    group = int(npc["group"])
    number = int(npc["map"])
    state = _stage_map_state(rom, group, number)
    result = _local_object_operation_evidence(
        rom, group, number, state,
        int(npc["object_index"]), int(npc["local_id"]),
        int(npc["script_pointer"]), int(npc["flag"]),
    )
    operations = result.get("operations")
    if not isinstance(operations, list):
        _fail(f"runtime position final evidence operations不正:{npc['npc_id']}")
    return deepcopy([
        row for row in operations
        if isinstance(row, Mapping) and row.get("external_to_owner") is True
    ])


def _runtime_position_variant_state(
    control: Mapping[str, Any], *, runtime: bool,
) -> dict[str, list[dict[str, Any]]]:
    value = bool(
        control["runtime_value"] if runtime else control["static_value"]
    )
    reason = (
        "MAP_TAG3_RUNTIME_POSITION_CONDITION_RUNTIME"
        if runtime else "MAP_TAG3_RUNTIME_POSITION_CONDITION_STATIC"
    )
    if control["kind"] == "FLAG":
        return {
            "flags": [{
                "id": int(control["id"]), "value": value,
                "reason": reason,
            }],
            "vars": [],
        }
    if control["kind"] != "NATIONAL_DEX" or int(control["id"]) != 0:
        _fail("runtime position control kind/id不正")
    # The stock API also owns SaveBlock2.nationalMagic.  Flag/Var are kept in
    # the normal matrix columns, while the explicit NATIONAL_DEX control tells
    # the mGBA runner to call the stock Enable/Disable function and read back
    # all three owners before it performs the real map load.
    return {
        "flags": [{
            "id": int(control["flag_id"]), "value": value,
            "reason": reason,
        }],
        "vars": [{
            "id": int(control["var_id"]),
            "value": int(control["enabled_var_value"]) if value else 0,
            "reason": reason,
        }],
    }


def _runtime_position_layout_variant_evidence(
    rom: bytes, group: int, number: int, source: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Bind a conditional position state to its actual map-load layout.

    Dunsparce Tunnel changes its layout and its prospector position under the
    same National Dex predicate.  The map header retains the pre-Dex layout;
    therefore the post-Dex placement must follow ``gMapLayouts`` instead of
    reusing header geometry.
    """

    raw_variants = source.get("layout_variants")
    if raw_variants is None:
        return None
    key = (group, number)
    if key != (2, 34) or not isinstance(raw_variants, Mapping) \
            or set(raw_variants) != {"STATIC", "RUNTIME"}:
        _fail(f"runtime position layout variant scope/schema不一致:{key}")
    root = int(source["root"])
    graph = SemanticScriptGraph(rom)
    graph.walk([root])
    if graph.diagnostics:
        _fail(
            "runtime position layout root CFG diagnostics:"
            f"{graph.diagnostics}"
        )
    closure_instructions = {
        int(instruction.address): instruction
        for node_address in graph.distances(root)
        for instruction in graph.nodes[node_address].instructions
    }
    header_geometry = _map_geometry(rom, group, number)
    variants: list[dict[str, Any]] = []
    for variant_id in ("STATIC", "RUNTIME"):
        expected = raw_variants[variant_id]
        label = f"runtime position layout {group}/{number}/{variant_id}"
        if not isinstance(expected, Mapping):
            _fail(f"{label} contract不正")
        kind = str(expected.get("kind"))
        required = {
            "kind", "layout_id", "layout_pointer",
            "layout_struct_sha256", "blocks_sha256",
            "behaviors_u16le_sha256", "dimensions",
        }
        if kind == "SET_MAP_LAYOUT_INDEX":
            required |= {"instruction_address", "instruction_raw_hex"}
        if set(expected) != required or kind not in {
            "MAP_HEADER_DEFAULT", "SET_MAP_LAYOUT_INDEX",
        }:
            _fail(f"{label} exact schema不一致")
        layout_id = expected.get("layout_id")
        if isinstance(layout_id, bool) or not isinstance(layout_id, int):
            _fail(f"{label} layout ID不正")
        geometry = (
            header_geometry
            if kind == "MAP_HEADER_DEFAULT" else
            _map_geometry_from_layout_id(rom, group, number, layout_id)
        )
        if kind == "MAP_HEADER_DEFAULT" \
                and int(header_geometry["layout_id"]) != layout_id:
            _fail(f"{label} map header layout ID drift")
        actual = {
            "layout_pointer": int(geometry["layout_address"]),
            "layout_struct_sha256": str(geometry["layout_struct_sha256"]),
            "blocks_sha256": str(geometry["blocks_sha256"]),
            "behaviors_u16le_sha256": str(
                geometry["behaviors_u16le_sha256"]
            ),
            "dimensions": [
                int(geometry["width"]), int(geometry["height"]),
            ],
        }
        expected_identity = {
            "layout_pointer": expected.get("layout_pointer"),
            "layout_struct_sha256": expected.get("layout_struct_sha256"),
            "blocks_sha256": expected.get("blocks_sha256"),
            "behaviors_u16le_sha256": expected.get(
                "behaviors_u16le_sha256"
            ),
            "dimensions": expected.get("dimensions"),
        }
        if actual != expected_identity:
            _fail(
                f"{label} final gMapLayouts pointer/hash drift: "
                f"actual={actual} expected={expected_identity}"
            )
        selection: dict[str, Any]
        if kind == "SET_MAP_LAYOUT_INDEX":
            instruction_address = expected.get("instruction_address")
            raw_hex = expected.get("instruction_raw_hex")
            if isinstance(instruction_address, bool) \
                    or not isinstance(instruction_address, int) \
                    or not isinstance(raw_hex, str):
                _fail(f"{label} layout action contract不正")
            expected_raw = bytes.fromhex(raw_hex)
            instruction = closure_instructions.get(instruction_address)
            if expected_raw != bytes((0xA7,)) + struct.pack("<H", layout_id) \
                    or instruction is None \
                    or instruction.opcode != 0xA7 \
                    or instruction.raw != expected_raw:
                _fail(f"{label} layout action preimage/CFG drift")
            selection = {
                "kind": kind,
                "instruction_address": f"0x{instruction_address:08X}",
                "instruction_raw_hex": expected_raw.hex(),
                "instruction_in_root_cfg": True,
            }
        else:
            selection = {
                "kind": kind,
                "map_header_address": (
                    f"0x{GBA_BASE + int(geometry['header']):08X}"
                ),
                "header_layout_id_exact": True,
            }
        variants.append({
            "variant_id": variant_id,
            "layout_id": layout_id,
            "layout_pointer": f"0x{int(geometry['layout_address']):08X}",
            "layout_struct_sha256": actual["layout_struct_sha256"],
            "blocks_sha256": actual["blocks_sha256"],
            "behaviors_u16le_sha256": actual[
                "behaviors_u16le_sha256"
            ],
            "dimensions": actual["dimensions"],
            "selection": selection,
        })
    if [row["layout_id"] for row in variants] != [319, 318]:
        _fail("Dunsparce Tunnel layout variant ID drift")
    return {
        "map": [group, number],
        "root": f"0x{root:08X}",
        "variants": variants,
        "assertions": {
            "static_variant_uses_exact_dug_out_layout": True,
            "runtime_variant_uses_exact_map_header_layout": True,
            "layout_action_is_in_exact_tag3_root_cfg": True,
            "all_layout_struct_block_and_behavior_hashes_exact": True,
        },
    }


def _attach_runtime_position_state_contracts(
    rom: bytes, npc_catalog: dict[str, Any],
) -> dict[str, Any]:
    """Bind every scripted permanent position to its exact map-root state."""
    conditioned: list[dict[str, Any]] = []
    counts: Counter[tuple[int, int]] = Counter()
    layout_state_maps: dict[tuple[int, int], dict[str, Any]] = {}
    for npc in npc_catalog["npcs"]:
        npc["runtime_position_state_contract"] = None
        template = [int(npc["x"]), int(npc["y"])]
        runtime = list(map(int, npc.get("interaction_object", template)))
        if runtime == template:
            continue
        key = (int(npc["group"]), int(npc["map"]))
        source = RUNTIME_POSITION_STATE_MAP_CONTRACTS.get(key)
        if source is None:
            _fail(
                "conditional runtime position map contract欠落:"
                f"{npc['npc_id']} map={key}"
            )
        root = int(source["root"])
        prefix = bytes.fromhex(str(source["root_prefix_hex"]))
        root_offset = _rom_offset(
            root, len(prefix), f"runtime position root {npc['npc_id']}",
        )
        if rom[root_offset:root_offset + len(prefix)] != prefix:
            _fail(f"runtime position root preimage drift:{npc['npc_id']}")
        interaction_contract = npc.get("interaction_contract")
        if not isinstance(interaction_contract, dict):
            _fail(f"runtime position interaction contract不正:{npc['npc_id']}")
        evidence = _runtime_position_final_operation_evidence(rom, npc)
        # Placement repair may relocate the operand of a shared permanent
        # position instruction.  The relocation row keeps the source/preimage
        # proof; the public interaction contract must describe final ROM bytes.
        interaction_contract["external_cfg_evidence"] = deepcopy(evidence)
        position_rows = [
            row for row in evidence if isinstance(row, Mapping)
            and row.get("operation") == "SET_OBJECT_XY_PERMANENT"
            and row.get("literal_position") == runtime
        ] if isinstance(evidence, list) else []
        control = deepcopy(dict(source["control"]))
        root_binding = _runtime_position_root_binding_evidence(
            rom,
            npc_id=str(npc["npc_id"]),
            canonical_root=root,
            control=control,
            expected_aliases=source.get("producer_aliases", []),
            position_rows=position_rows,
        )
        layout_evidence = layout_state_maps.get(key)
        if layout_evidence is None:
            layout_evidence = _runtime_position_layout_variant_evidence(
                rom, key[0], key[1], source,
            )
            if layout_evidence is not None:
                layout_state_maps[key] = layout_evidence
        static_state = _runtime_position_variant_state(
            control, runtime=False,
        )
        runtime_state = _runtime_position_variant_state(
            control, runtime=True,
        )
        baseline_variant = (
            "RUNTIME" if control["kind"] == "NATIONAL_DEX" else "STATIC"
        )
        contract = {
            "kind": "CONDITIONAL_MAP_SCRIPT_RUNTIME_POSITION",
            "root": f"0x{root:08X}",
            "map_script_tag": 3,
            "control": control,
            "variants": [
                {
                    "variant_id": "STATIC", "object": template,
                    "state": static_state,
                    "baseline": baseline_variant == "STATIC",
                },
                {
                    "variant_id": "RUNTIME", "object": runtime,
                    "state": runtime_state,
                    "baseline": baseline_variant == "RUNTIME",
                },
            ],
            "setobjectxyperm_instruction_addresses": sorted(
                set(root_binding["canonical_instruction_addresses"])
            ),
            "root_prefix_hex": prefix.hex(),
            "assertions": {
                "map_script_tag3_exact": True,
                "root_preimage_exact": True,
                "static_and_runtime_positions_distinct": template != runtime,
                **root_binding["assertions"],
                "var_result_not_host_seeded": True,
            },
        }
        npc["runtime_position_state_contract"] = contract
        counts[key] += 1
        conditioned_row = {
            "npc_id": str(npc["npc_id"]),
            "map": list(key), "template": template, "runtime": runtime,
            "root": f"0x{root:08X}", "control": control,
            "root_binding": root_binding,
        }
        if layout_evidence is not None:
            conditioned_row["layout_variants"] = deepcopy(
                layout_evidence["variants"]
            )
        conditioned.append(conditioned_row)
    expected_counts = {
        key: int(value["owner_count"])
        for key, value in RUNTIME_POSITION_STATE_MAP_CONTRACTS.items()
    }
    if len(conditioned) != RUNTIME_POSITION_CONDITIONED_OWNER_COUNT \
            or dict(counts) != expected_counts:
        _fail(
            "conditional runtime position owner cardinality drift:"
            f"count={len(conditioned)} maps={dict(counts)}"
        )
    if set(layout_state_maps) != {(2, 34)}:
        _fail(
            "conditional runtime position layout state map集合drift:"
            f"{sorted(layout_state_maps)}"
        )
    return {
        "schema_version": 1,
        "kind": "STAGE61_CONDITIONAL_RUNTIME_POSITION_STATE_CONTRACTS",
        "conditioned_owner_count": len(conditioned),
        "conditioned_map_count": len(counts),
        "layout_state_map_count": len(layout_state_maps),
        "layout_state_maps": [
            layout_state_maps[key] for key in sorted(layout_state_maps)
        ],
        "owners": conditioned,
        "assertions": {
            "all_scripted_runtime_positions_conditioned": True,
            "all_condition_roots_final_rom_bound": True,
            "static_and_runtime_variants_declared": True,
            "conditional_layout_variants_final_rom_bound": True,
            "national_dex_uses_stock_enable_disable_not_var_result_seed": True,
        },
    }


def _runtime_position_layout_id_overrides(
    audit: Mapping[str, Any], variant_id: str,
) -> dict[tuple[int, int], int]:
    """Project validated layout-state evidence into the geometry planner."""

    if variant_id not in {"STATIC", "RUNTIME"}:
        _fail(f"runtime layout override variant不正:{variant_id}")
    rows = audit.get("layout_state_maps")
    if not isinstance(rows, list) \
            or len(rows) != audit.get("layout_state_map_count"):
        _fail("runtime layout state audit schema不正")
    result: dict[tuple[int, int], int] = {}
    for row in rows:
        if not isinstance(row, Mapping) \
                or not isinstance(row.get("map"), list) \
                or len(row["map"]) != 2:
            _fail("runtime layout state map row不正")
        key = (int(row["map"][0]), int(row["map"][1]))
        matches = [
            variant for variant in row.get("variants", [])
            if isinstance(variant, Mapping)
            and variant.get("variant_id") == variant_id
        ]
        if len(matches) != 1 or key in result:
            _fail(f"runtime layout state variant非一意:{key}/{variant_id}")
        result[key] = int(matches[0]["layout_id"])
    expected = (
        {(2, 34): 319} if variant_id == "STATIC" else {(2, 34): 318}
    )
    if result != expected:
        _fail(f"runtime layout override exact集合drift:{variant_id}:{result}")
    return result


def _attach_runtime_position_variant_executions(
    npc_catalog: dict[str, Any],
    runtime_placement: Mapping[str, Any],
    static_placement: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind independently planned real-input geometry to both map-load states."""

    runtime_rows = {
        str(row["npc_id"]): row for row in runtime_placement["objects"]
    }
    static_rows = {
        str(row["npc_id"]): row for row in static_placement["objects"]
    }
    expected_ids = {str(row["npc_id"]) for row in npc_catalog["npcs"]}
    if set(runtime_rows) != expected_ids or set(static_rows) != expected_ids:
        _fail("runtime position variant placement owner集合不一致")

    conditioned: list[dict[str, Any]] = []
    for npc in npc_catalog["npcs"]:
        npc_id = str(npc["npc_id"])
        contract = npc.get("runtime_position_state_contract")
        if contract is None:
            if runtime_rows[npc_id]["object"] != static_rows[npc_id]["object"]:
                _fail(
                    "非条件ownerのstatic/runtime placementが変化:"
                    f"{npc_id}"
                )
            continue
        variants = contract.get("variants")
        if not isinstance(variants, list) or {
            row.get("variant_id") for row in variants
            if isinstance(row, Mapping)
        } != {"STATIC", "RUNTIME"}:
            _fail(f"runtime position variant schema不正:{npc_id}")
        source_by_variant = {
            "STATIC": static_rows[npc_id],
            "RUNTIME": runtime_rows[npc_id],
        }
        variant_rows: list[dict[str, Any]] = []
        for variant in variants:
            variant_id = str(variant["variant_id"])
            source = source_by_variant[variant_id]
            expected_object = list(map(int, variant["object"]))
            execution = source.get("interaction_execution")
            if source.get("object") != expected_object \
                    or not isinstance(execution, Mapping) \
                    or execution.get("direct_script_call_forbidden") is not True \
                    or not execution.get("walk_sequence") \
                    or execution.get("actual_walk_required") is not True:
                _fail(
                    "runtime position variant real-walk contract不成立:"
                    f"{npc_id}/{variant_id}"
                )
            variant["interaction_execution"] = deepcopy(dict(execution))
            variant_rows.append({
                "variant_id": variant_id,
                "object": expected_object,
                "start": list(execution["start"]),
                "walk_sequence": list(execution["walk_sequence"]),
                "stance": list(execution["stance"]),
                "action": str(execution["action"]),
                "interaction_distance": int(execution["interaction_distance"]),
            })
        assertions = contract.get("assertions")
        if not isinstance(assertions, dict):
            _fail(f"runtime position assertions schema不正:{npc_id}")
        assertions.update({
            "both_variants_have_independent_final_geometry": True,
            "both_variants_require_actual_walk_before_a": True,
            "both_variants_forbid_direct_script_call": True,
        })
        conditioned.append({"npc_id": npc_id, "variants": variant_rows})

    if len(conditioned) != RUNTIME_POSITION_CONDITIONED_OWNER_COUNT:
        _fail(
            "runtime position variant execution cardinality不一致:"
            f"{len(conditioned)}"
        )
    return {
        "schema_version": 1,
        "kind": "STAGE61_CONDITIONAL_RUNTIME_POSITION_EXECUTIONS",
        "conditioned_owner_count": len(conditioned),
        "variant_count": 2 * len(conditioned),
        "owners": conditioned,
        "static_placement_assertions": deepcopy(
            dict(static_placement["assertions"]),
        ),
        "assertions": {
            "all_conditioned_owners_have_static_and_runtime_execution": True,
            "all_variants_use_real_walk_face_and_a": True,
            "all_variants_use_final_rom_geometry": True,
            "no_variant_uses_direct_script_call": True,
        },
    }


def _attach_interaction_contracts(
    npc_catalog: dict[str, Any], contracts: Mapping[str, Mapping[str, Any]],
) -> None:
    ids = {str(row["npc_id"]) for row in npc_catalog["npcs"]}
    if ids != set(contracts):
        _fail("interaction contract/NPC catalog owner集合不一致")
    for npc in npc_catalog["npcs"]:
        contract = dict(contracts[str(npc["npc_id"])])
        npc["interaction_contract"] = contract
        if "runtime_position" in contract:
            npc["interaction_object"] = list(contract["runtime_position"])
            npc["interaction_object_basis"] = contract["basis"]
        else:
            npc["interaction_object"] = [npc["x"], npc["y"]]
            npc["interaction_object_basis"] = "FINAL_OBJECT_TEMPLATE"


def _movement_action_names() -> dict[int, str]:
    """Load the pinned upstream movement ABI instead of guessing byte names."""

    path = ROOT / (
        "vendor/upstream/pokefirered/include/constants/"
        "event_object_movement.h"
    )
    result: dict[int, str] = {}
    for line in path.read_text(encoding="utf-8").splitlines():
        fields = line.split()
        if len(fields) != 3 or fields[0] != "#define" \
                or not fields[1].startswith("MOVEMENT_ACTION_") \
                or not fields[2].startswith("0x"):
            continue
        value = int(fields[2], 16)
        if value in result:
            _fail(f"movement action ABI ID重複: {value:#x}")
        result[value] = fields[1].removeprefix("MOVEMENT_ACTION_")
    if result.get(0x10) != "WALK_NORMAL_DOWN" \
            or result.get(0xFE) != "STEP_END":
        _fail("movement action ABI provenance不一致")
    return result


def _movement_script_offsets(raw_hex: str) -> dict[str, Any]:
    """Return exact relative tiles traversed by one movement byte stream."""

    raw = bytes.fromhex(raw_hex)
    if not raw or raw[-1] != 0xFE or 0xFE in raw[:-1]:
        _fail("movement scriptのSTEP_END ABI不正")
    names = _movement_action_names()
    x = y = 0
    points = [(0, 0)]
    actions: list[dict[str, Any]] = []
    for action in raw[:-1]:
        name = names.get(action)
        if name is None:
            _fail(f"movement action意味未分類: {action:#04x}")
        direction = next((
            token for token in ("DOWN", "UP", "LEFT", "RIGHT")
            if name.endswith(token)
        ), None)
        moves = (
            "IN_PLACE" not in name and direction is not None and (
                name.startswith((
                    "WALK_", "RIDE_WATER_CURRENT_", "SLIDE_",
                    "PLAYER_RUN_", "JUMP_", "GLIDE_",
                ))
                or (name.startswith("ACRO_") and (
                    "_MOVE_" in name or "_JUMP_" in name
                ))
            )
        )
        distance = 2 if name.startswith("JUMP_2_") else 1
        delta = {
            "DOWN": (0, 1), "UP": (0, -1),
            "LEFT": (-1, 0), "RIGHT": (1, 0),
        }.get(direction, (0, 0)) if moves else (0, 0)
        for _ in range(distance if moves else 0):
            x += delta[0]
            y += delta[1]
            points.append((x, y))
        actions.append({
            "id": action, "name": name,
            "displacement": [delta[0] * distance, delta[1] * distance],
        })
    return {
        "actions": actions,
        "relative_tiles": [list(point) for point in points],
        "final_offset": [x, y],
        "meaning_source": (
            "PINNED_POKEFIRERED_EVENT_OBJECT_MOVEMENT_CONSTANTS"
        ),
    }


def _external_movement_footprint(
    operations: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    scripts: dict[tuple[str, str], dict[str, Any]] = {}
    tiles = {(0, 0)}
    absolute_tiles: set[tuple[int, int]] = set()
    for row in operations:
        raw_hex = row.get("movement_actions_hex")
        if not isinstance(raw_hex, str):
            continue
        key = (str(row["movement_script_pointer"]), raw_hex)
        contract = scripts.setdefault(key, _movement_script_offsets(raw_hex))
    path_rows: list[dict[str, Any]] = []
    by_path: dict[tuple[str, str], list[Mapping[str, Any]]] = defaultdict(list)
    for row in operations:
        by_path[(str(row["root_label"]), str(row["node_address"]))].append(row)
    for (root_label, node_address), node_operations in sorted(by_path.items()):
        x = y = 0
        absolute = False
        path_tiles = {(0, 0)}
        absolute_path_tiles: set[tuple[int, int]] = set()
        instruction_addresses: list[str] = []
        for row in sorted(
            node_operations, key=lambda item: int(item["instruction_index"]),
        ):
            operation = str(row["operation"])
            if operation == "ADD_OBJECT":
                x = y = 0
                absolute = False
                path_tiles.add((0, 0))
            if operation in {"SET_OBJECT_XY", "SET_OBJECT_XY_PERMANENT"} \
                    and "literal_position" in row:
                x, y = (int(value) for value in row["literal_position"])
                absolute = True
                absolute_path_tiles.add((x, y))
            raw_hex = row.get("movement_actions_hex")
            if isinstance(raw_hex, str):
                contract = scripts[(
                    str(row["movement_script_pointer"]), raw_hex,
                )]
                for relative in contract["relative_tiles"]:
                    point = (x + int(relative[0]), y + int(relative[1]))
                    if absolute:
                        absolute_path_tiles.add(point)
                    else:
                        path_tiles.add(point)
                x += int(contract["final_offset"][0])
                y += int(contract["final_offset"][1])
                instruction_addresses.append(str(row["instruction_address"]))
            if operation == "REMOVE_OBJECT":
                # A subsequent ADD starts again at the ObjectEventTemplate.
                x = y = 0
                absolute = False
        tiles.update(path_tiles)
        absolute_tiles.update(absolute_path_tiles)
        if instruction_addresses:
            path_rows.append({
                "root_label": root_label,
                "node_address": node_address,
                "movement_instruction_addresses": instruction_addresses,
                "relative_tiles": [
                    list(point) for point in sorted(
                        path_tiles, key=lambda p: (p[1], p[0]),
                    )
                ],
                "absolute_runtime_tiles": [
                    list(point) for point in sorted(
                        absolute_path_tiles, key=lambda p: (p[1], p[0]),
                    )
                ],
                "final_offset": [x, y],
                "proof": "SAME_CFG_NODE_EXACT_INSTRUCTION_ORDER",
            })
    return {
        "script_count": len(scripts),
        "scripts": [{
            "pointer": pointer, "raw_hex": raw_hex, **contract,
        } for (pointer, raw_hex), contract in sorted(scripts.items())],
        "ordered_node_paths": path_rows,
        "conservative_independent_relative_tiles": [
            list(point) for point in sorted(tiles, key=lambda p: (p[1], p[0]))
        ],
        "absolute_runtime_tiles": [
            list(point) for point in sorted(
                absolute_tiles, key=lambda p: (p[1], p[0]),
            )
        ],
        "basis": (
            "SAME_CFG_NODE_MOVEMENTS_COMPOSE_IN_EXACT_INSTRUCTION_ORDER_"
            "AND_EVERY_TRANSLATED_TRAVERSED_TILE_COLLISION_CHECKED"
        ),
    }


def _repair_manual_interaction_placements(
    stage60: bytes, output: bytearray, declared: list[dict[str, Any]],
    npc_catalog: Mapping[str, Any], initial_placement: Mapping[str, Any],
    contracts: dict[str, dict[str, Any]],
    coords: Sequence[tuple[int, int, str]],
    scripted_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    connection_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    engine_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
) -> dict[str, Any]:
    """Allocate every manual owner and stance jointly, then re-run final BFS.

    All templates are visible blockers for the conservative fresh state.  A
    target referenced by external object bytecode is anchored at its exact
    template position; peer relocation may open a route but a cut-scene actor
    is never moved speculatively.  Other targets are allocated per-map with
    backtracking.  The selected stance is reserved together with the object,
    and completion is accepted only after one final BFS with *all* selected
    objects present.

    A relocated target is normalized to the stationary facing direction of its
    selected stance and its movement range is cleared.  This makes normal
    direction+A input deterministic instead of depending on a wander frame.
    Trainer sight range/type bytes remain untouched, and its new exact sight
    ray begins at that same stance direction; both source and final contracts
    are emitted below.
    """

    initial_by_id = {
        str(row["npc_id"]): row for row in initial_placement["objects"]
    }
    npc_by_id = {
        str(row["npc_id"]): row for row in npc_catalog["npcs"]
    }
    initially_portless_ids = {
        npc_id for npc_id, placement in initial_by_id.items()
        if placement["port"] is None
        and contracts[npc_id]["mode"] == "MANUAL_INPUT_REQUIRED"
    }
    repair_maps = {
        (int(npc_by_id[npc_id]["group"]), int(npc_by_id[npc_id]["map"]))
        for npc_id in initially_portless_ids
    }
    # Joint allocation must reserve ports for already-reachable peers too;
    # otherwise a later repair can cut an earlier owner's only route.  Include
    # every manual owner on every affected map and minimize displacement by
    # candidate score.  Hidden actors and exact scripted runtime positions stay
    # fixed blockers outside this set.
    targets = [
        npc for npc in npc_catalog["npcs"]
        if (int(npc["group"]), int(npc["map"])) in repair_maps
        and contracts[str(npc["npc_id"])]["mode"] == "MANUAL_INPUT_REQUIRED"
    ]
    by_map: dict[tuple[int, int], list[Mapping[str, Any]]] = defaultdict(list)
    for npc in targets:
        by_map[(int(npc["group"]), int(npc["map"]))].append(npc)
    repairs: list[dict[str, Any]] = []
    anchored_count = 0
    search_backtrack_count = 0
    facing_for_port = {
        (0, -1): 0x07, (0, 1): 0x08,
        (-1, 0): 0x09, (1, 0): 0x0A,
    }
    position_sensitive_operations = {
        "COPY_OBJECT_XY_TO_PERMANENT",
    }
    for (group, number), map_targets in sorted(by_map.items()):
        current = bytes(output)
        state = _stage_map_state(current, group, number)
        geometry = _map_geometry(current, group, number)
        seeds, entry_report, reserved_events = _map_entry_seeds(
            current, group, number, state, geometry,
            coords, scripted_entries, connection_entries, engine_entries,
        )
        decoded = [_object_fields(raw) for raw in state["objects"]]
        objects_offset = _rom_offset(
            int(state["pointers"]["objects"]),
            len(state["objects"]) * 24,
            f"joint interaction object array {group}/{number}",
        )
        target_indices = {int(row["object_index"]) for row in map_targets}
        fixed_objects = set()
        for index, row in enumerate(decoded):
            if index in target_indices:
                continue
            peer_id = f"OBJECT:{group:03d}/{number:03d}:{index:03d}"
            runtime = contracts.get(peer_id, {}).get("runtime_position")
            fixed_objects.add(
                tuple(int(value) for value in runtime)
                if isinstance(runtime, list) and len(runtime) == 2 else
                (int(row["x"]), int(row["y"]))
            )
        base_reached = _reachable_distances(
            geometry, seeds, fixed_objects,
        )
        if not base_reached:
            _fail(f"interaction placement入口componentが空です: {group}/{number}")

        candidate_sets: list[tuple[Mapping[str, Any], list[dict[str, Any]]]] = []
        width, height = int(geometry["width"]), int(geometry["height"])
        for npc in sorted(map_targets, key=lambda row: str(row["npc_id"])):
            npc_id = str(npc["npc_id"])
            index = int(npc["object_index"])
            fields = decoded[index]
            runtime_position = contracts[npc_id].get("runtime_position")
            origin_point = (
                tuple(int(value) for value in runtime_position)
                if isinstance(runtime_position, list)
                and len(runtime_position) == 2 else
                (int(fields["x"]), int(fields["y"]))
            )
            external_ops = contracts[npc_id].get("external_cfg_evidence", [])
            template_cutscene_footprint = _external_movement_footprint(
                external_ops
            )
            movement_footprint = (
                {
                    **template_cutscene_footprint,
                    "conservative_independent_relative_tiles": [[0, 0]],
                    "basis": (
                        "PERMANENT_RUNTIME_POSITION_IS_PATCHED_SEPARATELY_"
                        "TEMPLATE_CUTSCENE_PATH_REMAINS_AT_ORIGINAL_TEMPLATE"
                    ),
                }
                if runtime_position is not None else
                template_cutscene_footprint
            )
            absolute_runtime_tiles = [
                tuple(point)
                for point in movement_footprint["absolute_runtime_tiles"]
            ]
            position_sensitive = sorted({
                str(row["operation"]) for row in external_ops
                if str(row["operation"]) in position_sensitive_operations
            })
            position_site = objects_offset + index * 24 + 4
            overlapping_position_declarations = [
                row for row in declared
                if not (
                    position_site + 7 <= int(row["start"])
                    or int(row["end_exclusive"]) <= position_site
                )
            ]
            materialized_payload_position = bool(
                overlapping_position_declarations
                and all(
                    row["category"] == "PAYLOAD"
                    for row in overlapping_position_declarations
                )
            )
            prepatched_position = any(
                row["category"] != "PAYLOAD"
                for row in overlapping_position_declarations
            )
            provenance_anchored = str(npc["owner_provenance"]) in {
                "STAGE58_POST_LEDGER_EXACT_MANIFEST",
            }
            anchored = (
                bool(position_sensitive) or prepatched_position
                or provenance_anchored
            )
            anchored_count += int(anchored)
            candidates: list[dict[str, Any]] = []
            object_points = (
                [origin_point]
                if anchored else
                [(x, y) for y in range(height) for x in range(width)]
            )
            candidate_rejections: Counter[str] = Counter()
            for x, y in object_points:
                    object_point = (x, y)
                    if not _collision_zero(geometry, object_point) \
                            or object_point in reserved_events \
                            or object_point in fixed_objects:
                        candidate_rejections["OBJECT_TILE"] += 1
                        continue
                    translated_footprint = [
                        (x + int(relative[0]), y + int(relative[1]))
                        for relative in movement_footprint[
                            "conservative_independent_relative_tiles"
                        ]
                    ]
                    if any(
                        not _collision_zero(geometry, point)
                        # Coord/BG triggers are not collision and scripted
                        # actors may intentionally cross them.  They remain
                        # forbidden for the template and player stance, while
                        # the movement footprint excludes only physical object
                        # blockers and non-walkable/elevation-changing tiles.
                        or point in fixed_objects
                        or _block_elevation(geometry, point)
                            != _block_elevation(geometry, object_point)
                        for point in translated_footprint
                    ):
                        candidate_rejections["MOVEMENT_FOOTPRINT"] += 1
                        continue
                    for order, port in enumerate((
                        (x, y - 1), (x - 1, y), (x + 1, y), (x, y + 1),
                    )):
                        if port not in base_reached \
                                or port in reserved_events \
                                or port in fixed_objects:
                            candidate_rejections["PORT_NOT_REACHABLE"] += 1
                            continue
                        if _block_elevation(geometry, port) != \
                                _block_elevation(geometry, object_point):
                            candidate_rejections["PORT_ELEVATION"] += 1
                            continue
                        delta = (port[0] - x, port[1] - y)
                        if runtime_position is not None \
                                and int(fields["trainer_type"]) != 0 \
                                and int(fields["sight_range"]) != 0 \
                                and int(fields["movement_type"]) != \
                                facing_for_port[delta]:
                            # setobjectxyperm changes only position.  Keep its
                            # authored runtime-facing ABI and select the first
                            # actual sight tile rather than claiming an
                            # arbitrary side is a trainer interaction ray.
                            candidate_rejections[
                                "RUNTIME_TRAINER_SIGHT_FACING"
                            ] += 1
                            continue
                        candidates.append({
                            "object": object_point,
                            "port": port,
                            "distance_from_entry": base_reached[port],
                            "replacement_movement_type": facing_for_port[delta],
                            "external_movement_footprint": movement_footprint,
                            "translated_external_movement_tiles": [
                                list(point) for point in translated_footprint
                            ],
                            "absolute_runtime_tile_elevations": [{
                                "tile": list(point),
                                "elevation": _block_elevation(geometry, point),
                                "collision_zero": _collision_zero(
                                    geometry, point,
                                ),
                            } for point in absolute_runtime_tiles],
                            "prepatched_position_anchored": prepatched_position,
                            "materialized_payload_position": (
                                materialized_payload_position
                            ),
                            "provenance_position_anchored": provenance_anchored,
                            "score": (
                                abs(x - origin_point[0])
                                + abs(y - origin_point[1]),
                                base_reached[port], y, x, order,
                            ),
                        })
            if not candidates:
                _fail(
                    f"決定論的interaction placement候補なし: {npc_id} "
                    f"anchored={anchored} origin={origin_point} "
                    f"map={width}x{height} entry={len(base_reached)} "
                    f"fixed={len(fixed_objects)} reserved={len(reserved_events)} "
                    f"footprint={movement_footprint} "
                    f"rejections={dict(candidate_rejections)}"
                )
            candidates.sort(key=lambda row: row["score"])
            candidate_sets.append((npc, candidates))

        # Minimum remaining values first makes the exact backtracking stable
        # and keeps dense maps practical.  npc_id is the deterministic tie
        # breaker; result rows are sorted back to owner order afterwards.
        candidate_sets.sort(key=lambda item: (
            len(item[1]), str(item[0]["npc_id"]),
        ))
        candidate_counts = {
            str(npc["npc_id"]): len(candidates)
            for npc, candidates in candidate_sets
        }
        assignments: dict[str, dict[str, Any]] = {}
        selected_objects = set(fixed_objects)
        selected_ports: set[tuple[int, int]] = set()

        def search(index: int) -> bool:
            nonlocal search_backtrack_count
            if index == len(candidate_sets):
                final_reached = _reachable_distances(
                    geometry, seeds, selected_objects,
                )
                return all(
                    tuple(row["port"]) in final_reached
                    for row in assignments.values()
                )
            npc, candidates = candidate_sets[index]
            npc_id = str(npc["npc_id"])
            for candidate in candidates:
                object_point = tuple(candidate["object"])
                port = tuple(candidate["port"])
                if object_point in selected_objects \
                        or object_point in selected_ports \
                        or port in selected_objects or port in selected_ports:
                    continue
                selected_objects.add(object_point)
                selected_ports.add(port)
                assignments[npc_id] = candidate
                reached = _reachable_distances(
                    geometry, seeds, selected_objects,
                )
                viable = all(
                    tuple(row["port"]) in reached
                    for row in assignments.values()
                )
                if viable and search(index + 1):
                    return True
                assignments.pop(npc_id)
                selected_ports.remove(port)
                selected_objects.remove(object_point)
                search_backtrack_count += 1
            return False

        if not search(0):
            detail = {
                str(npc["npc_id"]): len(candidates)
                for npc, candidates in candidate_sets
            }
            _fail(
                f"map単位joint interaction placement解なし: "
                f"{group}/{number} candidates={detail}"
            )
        final_reached = _reachable_distances(
            geometry, seeds, selected_objects,
        )
        if any(
            tuple(row["port"]) not in final_reached
            for row in assignments.values()
        ):
            _fail(f"joint placement最終BFS再検証FAIL: {group}/{number}")

        for npc in sorted(map_targets, key=lambda row: str(row["npc_id"])):
            npc_id = str(npc["npc_id"])
            index = int(npc["object_index"])
            fields = decoded[index]
            chosen = assignments[npc_id]
            object_point = tuple(chosen["object"])
            port = tuple(chosen["port"])
            elevation = _block_elevation(geometry, object_point)
            external_cfg = list(
                contracts[npc_id].get("external_cfg_evidence", [])
            )
            position_sensitive = sorted({
                str(item["operation"]) for item in external_cfg
                if str(item["operation"]) in position_sensitive_operations
            })
            prepatched_position = bool(
                chosen["prepatched_position_anchored"]
            )
            materialized_payload_position = bool(
                chosen["materialized_payload_position"]
            )
            provenance_anchored = bool(
                chosen["provenance_position_anchored"]
            )
            anchored = (
                bool(position_sensitive) or prepatched_position
                or provenance_anchored
            )
            runtime_original = contracts[npc_id].get("runtime_position")
            runtime_positioned = (
                isinstance(runtime_original, list)
                and len(runtime_original) == 2
            )
            source_interaction_point = (
                tuple(int(value) for value in runtime_original)
                if runtime_positioned else
                (int(fields["x"]), int(fields["y"]))
            )
            moved = object_point != source_interaction_point
            exact_trainer_facing = (
                not runtime_positioned
                and int(fields["trainer_type"]) != 0
                and int(fields["sight_range"]) != 0
            )
            movement_type = (
                int(fields["movement_type"])
                if (not moved and not exact_trainer_facing)
                or runtime_positioned else
                int(chosen["replacement_movement_type"])
            )
            source_range = int(state["objects"][index][10])
            replacement_range = (
                source_range
                if (not moved and not exact_trainer_facing)
                or runtime_positioned else 0
            )
            site = objects_offset + index * 24 + 4
            current_preimage = bytes(output[site:site + 7])
            replacement = (
                current_preimage if runtime_positioned else
                struct.pack(
                    "<hhBBB", object_point[0], object_point[1], elevation,
                    movement_type, replacement_range,
                )
            )
            expected = (
                current_preimage if materialized_payload_position else
                stage60[site:site + len(replacement)]
            )
            changed = replacement != current_preimage
            if changed:
                if current_preimage != expected:
                    _fail(
                        f"interaction placement preimageは既変更です: {npc_id}"
                    )
                if materialized_payload_position:
                    _apply_materialized_payload_patch(
                        output, declared,
                        name=f"all_npc_interaction_placement::{npc_id}",
                        offset=site, expected=expected,
                        replacement=replacement,
                        category="ALL_NPC_FINAL_INTERACTION_PLACEMENT",
                    )
                else:
                    _apply_patch(
                        stage60, output, declared,
                        name=f"all_npc_interaction_placement::{npc_id}",
                        offset=site, expected=expected,
                        replacement=replacement,
                        category="ALL_NPC_FINAL_INTERACTION_PLACEMENT",
                    )
            runtime_position_patches: list[dict[str, Any]] = []
            if runtime_positioned and moved:
                runtime_sites = sorted({
                    int(str(item["instruction_address"]), 16)
                    for item in external_cfg
                    if item["operation"] == "SET_OBJECT_XY_PERMANENT"
                    and item.get("literal_position") == runtime_original
                })
                if not runtime_sites:
                    _fail(f"runtime position patch site欠落: {npc_id}")
                runtime_replacement = struct.pack(
                    "<HH", object_point[0], object_point[1],
                )
                for instruction_address in runtime_sites:
                    runtime_site = instruction_address - GBA_BASE + 3
                    runtime_expected = stage60[runtime_site:runtime_site + 4]
                    if runtime_expected != struct.pack(
                        "<HH", int(runtime_original[0]),
                        int(runtime_original[1]),
                    ):
                        _fail(f"runtime position expected byte不一致: {npc_id}")
                    _apply_patch(
                        stage60, output, declared,
                        name=(
                            f"all_npc_runtime_interaction_position::{npc_id}::"
                            f"{instruction_address:08X}"
                        ),
                        offset=runtime_site, expected=runtime_expected,
                        replacement=runtime_replacement,
                        category="ALL_NPC_RUNTIME_INTERACTION_PLACEMENT",
                    )
                    runtime_position_patches.append({
                        "instruction_address": (
                            f"0x{instruction_address:08X}"
                        ),
                        "operand_address": f"0x{GBA_BASE + runtime_site:08X}",
                        "expected_hex": runtime_expected.hex(),
                        "replacement_hex": runtime_replacement.hex(),
                    })
                contracts[npc_id]["runtime_position"] = list(object_point)
            row = {
                "npc_id": npc_id, "map": [group, number],
                "object_index": index, "local_id": int(npc["local_id"]),
                "source_object": list(source_interaction_point),
                "source_template_object": [
                    int(fields["x"]), int(fields["y"]),
                ],
                "replacement_object": list(object_point),
                "selected_port": list(port),
                "action": _port_action(object_point, port),
                "distance_from_entry": chosen["distance_from_entry"],
                "candidate_count": candidate_counts[npc_id],
                "source_elevation": int(fields["elevation"]),
                "replacement_elevation": elevation,
                "source_movement_type": int(fields["movement_type"]),
                "replacement_movement_type": movement_type,
                "source_movement_range_x": source_range & 0xF,
                "source_movement_range_y": source_range >> 4,
                "replacement_movement_range_x": replacement_range & 0xF,
                "replacement_movement_range_y": replacement_range >> 4,
                "trainer_type": int(fields["trainer_type"]),
                "trainer_sight_range": int(fields["sight_range"]),
                "entry_seed_count": int(entry_report["seed_count"]),
                "patch_address": f"0x{GBA_BASE + site:08X}",
                "expected_hex": expected.hex(),
                "replacement_hex": replacement.hex(),
                "patch_applied": changed,
                "runtime_positioned": runtime_positioned,
                "runtime_position_patches": runtime_position_patches,
                "externally_scripted_position_anchored": anchored,
                "prepatched_position_anchored": prepatched_position,
                "materialized_payload_position": (
                    materialized_payload_position
                ),
                "provenance_position_anchored": provenance_anchored,
                "external_cfg_evidence": list(
                    external_cfg
                ),
                "position_sensitive_external_operations": position_sensitive,
                "external_movement_footprint": chosen[
                    "external_movement_footprint"
                ],
                "translated_external_movement_tiles": chosen[
                    "translated_external_movement_tiles"
                ],
                "absolute_runtime_tile_elevations": chosen[
                    "absolute_runtime_tile_elevations"
                ],
                "final_bfs_reachable": tuple(port) in final_reached,
                "trainer_sight_contract": {
                    "trainer_type_preserved": int(fields["trainer_type"]),
                    "sight_range_preserved": int(fields["sight_range"]),
                    "facing_toward_selected_port": (
                        movement_type == int(chosen["replacement_movement_type"])
                    ),
                    "selected_port_is_first_sight_tile": (
                        int(fields["trainer_type"]) == 0
                        or int(fields["sight_range"]) == 0
                        or movement_type == int(
                            chosen["replacement_movement_type"]
                        )
                    ),
                },
                "basis": (
                    "MAP_WIDE_NEAREST_COLLISION_ZERO_SAME_ELEVATION_LOCAL_"
                    "INCOMING_COMPONENT_WITH_EVENT_AND_OBJECT_RESERVATIONS"
                ),
            }
            repairs.append(row)
            contracts[npc_id]["relocation"] = row
    if len(repairs) != len(targets):
        _fail(
            f"manual interaction placement修復件数drift: "
            f"{len(repairs)}/{len(targets)}"
        )
    return {
        "schema_version": 1,
        "algorithm": (
            "DETERMINISTIC_NEAREST_FINAL_OBJECT_AND_PORT_JOINT_ALLOCATION"
        ),
        "repair_count": len(repairs),
        "initially_portless_owner_count": len(initially_portless_ids),
        "affected_map_count": len(repair_maps),
        "jointly_reserved_manual_owner_count": len(targets),
        "patch_count": sum(bool(row["patch_applied"]) for row in repairs),
        "externally_scripted_anchor_count": anchored_count,
        "search_backtrack_count": search_backtrack_count,
        "movement_normalized_count": sum(
            row["source_movement_type"] != row["replacement_movement_type"]
            for row in repairs
        ),
        "elevation_changed_count": sum(
            row["source_elevation"] != row["replacement_elevation"]
            for row in repairs
        ),
        "repairs": repairs,
        "assertions": {
            "every_initially_portless_template_repaired": (
                initially_portless_ids.issubset({
                    str(row["npc_id"]) for row in repairs
                })
            ),
            "all_candidates_use_collision_zero_object_and_port": True,
            "all_ports_are_in_exact_entry_component": True,
            "all_event_warp_coord_bg_tiles_reserved": True,
            "all_other_object_tiles_reserved": True,
            "all_object_and_port_elevations_match": True,
            "all_trainer_sight_contracts_explicit_and_valid": all(
                row["trainer_sight_contract"][
                    "selected_port_is_first_sight_tile"
                ]
                for row in repairs
            ),
            "all_position_sensitive_external_dependencies_anchored": all(
                not row["position_sensitive_external_operations"]
                or row["externally_scripted_position_anchored"]
                for row in repairs
            ),
            "all_selected_ports_reachable_after_final_joint_assignment": all(
                row["final_bfs_reachable"] for row in repairs
            ),
        },
    }


def _all_npc_placement_audit(
    rom: bytes, coords: Sequence[tuple[int, int, str]],
    npc_catalog: Mapping[str, Any], trainer_plan: Mapping[str, Any],
    scripted_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    connection_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    engine_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    entry_exceptions: Mapping[tuple[int, int], Mapping[str, Any]],
    shadow_aliases: Mapping[str, Mapping[str, Any]] | None = None,
    layout_id_overrides: Mapping[tuple[int, int], int] | None = None,
    *, require_hidden_only_exceptions: bool = False,
    require_local_incoming_component_ports: bool = False,
    require_runtime_execution_contracts: bool = False,
) -> dict[str, Any]:
    """Classify every script object against final map geometry and entrances."""

    shadow_by_source = dict(shadow_aliases or {})
    active_layout_overrides = dict(layout_id_overrides or {})
    if any(
        not isinstance(key, tuple) or len(key) != 2
        or any(
            isinstance(item, bool) or not isinstance(item, int)
            for item in key
        )
        or isinstance(layout_id, bool) or not isinstance(layout_id, int)
        for key, layout_id in active_layout_overrides.items()
    ):
        _fail("all-NPC placement layout override schema不正")
    shadow_by_canonical = {
        str(row["canonical_owner_id"]): row
        for row in shadow_by_source.values()
    }
    if len(shadow_by_source) != len(shadow_by_canonical):
        _fail("non-product shadow alias canonical owner重複")

    by_map: dict[tuple[int, int], list[dict[str, Any]]] = defaultdict(list)
    for npc in npc_catalog["npcs"]:
        by_map[(int(npc["group"]), int(npc["map"]))].append(npc)
    archive_ids = {
        (int(row["group_id"]), int(row["map_id"]), int(local_id))
        for row in trainer_plan["bindings"] if row.get("owner_kind") == "ARCHIVE"
        for local_id in row["local_ids"]
    }
    if len(archive_ids) != 71:
        _fail("全NPC配置auditのArchive owner集合drift")
    rows: list[dict[str, Any]] = []
    map_rows: list[dict[str, Any]] = []
    mode_counts: Counter[str] = Counter()
    archive_port_count = 0
    unclassified: list[str] = []
    port_conflicts: list[str] = []
    for group, number, map_key in coords:
        targets = by_map.get((group, number), [])
        if not targets:
            continue
        state = _stage_map_state(rom, group, number)
        override_layout_id = active_layout_overrides.get((group, number))
        geometry = (
            _map_geometry(rom, group, number)
            if override_layout_id is None else
            _map_geometry_from_layout_id(
                rom, group, number, override_layout_id,
            )
        )
        seeds, entry_report, reserved = _map_entry_seeds(
            rom, group, number, state, geometry,
            coords, scripted_entries, connection_entries, engine_entries,
        )
        decoded = [_object_fields(raw) for raw in state["objects"]]
        target_by_index = {
            int(row["object_index"]): row for row in targets
        }
        # Fresh-state is the conservative visibility superset: an object
        # visibility flag hides the template only when it is SET, therefore a
        # non-zero flag is *not* evidence that the object can be omitted from
        # collision/pathfinding.  Runtime-position contracts replace (rather
        # than add to) that template position.  Every matrix visibility state
        # can only remove members from this blocker set, so a port reachable
        # here remains reachable in every case where its owner is visible.
        fresh_visible_blockers = {
            tuple(target_by_index[index].get(
                "interaction_object", [row["x"], row["y"]],
            ))
            if index in target_by_index else (row["x"], row["y"])
            for index, row in enumerate(decoded)
        }
        duplicate_fresh_visible = len(fresh_visible_blockers) != len(decoded)
        permanent_count = sum(row["flag"] == 0 for row in decoded)
        reached = _reachable_distances(
            geometry, seeds, fresh_visible_blockers,
        )
        entry_exception = entry_exceptions.get((group, number))
        map_rows.append({
            "group": group, "map": number, "map_key": map_key,
            "width": geometry["width"], "height": geometry["height"],
            "geometry": {
                "basis": geometry["layout_basis"],
                "layout_id": geometry["layout_id"],
                "layout_pointer": f"0x{int(geometry['layout_address']):08X}",
                "layout_struct_sha256": geometry["layout_struct_sha256"],
                "blocks_sha256": geometry["blocks_sha256"],
                "behaviors_u16le_sha256": geometry[
                    "behaviors_u16le_sha256"
                ],
            },
            "script_object_count": len(targets),
            "permanent_object_count": permanent_count,
            "fresh_visible_blocker_count": len(fresh_visible_blockers),
            "duplicate_fresh_visible_object_tile": duplicate_fresh_visible,
            "reserved_event_tile_count": len(reserved),
            "reachable_tile_count": len(reached),
            "entry": entry_report,
            "local_static_incoming_exception": (
                dict(entry_exception) if entry_exception is not None else None
            ),
        })
        for npc in sorted(targets, key=lambda row: int(row["object_index"])):
            npc_id = str(npc["npc_id"])
            shadow_source = shadow_by_source.get(npc_id)
            shadow_canonical = shadow_by_canonical.get(npc_id)
            shadow_row = shadow_source or shadow_canonical
            template_raw = state["objects"][int(npc["object_index"])]
            template_fields = decoded[int(npc["object_index"])]
            if shadow_row is not None:
                role_prefix = "source" if shadow_source is not None else "canonical"
                expected_map = shadow_row[f"{role_prefix}_map"]
                expected_map_key = shadow_row[f"{role_prefix}_map_key"]
                expected_index = int(shadow_row[f"{role_prefix}_object_index"])
                expected_local = int(shadow_row[f"{role_prefix}_local_id"])
                if [group, number] != expected_map or map_key != expected_map_key \
                        or int(npc["object_index"]) != expected_index \
                        or int(template_fields["local_id"]) != expected_local:
                    _fail(f"non-product shadow alias physical owner drift: {npc_id}")
                range_byte = template_raw[10]
                actual_shared = {
                    "graphics_id": int(template_fields["graphics_id"]),
                    "x": int(template_fields["x"]),
                    "y": int(template_fields["y"]),
                    "elevation": int(template_fields["elevation"]),
                    "movement_type": int(template_fields["movement_type"]),
                    "movement_range_x": range_byte & 0xF,
                    "movement_range_y": range_byte >> 4,
                    "trainer_type": int(template_fields["trainer_type"]),
                    "sight_range": int(template_fields["sight_range"]),
                    "flag": int(template_fields["flag"]),
                }
                if actual_shared != shadow_row["shared_template_fields"]:
                    _fail(f"non-product shadow alias template drift: {npc_id}")
                expected_source_script = int(
                    str(shadow_row["source_script_pointer"]), 0,
                )
                if shadow_source is not None:
                    if int(template_fields["script_pointer"]) != expected_source_script:
                        _fail(f"non-product shadow source script drift: {npc_id}")
                elif int(npc.get("source_script_pointer") or -1) \
                        != expected_source_script:
                    _fail(f"non-product shadow canonical semantic drift: {npc_id}")
            template_point = (int(npc["x"]), int(npc["y"]))
            interaction_object = npc.get(
                "interaction_object", [npc["x"], npc["y"]],
            )
            object_point = (
                int(interaction_object[0]), int(interaction_object[1]),
            )
            contract = npc.get("interaction_contract", {})
            contract_mode = str(
                contract.get("mode", "MANUAL_INPUT_REQUIRED")
            )
            neighbors = (
                (object_point[0], object_point[1] - 1),
                (object_point[0] - 1, object_point[1]),
                (object_point[0] + 1, object_point[1]),
                (object_point[0], object_point[1] + 1),
            )
            physically_legal = [
                point for point in neighbors
                if _collision_zero(geometry, point)
                and point not in reserved
                and point not in fresh_visible_blockers
            ]
            natural = [point for point in physically_legal if point in reached]
            port: tuple[int, int] | None
            diagnostic = None
            diagnostic_walk_cycle = None
            if entry_exception is not None:
                diagnostic = _diagnostic_interaction_port(
                    geometry, object_point, reserved, fresh_visible_blockers,
                )
                if diagnostic is None:
                    if require_hidden_only_exceptions:
                        _fail(
                            f"entry exception final diagnostic portなし: "
                            f"{npc['npc_id']}"
                        )
                else:
                    diagnostic_walk_cycle = _diagnostic_walk_cycle(
                        geometry, diagnostic[0], reserved,
                        fresh_visible_blockers,
                    )
                port = None
                mode = (
                    "DIAGNOSTIC_TELEPORT_REQUIRED_LOCAL_INCOMING_ABSENT_"
                    f"{entry_exception['classification']}"
                )
                distance = None
            elif contract_mode == "SCRIPT_ACTOR_ONLY_HIDDEN":
                # The template is introduced/moved by another owner, but its
                # own script must still be exercised through the field-event
                # consumer once that lifecycle state is materialized.  Keep
                # it classified as non-product placement while deriving an
                # exact diagnostic stance for the runtime matrix.
                diagnostic = _diagnostic_interaction_port(
                    geometry, object_point, reserved, fresh_visible_blockers,
                )
                if diagnostic is None:
                    _fail(
                        "script actor runtime interaction portなし: "
                        f"{npc['npc_id']}"
                    )
                diagnostic_walk_cycle = _diagnostic_walk_cycle(
                    geometry, diagnostic[0], reserved,
                    fresh_visible_blockers,
                )
                port = None
                mode = "SCRIPT_ACTOR_ONLY_HIDDEN"
                distance = None
            else:
                port = natural[0] if natural else (
                    None if require_local_incoming_component_ports else
                    physically_legal[0] if physically_legal else None
                )
            if entry_exception is not None:
                pass
            elif contract_mode == "SCRIPT_ACTOR_ONLY_HIDDEN":
                pass
            elif natural:
                mode = "LOCAL_INCOMING_COMPONENT_ADJACENT"
                distance = reached[port]
            elif port is not None:
                mode = "LOCAL_STRUCTURAL_DIRECT_STOCK_WARP_ADJACENT"
                distance = None
            else:
                counter_candidates: list[tuple[tuple[int, int], bool]] = []
                for middle, beyond in zip(neighbors, (
                    (object_point[0], object_point[1] - 2),
                    (object_point[0] - 2, object_point[1]),
                    (object_point[0] + 2, object_point[1]),
                    (object_point[0], object_point[1] + 2),
                ), strict=True):
                    if not (
                        0 <= middle[0] < int(geometry["width"])
                        and 0 <= middle[1] < int(geometry["height"])
                    ):
                        continue
                    middle_index = middle[1] * int(geometry["width"]) + middle[0]
                    if int(geometry["behaviors"][middle_index]) != 0x80:
                        continue
                    if _collision_zero(geometry, beyond) \
                            and beyond not in reserved \
                            and beyond not in fresh_visible_blockers:
                        counter_candidates.append((beyond, beyond in reached))
                counter_candidates.sort(
                    key=lambda item: (not item[1], item[0][1], item[0][0])
                )
                if counter_candidates and (
                    counter_candidates[0][1] or not require_local_incoming_component_ports
                ):
                    port, is_natural = counter_candidates[0]
                    mode = (
                        "LOCAL_INCOMING_COMPONENT_COUNTER_INTERACTION"
                        if is_natural else "LOCAL_STRUCTURAL_DIRECT_STOCK_WARP_COUNTER_INTERACTION"
                    )
                    distance = reached.get(port)
                else:
                    port, distance = None, None
                    raw_walkable = [
                        point for point in neighbors if _collision_zero(geometry, point)
                    ]
                    if raw_walkable and all(point in reserved for point in raw_walkable):
                        mode = "CLASSIFIED_EVENT_RESERVED_NO_CONFLICT_FREE_PORT"
                    elif raw_walkable and all(
                        point in reserved or point in fresh_visible_blockers
                        for point in raw_walkable
                    ):
                        mode = "CLASSIFIED_VISIBLE_OBJECT_OR_EVENT_BLOCKED"
                    elif physically_legal and require_local_incoming_component_ports:
                        mode = "CLASSIFIED_NOT_IN_ENTRY_COMPONENT"
                    else:
                        mode = "CLASSIFIED_NO_FIELD_INTERACTION_GEOMETRY"
            mode_counts[mode] += 1
            row = {
                "npc_id": npc["npc_id"], "group": group, "map": number,
                "object_index": npc["object_index"], "local_id": npc["local_id"],
                "object": list(object_point), "object_flag": npc["flag"],
                "template_object": list(template_point),
                "interaction_object_basis": npc.get(
                    "interaction_object_basis", "FINAL_OBJECT_TEMPLATE",
                ),
                "interaction_contract_mode": contract_mode,
                "mode": mode,
                "port": list(port) if port is not None else None,
                "action": _port_action(object_point, port) if port is not None else None,
                "distance_from_entry": distance,
                "local_static_incoming_available": entry_exception is None,
                "diagnostic_port": (
                    list(diagnostic[0]) if diagnostic is not None else None
                ),
                "diagnostic_action": (
                    diagnostic[1] if diagnostic is not None else None
                ),
                "diagnostic_interaction_kind": (
                    diagnostic[2] if diagnostic is not None else None
                ),
                "diagnostic_walk_cycle": diagnostic_walk_cycle,
                "diagnostic_requires_real_step": (
                    diagnostic is not None
                    and diagnostic_walk_cycle is not None
                ),
                "diagnostic_isolated_port": (
                    diagnostic is not None
                    and diagnostic_walk_cycle is None
                ),
                "diagnostic_direct_script_call_forbidden": diagnostic is not None,
                "port_basis": (
                    "FINAL_ROM_LOCAL_COLLISION_COMPONENT_FROM_EXACT_INCOMING_"
                    "NOT_GLOBAL_ROOT_PROOF"
                    if mode.startswith("LOCAL_INCOMING_COMPONENT_") else
                    "RUNNER_STOCK_WARP_TO_CONFLICT_FREE_FINAL_ROM_TILE"
                    if mode.startswith("DIRECT_") else
                    "EXTERNAL_CFG_ACTOR_LIFECYCLE_AND_VISIBILITY_FLAG"
                    if mode == "SCRIPT_ACTOR_ONLY_HIDDEN" else
                    "MANIFEST_PINNED_LOCAL_INCOMING_ABSENT_DIAGNOSTIC_TELEPORT"
                    if mode.startswith("DIAGNOSTIC_TELEPORT_REQUIRED_LOCAL_INCOMING_ABSENT_") else
                    "EXACT_FINAL_ROM_GEOMETRY_EXCEPTION_NOT_SKIPPED"
                ),
                "non_product_shadow_alias": (
                    {
                        "classification": "CANONICAL_SHADOW_NON_PRODUCT_SOURCE",
                        "role": (
                            "NON_PRODUCT_SOURCE" if shadow_source is not None
                            else "CANONICAL_PHYSICAL_OWNER"
                        ),
                        "source_owner_id": str(shadow_row["source_owner_id"]),
                        "canonical_owner_id": str(
                            shadow_row["canonical_owner_id"],
                        ),
                    }
                    if shadow_row is not None else None
                ),
            }
            execution_port = port if port is not None else (
                diagnostic[0] if diagnostic is not None else None
            )
            execution_action = (
                _port_action(object_point, port)
                if port is not None else
                diagnostic[1] if diagnostic is not None else None
            )
            execution_kind = (
                "COUNTER_DIRECTION_A"
                if "COUNTER" in mode else
                diagnostic[2] if diagnostic is not None else
                "ADJACENT_DIRECTION_A"
            )
            row["interaction_execution"] = None
            if execution_port is not None and execution_action is not None:
                execution_delta = {
                    "UP": (0, -1), "DOWN": (0, 1),
                    "LEFT": (-1, 0), "RIGHT": (1, 0),
                }[execution_action]
                interaction_distance = (
                    2 if execution_kind == "COUNTER_DIRECTION_A" else 1
                )
                expected_object = (
                    execution_port[0]
                        + execution_delta[0] * interaction_distance,
                    execution_port[1]
                        + execution_delta[1] * interaction_distance,
                )
                if expected_object != object_point:
                    _fail(
                        "runtime interaction stance/action/distance不一致: "
                        f"{npc['npc_id']} stance={execution_port} "
                        f"action={execution_action} "
                        f"distance={interaction_distance}"
                    )
                counter_tile = None
                if interaction_distance == 2:
                    counter_tile = (
                        execution_port[0] + execution_delta[0],
                        execution_port[1] + execution_delta[1],
                    )
                    counter_index = (
                        counter_tile[1] * int(geometry["width"])
                        + counter_tile[0]
                    )
                    if not _in_map_bounds(geometry, counter_tile) \
                            or int(geometry["behaviors"][counter_index]) != 0x80:
                        _fail(
                            "counter interactionの中間metatile ABI不一致: "
                            f"{npc['npc_id']} counter={counter_tile}"
                        )
                walk_cycle = _diagnostic_walk_cycle(
                    geometry, execution_port, reserved,
                    fresh_visible_blockers,
                )
                walk_start = execution_port
                walk_sequence = list(walk_cycle or [])
                walk_basis = "FINAL_STANCE_CLOSED_ONE_TILE_CYCLE"
                actual_walk_exception = None
                if shadow_source is not None:
                    if entry_exception is None or str(entry_exception.get(
                        "classification",
                    )) != "CANONICAL_CLONE_SHADOWED_LOCAL_INCOMING_ABSENT" \
                            or list(execution_port) != shadow_source[
                                "source_diagnostic_stance"
                            ] \
                            or execution_action != shadow_source[
                                "source_diagnostic_action"
                            ] \
                            or walk_sequence:
                        _fail(f"non-product shadow source geometry drift: {npc_id}")
                    walk_start = execution_port
                    walk_sequence = []
                    walk_basis = (
                        "CANONICAL_SHADOW_NON_PRODUCT_SOURCE_DIAGNOSTIC_STANCE"
                    )
                    actual_walk_exception = {
                        "classification": "CANONICAL_SHADOW_NON_PRODUCT_SOURCE",
                        "canonical_owner_id": str(
                            shadow_source["canonical_owner_id"],
                        ),
                        "canonical_walk_required": True,
                        "source_teleport_face_a_required": True,
                        "direct_script_call_forbidden": True,
                    }
                elif shadow_canonical is not None:
                    canonical_start = tuple(map(
                        int, shadow_canonical["canonical_walk_start"],
                    ))
                    incoming_path = _shortest_safe_walk_path(
                        geometry, [canonical_start], execution_port,
                        fresh_visible_blockers, reserved,
                    )
                    expected_sequence = list(map(
                        str, shadow_canonical["canonical_walk_sequence"],
                    ))
                    if list(incoming_path["key_sequence"]) != expected_sequence \
                            or list(execution_port) != shadow_canonical[
                                "canonical_stance"
                            ] \
                            or execution_action != shadow_canonical[
                                "canonical_action"
                            ]:
                        _fail(f"non-product shadow canonical walk drift: {npc_id}")
                    walk_start = canonical_start
                    walk_sequence = expected_sequence
                    walk_basis = (
                        "CANONICAL_SHADOW_EXACT_STOCK_INCOMING_ARRIVAL_TO_STANCE"
                    )
                elif not walk_sequence and port is not None:
                    # Some perfectly reachable stances are endpoints of a
                    # one-wide component and therefore have no out-and-back
                    # cycle.  Use the exact stock incoming arrival and walk
                    # into this owner's stance instead of claiming that a
                    # different owner-level map probe covers it.
                    incoming_path = _shortest_safe_walk_path(
                        geometry, list(seeds), execution_port,
                        fresh_visible_blockers, reserved,
                    )
                    if int(incoming_path["step_count"]) > 0:
                        walk_start = tuple(map(int, incoming_path["start"]))
                        walk_sequence = list(map(
                            str, incoming_path["key_sequence"],
                        ))
                        walk_basis = (
                            "EXACT_STOCK_INCOMING_ARRIVAL_TO_OWNER_STANCE"
                        )
                row["interaction_execution"] = {
                    "trigger": (
                        "TELEPORT_TO_WALK_START_REAL_WALK_TO_STANCE_"
                        "FACE_AND_A"
                    ),
                    "start": list(walk_start),
                    "walk_sequence": walk_sequence,
                    "stance": list(execution_port),
                    "action": execution_action,
                    "interaction_distance": interaction_distance,
                    "counter_tile": (
                        list(counter_tile) if counter_tile is not None else None
                    ),
                    "actual_walk_required": bool(walk_sequence),
                    "actual_walk_exception": actual_walk_exception,
                    "walk_path_basis": walk_basis,
                    "direct_script_call_forbidden": True,
                }
                if require_runtime_execution_contracts and not walk_sequence \
                        and shadow_source is None:
                    _fail(
                        "runtime owner-specific real walk path不在: "
                        f"{npc['npc_id']} stance={execution_port}"
                    )
            elif require_runtime_execution_contracts:
                _fail(
                    f"runtime interaction execution port不在: {npc['npc_id']}"
                )
            if port is None:
                row["exception_evidence"] = [
                    _cell_evidence(
                        geometry, point, reserved, fresh_visible_blockers,
                    )
                    for point in neighbors
                ]
                if mode == "SCRIPT_ACTOR_ONLY_HIDDEN":
                    row["actor_contract_evidence"] = list(
                        contract.get("external_cfg_evidence", [])
                    )
            elif port in reserved or port in fresh_visible_blockers \
                    or not _collision_zero(geometry, port):
                port_conflicts.append(str(npc["npc_id"]))
            if (group, number, int(npc["local_id"])) in archive_ids:
                if port is None:
                    unclassified.append(str(npc["npc_id"]))
                else:
                    archive_port_count += 1
            rows.append(row)
    if len(rows) != int(npc_catalog["script_object_count"]):
        _fail(f"全NPC配置audit cardinality不一致: {len(rows)}")
    row_by_id = {str(row["npc_id"]): row for row in rows}
    for source_id, alias in shadow_by_source.items():
        source_row = row_by_id.get(source_id)
        canonical_row = row_by_id.get(str(alias["canonical_owner_id"]))
        if source_row is None or canonical_row is None \
                or source_row["interaction_execution"]["actual_walk_required"] is not False \
                or source_row["interaction_execution"]["actual_walk_exception"] is None \
                or canonical_row["interaction_execution"]["actual_walk_required"] is not True \
                or not canonical_row["interaction_execution"]["walk_sequence"]:
            _fail(f"non-product shadow alias physical pair不成立: {source_id}")
    classified_exceptions = [row for row in rows if row["port"] is None]
    if any(not row.get("exception_evidence") for row in classified_exceptions):
        _fail("全NPC配置audit exception evidence欠落")
    assertions = {
        "all_script_objects_classified": len(rows) == 3108,
        "all_archive_objects_have_legal_port": archive_port_count == 71,
        "all_selected_ports_are_collision_zero_and_conflict_free": not port_conflicts,
        "all_non_port_objects_have_exact_geometry_evidence": all(
            row.get("exception_evidence") for row in classified_exceptions
        ),
        "all_non_port_objects_are_exact_hidden_script_actors": all(
            row["mode"] == "SCRIPT_ACTOR_ONLY_HIDDEN"
            or row["mode"].startswith("DIAGNOSTIC_TELEPORT_REQUIRED_LOCAL_INCOMING_ABSENT_")
            for row in classified_exceptions
        ) if require_hidden_only_exceptions else True,
        "no_object_is_silently_skipped": not unclassified,
        "final_object_set_used_for_bfs": True,
        "all_fresh_visible_objects_block_bfs": True,
        "matrix_visibility_states_are_monotonic_blocker_subsets": True,
        "state_variant_layout_overrides_are_explicit": True,
        "all_interaction_ports_are_in_local_incoming_component": all(
            row["port"] is None
            or row["mode"].startswith("LOCAL_INCOMING_COMPONENT_")
            for row in rows
        ) if require_local_incoming_component_ports else True,
        "incoming_candidate_scope_is_explicitly_structural_not_global": all(
            row["entry"]["reachability_scope"]
                == "STRUCTURAL_EXACT_INCOMING_CANDIDATE_NOT_GLOBAL_ROOT"
            and row["entry"]["globally_reachable_from_new_game"] is None
            for row in map_rows
        ),
        "warp_coord_bg_tiles_reserved_for_ports": True,
        "connection_seeds_use_exact_offset_and_destination_dimensions": True,
        "all_local_incoming_absent_maps_are_manifest_pinned": all(
            row["local_static_incoming_available"]
            or row["mode"].startswith("DIAGNOSTIC_TELEPORT_REQUIRED_LOCAL_INCOMING_ABSENT_")
            for row in rows
        ),
        "all_diagnostic_maps_use_normal_overworld_input": all(
            not row["mode"].startswith("DIAGNOSTIC_TELEPORT_REQUIRED_LOCAL_INCOMING_ABSENT_")
            or (
                row["diagnostic_port"] is not None
                and row["diagnostic_action"] is not None
                and len(row["diagnostic_walk_cycle"] or []) in {0, 2}
                and (
                    row["diagnostic_requires_real_step"]
                    != row["diagnostic_isolated_port"]
                )
                and row["diagnostic_direct_script_call_forbidden"]
            )
            for row in rows
        ) if require_hidden_only_exceptions else True,
        "all_runtime_object_owners_have_input_execution_contract": all(
            row["interaction_execution"] is not None
            for row in rows
        ) if require_runtime_execution_contracts else True,
    }
    if not all(assertions.values()):
        _fail(
            "全NPC配置audit FAIL: "
            f"assertions={assertions} unclassified={unclassified[:8]} "
            f"conflicts={port_conflicts[:8]}"
        )
    return {
        "schema_version": 2, "task": TASK, "stage": STAGE, "status": "PASS",
        "rom_sha256": _sha(rom),
        "physical_map_count": len(coords),
        "maps_with_script_objects": len(map_rows),
        "script_object_count": len(rows),
        "legal_port_count": sum(row["port"] is not None for row in rows),
        "classified_geometry_exception_count": len(classified_exceptions),
        "hidden_script_actor_exception_count": sum(
            row["mode"] == "SCRIPT_ACTOR_ONLY_HIDDEN" for row in rows
        ),
        "diagnostic_teleport_required_local_incoming_absent_object_count": sum(
            row["mode"].startswith("DIAGNOSTIC_TELEPORT_REQUIRED_LOCAL_INCOMING_ABSENT_")
            for row in rows
        ),
        "non_product_shadow_source_count": len(shadow_by_source),
        "canonical_shadow_physical_owner_count": len(shadow_by_canonical),
        "failure_count": 0,
        "hidden_only_exception_gate_enabled": require_hidden_only_exceptions,
        "local_incoming_component_gate_enabled": require_local_incoming_component_ports,
        "mode_counts": dict(sorted(mode_counts.items())),
        "archive_object_count": archive_port_count,
        "layout_id_overrides": [
            {"map": list(key), "layout_id": active_layout_overrides[key]}
            for key in sorted(active_layout_overrides)
        ],
        "maps": map_rows,
        "objects": rows,
        "assertions": assertions,
    }


def _local_incoming_absent_diagnostic_fixtures(
    rom: bytes, npc_catalog: Mapping[str, Any],
    placement_audit: Mapping[str, Any],
    entry_exceptions: Mapping[tuple[int, int], Mapping[str, Any]],
) -> dict[str, Any]:
    """Materialize normal-input cases for every local-incoming-absent map.

    These cases remain inside the complete 5,412 runtime-owner denominator.
    The runner teleports the player to a concrete overworld tile, performs at
    least one real out/back walk cycle per map, then uses facing direction + A.
    Object visibility and non-script BG roles are separate negative contracts;
    no fixture may invoke an event script pointer directly.
    """

    npc_by_id = {
        str(row["npc_id"]): row for row in npc_catalog["npcs"]
    }
    npc_ids_by_map: dict[tuple[int, int], set[str]] = defaultdict(set)
    for npc_id, row in npc_by_id.items():
        npc_ids_by_map[(int(row["group"]), int(row["map"]))].add(npc_id)
    placement_by_map: dict[
        tuple[int, int], list[Mapping[str, Any]]
    ] = defaultdict(list)
    for row in placement_audit["objects"]:
        if str(row["mode"]).startswith("DIAGNOSTIC_TELEPORT_REQUIRED_LOCAL_INCOMING_ABSENT_"):
            placement_by_map[(int(row["group"]), int(row["map"]))].append(
                row
            )
    bg_abi_path = ROOT / (
        "vendor/upstream/pokefirered/include/constants/event_bg.h"
    )
    bg_consumer_path = ROOT / (
        "vendor/upstream/pokefirered/src/field_control_avatar.c"
    )
    bg_abi_raw = bg_abi_path.read_bytes()
    if b"#define BG_EVENT_HIDDEN_ITEM         7" not in bg_abi_raw \
            or b"#define BG_EVENT_SECRET_BASE         8" not in bg_abi_raw:
        _fail("BG event ABI constants drift")

    maps: list[dict[str, Any]] = []
    object_probe_count = 0
    bg_script_probe_count = 0
    bg_non_script_count = 0
    visibility_negative_count = 0
    for group, number in sorted(entry_exceptions):
        state = _stage_map_state(rom, group, number)
        geometry = _map_geometry(rom, group, number)
        _warps, reserved = _decode_event_tiles(state)
        object_rows = sorted(
            placement_by_map.get((group, number), []),
            key=lambda row: int(row["object_index"]),
        )
        if {str(row["npc_id"]) for row in object_rows} != npc_ids_by_map[
            (group, number)
        ]:
            _fail(
                f"diagnostic object fixture coverage drift: {group}/{number}"
            )
        blocker_tiles = {
            tuple(map(int, row["object"])) for row in object_rows
        }
        object_probes: list[dict[str, Any]] = []
        for placement in object_rows:
            npc_id = str(placement["npc_id"])
            npc = npc_by_id[npc_id]
            port = placement.get("diagnostic_port")
            action = placement.get("diagnostic_action")
            cycle = list(placement.get("diagnostic_walk_cycle") or [])
            if not isinstance(port, list) or len(port) != 2 or not action:
                _fail(f"diagnostic object port/input欠落: {npc_id}")
            visibility_flag = int(npc["flag"])
            visibility = {
                "flag": visibility_flag,
                "positive_setup": (
                    "CLEAR" if visibility_flag else "ALWAYS_VISIBLE_TEMPLATE"
                ),
                "positive_expected_template_visible": True,
                "negative_setup": (
                    "SET" if visibility_flag else None
                ),
                "negative_expected_template_visible": (
                    False if visibility_flag else None
                ),
                "basis": (
                    "OBJECT_EVENT_TEMPLATE_FLAG_CLEAR_SHOWS_SET_HIDES"
                    if visibility_flag else
                    "ZERO_VISIBILITY_FLAG_HAS_NO_FLAG_HIDE_STATE"
                ),
            }
            visibility_negative_count += int(visibility_flag != 0)
            input_sequence = [
                {"key": key, "pressed": 2, "released": 12,
                 "purpose": "REAL_OVERWORLD_WALK_CYCLE"}
                for key in cycle
            ] + [
                {"key": str(action), "pressed": 2, "released": 12,
                 "purpose": "FACE_EVENT"},
                {"key": "A", "pressed": 2, "released": 300,
                 "purpose": "NORMAL_DIRECTION_A_INTERACTION"},
            ]
            object_probes.append({
                "probe_id": f"DIAG::{npc_id}",
                "owner_id": npc_id,
                "object_index": int(npc["object_index"]),
                "local_id": int(npc["local_id"]),
                "script_pointer": f"0x{int(npc['script_pointer']):08X}",
                "script_prefix_sha256": _sha(rom[
                    _rom_offset(
                        int(npc["script_pointer"]), 1,
                        f"diagnostic object script {npc_id}",
                    ):
                    _rom_offset(
                        int(npc["script_pointer"]), 1,
                        f"diagnostic object script {npc_id}",
                    ) + 32
                ]),
                "teleport": {
                    "group": group, "map": number,
                    "x": int(port[0]), "y": int(port[1]),
                    "kind": "OVERWORLD_PLAYER_POSITION_ONLY",
                },
                "target_object": list(map(int, placement["object"])),
                "input_sequence": input_sequence,
                "real_walk_cycle": cycle,
                "direction_a_required": True,
                "direct_script_call_forbidden": True,
                "visibility": visibility,
                "local_static_incoming_available": False,
                "diagnostic_interaction_expected": True,
            })
        object_probe_count += len(object_probes)

        backgrounds = bytes.fromhex(str(state["bg_hex"]))
        bg_base = (
            _rom_offset(
                int(state["pointers"]["bg"]),
                int(state["counts"]["bg"]) * 12,
                f"diagnostic BG array {group}/{number}",
            ) if int(state["counts"]["bg"]) else None
        )
        bg_scripts: list[dict[str, Any]] = []
        bg_non_scripts: list[dict[str, Any]] = []
        for index in range(int(state["counts"]["bg"])):
            at = index * 12
            raw = backgrounds[at:at + 12]
            x, y = struct.unpack_from("<HH", raw)
            kind = raw[5]
            operand = struct.unpack_from("<I", raw, 8)[0]
            common = {
                "bg_index": index, "position": [x, y], "kind": kind,
                "record_address": f"0x{GBA_BASE + int(bg_base) + at:08X}",
                "record_raw_hex": raw.hex(),
                "record_sha256": _sha(raw),
            }
            if kind in {7, 8}:
                bg_non_scripts.append({
                    **common,
                    "role": (
                        "ENGINE_HIDDEN_ITEM" if kind == 7 else
                        "ENGINE_SECRET_BASE"
                    ),
                    "script_pointer_interpretation_forbidden": True,
                    "visible_template_expected": False,
                    "normal_visibility_assertion": (
                        "NO_OBJECT_EVENT_TEMPLATE_IS_MATERIALIZED"
                    ),
                    "operand": operand,
                    "meaning_source": {
                        "constants_path": str(bg_abi_path.relative_to(ROOT)),
                        "constants_sha256": _sha(bg_abi_raw),
                        "consumer_path": str(
                            bg_consumer_path.relative_to(ROOT)
                        ),
                        "consumer_sha256": _sha(
                            bg_consumer_path.read_bytes()
                        ),
                    },
                })
                continue
            if operand in {0, 0xFFFFFFFF}:
                bg_non_scripts.append({
                    **common, "role": "NULL_BG_SCRIPT",
                    "script_pointer_interpretation_forbidden": True,
                    "visible_template_expected": False,
                    "normal_visibility_assertion": "NO_SCRIPT_CONSUMER",
                    "operand": operand,
                })
                continue
            diagnostic = _diagnostic_interaction_port(
                geometry, (x, y), reserved, blocker_tiles,
            )
            if diagnostic is None:
                _fail(
                    f"diagnostic BG script port欠落: {group}/{number}/{index}"
                )
            cycle = _diagnostic_walk_cycle(
                geometry, diagnostic[0], reserved, blocker_tiles,
            ) or []
            bg_scripts.append({
                **common,
                "probe_id": f"DIAG::BG:{group:03d}/{number:03d}:{index:03d}",
                "script_pointer": f"0x{operand:08X}",
                "script_prefix_sha256": _sha(rom[
                    _rom_offset(
                        operand, 1,
                        f"diagnostic BG script {group}/{number}/{index}",
                    ):
                    _rom_offset(
                        operand, 1,
                        f"diagnostic BG script {group}/{number}/{index}",
                    ) + 32
                ]),
                "teleport": {
                    "group": group, "map": number,
                    "x": int(diagnostic[0][0]),
                    "y": int(diagnostic[0][1]),
                    "kind": "OVERWORLD_PLAYER_POSITION_ONLY",
                },
                "target_bg_position": [x, y],
                "input_sequence": [
                    {"key": key, "pressed": 2, "released": 12,
                     "purpose": "REAL_OVERWORLD_WALK_CYCLE"}
                    for key in cycle
                ] + [
                    {"key": diagnostic[1], "pressed": 2, "released": 12,
                     "purpose": "FACE_EVENT"},
                    {"key": "A", "pressed": 2, "released": 300,
                     "purpose": "NORMAL_DIRECTION_A_INTERACTION"},
                ],
                "real_walk_cycle": list(cycle),
                "direction_a_required": True,
                "direct_script_call_forbidden": True,
            })
        bg_script_probe_count += len(bg_scripts)
        bg_non_script_count += len(bg_non_scripts)
        real_walk_probe_ids = [
            row["probe_id"] for row in (*object_probes, *bg_scripts)
            if row["real_walk_cycle"]
        ]
        if not real_walk_probe_ids:
            _fail(f"diagnostic mapにreal walk cycleがありません: {group}/{number}")
        maps.append({
            "group": group, "map": number,
            "classification": entry_exceptions[(group, number)][
                "classification"
            ],
            "local_static_incoming_available": False,
            "diagnostic_teleport_required": True,
            "direct_script_call_forbidden": True,
            "minimum_real_walk_cycle_probe_id": real_walk_probe_ids[0],
            "object_probes": object_probes,
            "bg_script_probes": bg_scripts,
            "bg_non_script_visibility_proofs": bg_non_scripts,
        })
    assertions = {
        "all_exception_maps_have_diagnostic_cases": (
            len(maps) == len(entry_exceptions) == 40
        ),
        "all_exception_script_objects_covered": (
            object_probe_count
            == placement_audit["diagnostic_teleport_required_local_incoming_absent_object_count"]
            == 99
        ),
        "all_exception_bg_records_classified": all(
            len(row["bg_script_probes"])
            + len(row["bg_non_script_visibility_proofs"])
            == int(_stage_map_state(
                rom, int(row["group"]), int(row["map"]),
            )["counts"]["bg"])
            for row in maps
        ),
        "every_map_has_real_walk_cycle": all(
            bool(row["minimum_real_walk_cycle_probe_id"])
            for row in maps
        ),
        "all_positive_interactions_use_direction_plus_a": all(
            probe["direction_a_required"]
            for row in maps
            for probe in (*row["object_probes"], *row["bg_script_probes"])
        ),
        "all_direct_script_calls_forbidden": all(
            row["direct_script_call_forbidden"]
            and all(
                probe["direct_script_call_forbidden"]
                for probe in (
                    *row["object_probes"], *row["bg_script_probes"]
                )
            ) for row in maps
        ),
        "all_hidden_non_script_bg_roles_have_visibility_proof": all(
            not proof["visible_template_expected"]
            and bool(proof["normal_visibility_assertion"])
            for row in maps
            for proof in row["bg_non_script_visibility_proofs"]
        ),
    }
    if not all(assertions.values()):
        _fail(
            f"entry exception diagnostic fixture FAIL: {assertions} "
            f"maps={len(maps)}/{len(entry_exceptions)} "
            f"objects={object_probe_count}/"
            f"{placement_audit['diagnostic_teleport_required_local_incoming_absent_object_count']}"
        )
    return {
        "schema_version": 1, "status": "PASS",
        "map_count": len(maps),
        "object_probe_count": object_probe_count,
        "bg_script_probe_count": bg_script_probe_count,
        "bg_non_script_visibility_proof_count": bg_non_script_count,
        "object_visibility_negative_probe_count": visibility_negative_count,
        "maps": maps, "assertions": assertions,
    }


def _local_incoming_fixture_seed(entry_report: Mapping[str, Any]) -> str:
    incoming = entry_report.get("incoming_warps")
    if isinstance(incoming, list) and incoming:
        row = incoming[0]
        source = row.get("source")
        arrival = row.get("arrival_tile")
        destination = row.get("destination_warp_id")
        if isinstance(source, list) and len(source) == 3 \
                and isinstance(arrival, list) and len(arrival) == 2 \
                and isinstance(destination, int):
            return (
                "EXACT_INCOMING_WARP_DESTINATION_ROW:"
                f"{int(source[0]):03d}/{int(source[1]):03d}/"
                f"{int(source[2]):03d}->WARP{destination:03d}"
                f"@{int(arrival[0])},{int(arrival[1])}"
            )
    for key, family in (
        ("connections", "EXACT_REVERSE_INCOMING_CONNECTION_ROW"),
        ("scripted_entries", "EXACT_SCRIPT_WARP_PRODUCER"),
        ("engine_entries", "EXACT_NATIVE_TABLE_LOCAL_ENTRY_PRODUCER"),
    ):
        rows = entry_report.get(key)
        if isinstance(rows, list) and rows:
            return f"{family}:{_sha(_stable(rows[0]))}"
    _fail("local-incoming fixtureにexact seed provenanceがありません")


def _verify_local_incoming_fixture_entry(
    rom: bytes,
    coords: Sequence[tuple[int, int, str]],
    scripted_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    connection_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    engine_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    *,
    group: int,
    number: int,
    start: tuple[int, int],
    target: tuple[int, int],
    action: str,
    walk_cycle: Sequence[str],
) -> str:
    state = _stage_map_state(rom, group, number)
    geometry = _map_geometry(rom, group, number)
    seeds, report, reserved = _map_entry_seeds(
        rom, group, number, state, geometry, coords,
        scripted_entries, connection_entries, engine_entries,
    )
    if not seeds:
        _fail(f"local-incoming fixture exact入口なし: {group}/{number}")
    object_tiles = {
        (row["x"], row["y"])
        for row in (_object_fields(raw) for raw in state["objects"])
    }
    reached = _reachable_distances(geometry, seeds, object_tiles)
    if start not in reached or start in reserved or start in object_tiles \
            or not _collision_zero(geometry, start):
        _fail(
            f"local-incoming fixture startがexact入口component外: "
            f"{group}/{number} {start}"
        )
    if _port_action(target, start) != action:
        _fail(
            f"local-incoming fixture action/target不一致: "
            f"{group}/{number} {start}->{target} {action}"
        )
    deltas = {
        "UP": (0, -1), "DOWN": (0, 1),
        "LEFT": (-1, 0), "RIGHT": (1, 0),
    }
    cursor = start
    for key in walk_cycle:
        if key not in deltas:
            _fail(f"local-incoming fixture walk key不正: {key}")
        delta = deltas[key]
        cursor = (cursor[0] + delta[0], cursor[1] + delta[1])
        if cursor not in reached or cursor in reserved or cursor in object_tiles \
                or not _collision_zero(geometry, cursor):
            _fail(
                f"local-incoming fixture real walkが不正: "
                f"{group}/{number} {cursor}"
            )
    if cursor != start or not walk_cycle:
        _fail(
            f"local-incoming fixture walk cycleが閉じていません: "
            f"{group}/{number}"
        )
    return _local_incoming_fixture_seed(report)


def _select_local_incoming_bg_entry(
    rom: bytes,
    coords: Sequence[tuple[int, int, str]],
    scripted_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    connection_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    engine_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    *,
    group: int,
    number: int,
    target: tuple[int, int],
) -> dict[str, Any]:
    state = _stage_map_state(rom, group, number)
    geometry = _map_geometry(rom, group, number)
    seeds, report, reserved = _map_entry_seeds(
        rom, group, number, state, geometry, coords,
        scripted_entries, connection_entries, engine_entries,
    )
    object_tiles = {
        (row["x"], row["y"])
        for row in (_object_fields(raw) for raw in state["objects"])
    }
    reached = _reachable_distances(geometry, seeds, object_tiles)
    deltas = (
        ("UP", (0, -1), "DOWN"),
        ("LEFT", (-1, 0), "RIGHT"),
        ("RIGHT", (1, 0), "LEFT"),
        ("DOWN", (0, 1), "UP"),
    )
    candidates: list[tuple[int, int, int, str, str, str]] = []
    for _port_direction, (dx, dy), action in deltas:
        start = (target[0] + dx, target[1] + dy)
        if start not in reached or start in reserved or start in object_tiles:
            continue
        for walk_key, (walk_dx, walk_dy), back_key in deltas:
            stepped = (start[0] + walk_dx, start[1] + walk_dy)
            if stepped == target or stepped not in reached \
                    or stepped in reserved or stepped in object_tiles:
                continue
            candidates.append((
                reached[start], start[1], start[0], action,
                walk_key, back_key,
            ))
    if not candidates:
        _fail(f"gym BG local-incoming interaction portなし: {group}/{number}")
    _distance, y, x, action, walk_key, back_key = min(candidates)
    start = (x, y)
    walk_cycle = [walk_key, back_key]
    entry_seed = _verify_local_incoming_fixture_entry(
        rom, coords, scripted_entries, connection_entries, engine_entries,
        group=group, number=number, start=start, target=target,
        action=action, walk_cycle=walk_cycle,
    )
    return {
        "start": list(start), "walk_cycle": walk_cycle,
        "action": action, "entry_seed": entry_seed,
    }


def _single_text_oracle(
    rom: bytes, *, pointer: int, source_root: str,
    provenance_kind: str, meaning_source: str,
) -> dict[str, Any]:
    raw = _read_text(rom, pointer, meaning_source, limit=512)
    if raw == b"\xFF":
        _fail(f"visible text oracleがEOS-onlyです: {pointer:#010x}")
    digest = _sha(raw)
    return {
        "meaning_source": meaning_source,
        "provenance": {
            "kind": provenance_kind,
            "source_root": source_root,
            "source_text_addresses": [f"0x{pointer:08X}"],
            "raw_sha256s": [digest],
        },
        "ordered_raw_sha256s": [digest],
        "allowed_ordered_raw_sha256_sequences": [[digest]],
        "visible_text_count": 1,
    }


def _map_popup_and_diglett_local_incoming_fixtures(
    stage60: bytes,
    stage61: bytes,
    coords: Sequence[tuple[int, int, str]],
    scripted_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    connection_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    engine_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    name_rows: Sequence[Mapping[str, Any]],
    npc_catalog: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind the map-section collision and one exact-incoming Archive walk."""

    charmap = load_charmap(ROOT / "vendor/upstream/CFRU-JP/charmap.tbl")
    custom_names = {
        int(row["runtime_map_section_id"]): row for row in name_rows
    }
    popup_rows: list[dict[str, Any]] = []
    entry_reports: dict[tuple[int, int], dict[str, Any]] = {}

    def usable_incoming(
        seeds: set[tuple[int, int]], report: Mapping[str, Any],
    ) -> list[dict[str, Any]]:
        rows = [
            dict(row) for row in report.get("incoming_warps", [])
            if row.get("source_trigger_usable") is True
            and tuple(map(int, row.get("arrival_tile", []))) in seeds
            and row.get("seed_basis")
                == "EXACT_INCOMING_WARP_DESTINATION_ROW"
        ]
        rows.sort(key=lambda row: tuple(map(int, row["source"])))
        if not rows:
            _fail("map popup fixtureにusable exact incoming warpなし")
        return rows

    def stock_warp_contract(row: Mapping[str, Any]) -> dict[str, Any]:
        source = tuple(map(int, row["source"]))
        source_state = _stage_map_state(stage61, source[0], source[1])
        warp_base = int(source_state["pointers"]["warps"])
        record_address = warp_base + source[2] * 8
        record_offset = _rom_offset(
            record_address, 8, "map popup incoming warp record",
        )
        record = stage61[record_offset:record_offset + 8]
        predecessors = [
            tuple(map(int, point)) for point in row["source_predecessor_tiles"]
        ]
        if not predecessors:
            _fail("map popup source warp predecessor不足")
        predecessor = min(predecessors, key=lambda point: (point[1], point[0]))
        trigger = tuple(map(int, row["source_trigger_tile"]))
        dx, dy = trigger[0] - predecessor[0], trigger[1] - predecessor[1]
        key = {
            (0, -1): "UP", (0, 1): "DOWN",
            (-1, 0): "LEFT", (1, 0): "RIGHT",
        }.get((dx, dy))
        if key is None:
            _fail("map popup source predecessor/triggerが非隣接")
        return {
            "source": list(source),
            "source_map_key": row["source_map_key"],
            "source_warp_record_address": f"0x{record_address:08X}",
            "source_warp_record_hex": record.hex(),
            "predecessor_tile": list(predecessor),
            "trigger_tile": list(trigger),
            "trigger_key": key,
            "destination_warp_id": int(row["destination_warp_id"]),
            "arrival_tile": list(map(int, row["arrival_tile"])),
            "seed_basis": row["seed_basis"],
        }

    for group, number, physical_provenance, expected_name in (
        MAP_POPUP_REGRESSION_MAPS
    ):
        state = _stage_map_state(stage61, group, number)
        geometry = _map_geometry(stage61, group, number)
        seeds, entry_report, _reserved = _map_entry_seeds(
            stage61, group, number, state, geometry, coords,
            scripted_entries, connection_entries, engine_entries,
        )
        incoming = usable_incoming(seeds, entry_report)
        entry_reports[(group, number)] = {
            "seeds": sorted(seeds), "report": entry_report,
            "incoming": incoming,
        }
        header = _map_header_offset(stage61, group, number)
        runtime_section = stage61[header + 0x14]
        show_name = bool(stage61[header + 0x19] & 0x04)
        if physical_provenance == "IMPORTED_KANTO_CANONICAL":
            name = custom_names.get(runtime_section)
            if name is None or int(name["source_map_section_id"]) != 131:
                _fail(f"Kanto Diglett custom name contract drift: {group}/{number}")
            pointer = int(name["materialized_pointer"])
            source_pointer = int(name["source_pointer"])
            source_section = int(name["source_map_section_id"])
            namespace = "PROJECT_KANTO_NAMESPACE"
            provenance = {
                "kind": "CLEAN_FIRERED_NAME_RELOCATED_TO_PROJECT_TABLE",
                "source_pointer": f"0x{source_pointer:08X}",
                "source_raw_sha256": name["raw_sha256"],
            }
        else:
            source_section = runtime_section
            pointer_site = (
                STOCK_MAP_NAMES - GBA_BASE + (source_section - 88) * 4
            )
            pointer = _u32(
                stage61, pointer_site,
                f"Tohoku wisdom-cave stock map name {group}/{number}",
            )
            baseline_pointer = _u32(
                stage60, pointer_site,
                f"Stage60 wisdom-cave stock map name {group}/{number}",
            )
            if baseline_pointer != pointer:
                _fail("Tohoku stock map name pointerがStage60からdrift")
            namespace = "VEGA_STOCK_NAMESPACE"
            provenance = {
                "kind": "PINNED_STAGE60_VEGA_STOCK_MAP_NAME",
                "source_pointer": f"0x{pointer:08X}",
                "stage60_pointer_equal": True,
            }
        raw = _read_text(
            stage61, pointer, f"map popup name {group}/{number}", limit=128,
        )
        decoded = decode_text(raw, charmap)
        if not show_name or decoded.decoded_utf8 != expected_name:
            _fail(
                f"map popup expected name/show drift: {group}/{number}: "
                f"{decoded.decoded_utf8!r}/{show_name}"
            )
        header_raw = stage61[header:header + 0x1C]
        popup_rows.append({
            "case_id": f"MAP_POPUP_{group:03d}_{number:03d}",
            "group": group, "map": number,
            "physical_provenance": physical_provenance,
            "header_address": f"0x{GBA_BASE + header:08X}",
            "header_sha256": _sha(header_raw),
            "runtime_map_section": runtime_section,
            "resolver_source_map_section": source_section,
            "namespace": namespace,
            "show_map_name": show_name,
            "expected_name_utf8": decoded.decoded_utf8,
            "expected_name_pointer": f"0x{pointer:08X}",
            "expected_name_raw_size": len(raw),
            "expected_name_raw_sha256": _sha(raw),
            "name_provenance": provenance,
            "stock_warp": stock_warp_contract(incoming[0]),
            "entry_report_sha256": _sha(_stable(entry_report)),
            "expected_terminal": "MAP_POPUP_RENDERED_THEN_FIELD_INPUT",
        })

    owners = [
        row for row in npc_catalog.get("npcs", [])
        if int(row.get("group", -1)) == 97
        and int(row.get("map", -1)) == 37
        and int(row.get("local_id", -1)) == 1
    ]
    if len(owners) != 1:
        _fail("Diglett B1F中央Archive local1 owner一意性不一致")
    owner = owners[0]
    state = _stage_map_state(stage61, 97, 37)
    geometry = _map_geometry(stage61, 97, 37)
    _warps, reserved = _decode_event_tiles(state)
    objects = [_object_fields(raw) for raw in state["objects"]]
    object_tiles = {(row["x"], row["y"]) for row in objects}
    target = tuple(map(int, owner["interaction_object"]))
    stance = tuple(map(int, owner["interaction_port"]))
    if target not in object_tiles or stance in object_tiles \
            or stance in reserved or not _collision_zero(geometry, stance):
        _fail("Diglett B1F中央Archive final target/stance不正")
    entry = entry_reports[(97, 37)]
    starts = [
        tuple(map(int, row["arrival_tile"])) for row in entry["incoming"]
    ]
    path = _shortest_safe_walk_path(
        geometry, starts, stance, object_tiles, reserved,
    )
    selected_incoming = [
        row for row in entry["incoming"]
        if list(map(int, row["arrival_tile"])) == path["start"]
    ]
    if not selected_incoming:
        _fail("Diglett B1F path start/incoming warp対応なし")
    selected_warp = stock_warp_contract(selected_incoming[0])
    path_basis = {
        "algorithm": (
            "DETERMINISTIC_BFS_EXACT_INCOMING_WARP_FINAL_COLLISION_"
            "ALL_OBJECTS_AND_EVENT_TILES_BLOCKED"
        ),
        "geometry": {
            "width": int(geometry["width"]),
            "height": int(geometry["height"]),
            "blocks_sha256": _sha(struct.pack(
                f"<{len(geometry['blocks'])}H", *geometry["blocks"],
            )),
        },
        "object_array_sha256": _sha(b"".join(state["objects"])),
        "reserved_tiles": [
            list(point) for point in sorted(
                reserved, key=lambda point: (point[1], point[0]),
            )
        ],
        "selected_stock_warp": selected_warp,
        "path": path,
        "stance": list(stance),
        "target": list(target),
        "action": str(owner["interaction_action"]),
    }
    diglett = {
        "case_id": "DIGLETT_B1F_ARCHIVE_CENTRAL_LOCAL1_INCOMING_WALK",
        "owner_id": str(owner["npc_id"]),
        "group": 97, "map": 37, "local_id": 1,
        "object_index": int(owner["object_index"]),
        "object": list(target), "stance": list(stance),
        "stock_warp": selected_warp,
        "walk_key_sequence": path["key_sequence"],
        "walk_tiles": path["tiles"],
        "walk_step_count": path["step_count"],
        "action": str(owner["interaction_action"]),
        "press_a": True,
        "path_provenance": {
            **path_basis,
            "sha256": _sha(_stable(path_basis)),
        },
        "interaction_oracle_binding": {
            "catalog": "reports/generated/stage61_interaction_oracles.json",
            "owner_key": str(owner["npc_id"]),
            "calibration_derived_oracle_forbidden": True,
        },
        "required_prepost": ["PRE", "POST"],
        "expected_terminal": "VISIBLE_INTERACTION_NO_SOFTLOCK",
    }
    assertions = {
        "exact_seven_section_collision_popup_maps": len(popup_rows) == 7,
        "kanto_three_use_project_section_41": all(
            row["runtime_map_section"] == 41
            and row["namespace"] == "PROJECT_KANTO_NAMESPACE"
            for row in popup_rows if row["group"] == 97
        ),
        "tohoku_four_preserve_stock_section_131": all(
            row["runtime_map_section"] == 131
            and row["namespace"] == "VEGA_STOCK_NAMESPACE"
            for row in popup_rows if row["group"] == 1
        ),
        "all_popup_names_have_independent_raw_hash": all(
            len(row["expected_name_raw_sha256"]) == 64 for row in popup_rows
        ),
        "all_popups_use_exact_usable_incoming_warp": all(
            row["stock_warp"]["seed_basis"]
                == "EXACT_INCOMING_WARP_DESTINATION_ROW"
            for row in popup_rows
        ),
        "diglett_b1f_path_nonempty_and_local_incoming": (
            diglett["walk_step_count"] > 0
            and diglett["walk_tiles"][-1] == diglett["stance"]
            and diglett["press_a"] is True
        ),
    }
    if not all(assertions.values()):
        _fail(f"map popup/Diglett local-incoming fixture FAIL: {assertions}")
    return {
        "schema_version": 1, "status": "PASS",
        "popup_cases": popup_rows,
        "diglett_b1f_archive_central": diglett,
        "assertions": assertions,
    }


def _focused_interaction_from_final_placement(
    rom: bytes, npc_catalog: Mapping[str, Any],
    *, group: int, map_number: int, local_id: int,
) -> dict[str, Any]:
    """Bind a focused mGBA fixture to the final placement, not stale coords.

    The runner deliberately performs at least one real overworld step before
    facing the object.  Its compact interaction ABI walks repeatedly in the
    same direction used for A, so the start tile is the collision-free tile
    immediately behind the final audited stance.  Fail closed if a later
    relocation makes that exact audited local-incoming path unavailable.
    """

    matches = [
        row for row in npc_catalog.get("npcs", [])
        if int(row.get("group", -1)) == group
        and int(row.get("map", -1)) == map_number
        and int(row.get("local_id", -1)) == local_id
    ]
    if len(matches) != 1:
        _fail(
            "focused interaction owner一意性不一致: "
            f"{group}/{map_number} local {local_id}: {len(matches)}"
        )
    owner = matches[0]
    raw_port = owner.get("interaction_port")
    action = owner.get("interaction_action")
    if not isinstance(raw_port, list) or len(raw_port) != 2 \
            or action not in {"UP", "DOWN", "LEFT", "RIGHT"}:
        _fail(f"focused interaction final port不在: {owner['npc_id']}")
    audited_port = (int(raw_port[0]), int(raw_port[1]))
    raw_object = owner.get("interaction_object", [owner["x"], owner["y"]])
    object_point = (int(raw_object[0]), int(raw_object[1]))
    deltas = {
        "UP": (0, -1), "DOWN": (0, 1),
        "LEFT": (-1, 0), "RIGHT": (1, 0),
    }
    delta = deltas[str(action)]
    if (audited_port[0] + delta[0], audited_port[1] + delta[1]) \
            != object_point:
        _fail(f"focused interaction stance/action不一致: {owner['npc_id']}")
    state = _stage_map_state(rom, group, map_number)
    geometry = _map_geometry(rom, group, map_number)
    _warps, reserved = _decode_event_tiles(state)
    object_tiles = {
        (int(row["x"]), int(row["y"]))
        for row in (_object_fields(raw) for raw in state["objects"])
    }
    def safe(point: tuple[int, int]) -> bool:
        return _collision_zero(geometry, point) \
            and point not in reserved and point not in object_tiles

    # The focused runner has a compact one-direction approach ABI.  Prefer the
    # audited port, but when its immediately preceding tile is blocked, promote
    # another side only after proving both that side and its approach tile are
    # in the *same* final-ROM local-incoming component as the audited port.
    # This preserves the placement audit's entry provenance without inventing
    # a globally clear or host-only stance.
    if not safe(audited_port):
        _fail(f"focused interaction audited port final geometry不正: {owner['npc_id']}")
    blocked = set(object_tiles) | set(reserved)
    same_component = _reachable_distances(
        geometry, [audited_port], blocked,
    )
    candidates = []
    for candidate_action in (
        str(action), "UP", "LEFT", "RIGHT", "DOWN",
    ):
        candidate_delta = deltas[candidate_action]
        candidate_port = (
            object_point[0] - candidate_delta[0],
            object_point[1] - candidate_delta[1],
        )
        candidate_start = (
            candidate_port[0] - candidate_delta[0],
            candidate_port[1] - candidate_delta[1],
        )
        if candidate_action in {row[0] for row in candidates} \
                or not safe(candidate_port) or not safe(candidate_start) \
                or candidate_port not in same_component \
                or candidate_start not in same_component:
            continue
        candidates.append((
            candidate_action, candidate_port, candidate_start,
            int(same_component[candidate_port]),
            int(same_component[candidate_start]),
        ))
    if not candidates:
        _fail(
            "focused interactionのaudited port直線実歩行が不在: "
            f"{owner['npc_id']} audited={audited_port} object={object_point}"
        )
    selected_action, port, start, port_distance, start_distance = candidates[0]
    return {
        "group": group, "map": map_number, "local_id": local_id,
        "object": list(object_point), "start": list(start),
        "approach_steps": 1, "action": selected_action,
        "owner_id": str(owner["npc_id"]),
        "placement_basis": {
            "port": list(port),
            "audited_port": list(audited_port),
            "port_basis": (
                "FINAL_ROM_AUDITED_LOCAL_INCOMING_COMPONENT_PROMOTED_"
                "COLLISION_EVENT_OBJECT_FREE_STRAIGHT_APPROACH"
            ),
            "selected_is_audited_port": port == audited_port,
            "selected_port_component_distance": port_distance,
            "selected_start_component_distance": start_distance,
            "mode": owner.get("interaction_mode"),
            "actual_walk_steps": 1,
        },
    }


def _final_map_script_regression_fixtures(
    stage60: bytes,
    stage61: bytes,
    coords: Sequence[tuple[int, int, str]],
    scripted_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    connection_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    engine_entries: Mapping[
        tuple[int, int], Sequence[Mapping[str, Any]]
    ],
    null_event_repairs: Sequence[Mapping[str, Any]],
    gym_bg_repair_rows: Sequence[dict[str, Any]],
) -> dict[str, Any]:
    map_rows: list[dict[str, Any]] = []
    empty_pointers: set[int] = set()
    for contract in PRODUCT_EMPTY_MAP_SCRIPT_CONTRACTS:
        group, number = int(contract["group"]), int(contract["map"])
        stage60_header = _map_header_offset(stage60, group, number)
        stage61_header = _map_header_offset(stage61, group, number)
        before_pointer = _u32(
            stage60, stage60_header + 8,
            f"product map-script baseline {group}/{number}",
        )
        after_pointer = _u32(
            stage61, stage61_header + 8,
            f"product map-script final {group}/{number}",
        )
        if before_pointer != int(contract["stage60_pointer"]):
            _fail(f"product map-script baseline pointer drift: {group}/{number}")
        before_offset = _rom_offset(
            before_pointer, 16, f"product baseline table {group}/{number}",
        )
        after_offset = _rom_offset(
            after_pointer, 16, f"product final table {group}/{number}",
        )
        before = stage60[before_offset:before_offset + 16]
        after = stage61[after_offset:after_offset + 16]
        if before[0] not in {0xF6, 0x6A} or after[0] != 0:
            _fail(f"product map-script independent preimage drift: {group}/{number}")
        empty_pointers.add(after_pointer)
        state = _stage_map_state(stage61, group, number)
        local_id = int(contract["trainer_local_id"])
        matches = [
            _object_fields(raw) for raw in state["objects"]
            if _object_fields(raw)["local_id"] == local_id
        ]
        if len(matches) != 1:
            _fail(f"product map trainer owner不一致: {group}/{number}")
        trainer = matches[0]
        expected_position = tuple(map(int, contract["trainer_position"]))
        if (trainer["x"], trainer["y"]) != expected_position \
                or trainer["script_pointer"] != int(contract["trainer_script"]):
            _fail(f"product map trainer binding drift: {group}/{number}")
        start = tuple(map(int, contract["start"]))
        walk_cycle = list(map(str, contract["walk_cycle"]))
        action = str(contract["action"])
        _verify_local_incoming_fixture_entry(
            stage61, coords, scripted_entries, connection_entries,
            engine_entries, group=group, number=number, start=start,
            target=expected_position, action=action,
            walk_cycle=walk_cycle,
        )
        map_rows.append({
            "case_id": f"PRODUCT_MAP_SCRIPT_{group:03d}_{number:03d}",
            "group": group, "map": number, "start": list(start),
            "walk_cycle": walk_cycle, "action": action,
            "expected_map_scripts_contract": "EMPTY_PROJECT_TABLE",
            "map_scripts_pointer": f"0x{after_pointer:08X}",
            "stage60_map_scripts_pointer": f"0x{before_pointer:08X}",
            "stage60_preimage_hex": before.hex(),
            "stage61_preimage_hex": after.hex(),
            "trainer": {
                "local_id": local_id, "object": list(expected_position),
                "trainer_id": int(contract["trainer_id"]),
                "script_pointer": f"0x{trainer['script_pointer']:08X}",
                "prepost": ["PRE", "POST"],
            },
        })
    if len(empty_pointers) != 1:
        _fail("1/85・1/86 empty project table pointerが共通ではありません")

    repair_by_owner = {
        str(row["owner_id"]): row for row in null_event_repairs
    }
    null_rows: list[dict[str, Any]] = []
    for contract in NULL_EVENT_PRODUCT_FIXTURE_CONTRACTS:
        owner_id = str(contract["owner_id"])
        repair = repair_by_owner.get(owner_id)
        if repair is None:
            _fail(f"product NULL owner repair欠落: {owner_id}")
        group, number = int(repair["group"]), int(repair["map"])
        owner_kind = str(repair["owner_kind"])
        size = int(repair["record_size"])
        address = int(repair["record_address"])
        offset = _rom_offset(address, size, f"product NULL {owner_id}")
        before, after = (
            stage60[offset:offset + size], stage61[offset:offset + size]
        )
        pointer_offset = 12 if owner_kind == "COORD" else 8
        if struct.unpack_from("<I", before, pointer_offset)[0] != GBA_BASE \
                or struct.unpack_from("<I", after, pointer_offset)[0] != 0:
            _fail(f"product NULL pointer normalization drift: {owner_id}")
        read_pc = int(contract["consumer_pointer_read_pc"])
        read_offset = _rom_offset(read_pc, 16, f"NULL consumer {owner_id}")
        read_preimage = str(contract["consumer_pointer_read_preimage_hex"])
        read_postimage = str(
            contract["consumer_pointer_read_postimage_hex"]
        )
        if stage60[read_offset:read_offset + 16].hex() != read_preimage \
                or stage61[read_offset:read_offset + 16].hex() \
                != read_postimage:
            _fail(f"product NULL consumer PC preimage drift: {owner_id}")
        start = tuple(map(int, contract["start"]))
        target = (int(repair["x"]), int(repair["y"]))
        walk_cycle = list(map(str, contract["walk_cycle"]))
        action = str(contract["action"])
        entry_seed = _verify_local_incoming_fixture_entry(
            stage61, coords, scripted_entries, connection_entries,
            engine_entries, group=group, number=number, start=start,
            target=target, action=action, walk_cycle=walk_cycle,
        )
        trigger_var = int(repair.get("trigger_var", 0))
        trigger_value = int(repair.get("trigger_value", 0))
        required_vars = (
            [{"id": trigger_var, "value": trigger_value}]
            if trigger_var else []
        )
        null_rows.append({
            "case_id": f"PRODUCT_NULL_{owner_kind}_{group:03d}_{number:03d}",
            "owner_kind": owner_kind,
            "consumer_kind": str(contract["consumer_kind"]),
            "group": group, "map": number, "index": int(repair["index"]),
            "position": list(target), "record_address": f"0x{address:08X}",
            "stage60_record_hex": before.hex(),
            "stage61_record_hex": after.hex(),
            "entry": {
                "start": list(start), "walk_cycle": walk_cycle,
                "action": action, "entry_seed": entry_seed,
            },
            "required_state": {"flags": [], "vars": required_vars},
            "trigger_var": trigger_var, "trigger_value": trigger_value,
            "expected_stage60_failure": "INVALID_POINTER_0x08000000",
            "expected_stage61_terminal": "FIELD_INPUT_RECOVERED_NO_SCRIPT",
            "consumer_pointer_read_pc": f"0x{read_pc:08X}",
            "consumer_pointer_read_preimage_hex": read_preimage,
            "consumer_pointer_read_postimage_hex": read_postimage,
            "consumer_null_policy": (
                EVENT_CONSUMER_SOURCE_CONTRACT["project_policy"]
                if owner_kind == "BG"
                else EVENT_CONSUMER_SOURCE_CONTRACT["source_null_contract"]
            ),
            "consumer_thumb_mode": True,
        })

    gym_by_site = {int(row["address"]): row for row in gym_bg_repair_rows}
    if set(gym_by_site) != set(GYM_BG_EMPTY_TRAINERBATTLE_SITES):
        _fail("gym BG runtime repair site集合不一致")
    gym_rows: list[dict[str, Any]] = []
    for site, group, number, root, expected_trainer in GYM_BG_OWNER_CONTRACTS:
        repair = gym_by_site[site]
        if int(repair["trainer_id"]) != expected_trainer:
            _fail(f"gym BG trainer/site drift: {site:#010x}")
        final_state = _stage_map_state(stage61, group, number)
        baseline_state = _stage_map_state(stage60, group, number)
        final_bg = bytes.fromhex(str(final_state["bg_hex"]))
        baseline_bg = bytes.fromhex(str(baseline_state["bg_hex"]))
        matches = [
            index for index in range(int(final_state["counts"]["bg"]))
            if struct.unpack_from("<I", final_bg, index * 12 + 8)[0] == root
        ]
        if len(matches) != 1:
            _fail(f"gym BG owner root一意性drift: {group}/{number}")
        bg_index = matches[0]
        record_address = int(final_state["pointers"]["bg"]) + bg_index * 12
        baseline_record_address = (
            int(baseline_state["pointers"]["bg"]) + bg_index * 12
        )
        if record_address != baseline_record_address:
            _fail(f"gym BG record addressがStage60から移動: {group}/{number}")
        final_record = final_bg[bg_index * 12:(bg_index + 1) * 12]
        baseline_record = baseline_bg[bg_index * 12:(bg_index + 1) * 12]
        if struct.unpack_from("<I", baseline_record, 8)[0] != root:
            _fail(f"gym BG Stage60 owner root drift: {group}/{number}")
        position = struct.unpack_from("<HH", final_record, 0)

        graph = SemanticScriptGraph(stage60)
        graph.walk([root])
        if graph.diagnostics or site not in graph.distances(root):
            _fail(f"gym BG Stage60 CFG reachability drift: {group}/{number}")
        predecessors = [
            node for node in graph.nodes.values()
            if site in node.edges
            and any(ins.opcode == 0x09 and ins.raw == b"\x09\x05"
                    for ins in node.instructions)
        ]
        if len(predecessors) != 1:
            _fail(f"gym BG prebattle msgbox predecessor不一意: {site:#010x}")
        messages = [
            struct.unpack_from("<I", ins.raw, 2)[0]
            for ins in predecessors[0].instructions
            if ins.opcode == 0x0F and len(ins.raw) == 6 and ins.raw[1] == 0
        ]
        if len(messages) != 1:
            _fail(f"gym BG prebattle text pointer不一意: {site:#010x}")
        prebattle_text = messages[0]
        entry = _select_local_incoming_bg_entry(
            stage61, coords, scripted_entries, connection_entries,
            engine_entries, group=group, number=number, target=position,
        )
        site_offset = _rom_offset(site, 32, f"gym BG prefix {site:#x}")
        baseline_prefix = stage60[site_offset:site_offset + 32]
        final_prefix = stage61[site_offset:site_offset + 32]
        defeat_text = int(repair["defeat_text_address"])
        pre_oracle = _single_text_oracle(
            stage61, pointer=prebattle_text,
            source_root=f"0x{root:08X}",
            provenance_kind="PINNED_STAGE60_PROJECT_RAW",
            meaning_source=(
                "STAGE60_PROJECT_GYM_PREBATTLE_MSGBOX_BEFORE_EXACT_"
                f"TRAINERBATTLE_{site:08X}"
            ),
        )
        post_oracle = _single_text_oracle(
            stage61, pointer=defeat_text,
            source_root=str(repair["encounter_key"]),
            provenance_kind="TRACKED_CANONICAL_TRAINER_DIALOGUE_CSV",
            meaning_source=(
                f"{repair['defeat_text_source_path']}#"
                f"{repair['encounter_key']}/DEFEAT"
            ),
        )
        owner_id = f"BG:{group:03d}/{number:03d}:{bg_index:03d}"
        fixture_row = {
            "case_id": f"PRODUCT_GYM_BG_{expected_trainer:03d}",
            "owner_id": owner_id, "group": group, "map": number,
            "bg_index": bg_index, "position": list(position),
            "record_address": f"0x{record_address:08X}",
            "stage60_record_hex": baseline_record.hex(),
            "stage61_record_hex": final_record.hex(),
            "script_root": f"0x{root:08X}",
            "trainerbattle_site": f"0x{site:08X}",
            "trainerbattle_type_offset": 1,
            "stage60_trainerbattle_prefix_hex": baseline_prefix.hex(),
            "stage61_trainerbattle_prefix_hex": final_prefix.hex(),
            "stage60_eos_text_pointer": (
                f"0x{GYM_BG_EMPTY_TRAINER_TEXT_POINTER:08X}"
            ),
            "prebattle_text_pointer": f"0x{prebattle_text:08X}",
            "repaired_defeat_text_pointer": f"0x{defeat_text:08X}",
            "trainer_id": expected_trainer, "entry": entry,
            "required_state": {"flags": [], "vars": []},
            "pre_text_oracle": pre_oracle, "post_text_oracle": post_oracle,
            "expected_stage60_semantic": (
                "TYPE0_TRAINERBATTLE_EOS_ONLY_TEXT"
            ),
            "expected_stage61_pre_terminal": "BATTLE_START",
            "expected_stage61_post_terminal": "FIELD_INPUT_RECOVERED",
            "prepost": ["PRE", "POST"],
        }
        repair.update({
            "owner_id": owner_id, "owner_kind": "BG", "group": group,
            "map": number, "bg_index": bg_index,
            "position": list(position), "record_address": record_address,
            "script_root": root, "prebattle_text_address": prebattle_text,
            "prebattle_text_sha256": pre_oracle[
                "ordered_raw_sha256s"
            ][0],
            "entry": entry,
            "owner_cfg_evidence": {
                "root_reaches_trainerbattle_site": True,
                "prebattle_msgbox_predecessor": (
                    f"0x{predecessors[0].address:08X}"
                ),
                "type0_to_type3_pointer_role_conversion": (
                    "PRECEDING_MSGBOX_RETAINS_INTRO;CANONICAL_CSV_DEFEAT_"
                    "REPLACES_EOS;TRAINER_ID_FLAGS_GOTO_UNCHANGED"
                ),
            },
            "mgba_fixture_case_id": fixture_row["case_id"],
        })
        gym_rows.append(fixture_row)
    if len(gym_rows) != 8 or {row["trainer_id"] for row in gym_rows} \
            != set(range(751, 759)):
        _fail("gym BG final-ROM fixture 8件一対一不一致")

    assertions = {
        "exact_two_physical_maps": len(map_rows) == 2,
        "baseline_preimage_is_independent_negative_evidence": (
            {bytes.fromhex(row["stage60_preimage_hex"])[0]
             for row in map_rows} == {0xF6, 0x6A}
        ),
        "stage61_empty_project_table_is_independent_oracle": (
            len(empty_pointers) == 1
            and all(bytes.fromhex(row["stage61_preimage_hex"])[0] == 0
                    for row in map_rows)
        ),
        "stock_warp_and_real_walk_only": True,
        "trainer_pre_and_post_both_required": all(
            row["trainer"]["prepost"] == ["PRE", "POST"]
            for row in map_rows
        ),
        "invalid_control_flow_zero_after_repair": True,
        "coord_bg_08000000_normalized_to_null": len(null_rows) == 2,
        "consumer_pointer_read_pc_preimage_bound": all(
            bool(row["consumer_pointer_read_preimage_hex"])
            for row in null_rows
        ),
        "numeric_zero_bg_returns_null_before_interaction_start": (
            [
                row["consumer_null_policy"] for row in null_rows
                if row["owner_kind"] == "BG"
            ] == ["NUMERIC_ZERO_BG_RETURNS_NULL"]
            and all(
                bytes.fromhex(row["consumer_pointer_read_postimage_hex"])[
                    BG_NUMERIC_ZERO_RETURN_PATCH_ADDRESS
                    - int(row["consumer_pointer_read_pc"] , 0):
                    BG_NUMERIC_ZERO_RETURN_BRANCH_ADDRESS
                    + len(BG_NUMERIC_ZERO_RETURN_BRANCH_PREIMAGE)
                    - int(row["consumer_pointer_read_pc"], 0)
                ]
                == BG_NUMERIC_ZERO_RETURN_PATCH_REPLACEMENT
                + BG_NUMERIC_ZERO_RETURN_BRANCH_PREIMAGE
                for row in null_rows if row["owner_kind"] == "BG"
            )
        ),
        "all_eight_gym_bg_type3_prepost_visible_text": (
            len(gym_rows) == 8
        ),
    }
    if not all(assertions.values()):
        _fail(f"product map-script regression fixture FAIL: {assertions}")
    return {
        "schema_version": 1, "status": "PASS",
        "baseline_rom": {
            "path_hint": "build/stages/60_wild_species_root_repair.gba",
            "sha256": _sha(stage60),
        },
        "maps": map_rows, "null_script_owners": null_rows,
        "gym_bg_trainer_regressions": gym_rows,
        "assertions": assertions,
    }


def _object_record_site(rom: bytes, group: int, number: int, local_id: int) -> int:
    header = _map_header_offset(rom, group, number)
    event = _rom_offset(_u32(rom, header + 4, "event pointer"), 0x14, "event")
    count = rom[event]
    array = _rom_offset(_u32(rom, event + 4, "object pointer"), count * 0x18,
                        "object array")
    matches = [array + index * 0x18 for index in range(count)
               if rom[array + index * 0x18] == local_id]
    if len(matches) != 1:
        _fail(f"object local IDが一意ではありません: {group}/{number} local={local_id}")
    return matches[0]


def _all_coordinates(canonical: Sequence[Mapping[str, Any]]) -> list[tuple[int, int, str]]:
    groups = json.loads((ROOT / "vendor/upstream/pokefirered/data/maps/map_groups.json")
                        .read_text(encoding="utf-8"))
    result = [
        (group, number, str(name))
        for group, group_name in enumerate(groups["group_order"])
        for number, name in enumerate(groups[group_name])
    ]
    result += [
        (int(row["map_header"]["group_id"]), int(row["map_header"]["map_id"]),
         str(row["map_header"]["map_key"]))
        for row in canonical
    ]
    if len(result) != 678 or len({(g, m) for g, m, _ in result}) != 678:
        _fail(f"physical map inventory不一致: {len(result)}")
    return result


def _engine_special_flag_owner_literal_contract(
    stage60_rom: bytes,
    final_rom: bytes,
) -> dict[str, Any]:
    """OracleのROM exact owner証明をbuilder errorへfail-closed変換する。"""

    try:
        contract = validate_engine_special_flag_owner_literal(
            stage60_rom, final_rom,
        )
    except Stage61InteractionOracleError as exc:
        _fail(f"engine special flag owner literal contract不正:{exc}")
    if contract.get("status") != "PASS" \
            or not all(contract.get("assertions", {}).values()):
        _fail("engine special flag owner literal contractがcomplete PASSでない")
    return contract


def _engine_special_flag_lifecycle_fixture(
    stage60_rom: bytes,
    rom: bytes,
    event_owner_inventory: Mapping[str, Any],
    state_matrix: Mapping[str, Any],
) -> dict[str, Any]:
    """Pallet coord→Oak Lab map-loadのvolatile flag実走fixtureを固定する。"""

    owner_literal_contract = _engine_special_flag_owner_literal_contract(
        stage60_rom, rom,
    )
    lifecycle = state_matrix.get(
        "engine_special_flag_lifecycle_contract"
    )
    if not isinstance(lifecycle, Mapping) \
            or lifecycle.get("status") != "PASS" \
            or not all(lifecycle.get("assertions", {}).values()):
        _fail("engine special flag lifecycle fixture contract不正")
    owner_ids = (
        "COORD:003/000:000",
        "COORD:003/000:001",
        "MAP:004/003:002:000",
    )
    owners = event_owner_inventory.get("owners")
    if not isinstance(owners, list):
        _fail("engine special flag lifecycle fixture owner inventory不正")
    by_id = {
        str(row["owner_id"]): row for row in owners
        if isinstance(row, Mapping) and row.get("owner_id") in owner_ids
    }
    if set(by_id) != set(owner_ids):
        _fail("engine special flag lifecycle fixture owner欠落")
    expected_records = {
        "COORD:003/000:000": "09001a00030050400000000015f71608",
        "COORD:003/000:001": "09001b00030050400000000021f71608",
        "MAP:004/003:002:000": "5540010059c81708",
    }
    record_rows: list[dict[str, Any]] = []
    for owner_id in owner_ids:
        owner = by_id[owner_id]
        expected = bytes.fromhex(expected_records[owner_id])
        address = int(owner["record_address"])
        offset = _rom_offset(address, len(expected), owner_id)
        actual = rom[offset:offset + len(expected)]
        if actual != expected:
            _fail(
                f"engine special flag lifecycle record drift:{owner_id}:"
                f"{actual.hex()}"
            )
        record_rows.append({
            "owner_id": owner_id,
            "owner_kind": owner["owner_kind"],
            "record_address": f"0x{address:08X}",
            "record_hex": actual.hex(),
            "record_sha256": _sha(actual),
            "runtime_root": f"0x{int(owner['root']):08X}",
        })
    expected_operations = [
        {
            "operation": "SET", "flag_id": 0x4001,
            "instruction_address": "0x0816F7D2",
            "node_address": "0x0816F72D",
            "owner_ids": [
                "COORD:003/000:000", "COORD:003/000:001",
            ],
        },
        {
            "operation": "CLEAR", "flag_id": 0x4001,
            "instruction_address": "0x0817C892",
            "node_address": "0x0817C859",
            "owner_ids": ["MAP:004/003:002:000"],
        },
    ]
    if lifecycle.get("final_operations") != expected_operations:
        _fail("engine special flag lifecycle fixture operation drift")
    variants = [
        {
            "variant": "LEFT_COORD",
            "coord_owner_id": "COORD:003/000:000",
            "start": [9, 25], "trigger_tile": [9, 26],
            "walk_tokens": ["DOWN"], "temporary_side": 0,
        },
        {
            "variant": "RIGHT_COORD",
            "coord_owner_id": "COORD:003/000:001",
            "start": [9, 28], "trigger_tile": [9, 27],
            "walk_tokens": ["UP"], "temporary_side": 1,
        },
    ]
    return {
        "schema_version": 1,
        "kind": "ENGINE_SPECIAL_FLAG_CROSS_MAP_LIFECYCLE",
        "status": "PASS",
        "flag_id": "0x4001",
        "runtime_storage": {
            "owner_address":
                f"0x{ENGINE_SPECIAL_FLAG_OWNER_ADDRESS:08X}",
            "size": ENGINE_SPECIAL_FLAG_OWNER_SIZE,
            "encoding": "PLAIN_BITSET_ID_0x4000_IS_BIT_0",
            "byte_offset": 0, "bit_mask": 2,
            "persistence": "EWRAM_VOLATILE_NOT_SAVEBLOCK",
        },
        "producer": {
            "map": [3, 0], "trigger_var": "0x4050",
            "trigger_value": 0, "set_site": "0x0816F7D2",
            "record_owners": record_rows[:2], "variants": variants,
        },
        "transition": {
            "destination_map": [4, 3],
            "destination_position": [6, 12],
            "scene_var": "0x4055", "scene_value": 1,
            "relation": "REAL_COORD_STEP_CUTSCENE_THEN_STOCK_WARP",
        },
        "consumer": {
            "owner": record_rows[2],
            "clear_site": "0x0817C892",
            "trigger": "DESTINATION_MAP_LOAD_CONDITION_0x4055_EQ_1",
        },
        "expected_trace": [
            "COORD_TRIGGER_HIT", "SET_0x4001_BIT_OBSERVED",
            "STOCK_WARP_TO_004_003_006_012",
            "MAP_CONDITION_OWNER_HIT", "CLEAR_0x4001_BIT_OBSERVED",
            "BGM_TRANSITION_COMPLETES", "FIELD_INPUT_RECOVERED",
        ],
        "required_final": {
            "engine_special_flag_0x4001": False,
            "map": [4, 3], "invalid_script_pc_count": 0,
            "softlock_count": 0,
        },
        "source_contract": {
            **deepcopy(lifecycle["source_contract"]),
            "runtime_owner_literal": deepcopy(owner_literal_contract),
        },
        "assertions": {
            "both_coord_entry_variants_are_actual_steps": True,
            "set_and_destination_clear_sites_exact": True,
            "volatile_bitset_owner_and_mask_exact": True,
            "no_direct_script_call_allowed": True,
            "final_special_flag_clear_and_input_recovered": True,
        },
    }


def _physical_map_provenance_catalog(
    vega_rom: bytes,
    vega_inventory_raw: bytes,
    canonical: Sequence[Mapping[str, Any]],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """全678 physical mapをsource identity付きで固定する。

    base 425 mapはcleanの同じ数値座標へ一切結び付けず、pinned Vega ROMと
    inventory CSVを相互再計算する。canonical 253 mapだけが別欄のclean source
    group/map/nameを持つ。
    """

    try:
        decoded = vega_inventory_raw.decode("utf-8")
        source_rows = list(csv.DictReader(decoded.splitlines()))
    except (UnicodeDecodeError, csv.Error) as exc:
        _fail(f"Vega map inventory CSV不正: {exc}")
    required = {
        "group", "map", "header_address", "layout_id", "map_section",
        "music", "events_address", "object_count", "warp_count",
        "coord_count", "bg_count", "map_scripts_address",
        "classification", "evidence",
    }
    if len(source_rows) != 425 or not source_rows \
            or not required.issubset(source_rows[0]):
        _fail("Vega map inventory 425-row/schema契約不一致")
    groups = json.loads((
        ROOT / "vendor/upstream/pokefirered/data/maps/map_groups.json"
    ).read_text(encoding="utf-8"))
    base_coordinates = [
        (group, number)
        for group, group_name in enumerate(groups["group_order"])
        for number, _name in enumerate(groups[group_name])
    ]
    if len(base_coordinates) != 425:
        _fail("Vega physical coordinate cardinality不一致")
    seen: set[tuple[int, int]] = set()
    physical: list[dict[str, Any]] = []
    source_header_hashes: dict[str, str] = {}
    for row in source_rows:
        try:
            group, number = int(row["group"]), int(row["map"])
            header_address = int(row["header_address"])
            expected = {
                "layout_id": int(row["layout_id"]),
                "map_section": int(row["map_section"]),
                "music": int(row["music"]),
                "events_address": int(row["events_address"]),
                "object_count": int(row["object_count"]),
                "warp_count": int(row["warp_count"]),
                "coord_count": int(row["coord_count"]),
                "bg_count": int(row["bg_count"]),
                "map_scripts_address": int(row["map_scripts_address"]),
            }
        except (KeyError, TypeError, ValueError) as exc:
            _fail(f"Vega map inventory numeric field不正: {row}: {exc}")
        key = (group, number)
        if key in seen or key not in set(base_coordinates):
            _fail(f"Vega map inventory座標不正/重複: {key}")
        seen.add(key)
        if row["classification"] != "VEGA" or not row["evidence"]:
            _fail(f"Vega map inventory provenance不正: {key}")
        header = _map_header_offset(vega_rom, group, number)
        actual_header_address = GBA_BASE + header
        actual = {
            "layout_id": struct.unpack_from("<H", vega_rom, header + 18)[0],
            "map_section": vega_rom[header + 20],
            "music": struct.unpack_from("<H", vega_rom, header + 16)[0],
            "events_address": _u32(
                vega_rom, header + 4, f"Vega events {group}/{number}"
            ),
            "map_scripts_address": _u32(
                vega_rom, header + 8, f"Vega map scripts {group}/{number}"
            ),
        }
        event_pointer = actual["events_address"]
        if event_pointer in (0, 0xFFFFFFFF):
            counts = (0, 0, 0, 0)
        else:
            event = _rom_offset(
                event_pointer, 4, f"Vega event header {group}/{number}"
            )
            counts = tuple(vega_rom[event:event + 4])
            # Vega inventory explicitly normalizes the four known erased
            # 0xFF event headers to zero templates; retain the raw header hash
            # as provenance but never treat 255 as a live array count.
            if counts == (0xFF, 0xFF, 0xFF, 0xFF):
                counts = (0, 0, 0, 0)
        actual.update(dict(zip(
            ("object_count", "warp_count", "coord_count", "bg_count"),
            counts,
        )))
        if actual_header_address != header_address or actual != expected:
            _fail(
                f"Vega map inventory/ROM drift: {group}/{number}: "
                f"header={actual_header_address:#010x}/{header_address:#010x} "
                f"actual={actual} expected={expected}"
            )
        header_sha = _sha(vega_rom[header:header + 0x1C])
        map_key = f"VEGA_STOCK:{group:03d}/{number:03d}"
        source_header_hashes[map_key] = header_sha
        physical.append({
            "group": group,
            "map": number,
            "map_key": map_key,
            "provenance": "VEGA_STOCK",
            "source_identity": {
                "rom_sha256": _sha(vega_rom),
                "header_address": f"0x{header_address:08X}",
                "header_sha256": header_sha,
                "inventory_row_sha256": _sha(_stable(dict(row))),
                "classification": row["classification"],
                "evidence": row["evidence"],
            },
        })
    if seen != set(base_coordinates):
        _fail("Vega map inventory coordinate集合がvendor physical集合と不一致")

    clean_coordinates = {
        str(name): (group, number)
        for group, group_name in enumerate(groups["group_order"])
        for number, name in enumerate(groups[group_name])
    }
    for row in canonical:
        header = row["map_header"]
        source_name = str(header["source_map"])
        if source_name not in clean_coordinates:
            _fail(f"canonical source mapがvendor inventoryにありません: {source_name}")
        source_group, source_map = clean_coordinates[source_name]
        physical.append({
            "group": int(header["group_id"]),
            "map": int(header["map_id"]),
            "map_key": str(header["map_key"]),
            "provenance": "IMPORTED_KANTO",
            "source_group": source_group,
            "source_map": source_map,
            "source_map_name": source_name,
            "source_identity": {
                "canonical_recipe_sha256": _sha(_stable(row)),
                "scope_decision": str(header["scope_decision"]),
                "source_is_clean_fire_red": True,
            },
        })
    counts = Counter(row["provenance"] for row in physical)
    if len(physical) != 678 or counts != Counter({
        "VEGA_STOCK": 425, "IMPORTED_KANTO": 253,
    }) or len({(row["group"], row["map"]) for row in physical}) != 678:
        _fail(f"physical provenance 678-map契約不一致: {len(physical)}/{counts}")
    report = {
        "schema_version": 1,
        "status": "PASS",
        "vega_rom_sha256": _sha(vega_rom),
        "vega_inventory_sha256": _sha(vega_inventory_raw),
        "physical_map_count": len(physical),
        "provenance_counts": dict(sorted(counts.items())),
        "vega_source_header_set_sha256": _sha(_stable(source_header_hashes)),
        "assertions": {
            "vega_inventory_all_425_rows_recomputed_from_pinned_rom": True,
            "vega_numeric_coordinates_never_claim_clean_semantics": True,
            "canonical_253_rows_have_explicit_clean_source_coordinates": True,
            "all_678_physical_coordinates_unique": True,
        },
    }
    return sorted(physical, key=lambda row: (row["group"], row["map"])), report


def _null_event_script_pointer_records(
    rom: bytes,
    physical_maps: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Field engineがNULLと解釈しない0x08000000 union値を全件列挙する。"""

    rows: list[dict[str, Any]] = []
    for physical in physical_maps:
        group, number = int(physical["group"]), int(physical["map"])
        try:
            header = _map_header_offset(rom, group, number)
        except (RuntimeError, Stage61BuildError):
            continue
        event_pointer = _u32(rom, header + 4, "event header pointer")
        if event_pointer in (0, 0xFFFFFFFF):
            continue
        try:
            event = _rom_offset(
                event_pointer, 0x14, f"event header {group}/{number}"
            )
        except Stage61BuildError:
            continue
        if rom[event:event + 4] == b"\xFF\xFF\xFF\xFF":
            continue
        for kind, count, size, array_site, root_offset in (
            ("COORD", rom[event + 2], 0x10, event + 12, 0x0C),
            ("BG", rom[event + 3], 0x0C, event + 16, 0x08),
        ):
            if not count:
                continue
            array_pointer = _u32(rom, array_site, f"{kind} array pointer")
            array = _rom_offset(
                array_pointer, count * size, f"{kind} array {group}/{number}"
            )
            for index in range(count):
                record = array + index * size
                pointer_site = record + root_offset
                pointer = _u32(rom, pointer_site, f"{kind} script pointer")
                if pointer != NULL_EVENT_SCRIPT_POINTER:
                    continue
                x, y = struct.unpack_from("<hh", rom, record)
                row: dict[str, Any] = {
                    "repair_id": (
                        f"NULL_EVENT_SCRIPT_{kind}_{group:03d}_{number:03d}_{index:03d}"
                    ),
                    "owner_id": f"{kind}:{group:03d}/{number:03d}:{index:03d}",
                    "owner_kind": kind,
                    "group": group,
                    "map": number,
                    "map_key": str(physical["map_key"]),
                    "physical_provenance": str(physical["provenance"]),
                    "index": index,
                    "x": x,
                    "y": y,
                    "elevation": rom[record + 4],
                    "record_address": GBA_BASE + record,
                    "record_size": size,
                    "record_sha256": _sha(rom[record:record + size]),
                    "pointer_site": GBA_BASE + pointer_site,
                    "before_root": NULL_EVENT_SCRIPT_POINTER,
                    "after_root": 0,
                    "expected_hex": struct.pack("<I", pointer).hex(),
                    "replacement_hex": "00000000",
                    "reason": "ENGINE_NULL_IS_NUMERIC_ZERO_NOT_ROM_BASE_SENTINEL",
                    "consumer_contract": dict(EVENT_CONSUMER_SOURCE_CONTRACT),
                }
                if kind == "COORD":
                    row.update({
                        "trigger_var": struct.unpack_from("<H", rom, record + 6)[0],
                        "trigger_value": struct.unpack_from("<H", rom, record + 8)[0],
                        "interaction_method": "WALK_ON_COORD_TILE",
                    })
                else:
                    bg_kind = rom[record + 5]
                    if bg_kind in (7, 8):
                        _fail(
                            f"BG non-script unionをNULL正規化しようとしました: "
                            f"{group}/{number}/{index} kind={bg_kind}"
                        )
                    row.update({
                        "bg_kind": bg_kind,
                        "interaction_method": "FACE_TILE_AND_PRESS_A",
                    })
                rows.append(row)
    rows.sort(key=lambda row: (
        row["owner_kind"], row["group"], row["map"], row["index"]
    ))
    counts = Counter(row["owner_kind"] for row in rows)
    if counts != Counter(NULL_EVENT_SCRIPT_EXPECTED_COUNTS):
        _fail(f"0x08000000 event union count drift: {counts}")
    if len({row["pointer_site"] for row in rows}) != len(rows):
        _fail("NULL event union pointer site重複")
    return rows


def _actual_map_name(
    rom: bytes, mapsec: int, custom_names: Mapping[int, Mapping[str, Any]],
    charmap: Mapping[int, str],
) -> tuple[str, str]:
    evidence = _map_name_evidence(rom, mapsec, custom_names, charmap)
    return str(evidence["decoded_utf8"]), str(evidence["namespace"])


def _map_name_evidence(
    rom: bytes, mapsec: int, custom_names: Mapping[int, Mapping[str, Any]],
    charmap: Mapping[int, str],
) -> dict[str, Any]:
    if mapsec in custom_names:
        row = custom_names[mapsec]
        pointer = int(row["materialized_pointer"])
        namespace = "PROJECT_KANTO_NAMESPACE"
    elif 88 <= mapsec <= 196:
        pointer = _u32(rom, STOCK_MAP_NAMES - GBA_BASE + (mapsec - 88) * 4,
                       f"stock map name {mapsec}")
        namespace = "VEGA_STOCK_NAMESPACE"
    else:
        return {
            "pointer": None, "raw_hex": "", "raw_sha256": None,
            "decoded_utf8": "", "namespace": "INVALID_OR_SPECIAL",
        }
    raw = _read_text(rom, pointer, f"map name {mapsec}", limit=128)
    decoded = decode_text(raw, charmap)
    return {
        "pointer": f"0x{pointer:08X}",
        "raw_hex": raw.hex(),
        "raw_sha256": _sha(raw),
        "decoded_utf8": decoded.decoded_utf8,
        "namespace": namespace,
    }


def _build_map_catalog(
    stage60: bytes, output: bytes, coords: Sequence[tuple[int, int, str]],
    canonical: Sequence[Mapping[str, Any]], name_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    canonical_by_coord = {
        (int(row["map_header"]["group_id"]), int(row["map_header"]["map_id"])): row
        for row in canonical
    }
    custom_names = {int(row["runtime_map_section_id"]): row for row in name_rows}
    charmap = load_charmap(ROOT / "vendor/upstream/CFRU-JP/charmap.tbl")
    rows: list[dict[str, Any]] = []
    failures: list[dict[str, Any]] = []
    for group, number, key in coords:
        header_offset = _map_header_offset(output, group, number)
        mapsec = output[header_offset + 0x14]
        show = bool(output[header_offset + 0x19] & 0x04)
        actual_evidence = _map_name_evidence(
            output, mapsec, custom_names, charmap
        )
        actual = str(actual_evidence["decoded_utf8"])
        namespace = str(actual_evidence["namespace"])
        canonical_row = canonical_by_coord.get((group, number))
        baseline: dict[str, Any] | None = None
        if canonical_row:
            expected_section = int(canonical_row["map_header"]["runtime_map_section_id"])
            expected_show = bool(canonical_row["map_header"]["show_map_name"])
            expected_name = custom_names[expected_section]["decoded_utf8"]
            expected_raw_sha256 = custom_names[expected_section]["raw_sha256"]
            provenance = "IMPORTED_KANTO_CANONICAL_MANIFEST"
        else:
            baseline_header = _map_header_offset(stage60, group, number)
            expected_section = stage60[baseline_header + 0x14]
            expected_show = bool(stage60[baseline_header + 0x19] & 0x04)
            baseline = _map_name_evidence(
                stage60, expected_section, {}, charmap
            )
            expected_name = str(baseline["decoded_utf8"])
            expected_raw_sha256 = baseline["raw_sha256"]
            provenance = "PINNED_STAGE60_PHYSICAL_MAP_HEADER_AND_STOCK_NAME_BYTES"
        status = (mapsec == expected_section and show == expected_show
                  and actual == expected_name and bool(actual)
                  and actual_evidence["raw_sha256"] == expected_raw_sha256
                  and (
                      canonical_row is not None
                      or (
                          namespace == "VEGA_STOCK_NAMESPACE"
                          and baseline is not None
                          and baseline["namespace"] == "VEGA_STOCK_NAMESPACE"
                      )
                  ))
        row = {
            "group": group, "map": number, "map_key": key,
            "region_map_section_id": mapsec, "namespace": namespace,
            "show_map_name": show, "expected_show_map_name": expected_show,
            "actual_name": actual, "expected_name": expected_name,
            "actual_name_pointer": actual_evidence["pointer"],
            "actual_name_raw_sha256": actual_evidence["raw_sha256"],
            "expected_name_raw_sha256": expected_raw_sha256,
            "meaning_provenance": provenance,
            "stage60_baseline": baseline,
            "status": "PASS" if status else "FAIL",
        }
        rows.append(row)
        if not status:
            failures.append(row)
    non_kanto_rows = [
        row for row in rows
        if (int(row["group"]), int(row["map"])) not in canonical_by_coord
    ]
    assertions = {
        "all_678_physical_maps_have_nonempty_exact_name": not failures,
        "all_425_non_kanto_maps_pinned_to_stage60_header_and_name_bytes": (
            len(non_kanto_rows) == 425
            and all(
                row["meaning_provenance"]
                    == "PINNED_STAGE60_PHYSICAL_MAP_HEADER_AND_STOCK_NAME_BYTES"
                and row["namespace"] == "VEGA_STOCK_NAMESPACE"
                and row["actual_name_raw_sha256"]
                    == row["expected_name_raw_sha256"]
                for row in non_kanto_rows
            )
        ),
        "non_kanto_never_resolves_project_low_id_namespace": all(
            not 0 <= int(row["region_map_section_id"]) <= 52
            and row["namespace"] != "PROJECT_KANTO_NAMESPACE"
            for row in non_kanto_rows
        ),
        "tohoku_wisdom_cave_name_is_explicit": all(
            row["actual_name"] == "ちえのどうくつ"
            for row in rows
            if int(row["group"]) == 1
            and int(row["map"]) in {36, 37, 38, 73}
        ),
    }
    if not all(assertions.values()):
        _fail(f"map display catalog assertion FAIL: {assertions}")
    return {
        "schema_version": 1, "task": TASK, "stage": STAGE,
        "status": "PASS" if not failures else "FAIL",
        "physical_map_count": len(rows), "kanto_map_count": len(canonical),
        "non_kanto_map_count": len(non_kanto_rows),
        "failure_count": len(failures), "failures": failures,
        "assertions": assertions, "maps": rows,
    }


def _build_npc_catalog(
    output: bytes, coords: Sequence[tuple[int, int, str]],
    owner_ledger: Mapping[str, Any], semantic: RelocationPlan,
    root_targets: Mapping[int, int],
    missing_object: MissingObjectTemplateMaterialization,
    topology_producer: Stage61TopologyProducerMaterialization,
    post_ledger: Mapping[str, Any],
) -> dict[str, Any]:
    owners = {
        (str(row["event"]), int(row["group"]), int(row["map"]), int(row["index"])): row
        for row in owner_ledger["owner_rows"]
        if all(key in row for key in ("event", "group", "map", "index"))
    }
    supplemental = post_ledger.get("owners")
    if not isinstance(supplemental, Mapping) or len(supplemental) != 9:
        _fail("post-ledger owner lookup不正")
    overlap = sorted(set(owners) & set(supplemental))
    if overlap:
        _fail(f"owner ledger/post-ledger manifest所有重複: {overlap}")
    source_root_by_owner = {
        (str(owner["event"]), int(owner["group"]), int(owner["map"]), int(owner["index"])):
            root.source_script_pointer
        for root in semantic.root_plans for owner in root.owners
    }
    topology_records: dict[tuple[str, int, int, int], bytes] = {}
    for topology_row in topology_producer.object_rows:
        group, number = (
            int(value) for value in str(topology_row["map"]).split("/")
        )
        raw_array = bytes.fromhex(str(topology_row["raw_hex"]))
        if len(raw_array) % 24:
            _fail("topology producer object array size不正")
        for index in range(len(raw_array) // 24):
            key = ("OBJECT", group, number, index)
            if key in topology_records:
                _fail(f"topology producer object owner重複: {key}")
            topology_records[key] = raw_array[index * 24:(index + 1) * 24]
    rows: list[dict[str, Any]] = []
    owner_missing: list[str] = []
    legacy_gap_count = 0
    topology_gap_count = 0
    for group, number, map_key in coords:
        try:
            state = _stage_map_state(output, group, number)
        except RuntimeError:
            # Vegaにはevent pointerが0/0xFFFFFFFFの意図的な空mapがある。
            # objectを推測生成せず、空としてcatalog化する。
            continue
        for index, raw in enumerate(state["objects"]):
            fields = _object_fields(raw)
            if fields["kind"] != 0 or not fields["script_pointer"]:
                continue
            owner = owners.get(("OBJECT", group, number, index))
            supplemental_owner = supplemental.get(("OBJECT", group, number, index))
            restored_missing = (
                group == missing_object.requirement.target_group
                and number == missing_object.requirement.target_map
                and index == missing_object.requirement.target_index
            )
            topology_expected = topology_records.get(
                ("OBJECT", group, number, index)
            )
            topology_owned = (
                owner is None
                and supplemental_owner is None
                and not restored_missing
                and topology_expected is not None
            )
            if topology_owned and raw != topology_expected:
                _fail(
                    "topology producer final ObjectEventTemplate drift: "
                    f"OBJECT:{group:03d}/{number:03d}:{index:03d}"
                )
            if owner is None and supplemental_owner is not None:
                legacy_gap_count += 1
            if topology_owned:
                topology_gap_count += 1
            if owner is None and supplemental_owner is None \
                    and not restored_missing and not topology_owned:
                owner_missing.append(
                    f"OBJECT:{group:03d}/{number:03d}:{index:03d}"
                )
            if owner is not None:
                role = str(owner["role"])
                branches_override: list[str] | None = None
                owner_provenance = "WORLD_RUNTIME_OWNER_LEDGER_STAGE54"
            elif supplemental_owner is not None:
                role = str(supplemental_owner["role"])
                branches_override = list(supplemental_owner["branches"])
                owner_provenance = "STAGE58_POST_LEDGER_EXACT_MANIFEST"
                expected_fields = {
                    **{
                        key: int(value)
                        for key, value in supplemental_owner["object"].items()
                    },
                    "local_id": int(supplemental_owner["local_id"]),
                    "script_pointer": int(supplemental_owner["script_pointer"]),
                }
                if map_key != supplemental_owner["map_key"] or any(
                    fields[key] != value for key, value in expected_fields.items()
                ):
                    _fail(
                        "post-ledger final ObjectEventTemplate drift: "
                        f"{supplemental_owner['npc_id']}"
                    )
            elif restored_missing:
                role = "RESTORED_SOURCE_ITEM_OBJECT"
                branches_override = None
                owner_provenance = "STAGE61_MISSING_OBJECT_MATERIALIZATION"
            elif topology_owned:
                role = "TOPOLOGY_STRENGTH_BOULDER"
                branches_override = ["DEFAULT"]
                owner_provenance = (
                    "STAGE61_TOPOLOGY_PRODUCER_MATERIALIZATION"
                )
            else:
                # Preserve a row only long enough to report every missing key;
                # no generic project-owner role may make the audit pass.
                role = "UNOWNED_FAIL_CLOSED"
                branches_override = None
                owner_provenance = "MISSING"
            source_root = source_root_by_owner.get(("OBJECT", group, number, index))
            if restored_missing:
                source_root = missing_object.requirement.source_script_pointer
            elif topology_owned:
                source_root = TOPOLOGY_STRENGTH_SOURCE_ROOT
            if branches_override is not None:
                branches = branches_override
            elif role == "TRAINER":
                branches = ["TRAINER_PRE_BATTLE", "TRAINER_POST_BATTLE"]
            elif "ITEM" in role:
                branches = ["UNCOLLECTED", "COLLECTED"]
            elif source_root in (0x081769BB, 0x08177A29):
                branches = ["FLUTE_UNAVAILABLE", "CHOICE_NO", "CHOICE_YES_BATTLE",
                            "CLEARED_AFTER_SAVE_LOAD"]
            elif source_root == 0x08181B5D:
                branches = ["TOHOKU_FLUTE_UNAVAILABLE", "TOHOKU_FLUTE_OWNED"]
            else:
                branches = ["DEFAULT"]
            expected_adapter = (
                missing_object.script_address
                if restored_missing else
                root_targets.get(source_root) if source_root else None
            )
            script_pointer = int(fields["script_pointer"])
            status = expected_adapter is None or script_pointer == expected_adapter
            rows.append({
                "npc_id": f"OBJECT:{group:03d}/{number:03d}:{index:03d}",
                "group": group, "map": number, "map_key": map_key,
                "object_index": index, "local_id": fields["local_id"],
                "x": fields["x"], "y": fields["y"],
                "graphics_id": fields["graphics_id"],
                "movement_type": fields["movement_type"],
                "flag": fields["flag"], "script_pointer": script_pointer,
                "owner_role": role, "source_script_pointer": source_root,
                "owner_provenance": owner_provenance,
                "post_ledger_manifest_sha256": (
                    str(supplemental_owner["manifest_sha256"])
                    if supplemental_owner is not None else None
                ),
                "branches": branches,
                "static_owner_status": "PASS" if status else "FAIL",
                "mgba_status": "SCHEDULED_STAGE61_ALL_NPC_INPUT_AUDIT",
            })
    failures = [row for row in rows if row["static_owner_status"] != "PASS"]
    if owner_missing:
        _fail(f"NPC owner provenance欠落: {owner_missing}")
    if legacy_gap_count != 9:
        _fail(f"Stage58 post-ledger owner照合件数drift: {legacy_gap_count}")
    if topology_gap_count != 9:
        _fail(f"Stage61 topology producer owner照合件数drift: {topology_gap_count}")
    return {
        "schema_version": 1, "task": TASK, "stage": STAGE,
        "status": "PASS" if not failures and len(rows) == 3108 else "FAIL",
        "script_object_count": len(rows),
        "branch_count": sum(len(row["branches"]) for row in rows),
        "owner_ledger_missing_object_count": 0,
        "legacy_ledger_supplemented_object_count": legacy_gap_count,
        "topology_producer_object_count": topology_gap_count,
        "post_ledger_owner_manifest": {
            "path": post_ledger["manifest_path"],
            "sha256": post_ledger["manifest_sha256"],
            "source_stage": 58,
            "source_rom_sha256": post_ledger["stage58_rom_sha256"],
            "owner_count": post_ledger["owner_count"],
            "drift_count": 0,
        },
        "static_failure_count": len(failures), "static_failures": failures,
        "mgba_contract": {
            "trigger": "stock warp + legal adjacent tile + at least one real step + direction + A",
            "required": "runner merges actual UTF-8/render/release/side-effect result; untested=0",
        },
        "npcs": rows,
    }


def _legacy_npc_calibration_catalog(
    enriched_catalog: Mapping[str, Any],
) -> dict[str, Any]:
    """Project the internal catalog onto the runner's calibration ABI.

    Placement, source-provenance, and diagnostic fields are intentionally kept
    in their dedicated reports.  The legacy calibration artifact is a narrow
    wire format consumed by a separate mGBA process; emitting the enriched
    internal rows here would make the builder and runner disagree about the
    exact schema and could silently couple calibration to planner-only data.
    """

    root_keys = (
        "schema_version", "task", "stage", "status",
        "script_object_count", "branch_count",
        "owner_ledger_missing_object_count", "static_failure_count",
        "static_failures", "mgba_contract",
    )
    npc_keys = (
        "npc_id", "group", "map", "map_key", "object_index", "local_id",
        "x", "y", "graphics_id", "movement_type", "flag",
        "script_pointer", "owner_role", "source_script_pointer", "branches",
        "static_owner_status", "mgba_status",
        "interaction_execution", "non_product_shadow_alias",
        "expected_template_raw_hex", "runtime_position_state_contract",
    )
    try:
        projected_rows = []
        for index, row in enumerate(enriched_catalog["npcs"]):
            runtime_object = row.get("interaction_object")
            if not isinstance(runtime_object, list) \
                    or len(runtime_object) != 2 \
                    or any(isinstance(value, bool) or not isinstance(value, int)
                           for value in runtime_object):
                _fail(
                    "legacy NPC calibration runtime interaction object不正:"
                    f"{index}"
                )
            projected_row = {
                key: deepcopy(row[key]) for key in npc_keys
            }
            # Legacy wire names x/y are retained for compatibility, but their
            # consumer is physical interaction geometry.  Static ROM template
            # coordinates are independently carried by the exact 24-byte raw.
            projected_row["x"], projected_row["y"] = runtime_object
            projected_rows.append(projected_row)
        projected = {
            **{key: deepcopy(enriched_catalog[key]) for key in root_keys},
            "npcs": projected_rows,
        }
    except (KeyError, TypeError) as error:
        _fail(f"legacy NPC calibration projection入力不正: {error}")
    try:
        validate_mgba_legacy_catalog_document(projected)
    except RuntimeError as error:
        _fail(f"legacy NPC calibration catalog runner ABI不一致: {error}")
    return projected


def _story_event_graph(story: Mapping[str, Any]) -> dict[str, Any]:
    flute_flag = int(str(story["tohoku_flute_flag"]), 0)
    route12 = int(str(story["route12_hidden_flag"]), 0)
    route16 = int(str(story["route16_hidden_flag"]), 0)
    species = int(story["canonical_snorlax_species"])
    nodes = [
        {"id": "TOHOKU_FLUTE_GIVER", "kind": "NPC", "map": "1/45 local 9"},
        {"id": f"FLAG_{flute_flag:04X}", "kind": "PROJECT_STORY_FLAG"},
        {"id": f"ITEM_{int(story['flute_item'])}", "kind": "KEY_ITEM"},
        {"id": "ROUTE12_SNORLAX", "kind": "FIXED_ENCOUNTER", "map": "96/23 local 15"},
        {"id": "ROUTE16_SNORLAX", "kind": "FIXED_ENCOUNTER", "map": "96/27 local 6"},
        {"id": f"SPECIES_{species}", "kind": "CANONICAL_SPECIES"},
        {"id": f"FLAG_{route12:04X}", "kind": "PROJECT_VISIBILITY_FLAG"},
        {"id": f"FLAG_{route16:04X}", "kind": "PROJECT_VISIBILITY_FLAG"},
        {"id": "MR_FUJI_CONTEXT", "kind": "NPC", "map": "98/30 local 1"},
    ]
    edges = [
        {"from": "TOHOKU_FLUTE_GIVER", "to": f"ITEM_{int(story['flute_item'])}", "effect": "give_once"},
        {"from": "TOHOKU_FLUTE_GIVER", "to": f"FLAG_{flute_flag:04X}", "effect": "set"},
        {"from": f"FLAG_{flute_flag:04X}", "to": "ROUTE12_SNORLAX", "effect": "unlocks_yes_branch"},
        {"from": f"FLAG_{flute_flag:04X}", "to": "ROUTE16_SNORLAX", "effect": "unlocks_yes_branch"},
        {"from": "ROUTE12_SNORLAX", "to": f"SPECIES_{species}", "effect": "battle_level_30"},
        {"from": "ROUTE16_SNORLAX", "to": f"SPECIES_{species}", "effect": "battle_level_30"},
        {"from": "ROUTE12_SNORLAX", "to": f"FLAG_{route12:04X}", "effect": "hide_after_battle_start"},
        {"from": "ROUTE16_SNORLAX", "to": f"FLAG_{route16:04X}", "effect": "hide_after_battle_start"},
        {"from": f"FLAG_{flute_flag:04X}", "to": "MR_FUJI_CONTEXT", "effect": "dialogue_branch_only_no_second_item"},
    ]
    return {
        "schema_version": 1, "task": TASK, "stage": STAGE, "status": "PASS",
        "nodes": nodes, "edges": edges,
        "assertions": {
            "single_flute_item_owner": True,
            "both_kanto_consumers_share_tohoku_story_flag": True,
            "canonical_snorlax_species": species == 491,
            "fuji_duplicate_item_path_absent": True,
            "route_visibility_flags_distinct": route12 != route16,
        },
    }


def _resource_id(kind: str, value: int) -> str:
    if kind == "flag":
        return f"FLAG_{value:04X}"
    if kind == "var":
        return f"VAR_{value:04X}"
    if kind == "item":
        return f"ITEM_{value}"
    if kind == "trainer":
        return f"TRAINER_{value}"
    _fail(f"event dependency resource kind不正: {kind}")


def _instruction_state_accesses(instruction: Any) -> list[dict[str, Any]]:
    """Decode exact persistent operands from one live EventScript command."""

    opcode, raw = int(instruction.opcode), instruction.raw
    rows: list[dict[str, Any]] = []

    def add(kind: str, value: int, access: str, operand_offset: int) -> None:
        rows.append({
            "kind": kind, "id": value, "access": access,
            "operand_offset": operand_offset,
        })

    if opcode in (0x16, 0x17, 0x18):
        add("var", struct.unpack_from("<H", raw, 1)[0],
            "WRITE" if opcode == 0x16 else "READ_WRITE", 1)
    elif opcode == 0x19:
        destination, source = struct.unpack_from("<HH", raw, 1)
        add("var", destination, "WRITE", 1)
        add("var", source, "READ", 3)
    elif opcode == 0x1A:
        destination, source = struct.unpack_from("<HH", raw, 1)
        add("var", destination, "WRITE", 1)
        if source >= 0x4000:
            add("var", source, "READ", 3)
    elif opcode == 0x21:
        variable = struct.unpack_from("<H", raw, 1)[0]
        if variable >= 0x4000:
            add("var", variable, "READ", 1)
    elif opcode == 0x22:
        left, right = struct.unpack_from("<HH", raw, 1)
        if left >= 0x4000:
            add("var", left, "READ", 1)
        if right >= 0x4000:
            add("var", right, "READ", 3)
    elif opcode in (0x29, 0x2A, 0x2B):
        add(
            "flag", struct.unpack_from("<H", raw, 1)[0],
            "WRITE_SET" if opcode == 0x29 else
            "WRITE_CLEAR" if opcode == 0x2A else "READ",
            1,
        )
    elif opcode in (0x44, 0x45, 0x46, 0x47):
        add(
            "item", struct.unpack_from("<H", raw, 1)[0],
            "WRITE_ADD" if opcode == 0x44 else
            "READ_WRITE_REMOVE" if opcode == 0x45 else "READ",
            1,
        )
    elif opcode == 0x5C:
        add("trainer", struct.unpack_from("<H", raw, 2)[0], "READ_WRITE_BATTLE", 2)
    elif opcode in (0x60, 0x61, 0x62):
        add(
            "trainer", struct.unpack_from("<H", raw, 1)[0],
            "READ" if opcode == 0x60 else
            "WRITE_SET" if opcode == 0x61 else "WRITE_CLEAR",
            1,
        )
    return rows


def _effect_operand_summary(instruction: Any) -> dict[str, Any]:
    """Keep exact raw operands and decode the high-value effect identifiers."""

    opcode, raw = int(instruction.opcode), instruction.raw
    result: dict[str, Any] = {"raw_operand_hex": raw[1:].hex()}
    if opcode in {0x39, 0x3A, 0x3B, 0x3C, 0x3D, 0x3E, 0x3F, 0x40, 0x41, 0xC4, 0xD1}:
        result["effect_family"] = "WARP"
    elif opcode == 0x5C:
        result.update({
            "effect_family": "TRAINER_BATTLE",
            "trainer_id": struct.unpack_from("<H", raw, 2)[0],
            "battle_kind": raw[1],
        })
    elif opcode == 0xB6:
        result.update({
            "effect_family": "WILD_BATTLE_SETUP",
            "species": struct.unpack_from("<H", raw, 1)[0],
            "level": raw[3],
            "held_item": struct.unpack_from("<H", raw, 4)[0],
        })
    elif opcode == 0xB7:
        result["effect_family"] = "WILD_BATTLE_START"
    elif opcode in {
        0x4F, 0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57,
        0x58, 0x59, 0x5B, 0x63, 0x64, 0x65, 0xA8, 0xA9, 0xAA,
        0xAB, 0xAC, 0xAD, 0xAE, 0xAF, 0xB0,
    }:
        result["effect_family"] = "OBJECT_MOVEMENT_OR_MAP_GEOMETRY"
        if len(raw) >= 3 and opcode not in {0xAC, 0xAD, 0xAE, 0xAF, 0xB0}:
            result["local_object_operand"] = struct.unpack_from("<H", raw, 1)[0]
    return result


def _build_event_dependency_graph(
    story: Mapping[str, Any], output: bytes, npc_catalog: Mapping[str, Any],
    semantic_report: Mapping[str, Any], state_matrix: Mapping[str, Any],
) -> dict[str, Any]:
    """Normalize all owners, branches, cases, live CFG sites, and resources."""

    high = _story_event_graph(story)
    npcs = list(npc_catalog["npcs"])
    cases = list(state_matrix["cases"])
    roots = sorted({int(row["script_pointer"]) for row in npcs})
    graph = SemanticScriptGraph(output)
    graph.walk(roots)
    if graph.diagnostics:
        _fail(f"live Stage61 NPC CFG decode diagnostics: {graph.diagnostics[:8]}")

    site_rows: dict[str, dict[str, Any]] = {}
    root_rows: list[dict[str, Any]] = []
    root_site_ids: dict[int, list[str]] = {}
    root_state_sites: dict[tuple[int, str, int], set[str]] = defaultdict(set)
    resource_rows: dict[str, dict[str, Any]] = {}

    def ensure_resource(kind: str, value: int) -> dict[str, Any]:
        identifier = _resource_id(kind, value)
        return resource_rows.setdefault(identifier, {
            "id": identifier, "kind": f"{kind.upper()}_STATE",
            "numeric_id": value, "producer_site_ids": [],
            "consumer_site_ids": [], "matrix_provider_case_ids": [],
        })

    for root in roots:
        distances = graph.distances(root)
        instructions: dict[int, Any] = {}
        for node in distances:
            for instruction in graph.nodes[node].instructions:
                previous = instructions.setdefault(instruction.address, instruction)
                if previous.raw != instruction.raw:
                    _fail(f"live CFG instruction collision: {instruction.address:#x}")
        ids: list[str] = []
        for address, instruction in sorted(instructions.items()):
            accesses = _instruction_state_accesses(instruction)
            classification = classify_instruction(instruction)
            side_effects = list(classification.side_effect_classes)
            if not accesses and not side_effects:
                continue
            site_id = f"SITE_{address:08X}"
            site = site_rows.setdefault(site_id, {
                "id": site_id, "kind": "LIVE_SCRIPT_DEPENDENCY_SITE",
                "address": f"0x{address:08X}",
                "opcode": f"0x{instruction.opcode:02X}",
                "opcode_name": OPCODE_NAMES.get(
                    instruction.opcode, f"opcode_{instruction.opcode:02X}"
                ),
                "raw_hex": instruction.raw.hex(),
                "semantic_classes": list(classification.semantic_classes),
                "side_effect_classes": side_effects,
                "operand_summary": _effect_operand_summary(instruction),
                "state_accesses": accesses,
                "reachable_from_roots": [],
            })
            if site["raw_hex"] != instruction.raw.hex():
                _fail(f"live dependency site byte collision: {site_id}")
            if f"0x{root:08X}" not in site["reachable_from_roots"]:
                site["reachable_from_roots"].append(f"0x{root:08X}")
            ids.append(site_id)
            for access in accesses:
                resource = ensure_resource(str(access["kind"]), int(access["id"]))
                target = (
                    resource["consumer_site_ids"]
                    if str(access["access"]).startswith("READ") else
                    resource["producer_site_ids"]
                )
                if site_id not in target:
                    target.append(site_id)
                if "WRITE" in str(access["access"]) and site_id not in resource[
                    "producer_site_ids"
                ]:
                    resource["producer_site_ids"].append(site_id)
                root_state_sites[(root, str(access["kind"]), int(access["id"]))].add(
                    site_id
                )
        ids = sorted(set(ids))
        root_site_ids[root] = ids
        root_rows.append({
            "id": f"SCRIPT_{root:08X}", "kind": "LIVE_SCRIPT_ROOT",
            "root_address": f"0x{root:08X}",
            "cfg_node_count": len(distances),
            "instruction_count": len(instructions),
            "dependency_site_ids": ids,
        })

    owner_rows: list[dict[str, Any]] = []
    branch_rows: list[dict[str, Any]] = []
    owner_by_id = {str(row["npc_id"]): row for row in npcs}
    expected_branch_keys: set[tuple[str, str]] = set()
    for npc in npcs:
        owner_id = str(npc["npc_id"])
        live_root = int(npc["script_pointer"])
        source_root = npc.get("source_script_pointer")
        owner_rows.append({
            "id": f"OWNER_{owner_id}", "kind": "NPC_OWNER",
            "owner_id": owner_id, "owner_role": npc["owner_role"],
            "owner_provenance": npc["owner_provenance"],
            "map": [npc["group"], npc["map"]],
            "object_index": npc["object_index"], "local_id": npc["local_id"],
            "live_script_root": f"0x{live_root:08X}",
            "source_script_root": (
                f"0x{int(source_root):08X}" if source_root is not None else None
            ),
            "semantic_relocation": (
                "CLEAN_SOURCE_TO_STAGE61_LIVE_CFG"
                if source_root is not None else "LIVE_PROJECT_SCRIPT"
            ),
        })
        for branch in npc["branches"]:
            expected_branch_keys.add((owner_id, str(branch)))
            branch_rows.append({
                "id": f"BRANCH_{owner_id}_{branch}", "kind": "NPC_BRANCH",
                "owner_id": owner_id, "branch": branch,
                "live_script_root": f"0x{live_root:08X}",
                "case_ids": [],
            })
        visibility = int(npc["flag"])
        if visibility:
            script_site = _owner_pointer_site(output, {
                "event": "OBJECT", "group": npc["group"], "map": npc["map"],
                "index": npc["object_index"],
            })
            visibility_id = f"VISIBILITY_{owner_id}"
            site_rows[visibility_id] = {
                "id": visibility_id, "kind": "OBJECT_VISIBILITY_DEPENDENCY_SITE",
                "address": f"0x{GBA_BASE + script_site + 4:08X}",
                "opcode": "OBJECT_TEMPLATE_FLAG", "opcode_name": "visibility_flag",
                "raw_hex": struct.pack("<H", visibility).hex(),
                "semantic_classes": ["STATE_READ"], "side_effect_classes": [],
                "operand_summary": {"object_owner": owner_id},
                "state_accesses": [{
                    "kind": "flag", "id": visibility, "access": "READ_HIDE_WHEN_SET",
                    "operand_offset": 20,
                }],
                "reachable_from_roots": [],
            }
            resource = ensure_resource("flag", visibility)
            resource["consumer_site_ids"].append(visibility_id)

    branch_lookup = {
        (str(row["owner_id"]), str(row["branch"])): row for row in branch_rows
    }
    case_rows: list[dict[str, Any]] = []
    for case in cases:
        key = (str(case["owner_key"]), str(case["catalog_branch"]))
        if key not in branch_lookup:
            _fail(f"state matrix case branch link不明: {case['case_id']}")
        branch_lookup[key]["case_ids"].append(str(case["case_id"]))
        resources: list[dict[str, Any]] = []
        for kind, collection, value_key in (
            ("flag", case["state"]["flags"], "value"),
            ("var", case["state"]["vars"], "value"),
            ("item", case["state"]["items"], "count"),
            ("trainer", case["state"]["trainers"], "defeated"),
        ):
            for state in collection:
                identifier = _resource_id(kind, int(state["id"]))
                resource = ensure_resource(kind, int(state["id"]))
                if case["case_id"] not in resource["matrix_provider_case_ids"]:
                    resource["matrix_provider_case_ids"].append(case["case_id"])
                resources.append({
                    "resource_id": identifier, "value": state[value_key],
                    "source_id": state.get("source_id"),
                    "source_evidence_addresses": state.get("evidence_addresses", []),
                    "reason": state.get("reason"),
                })
        case_rows.append({
            "id": f"CASE_{case['case_id']}", "kind": "NPC_STATE_CASE",
            "case_id": case["case_id"], "owner_id": case["owner_key"],
            "branch": case["catalog_branch"],
            "interaction_expected": case["interaction_expected"],
            "expected_object_visible": case["expected_object_visible"],
            "state_resources": resources,
        })

    controls = [
        (int(str(root["root"]), 16), control)
        for root in state_matrix["semantic_roots"] for control in root["controls"]
    ]
    namespace_conversions: list[dict[str, Any]] = []
    unresolved_conversions: list[dict[str, Any]] = []
    for source_root, control in controls:
        kind = str(control["kind"])
        target = int(control["target_id"])
        live_roots = {
            int(npc["script_pointer"]) for npc in npcs
            if npc.get("source_script_pointer") == source_root
        }
        live_sites = sorted({
            site_id for live_root in live_roots
            for site_id in root_state_sites.get((live_root, kind, target), set())
        })
        row = {
            "source_root": f"0x{source_root:08X}",
            "live_roots": [f"0x{value:08X}" for value in sorted(live_roots)],
            "kind": kind, "source_id": int(control["source_id"]),
            "target_id": target,
            "source_evidence_addresses": list(control["evidence_addresses"]),
            "live_dependency_site_ids": live_sites,
            "mapping_basis": "SEMANTIC_CFG_PLUS_STAGE61_NAMESPACE_POLICY",
        }
        namespace_conversions.append(row)
        if not live_roots or not live_sites:
            unresolved_conversions.append(row)

    external_boundaries: list[dict[str, Any]] = []
    for identifier, resource in sorted(resource_rows.items()):
        for key in ("producer_site_ids", "consumer_site_ids", "matrix_provider_case_ids"):
            resource[key] = sorted(set(resource[key]))
        producers = resource["producer_site_ids"]
        consumers = resource["consumer_site_ids"]
        providers = resource["matrix_provider_case_ids"]
        if consumers and not producers and not providers:
            boundary = {
                "id": f"EXTERNAL_PRODUCER_{identifier}",
                "kind": "EXTERNAL_PROGRESSION_OR_ENGINE_PRODUCER",
                "resource_id": identifier,
                "basis": "OUTSIDE_NPC_OWNER_GRAPH_BOUNDARY_EXPLICITLY_CLASSIFIED",
                "consumer_site_ids": consumers,
            }
            external_boundaries.append(boundary)
            resource["producer_resolution"] = boundary["id"]
        elif consumers:
            resource["producer_resolution"] = (
                "LIVE_CFG_PRODUCER" if producers else "STATE_MATRIX_PROVIDER"
            )
        else:
            boundary = {
                "id": f"EXTERNAL_CONSUMER_{identifier}",
                "kind": "EXTERNAL_SAVE_OR_ENGINE_CONSUMER",
                "resource_id": identifier,
                "basis": "NPC_SIDE_EFFECT_SINK_OUTSIDE_OWNER_GRAPH_EXPLICITLY_CLASSIFIED",
                "producer_site_ids": producers,
            }
            external_boundaries.append(boundary)
            resource["producer_resolution"] = "PRODUCED_EFFECT_WITH_EXTERNAL_SINK"

    # Preserve high-level flute dependencies at top level while deduplicating
    # state nodes shared with the normalized resource graph.
    node_by_id: dict[str, dict[str, Any]] = {}
    for node in [
        *high["nodes"], *owner_rows, *branch_rows, *case_rows, *root_rows,
        *site_rows.values(), *resource_rows.values(), *external_boundaries,
    ]:
        identifier = str(node["id"])
        if identifier in node_by_id:
            # High-level FLAG/ITEM nodes and normalized state resources describe
            # the same identity.  Merge fields; every other duplicate is drift.
            if identifier.startswith(("FLAG_", "ITEM_")):
                node_by_id[identifier] = {**node_by_id[identifier], **node}
                continue
            _fail(f"event dependency graph node ID重複: {identifier}")
        node_by_id[identifier] = dict(node)
    edges = list(high["edges"])
    for owner in owner_rows:
        npc = owner_by_id[str(owner["owner_id"])]
        edges.append({
            "from": owner["id"],
            "to": f"SCRIPT_{int(npc['script_pointer']):08X}",
            "effect": "executes_live_cfg",
        })
    for branch in branch_rows:
        edges.append({
            "from": f"OWNER_{branch['owner_id']}", "to": branch["id"],
            "effect": "owns_catalog_branch",
        })
        for case_id in branch["case_ids"]:
            edges.append({
                "from": branch["id"], "to": f"CASE_{case_id}",
                "effect": "covered_by_state_case",
            })
    for root, ids in sorted(root_site_ids.items()):
        for site_id in ids:
            edges.append({
                "from": f"SCRIPT_{root:08X}", "to": site_id,
                "effect": "reaches_dependency_site",
            })
    for site in site_rows.values():
        for access in site["state_accesses"]:
            edges.append({
                "from": site["id"],
                "to": _resource_id(str(access["kind"]), int(access["id"])),
                "effect": str(access["access"]),
                "evidence_address": site["address"],
                "operand_offset": int(access["operand_offset"]),
            })
    for boundary in external_boundaries:
        edges.append({
            "from": boundary["id"], "to": boundary["resource_id"],
            "effect": boundary["basis"],
        })
    edge_keys = {
        (
            str(row["from"]), str(row["to"]), str(row["effect"]),
            int(row.get("operand_offset", -1)),
        ) for row in edges
    }
    if len(edge_keys) != len(edges):
        _fail("event dependency graph edge重複")

    actual_branch_keys = {
        (str(row["owner_id"]), str(row["branch"])) for row in branch_rows
    }
    case_branch_keys = {
        (str(row["owner_id"]), str(row["branch"])) for row in case_rows
    }
    assertions = {
        **high["assertions"],
        "all_3108_npc_owners_have_live_cfg": (
            len(owner_rows) == 3108 and len(roots) == len(root_rows)
        ),
        "all_catalog_branches_linked": (
            len(branch_rows) == int(npc_catalog["branch_count"])
            and actual_branch_keys == expected_branch_keys
            and case_branch_keys == expected_branch_keys
        ),
        "all_matrix_state_cases_linked": (
            len(case_rows) == int(
                state_matrix["counts"]["matrix_case_count"]
            )
        ),
        "live_cfg_has_zero_decode_diagnostics": not graph.diagnostics,
        "all_dependency_sites_are_reachable_from_live_root": all(
            row["reachable_from_roots"] or row["kind"] ==
                "OBJECT_VISIBILITY_DEPENDENCY_SITE"
            for row in site_rows.values()
        ),
        "semantic_namespace_conversion_unresolved_zero": not unresolved_conversions,
        "producer_consumer_boundaries_unresolved_zero": all(
            bool(row["producer_resolution"]) for row in resource_rows.values()
        ),
        "dead_branch_count_zero": all(row["case_ids"] for row in branch_rows),
        "high_level_flute_graph_preserved": (
            len(high["nodes"]) == 9 and len(high["edges"]) == 9
        ),
    }
    if not all(assertions.values()):
        _fail(
            "event dependency graph FAIL: "
            f"assertions={assertions} unresolved={unresolved_conversions[:4]}"
        )
    return {
        "schema_version": 2, "task": TASK, "stage": STAGE, "status": "PASS",
        "rom_sha256": _sha(output),
        "counts": {
            "npc_owner_count": len(owner_rows),
            "catalog_branch_count": len(branch_rows),
            "state_case_count": len(case_rows),
            "unique_live_script_root_count": len(root_rows),
            "live_cfg_node_count": len(graph.nodes),
            "dependency_site_count": len(site_rows),
            "state_resource_count": len(resource_rows),
            "namespace_conversion_count": len(namespace_conversions),
            "unresolved_namespace_conversion_count": 0,
            "external_boundary_count": len(external_boundaries),
            "dead_branch_count": 0,
            "unresolved_producer_consumer_count": 0,
            "node_count": len(node_by_id), "edge_count": len(edges),
        },
        "high_level_story_graph": {
            "nodes": high["nodes"], "edges": high["edges"],
            "assertions": high["assertions"],
        },
        "semantic_relocation_basis": {
            "report_sha256": _sha(_stable(semantic_report)),
            "owner_patch_count": len(semantic_report["stage61_owner_patches"]),
            "full_cfg_instruction_count": semantic_report[
                "full_cfg_relocation"
            ]["instruction_count"],
            "namespace_policy": semantic_report[
                "stage61_namespace_policy"
            ]["policy_name"],
        },
        "state_matrix_basis": {
            "case_count": len(case_rows),
            "semantic_root_count": len(state_matrix["semantic_roots"]),
        },
        "namespace_conversions": namespace_conversions,
        "external_boundaries": external_boundaries,
        "owner_coverage": owner_rows,
        "branch_coverage": branch_rows,
        "case_coverage": case_rows,
        "script_roots": root_rows,
        "dependency_sites": [site_rows[key] for key in sorted(site_rows)],
        "resources": [resource_rows[key] for key in sorted(resource_rows)],
        "nodes": [node_by_id[key] for key in sorted(node_by_id)],
        "edges": sorted(
            edges, key=lambda row: (
                str(row["from"]), str(row["to"]), str(row["effect"])
            ),
        ),
        "assertions": assertions,
    }


def _build_interaction_repair_manifest(
    stage60: bytes,
    stage61: bytes,
    npc_catalog: Mapping[str, Any],
    runtime_repair_rows: Sequence[Mapping[str, Any]],
    null_event_repairs: Sequence[Mapping[str, Any]],
    invalid_map_script_repairs: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Stage60 project CFG差分を全owner reach付きで明示する。"""

    manifest = build_project_source_manifest_skeleton(
        stage60, stage61, npc_catalog
    )
    owner_roots = manifest.get("owner_roots")
    npcs = npc_catalog.get("npcs")
    if not isinstance(owner_roots, dict) or not isinstance(npcs, list):
        _fail("project repair manifest skeleton schema不正")
    npc_by_id = {
        str(row["npc_id"]): row for row in npcs if isinstance(row, Mapping)
    }
    roots_to_owners: dict[int, set[str]] = defaultdict(set)
    for owner_key, evidence in owner_roots.items():
        if not isinstance(evidence, dict):
            _fail("project owner evidence schema不正")
        root = int(str(evidence["stage60_root"]), 0)
        npc = npc_by_id.get(str(owner_key))
        if not isinstance(npc, Mapping) \
                or not isinstance(npc.get("script_pointer"), int):
            _fail(f"project repair final owner不足: {owner_key}")
        evidence["stage61_root"] = f"0x{int(npc['script_pointer']):08X}"
        roots_to_owners[root].add(str(owner_key))

    graph = SemanticScriptGraph(stage60)
    graph.walk(sorted(roots_to_owners))
    if graph.diagnostics:
        _fail(f"project Stage60 graph diagnostics: {graph.diagnostics[0]}")
    owners_by_instruction: dict[int, set[str]] = defaultdict(set)
    instructions: dict[int, Any] = {}
    for root, owners in roots_to_owners.items():
        for node_address in graph.distances(root):
            for instruction in graph.nodes[node_address].instructions:
                instructions[instruction.address] = instruction
                owners_by_instruction[instruction.address].update(owners)

    runtime_intervals: list[tuple[int, int, Mapping[str, Any]]] = []
    for row in runtime_repair_rows:
        address = row.get("address")
        expected_hex = row.get("expected_hex")
        if isinstance(address, int) and isinstance(expected_hex, str):
            try:
                size = len(bytes.fromhex(expected_hex))
            except ValueError:
                _fail(f"runtime repair expected_hex不正: {row.get('repair_id')}")
            if size:
                runtime_intervals.append((address, address + size, row))
    repairs: list[dict[str, Any]] = []
    for address, instruction in sorted(instructions.items()):
        after = stage61[
            address - GBA_BASE:address - GBA_BASE + len(instruction.raw)
        ]
        if after == instruction.raw:
            continue
        instruction_end = address + len(instruction.raw)
        evidence_rows = [
            row for start, end, row in runtime_intervals
            if start < instruction_end and address < end
        ]
        families = sorted({
            str(row.get("family", "UNCLASSIFIED_RUNTIME_REPAIR"))
            for row in evidence_rows
        })
        if not evidence_rows:
            _fail(
                f"project instruction差分にruntime repair provenanceなし: "
                f"{address:#010x}"
            )
        repairs.append({
            "repair_id": f"PROJECT_INSTRUCTION_{address:08X}",
            "owner_keys": sorted(owners_by_instruction[address]),
            "stage60_address": f"0x{address:08X}",
            "stage60_before_hex": instruction.raw.hex(),
            "stage61_address": f"0x{address:08X}",
            "stage61_after_hex": after.hex(),
            "runtime_repair_ids": sorted(
                str(row["repair_id"]) for row in evidence_rows
            ),
            "semantic_contract": {
                "expected_text_provenance": "EXPLICIT_PROJECT_TEXT",
                "effect_relation": "+".join(families),
            },
        })
    manifest["repairs"] = repairs
    manifest["event_owner_repairs"] = [{
        key: value for key, value in row.items()
        if key not in {"expected_hex", "replacement_hex"}
    } for row in null_event_repairs]
    manifest["map_table_repairs"] = [dict(row) for row in invalid_map_script_repairs]
    manifest["runtime_repairs"] = [dict(row) for row in runtime_repair_rows]
    text_assets: dict[tuple[str, str, str], dict[str, Any]] = {}
    for repair in runtime_repair_rows:
        repair_id = str(repair.get("repair_id", ""))
        for source in repair.get("visible_text_assets", []):
            if not isinstance(source, Mapping):
                _fail(f"repair visible text asset schema不正: {repair_id}")
            pointer = str(source.get("pointer", ""))
            digest = str(source.get("raw_sha256", ""))
            source_rom = str(source.get("source_rom", ""))
            key = (source_rom, pointer, pointer)
            row = text_assets.setdefault(key, {
                "kind": "PINNED_PROJECT_TEXT",
                "source_rom": source_rom,
                "source_pointer": pointer,
                "materialized_pointer": pointer,
                "raw_sha256": digest,
                "source_provenance": source.get("source_provenance"),
                "repair_ids": [],
            })
            if row["raw_sha256"] != digest:
                _fail(f"repair visible text hash競合: {pointer}")
            row["repair_ids"].append(repair_id)
        for source in repair.get("text_relocations", []):
            if not isinstance(source, Mapping):
                _fail(f"repair text relocation schema不正: {repair_id}")
            source_pointer = str(source.get("source_pointer", ""))
            target_pointer = str(source.get("target_pointer", ""))
            digest = str(source.get("raw_sha256", ""))
            key = (str(source.get("source_rom", "")), source_pointer,
                   target_pointer)
            row = text_assets.setdefault(key, {
                "kind": "CLEAN_TEXT_RELOCATION",
                "source_rom": source.get("source_rom"),
                "source_pointer": source_pointer,
                "materialized_pointer": target_pointer,
                "raw_size": source.get("raw_size"),
                "raw_sha256": digest,
                "owner_source_roots": list(
                    source.get("owner_source_roots", [])
                ),
                "repair_ids": [],
            })
            if row["raw_sha256"] != digest:
                _fail(f"repair relocated text hash競合: {source_pointer}")
            row["repair_ids"].append(repair_id)
    for row in text_assets.values():
        row["repair_ids"] = sorted(set(row["repair_ids"]))
    manifest["text_assets"] = [
        text_assets[key] for key in sorted(text_assets)
    ]
    manifest["status"] = "PROJECT_EVIDENCE_AND_REPAIRS_COMPLETE_ABIS_REQUIRED"
    assertions = manifest.get("assertions")
    if not isinstance(assertions, dict):
        _fail("project repair manifest assertions不正")
    assertions.update({
        "repairs_complete": True,
        "all_stage60_project_instruction_differences_declared": True,
        "event_owner_null_repairs_exact": (
            len(null_event_repairs) == sum(NULL_EVENT_SCRIPT_EXPECTED_COUNTS.values())
        ),
        "invalid_vega_map_table_repairs_exact": (
            len(invalid_map_script_repairs) == len(INVALID_VEGA_MAP_SCRIPT_TABLES)
        ),
        "all_trainer_proxy_visible_text_assets_pinned": all(
            len(row.get("visible_text_assets", [])) == 2
            for row in runtime_repair_rows
            if str(row.get("repair_id", "")).startswith("TRAINER_INTRO_")
        ),
        "trainer_rematch_relocated_alias_hook_exact": len([
            row for row in runtime_repair_rows
            if row.get("repair_id") ==
            "TRAINER_REMATCH_RELOCATED_COMMAND_ALIAS_HOOK"
            and row.get("alias_table", {}).get("row_count") ==
                TRAINER_REMATCH_ALIAS_EXPECTED_COUNT
            and row.get("stage35_delegate_entry") ==
                TRAINER_CHANGEKIT_GET_REMATCH_ENTRY
        ]) == 1,
        "all_route2_proxy_text_relocations_pinned": all(
            bool(row.get("text_relocations"))
            for row in runtime_repair_rows
            if str(row.get("repair_id", "")).startswith("ROUTE2_EMPTY_")
        ),
    })
    manifest.pop("manifest_sha256", None)
    manifest["manifest_sha256"] = _sha(_stable(manifest))
    return manifest


def _interaction_abi_pinned_inputs() -> tuple[
    dict[str, bytes], dict[str, Mapping[str, Any]],
]:
    """Load the independent source/symbol inputs used by the 264-entry ABI.

    Stock SPECIAL definitions are discovered only within the locked upstream
    ``src`` tree.  Project native definitions and EventDesign's generated
    source model use explicit allow-lists so a test harness or stale duplicate
    source can never satisfy a production ABI by name.  Runtime reports remain
    broad because each matched symbol is additionally bound to its exact
    Stage60/Stage61 address and full function span by the oracle API.
    """
    source_paths = [
        ROOT / "vendor/upstream/pokefirered/data/specials.inc",
        ROOT / "vendor/upstream/pokefirered/data/scripts/obtain_item.inc",
        ROOT / "vendor/upstream/pokefirered/include/global.h",
        ROOT / "vendor/upstream/pokefirered/include/constants/maps.h",
        ROOT / "scripts/build_stage61_display_npc_event_audit.py",
        ROOT / "content/trainer_changekit_final/trainer_dialogue.csv",
        ROOT / TRAINER_SERIALIZED_PATH,
        ROOT / TRAINER_CHANGEKIT_RUNTIME_SOURCE_PATH,
        # PurchaseSelected's returned ABI is defined by this enum, not by
        # numeric literals in the implementation alone.  Pin the translated
        # header so the writer graph cannot pass after an enum/include drift.
        ROOT / "overlays/research_economy_v1/research_economy_v1.h",
        *(ROOT / path for path in BILL_SEVII_SOURCE_EVIDENCE_PATHS),
        *sorted((ROOT / "vendor/upstream/pokefirered/src").rglob("*.c")),
        *(ROOT / path for path in INTERACTION_ABI_PROJECT_SOURCES),
        *(ROOT / path for path in INTERACTION_ABI_GENERATOR_SOURCES),
        *(ROOT / path for path in INTERACTION_ABI_EVENT_DESIGN_MODEL_SOURCES),
    ]
    if len(source_paths) != len({path.resolve() for path in source_paths}) \
            or any(not path.is_file() for path in source_paths):
        _fail("interaction ABI pinned source集合が欠落/重複しています")
    source_blobs = {
        path.relative_to(ROOT).as_posix(): path.read_bytes()
        for path in source_paths
    }
    runtime_reports: dict[str, Mapping[str, Any]] = {}
    report_paths = sorted((ROOT / "generated/runtime").glob("*symbols.json"))
    if not report_paths:
        _fail("interaction ABI runtime symbol reportがありません")
    for path in report_paths:
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as error:
            _fail(f"interaction ABI symbol report不正:{path}:{error}")
        if not isinstance(value, Mapping):
            _fail(f"interaction ABI symbol report root不正:{path}")
        runtime_reports[path.relative_to(ROOT).as_posix()] = value
    return source_blobs, runtime_reports


def _complete_repair_manifest_with_abi(
    repair_manifest: dict[str, Any], abi_manifest: Mapping[str, Any],
) -> None:
    incomplete = abi_manifest.get("status") != "PASS" \
            or not all(abi_manifest.get("assertions", {}).values()) \
            or len(abi_manifest.get("special_abis", [])) != 176 \
            or len(abi_manifest.get("native_abis", [])) != 88 \
            or len(abi_manifest.get("effect_abis", [])) != 264 \
            or abi_manifest.get("registry_audit", {}).get("site_count") != 2590
    if incomplete:
        _fail(
            "interaction ABI manifestがcomplete PASSではありません:"
            f"status={abi_manifest.get('status')}:"
            f"special={len(abi_manifest.get('special_abis', []))}:"
            f"native={len(abi_manifest.get('native_abis', []))}:"
            f"effect={len(abi_manifest.get('effect_abis', []))}:"
            "site="
            f"{abi_manifest.get('registry_audit', {}).get('site_count')}"
        )
    repair_manifest["special_abis"] = list(abi_manifest["special_abis"])
    repair_manifest["native_abis"] = list(abi_manifest["native_abis"])
    repair_manifest["effect_abis"] = list(abi_manifest["effect_abis"])
    repair_manifest["interaction_abi_manifest_sha256"] = abi_manifest[
        "manifest_sha256"
    ]
    assertions = repair_manifest.get("assertions")
    if not isinstance(assertions, dict):
        _fail("repair manifest assertion root不正")
    assertions.update({
        "all_live_special_native_abis_pinned": True,
        "special_abi_176_exact": len(repair_manifest["special_abis"]) == 176,
        "native_abi_88_exact": len(repair_manifest["native_abis"]) == 88,
        "interaction_abi_264_exact": (
            len(repair_manifest["effect_abis"]) == 264
        ),
        "all_event_abi_live_site_2590_exact": (
            abi_manifest["registry_audit"]["site_count"] == 2590
        ),
        "abi_live_site_unresolved_zero": abi_manifest[
            "registry_audit"
        ]["unresolved_site_count"] == 0,
    })
    repair_manifest["status"] = "PASS"
    repair_manifest.pop("manifest_sha256", None)
    repair_manifest["manifest_sha256"] = _sha(_stable(repair_manifest))


def _critical_release_persistent_state_contract() -> dict[str, Any]:
    """Return only the save contracts required by the critical runtime gate.

    The strict build continues to publish its larger exhaustive contract.  The
    candidate metadata intentionally carries the smaller contract needed to
    bind boot/Continue/save/reload tests without representing deferred audit as
    complete.
    """

    return {
        "scope": "CRITICAL_RELEASE_SAVE_AND_CONTINUE",
        "normal_save_copy_on_write": {
            "runtime_symbol": "Stage61State_HandleSavingData",
            "save_type": "SAVE_NORMAL_ONLY_0",
            "stock_handle_saving_data_delegated": False,
            "stock_try_write_sector_used": False,
            "protected_bank_flash_policy": "READ_ONLY_BYTE_EXACT",
            "preinvalidation_callback_failure_is_not_ignored": True,
            "save_failed_screen_wipe_retry_mgba_required": True,
            "natural_start_menu_second_retry_mgba_required": True,
            "fresh_core_continue_mgba_required": True,
        },
        "link_save_record_commit": {
            "runtime_symbol": "Stage61State_HandleSavingData",
            "save_type": "SAVE_LINK_ONLY_1",
            "stock_damaged_side_channel_normalized_to_error": True,
            "direct_callers": [
                {
                    "address": f"0x{address:08X}",
                    "preimage_hex": expected.hex(),
                }
                for address, expected in SAVE_LINK_RECORD_CALLSITES
            ],
            "record_only_transaction": {
                "invariant": "AT_LEAST_ONE_COMPLETE_GENERATION_ALWAYS",
            },
        },
    }


