    # The shared Route 11/Route 18 gate script jumps one byte into the
    # operand of a valid ``specialvar VAR_RESULT, 184`` instruction.  Calling
    # that address as a script decodes operand 0x0D as an opcode, so the
    # result==6 branch can retain the field lock and wander through unrelated
    # bytes.  Bind the repair to the complete five-byte goto preimage and the
    # exact target closure instead of accepting a permissive decoder recovery.
    misaligned_site = 0x08174EF3
    misaligned_expected = bytes.fromhex("058d893709")
    misaligned_replacement = bytes.fromhex("058c893709")
    corrected_target = 0x0937898C
    corrected_closure = stage60[
        corrected_target - GBA_BASE:corrected_target - GBA_BASE + 0x3D
    ]
    corrected_closure_sha256 = (
        "12ce2ad19b8e4e6d165286508fa6c1e3dced69ccc4ee42f8de6122ceeff029c7"
    )
    if len(corrected_closure) != 0x3D \
            or _sha(corrected_closure) != corrected_closure_sha256:
        _fail("misaligned goto corrected target closure不一致")
    _apply_patch(
        stage60, output, declared,
        name="event_repair::misaligned_goto_specialvar_operand",
        offset=misaligned_site - GBA_BASE,
        expected=misaligned_expected,
        replacement=misaligned_replacement,
        category="EVENT_SCRIPT_CONTROL_FLOW_ALIGNMENT_REPAIR",
    )
    runtime_event_repair_patch_rows.append({
        "repair_id": "MISALIGNED_GOTO_SPECIALVAR_OPERAND_08174EF3",
        "family": "MISALIGNED_GOTO_INTO_SPECIALVAR_DESTINATION_OPERAND",
        "owner_ids": ["OBJECT:003/015:000", "OBJECT:003/037:001"],
        "shared_root": "0x08174E5D",
        "address": misaligned_site,
        "before_target": "0x0937898D",
        "after_target": f"0x{corrected_target:08X}",
        "expected_hex": misaligned_expected.hex(),
        "replacement_hex": misaligned_replacement.hex(),
        "target_closure_size": len(corrected_closure),
        "target_closure_sha256": corrected_closure_sha256,
        "semantic_contract": (
            "SPECIALVAR_184_RESULT_BRANCHES_END_WITH_FIELD_RELEASE"
        ),
        "source_provenance": (
            "LIVE_STAGE60_CFG_EXACT_EDGE_AND_CORRECTED_TARGET_CLOSURE"
        ),
    })

